#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RuntimeObservation {
    pub runtime_id: String,
    pub terminal: bool,
    pub status: String,
    pub exit_code: Option<i64>,
    pub incarnation_id: Option<String>,
}

pub trait RuntimeControl: Send + Sync + 'static {
    fn snapshot_ptys(&self) -> Result<Vec<RuntimeObservation>>;
    fn observe_exec(&self, runtime_id: &str) -> Result<Option<RuntimeObservation>>;
    fn start(&self, member: &MemberSpec) -> Result<()>;
    fn start_guarded(&self, member: &MemberSpec, guard: &dyn Fn() -> Result<()>) -> Result<()> {
        guard()?;
        self.start(member)
    }
    /// Physical launch provenance, if the runtime persists it independently of daemon receipts.
    fn rollout_operation(&self, _runtime_id: &str, _incarnation: &str) -> Result<Option<String>> {
        Ok(None)
    }
    fn rollout_exited(&self, runtime_id: &str, terminal: bool, incarnation: &str) -> Result<bool> {
        let observed = if terminal {
            self.snapshot_ptys()?
                .into_iter()
                .find(|o| o.runtime_id == runtime_id)
        } else {
            self.observe_exec(runtime_id)?
        };
        Ok(observed.is_some_and(|o| {
            o.incarnation_id.as_deref() == Some(incarnation)
                && matches!(o.status.as_str(), "exited" | "stopped" | "vanished")
        }))
    }
    fn stop(
        &self,
        runtime_id: &str,
        terminal: bool,
        expected_incarnation: Option<&str>,
    ) -> Result<()>;
    fn kill(
        &self,
        runtime_id: &str,
        terminal: bool,
        expected_incarnation: Option<&str>,
    ) -> Result<()>;
    fn remove(&self, runtime_id: &str, terminal: bool) -> Result<()>;
    fn screen(&self, runtime_id: &str) -> Result<String>;
    fn send_key(&self, runtime_id: &str, key: &str) -> Result<()>;
    fn read_exec_log(&self, runtime_id: &str) -> Result<Option<String>>;
    /// Ends, without waiting, what a runtime that is not running left in its work scope: a build
    /// or test its harness started that outlived it.
    fn end_leftovers(&self, _runtime_id: &str, _terminal: bool) {}
}

pub struct NativeRuntime {
    pty: st_runtime::PtyRuntime,
    exec: st_runtime::ExecRuntime,
    /// Goes first on every member's PATH so its `git` and `gh` calls are recorded.
    recorder: Option<PathBuf>,
}

impl NativeRuntime {
    pub fn new(state_dir: &Path, pty_root: Option<&Path>, pty_binary: &Path) -> Self {
        Self {
            pty: st_runtime::PtyRuntime::new(
                pty_root
                    .map(Path::to_path_buf)
                    .unwrap_or_else(|| state_dir.join("pty")),
            )
            .with_binary(pty_binary.to_string_lossy()),
            exec: st_runtime::ExecRuntime::new(state_dir.join("exec"), state_dir.join("logs")),
            recorder: None,
        }
    }
    pub fn with_recorder(mut self, directory: Option<PathBuf>) -> Self {
        self.recorder = directory;
        self
    }
    fn pty(&self) -> Result<st_runtime::PtyRuntime> {
        Ok(self
            .pty
            .clone()
            .with_environment(crate::environment::snapshot()?))
    }
}

/// The environment a started process gets: `declared` over the account's captured login-shell
/// environment, with the st3 executable's directory and then the command recorder first on PATH.
/// Members and `st missions check` both launch with it.
pub(crate) fn member_environment(
    declared: &BTreeMap<String, String>,
    executable: &Path,
    recorder: Option<&Path>,
) -> Result<BTreeMap<String, String>> {
    let mut environment =
        st_runtime::overlay_environment(crate::environment::snapshot()?, declared, executable)?;
    record_member_commands(&mut environment, recorder)?;
    Ok(environment)
}

/// Puts the recorder directory first on a member's PATH, after the declaration and the st3
/// executable directory are applied, so no authored PATH can place a program before it.
fn record_member_commands(
    environment: &mut BTreeMap<String, String>,
    recorder: Option<&Path>,
) -> Result<()> {
    let Some(recorder) = recorder else {
        return Ok(());
    };
    let path =
        crate::recorder::prepend(recorder, environment.get("PATH").map(std::ffi::OsStr::new))?;
    environment.insert("PATH".into(), path.to_string_lossy().into_owned());
    Ok(())
}

fn observed_pty_status(observation: &st_runtime::PtyObservation) -> String {
    if observation.status == "running"
        && observation
            .pid
            .is_some_and(|pid| !local_process_is_alive(pid))
    {
        return "vanished".into();
    }
    observation.status.clone()
}

#[cfg(unix)]
fn local_process_is_alive(pid: u32) -> bool {
    if pid == 0 || pid > i32::MAX as u32 {
        return false;
    }
    let result = unsafe { libc::kill(pid as i32, 0) };
    result == 0 || std::io::Error::last_os_error().raw_os_error() == Some(libc::EPERM)
}

#[cfg(not(unix))]
fn local_process_is_alive(_pid: u32) -> bool {
    true
}

impl RuntimeControl for NativeRuntime {
    fn snapshot_ptys(&self) -> Result<Vec<RuntimeObservation>> {
        let observations = self.pty()?.snapshot()?;
        // A PTY server started before st moved servers out of their harness's scope moves here.
        st_runtime::protect_servers(&observations);
        observations
            .into_iter()
            .map(|item| {
                let incarnation_id = match (&item.pid, &item.created_at) {
                    (Some(pid), Some(created)) => Some(format!("{pid}:{created}")),
                    _ => None,
                };
                let status = observed_pty_status(&item);
                Ok(RuntimeObservation {
                    runtime_id: item.name,
                    terminal: true,
                    status,
                    exit_code: item.exit_code,
                    incarnation_id,
                })
            })
            .collect()
    }

    fn observe_exec(&self, runtime_id: &str) -> Result<Option<RuntimeObservation>> {
        Ok(self
            .exec
            .observe(runtime_id)?
            .map(|observation| match observation {
                st_runtime::ExecObservation::Running(generation) => RuntimeObservation {
                    runtime_id: runtime_id.into(),
                    terminal: false,
                    status: "running".into(),
                    exit_code: None,
                    incarnation_id: Some(generation.generation_id),
                },
                st_runtime::ExecObservation::Exited(generation) => RuntimeObservation {
                    runtime_id: runtime_id.into(),
                    terminal: false,
                    status: "exited".into(),
                    exit_code: generation.exit_code.map(i64::from),
                    incarnation_id: Some(generation.generation_id),
                },
                st_runtime::ExecObservation::Indeterminate(reason) => RuntimeObservation {
                    runtime_id: runtime_id.into(),
                    terminal: false,
                    status: "indeterminate".into(),
                    exit_code: None,
                    incarnation_id: Some(reason),
                },
            }))
    }

    fn rollout_exited(&self, runtime_id: &str, terminal: bool, incarnation: &str) -> Result<bool> {
        if !terminal {
            return Ok(self.observe_exec(runtime_id)?.is_some_and(|o| {
                o.incarnation_id.as_deref() == Some(incarnation) && o.status == "exited"
            }));
        }
        let Some((pid, created)) = incarnation.split_once(':') else {
            return Ok(false);
        };
        let observed = self
            .pty()?
            .snapshot()?
            .into_iter()
            .find(|o| o.name == runtime_id);
        if let Some(observed) = observed {
            return Ok(
                matches!(observed.status.as_str(), "exited" | "stopped" | "vanished")
                    && observed.created_at.as_deref() == Some(created)
                    && observed
                        .pid
                        .is_none_or(|observed| pid.parse::<u32>().ok() == Some(observed)),
            );
        }
        let Some(pid) = pid.parse::<i32>().ok().filter(|pid| *pid > 0) else {
            return Ok(false);
        };
        #[cfg(unix)]
        {
            return Ok(unsafe { libc::kill(pid, 0) } != 0
                && std::io::Error::last_os_error().raw_os_error() == Some(libc::ESRCH));
        }
        #[cfg(not(unix))]
        {
            Ok(false)
        }
    }
    fn rollout_operation(&self, runtime_id: &str, incarnation: &str) -> Result<Option<String>> {
        Ok(self
            .pty()?
            .snapshot()?
            .into_iter()
            .find(|item| {
                item.name == runtime_id
                    && item
                        .pid
                        .zip(item.created_at.as_ref())
                        .is_some_and(|(pid, at)| format!("{pid}:{at}") == incarnation)
            })
            .and_then(|item| item.tags.get("st3.rollout").cloned()))
    }
    fn start(&self, member: &MemberSpec) -> Result<()> {
        self.start_checked(member, None)
    }
    fn start_guarded(&self, member: &MemberSpec, guard: &dyn Fn() -> Result<()>) -> Result<()> {
        self.start_checked(member, Some(guard))
    }

    fn stop(
        &self,
        runtime_id: &str,
        terminal: bool,
        expected_incarnation: Option<&str>,
    ) -> Result<()> {
        if terminal {
            self.pty()?.stop_if(runtime_id, expected_incarnation)
        } else {
            self.exec.stop_if(runtime_id, expected_incarnation)
        }
    }

    fn kill(
        &self,
        runtime_id: &str,
        terminal: bool,
        expected_incarnation: Option<&str>,
    ) -> Result<()> {
        if terminal {
            self.pty()?.kill_if(runtime_id, expected_incarnation)
        } else {
            self.exec.kill_if(runtime_id, expected_incarnation)
        }
    }

    fn remove(&self, runtime_id: &str, terminal: bool) -> Result<()> {
        if terminal {
            if self
                .pty()?
                .snapshot()?
                .iter()
                .any(|item| item.name == runtime_id)
            {
                self.pty()?.remove(runtime_id)
            } else {
                Ok(())
            }
        } else {
            self.exec.remove(runtime_id)
        }
    }

    fn screen(&self, runtime_id: &str) -> Result<String> {
        self.pty()?.screen(runtime_id)
    }

    fn send_key(&self, runtime_id: &str, key: &str) -> Result<()> {
        self.pty()?.send_key(runtime_id, key)
    }

    fn read_exec_log(&self, runtime_id: &str) -> Result<Option<String>> {
        self.exec.read_log(runtime_id)
    }

    fn end_leftovers(&self, runtime_id: &str, terminal: bool) {
        if terminal {
            self.pty.end_leftovers_later(runtime_id);
        } else {
            self.exec.end_leftovers_later(runtime_id);
        }
    }
}

impl NativeRuntime {
    fn start_checked(
        &self,
        member: &MemberSpec,
        guard: Option<&dyn Fn() -> Result<()>>,
    ) -> Result<()> {
        let executable = launch_executable()?;
        let environment =
            member_environment(&member.environment, &executable, self.recorder.as_deref())?;
        let mut launch = st_runtime::Launch::from(&member.launch);
        match &mut launch {
            st_runtime::Launch::Shell(source) => {
                st_runtime::expand_path_placeholder(source, &environment);
            }
            st_runtime::Launch::Argv(argv) => {
                for value in argv {
                    st_runtime::expand_path_placeholder(value, &environment);
                }
            }
        }
        // Resolve before crossing the PTY/isolation boundary; service-manager PATH is
        // unrelated to the environment captured from the account's login shell.
        match &mut launch {
            st_runtime::Launch::Shell(source) => {
                launch = st_runtime::Launch::Argv(vec![
                    st_runtime::resolve_executable("sh", &environment)?
                        .to_string_lossy()
                        .into_owned(),
                    "-c".into(),
                    source.clone(),
                ]);
            }
            st_runtime::Launch::Argv(argv) => {
                let program = argv
                    .first_mut()
                    .context("an argv launch must contain a program")?;
                *program = st_runtime::resolve_executable(program, &environment)?
                    .to_string_lossy()
                    .into_owned();
            }
        }
        let cwd = PathBuf::from(&member.cwd);
        if member.terminal {
            let pty_binary = st_runtime::resolve_executable("pty", &environment)?;
            let runtime = self
                .pty()?
                .clone()
                .with_binary(pty_binary.to_string_lossy());
            if let Some(operation) = member.environment.get(crate::rollout::OPERATION_ENV) {
                let predecessor = member
                    .environment
                    .get(crate::rollout::PREDECESSOR_ENV)
                    .context("rollout launch needs its predecessor fence")?;
                if let Some(guard) = guard {
                    runtime.spawn_after_checked(
                        &member.runtime_id,
                        &launch,
                        &cwd,
                        &environment,
                        member.display_name.as_deref(),
                        &member.tags,
                        predecessor,
                        operation,
                        guard,
                    )
                } else {
                    runtime.spawn_after(
                        &member.runtime_id,
                        &launch,
                        &cwd,
                        &environment,
                        member.display_name.as_deref(),
                        &member.tags,
                        predecessor,
                        operation,
                    )
                }
            } else {
                runtime.spawn(
                    &member.runtime_id,
                    &launch,
                    &cwd,
                    &environment,
                    member.display_name.as_deref(),
                    &member.tags,
                )
            }
        } else {
            self.exec
                .spawn(&member.runtime_id, &launch, &cwd, &environment)
                .map(|_| ())
        }
    }
}

/// A test hook that fails one item of a reconcile pass where the reconciler takes it up.
///
/// `fault(scope, subject)` returns the error that item should fail with, or panics to fail it
/// with a panic. The daemon never installs one; fault-isolation tests use it to fail each kind of
/// item on its own.
pub trait FaultInjection: Send + Sync + 'static {
    fn fault(&self, scope: &str, subject: &str) -> Option<String>;
}

pub struct Reconciler<R = NativeRuntime> {
    store: Arc<Store>,
    runtime: Arc<R>,
    host: String,
    endpoint: String,
    driver_state_dir: PathBuf,
    /// The `ST3_BIN` members get; see [`st_binary_link`]. Without one they get the executable.
    st_binary: Option<PathBuf>,
    runtime_environment: BTreeMap<String, String>,
    notify: Arc<Notify>,
    event_notify: watch::Sender<u64>,
    armed_schedules: Arc<Mutex<std::collections::HashSet<String>>>,
    schedule_peers: Vec<String>,
    started_at_unix_ms: u128,
    armed_observers: Arc<Mutex<std::collections::HashSet<String>>>,
    gate_poll_armed: Arc<AtomicBool>,
    /// The gate runners the gate poll watches.
    gate_poll_runtimes: Arc<Mutex<BTreeSet<String>>>,
    /// What each item's last evaluation read, so a pass can tell what a change affects.
    incremental: crate::incremental::Incremental,
    /// Fail a pass that makes a correction an incremental pass would have missed (tests).
    strict_incremental: bool,
    /// Skip items nothing changed for, between periodic full passes. Off in test reconcilers,
    /// whose every pass checks what an incremental pass would have missed.
    skip_unneeded: bool,
    /// The wake each running step has armed for its timeout or lease expiry, by step subject.
    step_deadlines: Arc<Mutex<HashMap<String, u128>>>,
    observer_deadlines: Arc<Mutex<HashMap<String, u128>>>,
    observer_cursors: Arc<Mutex<HashMap<String, Option<String>>>>,
    delayed_restarts: Arc<Mutex<HashMap<String, u128>>>,
    /// When each batched subscription may next send what it collected.
    batch_deadlines: Arc<Mutex<HashMap<String, u128>>>,
    /// When a failed `checkout` may run Git again, and why it failed, by agent subject.
    checkout_retries: Arc<Mutex<HashMap<String, (u128, String)>>>,
    /// A branch checked out elsewhere is a configuration conflict, held until the checkout changes.
    checkout_conflicts: Mutex<HashMap<String, (u64, Checkout, PathBuf, String)>>,
    /// The last agent declaration's run-end checkout and workspace, by subject, with the store
    /// index of the subject's newest declaration it was read from.
    declared_checkouts: Mutex<HashMap<String, (u64, Option<(Checkout, String)>)>>,
    materialized_mission_generations: Mutex<BTreeSet<String>>,
    /// Each running seat's incarnation and the member it was launched from, read once per
    /// incarnation, so a pass compares the declared launch without reading the store.
    launched_members: Mutex<HashMap<String, (String, Option<MemberSpec>)>>,
    retired_predecessor_generations: Mutex<BTreeSet<String>>,
    #[cfg(test)]
    mission_declaration_parses: std::sync::atomic::AtomicUsize,
    file_watchers: Arc<Mutex<HashMap<String, notify::RecommendedWatcher>>>,
    file_watchers_used: Arc<Mutex<HashSet<String>>>,
    file_observations: Arc<Mutex<HashMap<String, FileStamp>>>,
    resource_provider: Arc<dyn ResourceProvider>,
    /// Open faults by subject and scope, loaded from the graph on first use.
    faults: Mutex<Option<BTreeMap<(String, String), String>>>,
    /// Faults that could not be recorded in the graph during the current pass.
    unrecorded_faults: Mutex<Vec<String>>,
    /// Step-timeout faults this reconciler has already raised, so a pass records each once.
    step_timeout_faults: Mutex<BTreeSet<String>>,
    /// Broken-gate attention episodes this reconciler has already raised, so a pass that finds a
    /// gate still broken does not read every operational failure again.
    raised_broken_gates: Mutex<BTreeSet<String>>,
    /// The wait before an exec gate's second check; see [`GATE_RECHECK_BASE_MS`].
    gate_recheck_base_ms: u128,
    /// Each seat's last retention reading.
    seat_retention: Mutex<HashMap<String, SeatRetention>>,
    /// The gate runners the last read found, kept until a change they depend on.
    gate_runners: Mutex<Option<Vec<crate::store::MissionGateRunner>>>,
    /// Why each member failed its last render, kept while render is skipped.
    render_failures: Mutex<BTreeMap<String, String>>,
    /// The work wake each live agent's last evaluation queued, queued again while it is skipped.
    member_wakes: Mutex<HashMap<String, (String, String, MemberSpec)>>,
    /// How often a skipped member's terminal screen is looked at again for a prompt.
    screen_poll_every_ms: u128,
    fault_injection: Option<Arc<dyn FaultInjection>>,
    /// Reads free space for the disk stage. Without one the stage does nothing.
    disk_probe: Option<DiskProbe>,
    /// Paths whose filesystems the disk stage always watches, beside this host's workspaces.
    disk_paths: Vec<PathBuf>,
    /// When the disk stage last read free space, and whether its episode raised an item.
    disk_check: Mutex<(Option<u128>, bool)>,
    disk_check_every_ms: u128,
    /// When the fault stage last sent faults to their owning agents.
    fault_delivery: Mutex<Option<u128>>,
    fault_delivery_every_ms: u128,
    /// The claim the subagent stage starts its next look from; see `SubagentSweep::low_water`.
    subagent_low_water: Mutex<u64>,
    /// How long run cleanup waits for its runtimes to stop before the run ends without them.
    cleanup_deadline: Duration,
    /// Unit tests fail a pass that raises a fault unless they opt in, so an isolated error
    /// cannot hide inside a test that expects a clean pass.
    #[cfg(test)]
    raised_faults: Mutex<Option<Vec<String>>>,
}

#[derive(Clone, Eq, PartialEq)]
struct FileStamp {
    modified: Option<std::time::SystemTime>,
    size: u64,
    mode: u32,
}

impl FileStamp {
    fn read(path: &Path) -> Option<Self> {
        use std::os::unix::fs::PermissionsExt as _;
        let metadata = std::fs::metadata(path).ok()?;
        Some(Self {
            modified: metadata.modified().ok(),
            size: metadata.len(),
            mode: metadata.permissions().mode() & 0o7777,
        })
    }
}

impl Reconciler<NativeRuntime> {
    #[allow(clippy::too_many_arguments)]
    pub fn native(
        store: Arc<Store>,
        state_dir: &Path,
        pty_root: Option<&Path>,
        pty_binary: &Path,
        host: String,
        endpoint: String,
        notify: Arc<Notify>,
        event_notify: watch::Sender<u64>,
        recorder: Option<PathBuf>,
    ) -> Result<Self> {
        let selected_pty_root = pty_root
            .map(Path::to_path_buf)
            .unwrap_or_else(|| state_dir.join("pty"));
        Ok(Self {
            store,
            runtime: Arc::new(
                NativeRuntime::new(state_dir, Some(&selected_pty_root), pty_binary)
                    .with_recorder(recorder),
            ),
            host,
            endpoint,
            driver_state_dir: state_dir.join("drivers"),
            st_binary: Some(publish_st_binary(state_dir)?),
            runtime_environment: BTreeMap::from([
                (
                    "PTY_ROOT".into(),
                    selected_pty_root.to_string_lossy().into_owned(),
                ),
                // st3's own hook set, which `st up` publishes beneath this state directory.
                (
                    "ST_HOOKS".into(),
                    crate::hooks::set_dir(&crate::hooks::root(state_dir))
                        .to_string_lossy()
                        .into_owned(),
                ),
            ]),
            notify,
            event_notify,
            armed_schedules: Arc::new(Mutex::new(std::collections::HashSet::new())),
            schedule_peers: Vec::new(),
            started_at_unix_ms: now_ms(),
            armed_observers: Arc::new(Mutex::new(std::collections::HashSet::new())),
            gate_poll_armed: Arc::new(AtomicBool::new(false)),
            gate_poll_runtimes: Arc::new(Mutex::new(BTreeSet::new())),
            incremental: Default::default(),
            strict_incremental: false,
            skip_unneeded: std::env::var("ST3_INCREMENTAL").as_deref() != Ok("off"),
            step_deadlines: Arc::new(Mutex::new(HashMap::new())),
            observer_deadlines: Arc::new(Mutex::new(HashMap::new())),
            observer_cursors: Arc::new(Mutex::new(HashMap::new())),
            delayed_restarts: Arc::new(Mutex::new(HashMap::new())),
            batch_deadlines: Arc::new(Mutex::new(HashMap::new())),
            checkout_retries: Arc::new(Mutex::new(HashMap::new())),
            checkout_conflicts: Mutex::new(HashMap::new()),
            declared_checkouts: Mutex::new(HashMap::new()),
            materialized_mission_generations: Mutex::new(BTreeSet::new()),
            launched_members: Mutex::new(HashMap::new()),
            retired_predecessor_generations: Mutex::new(BTreeSet::new()),
            #[cfg(test)]
            mission_declaration_parses: std::sync::atomic::AtomicUsize::new(0),
            file_watchers: Arc::new(Mutex::new(HashMap::new())),
            file_watchers_used: Arc::new(Mutex::new(HashSet::new())),
            file_observations: Arc::new(Mutex::new(HashMap::new())),
            resource_provider: Arc::new(RegisteredResourceProvider),
            faults: Mutex::new(None),
            unrecorded_faults: Mutex::new(Vec::new()),
            step_timeout_faults: Mutex::new(BTreeSet::new()),
            raised_broken_gates: Mutex::new(BTreeSet::new()),
            gate_recheck_base_ms: GATE_RECHECK_BASE_MS,
            seat_retention: Mutex::new(HashMap::new()),
            gate_runners: Mutex::new(None),
            member_wakes: Mutex::new(HashMap::new()),
            render_failures: Mutex::new(BTreeMap::new()),
            fault_injection: None,
            disk_probe: Some(Arc::new(crate::disk::disk_space)),
            disk_paths: vec![state_dir.to_path_buf()],
            disk_check: Mutex::new((None, false)),
            disk_check_every_ms: DISK_CHECK_EVERY_MS,
            fault_delivery: Mutex::new(None),
            fault_delivery_every_ms: FAULT_DELIVERY_EVERY_MS,
            screen_poll_every_ms: SCREEN_POLL_EVERY_MS,
            subagent_low_water: Mutex::new(0),
            cleanup_deadline: CLEANUP_DEADLINE,
            #[cfg(test)]
            raised_faults: Mutex::new(Some(Vec::new())),
        })
    }
}

impl<R: RuntimeControl> Reconciler<R> {
    pub fn new(store: Arc<Store>, runtime: Arc<R>, host: String, notify: Arc<Notify>) -> Self {
        Self {
            store,
            runtime,
            host,
            endpoint: "unused-test-endpoint".into(),
            driver_state_dir: std::env::temp_dir().join("st3-test-drivers"),
            st_binary: None,
            runtime_environment: BTreeMap::new(),
            notify,
            event_notify: watch::channel(0_u64).0,
            armed_schedules: Arc::new(Mutex::new(std::collections::HashSet::new())),
            schedule_peers: Vec::new(),
            started_at_unix_ms: now_ms(),
            armed_observers: Arc::new(Mutex::new(std::collections::HashSet::new())),
            gate_poll_armed: Arc::new(AtomicBool::new(false)),
            gate_poll_runtimes: Arc::new(Mutex::new(BTreeSet::new())),
            incremental: Default::default(),
            strict_incremental: true,
            skip_unneeded: false,
            step_deadlines: Arc::new(Mutex::new(HashMap::new())),
            observer_deadlines: Arc::new(Mutex::new(HashMap::new())),
            observer_cursors: Arc::new(Mutex::new(HashMap::new())),
            delayed_restarts: Arc::new(Mutex::new(HashMap::new())),
            batch_deadlines: Arc::new(Mutex::new(HashMap::new())),
            checkout_retries: Arc::new(Mutex::new(HashMap::new())),
            checkout_conflicts: Mutex::new(HashMap::new()),
            declared_checkouts: Mutex::new(HashMap::new()),
            materialized_mission_generations: Mutex::new(BTreeSet::new()),
            launched_members: Mutex::new(HashMap::new()),
            retired_predecessor_generations: Mutex::new(BTreeSet::new()),
            #[cfg(test)]
            mission_declaration_parses: std::sync::atomic::AtomicUsize::new(0),
            file_watchers: Arc::new(Mutex::new(HashMap::new())),
            file_watchers_used: Arc::new(Mutex::new(HashSet::new())),
            file_observations: Arc::new(Mutex::new(HashMap::new())),
            resource_provider: Arc::new(RegisteredResourceProvider),
            faults: Mutex::new(None),
            unrecorded_faults: Mutex::new(Vec::new()),
            step_timeout_faults: Mutex::new(BTreeSet::new()),
            raised_broken_gates: Mutex::new(BTreeSet::new()),
            gate_recheck_base_ms: GATE_RECHECK_BASE_MS,
            seat_retention: Mutex::new(HashMap::new()),
            gate_runners: Mutex::new(None),
            member_wakes: Mutex::new(HashMap::new()),
            render_failures: Mutex::new(BTreeMap::new()),
            fault_injection: None,
            disk_probe: None,
            disk_paths: Vec::new(),
            disk_check: Mutex::new((None, false)),
            disk_check_every_ms: 0,
            fault_delivery: Mutex::new(None),
            fault_delivery_every_ms: 0,
            screen_poll_every_ms: 0,
            subagent_low_water: Mutex::new(0),
            cleanup_deadline: CLEANUP_DEADLINE,
            #[cfg(test)]
            raised_faults: Mutex::new(Some(Vec::new())),
        }
    }

    #[doc(hidden)]
    pub fn with_fault_injection(mut self, injection: Arc<dyn FaultInjection>) -> Self {
        self.fault_injection = Some(injection);
        self
    }

    /// Skip mission runs whose inputs did not change between full passes, as a daemon does
    /// unless `ST3_INCREMENTAL=off`.
    #[doc(hidden)]
    pub fn skipping_unneeded(mut self, skip: bool) -> Self {
        self.skip_unneeded = skip;
        self
    }

    #[doc(hidden)]
    pub fn with_cleanup_deadline(mut self, deadline: Duration) -> Self {
        self.cleanup_deadline = deadline;
        self
    }

    /// Legacy configured peers supplement the current claim-derived fleet membership.
    pub fn with_schedule_peers(mut self, peers: Vec<String>) -> Self {
        self.schedule_peers = peers;
        self
    }

    /// Read free space for `paths` and this host's workspaces with `probe` on every pass.
    #[cfg(test)]
    fn with_disk_probe(mut self, paths: Vec<PathBuf>, probe: DiskProbe) -> Self {
        self.disk_probe = Some(probe);
        self.disk_paths = paths;
        self
    }

    /// Let passes raise faults, for a unit test of fault isolation itself.
    #[cfg(test)]
    fn tolerating_faults(self) -> Self {
        *self.raised_faults.lock().unwrap() = None;
        self
    }

    #[cfg(test)]
    fn with_resource_provider(mut self, provider: Arc<dyn ResourceProvider>) -> Self {
        self.resource_provider = provider;
        self
    }

    #[cfg(test)]
    fn with_event_notify(mut self, event_notify: watch::Sender<u64>) -> Self {
        self.event_notify = event_notify;
        self
    }

    pub async fn run(self: Arc<Self>) {
        self.notify.notify_one();
        // When the last pass began, and whether it changed nothing.
        let mut quiet_pass_started = None;
        // Whether a successful pass must close this host's reconciler item. The first pass after a
        // start checks, since a panic or a restart can leave one open.
        let mut may_have_failed = true;
        loop {
            match self
                .blocking(|this| {
                    crate::profile::task("task reconcile-deadline", || {
                        this.next_reconcile_deadline()
                    })
                })
                .await
            {
                Some(deadline) => {
                    let delay = deadline_sleep_ms(deadline, now_ms(), quiet_pass_started);
                    tokio::select! {
                        _ = self.notify.notified() => {}
                        _ = tokio::time::sleep(Duration::from_millis(delay)) => {
                            crate::performance::record_wake("deadline", None);
                        }
                    }
                }
                None => self.notify.notified().await,
            }
            for pass in 0..64 {
                let started = now_ms();
                let check_recovery = may_have_failed;
                let (changed, failed) = self
                    .blocking(move |this| {
                        let before = this.store.index().ok();
                        let failed = match crate::profile::task("task reconcile-pass", || {
                            this.reconcile_once()
                        }) {
                            Err(error) => {
                                let _ = this.record_once(
                                    &format!("daemon/{}", this.host),
                                    "daemon.diagnostic",
                                    BTreeMap::from([
                                        ("severity".into(), Value::String("error".into())),
                                        ("code".into(), Value::String("reconcile-failed".into())),
                                        ("status".into(), Value::String("unreachable".into())),
                                        ("reason".into(), Value::String(error.to_string())),
                                    ]),
                                );
                                let _ = this.request_reconciler_attention(&format!(
                                    "A reconcile pass failed: {error:#}"
                                ));
                                true
                            }
                            Ok(()) => {
                                if check_recovery {
                                    let _ = this.resolve_reconciler_attention();
                                }
                                false
                            }
                        };
                        (before != this.store.index().ok(), failed)
                    })
                    .await;
                may_have_failed = failed;
                self.event_notify
                    .send_modify(|generation| *generation = generation.saturating_add(1));
                quiet_pass_started = (!changed).then_some(started);
                if !changed {
                    break;
                }
                if pass == 63 {
                    self.notify.notify_one();
                } else {
                    tokio::task::yield_now().await;
                }
            }
        }
    }

    /// Run blocking reconciler work on the blocking pool. A pass reads and writes the store and
    /// can wait for its writer; inline, that would hold an async worker that the API, timers and
    /// health checks need. A panic resumes here, so the supervisor still restarts the reconciler.
    async fn blocking<T: Send + 'static>(
        self: &Arc<Self>,
        work: impl FnOnce(&Self) -> T + Send + 'static,
    ) -> T {
        let this = self.clone();
        match tokio::task::spawn_blocking(move || work(&this)).await {
            Ok(value) => value,
            Err(error) => std::panic::resume_unwind(error.into_panic()),
        }
    }

    /// Run the reconciler and start it again if it panics. A panic ends only the task, so without
    /// this the daemon would keep serving its API with nothing reconciling the host.
    pub async fn supervise(self: Arc<Self>) {
        let mut delay = Duration::from_secs(1);
        loop {
            let started = std::time::Instant::now();
            let Err(error) = tokio::spawn(self.clone().run()).await else {
                return;
            };
            if !error.is_panic() {
                return;
            }
            let reason = panic_message(error.into_panic().as_ref());
            let _ = self.request_reconciler_attention(&format!(
                "The reconciler panicked and restarts: {reason}"
            ));
            let _ = self.record_once(
                &format!("daemon/{}", self.host),
                "daemon.diagnostic",
                BTreeMap::from([
                    ("severity".into(), Value::String("error".into())),
                    ("code".into(), Value::String("reconciler-panicked".into())),
                    ("status".into(), Value::String("restarting".into())),
                    ("reason".into(), Value::String(reason)),
                ]),
            );
            if started.elapsed() > Duration::from_secs(60) {
                delay = Duration::from_secs(1);
            }
            tokio::time::sleep(delay).await;
            delay = (delay * 2).min(Duration::from_secs(30));
        }
    }

    fn signal_changed(&self) {
        signal_changed(&self.notify, &self.event_notify);
    }

    /// Raise one host item while a filesystem that this daemon or one of its workspaces writes to
    /// is low on space, and close it once every one of them has recovered. A person who closes
    /// the item early is not asked again until the space recovers.
    /// Send each current fault once to its owning agent, from the host that runs that agent.
    /// No fault waits on a person: the agent retries, revises or cancels, and asks a person
    /// with `st work ask` only for what only a person can give.
    /// End the subagents this node recorded whose seat, harness or lease went away, and look
    /// again when the next lease runs out.
    fn end_stale_subagents(&self) -> Result<()> {
        let mut low_water = self
            .subagent_low_water
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        let sweep = self
            .store
            .end_stale_subagents(now_ms() as u64, *low_water)?;
        *low_water = sweep.low_water;
        if let Some(next) = sweep.next_expiry_unix_ms {
            self.arm_restart("stage/subagents", u128::from(next).saturating_add(1));
        }
        Ok(())
    }

    /// Keep each GitHub watch this host declared true to its seat and deadline: stop the
    /// declaration of a watch that ended, end one whose seat is retired or fresh without a wake,
    /// end one whose deadline passed with a final wake, and start the standing observer again when
    /// a running watch has none. A mission's subscription to a standing observer, such as an
    /// intake's, keeps it running the same way. Stop each standing observer this host declared
    /// once no running subscription uses it, and look again at the next deadline.
    pub(crate) fn reconcile_github_watches(&self, desired: &[DesiredSubject]) -> Result<()> {
        let now = now_ms();
        let mut next_deadline: Option<u128> = None;
        let mut used_observers = BTreeSet::new();
        let observers = desired
            .iter()
            .filter(|subject| subject.kind == "observer")
            .filter_map(|subject| {
                crate::graph::observer_spec(&subject.desired)
                    .map(|spec| (subject.subject.clone(), spec))
            })
            .collect::<Vec<_>>();
        let mut ensured = BTreeSet::new();
        let mut ensure = |locator: String| -> Result<()> {
            if ensured.insert(locator.clone()) {
                self.store.ensure_standing_observer(&locator, &observers)?;
            }
            Ok(())
        };
        let subscriptions = desired
            .iter()
            .filter(|subject| subject.kind == "subscription")
            .filter_map(|subject| {
                let spec = crate::graph::subscription_spec(&subject.desired)?;
                (!spec.stopped).then_some((subject, spec))
            })
            .collect::<Vec<_>>();
        for (subject, spec) in &subscriptions {
            if subject.subject.starts_with("subscription/watch/") {
                continue;
            }
            let Some(locator) = crate::github_watch::standing_locator(&spec.observer) else {
                continue;
            };
            used_observers.insert(spec.observer.clone());
            if self
                .store
                .selected_desired_origin(&subject.subject)?
                .as_deref()
                == Some(self.host.as_str())
            {
                ensure(locator)?;
            }
        }
        let watches = subscriptions
            .iter()
            .filter(|(subject, _)| subject.subject.starts_with("subscription/watch/"))
            .filter_map(|(subject, spec)| Some((*subject, spec, spec.watch.clone()?)))
            .collect::<Vec<_>>();
        for (subject, spec, watch) in watches {
            let Some((thread, _)) = crate::github_watch::watch_parts(&subject.subject) else {
                continue;
            };
            if self.store.watch_ended(&subject.subject, &watch)?.is_some() {
                if self
                    .store
                    .selected_desired_origin(&subject.subject)?
                    .as_deref()
                    == Some(self.host.as_str())
                {
                    self.store.stop_watch_declaration(&subject.subject)?;
                }
                continue;
            }
            if self
                .store
                .selected_desired_origin(&subject.subject)?
                .as_deref()
                != Some(self.host.as_str())
            {
                used_observers.insert(spec.observer.clone());
                continue;
            }
            if self.store.watch_seat_ended(&subject.subject, &spec.to, &watch)? {
                self.store.end_watch(&subject.subject, "seat-ended", None)?;
                continue;
            }
            if let Some(until) = watch.until_unix_ms {
                if until <= now {
                    let wake =
                        crate::github_watch::deadline_wake(&subject.subject, &watch, &thread)?;
                    self.store
                        .end_watch(&subject.subject, "deadline", Some(&wake))?;
                    continue;
                }
                next_deadline = Some(next_deadline.map_or(until, |next| next.min(until)));
            }
            used_observers.insert(spec.observer.clone());
            ensure(thread.locator())?;
        }
        for observer in desired.iter().filter(|subject| {
            subject.kind == "observer"
                && subject.owner_run.is_none()
                && subject.subject.starts_with("observer/github/")
        }) {
            // Only a standing repository observer is this stage's.
            let running = crate::graph::observer_spec(&observer.desired).is_some_and(|spec| {
                !spec.stopped && crate::github_watch::is_standing_observer(&observer.subject, &spec)
            });
            if running
                && !used_observers.contains(&observer.subject)
                && self
                    .store
                    .selected_desired_origin(&observer.subject)?
                    .as_deref()
                    == Some(self.host.as_str())
            {
                self.store.stop_watch_declaration(&observer.subject)?;
            }
        }
        if let Some(next) = next_deadline {
            self.arm_restart("stage/github-watches", next.saturating_add(1));
        }
        Ok(())
    }

    fn deliver_faults(&self, desired: &[DesiredSubject]) -> Result<()> {
        let local_agents = desired
            .iter()
            .filter(|subject| {
                subject.kind == "agent"
                    && subject
                        .member
                        .as_ref()
                        .is_some_and(|member| member.host == self.host)
            })
            .map(|subject| subject.subject.as_str())
            .collect::<BTreeSet<_>>();
        if local_agents.is_empty() {
            return Ok(());
        }
        let now = now_ms();
        {
            let mut last = self
                .fault_delivery
                .lock()
                .unwrap_or_else(PoisonError::into_inner);
            if let Some(at) = *last
                && now.saturating_sub(at) < self.fault_delivery_every_ms
            {
                // A fault raised since then still reaches its agent without another change.
                self.arm_restart(
                    "stage/faults",
                    at.saturating_add(self.fault_delivery_every_ms),
                );
                return Ok(());
            }
            *last = Some(now);
        }
        for fault in self.store.fault_snapshot(now)? {
            let Some(owner) = fault.owner.as_deref() else {
                continue;
            };
            if local_agents.contains(owner) {
                self.isolate("fault-delivery", owner, || {
                    append_fault_message(&self.store, owner, &fault.item)
                });
            }
        }
        Ok(())
    }

    fn reconcile_disk_space(&self, desired: &[DesiredSubject]) -> Result<()> {
        let Some(probe) = &self.disk_probe else {
            return Ok(());
        };
        let now = now_ms();
        {
            let mut check = self
                .disk_check
                .lock()
                .unwrap_or_else(PoisonError::into_inner);
            if check
                .0
                .is_some_and(|at| now.saturating_sub(at) < self.disk_check_every_ms)
            {
                return Ok(());
            }
            check.0 = Some(now);
        }
        let workspaces = desired
            .iter()
            .filter(|subject| subject.kind != "stop")
            .filter_map(|subject| subject.member.as_ref())
            .filter(|member| member.host == self.host)
            .map(|member| PathBuf::from(&member.workspace));
        // One reading per filesystem, named by the first path on it. A workspace that does not
        // exist yet has no filesystem to read.
        let mut filesystems = BTreeMap::<u64, (PathBuf, crate::disk::DiskSpace)>::new();
        for path in self.disk_paths.iter().cloned().chain(workspaces) {
            if let Ok(space) = probe(&path) {
                filesystems.entry(space.filesystem).or_insert((path, space));
            }
        }
        if filesystems.is_empty() {
            return Ok(());
        }
        let daemon = format!("daemon/{}", self.host);
        let title = format!("Disk space is low on {}", self.host);
        let pending = self
            .store
            .pending_operational_failures(RECONCILER_ACTOR, &self.host)?
            .into_iter()
            .filter(|request| request.title == title && request.targets == [daemon.as_str()])
            .collect::<Vec<_>>();
        let low = filesystems
            .values()
            .filter(|(_, space)| space.is_low())
            .map(|(path, space)| format!("`{}` has {}", path.display(), space.describe()))
            .collect::<Vec<_>>();
        if !low.is_empty() {
            let mut check = self
                .disk_check
                .lock()
                .unwrap_or_else(PoisonError::into_inner);
            if pending.is_empty() && !check.1 {
                let key = format!("disk-low:{}:{}", self.host, self.store.index()?);
                let digest = hex::encode(sha2::Sha256::digest(key.as_bytes()));
                self.store.record_operational_failure(
                    &format!("attention/{}", &digest[..32]),
                    &AttentionRequest {
                        reviewer: "person/operator".into(),
                        title,
                        reason: format!(
                            "On {}, {}. Builds and the claim store fail once a filesystem fills. Free space there, for example by removing the `target/` directories of finished worktrees with `cargo clean`; `df -h PATH` and `st doctor` show what is left. This item closes once each filesystem has 4 GiB and 4% free.",
                            self.host,
                            low.join("; ")
                        ),
                        severity: "error".into(),
                        targets: vec![daemon],
                        actor: RECONCILER_ACTOR.into(),
                        idempotency_key: key,
                    },
                )?;
                self.signal_changed();
            }
            check.1 = true;
            return Ok(());
        }
        if !filesystems.values().all(|(_, space)| space.has_recovered()) {
            return Ok(());
        }
        for request in pending {
            self.store.recover_operational_failure(
                &request.subject,
                "every filesystem this daemon writes to has 4 GiB and 4% free again",
                &format!("disk-recovered:{}", request.request),
            )?;
            self.signal_changed();
        }
        self.disk_check
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .1 = false;
        Ok(())
    }

    /// Raise one host item while whole reconcile passes fail or the reconciler panics. Nothing on
    /// the host advances in that time. The first cause names the item; later failures keep it.
    fn request_reconciler_attention(&self, cause: &str) -> Result<()> {
        let daemon = format!("daemon/{}", self.host);
        if self
            .store
            .pending_operational_failures(RECONCILER_ACTOR, &self.host)?
            .iter()
            .any(|request| {
                request.title == RECONCILER_FAILING_TITLE && request.targets == [daemon.as_str()]
            })
        {
            return Ok(());
        }
        let key = format!("reconciler-failing:{}:{}", self.host, now_ms());
        let digest = hex::encode(sha2::Sha256::digest(key.as_bytes()));
        self.store.record_operational_failure(
            &format!("attention/{}", &digest[..32]),
            &AttentionRequest {
                reviewer: "person/operator".into(),
                title: RECONCILER_FAILING_TITLE.into(),
                reason: format!(
                    "{cause}. Nothing on {} advances until a pass succeeds. Check the host with `st doctor` and the daemon's log; `st service restart` restarts the daemon. This item closes after the next successful pass.",
                    self.host
                ),
                severity: "error".into(),
                targets: vec![daemon],
                actor: RECONCILER_ACTOR.into(),
                idempotency_key: key,
            },
        )?;
        Ok(())
    }

    fn resolve_reconciler_attention(&self) -> Result<()> {
        let daemon = format!("daemon/{}", self.host);
        for request in self
            .store
            .pending_operational_failures(RECONCILER_ACTOR, &self.host)?
        {
            if request.title == RECONCILER_FAILING_TITLE && request.targets == [daemon.as_str()] {
                self.store.recover_operational_failure(
                    &request.subject,
                    "a reconcile pass succeeded",
                    &format!("reconciler-recovered:{}", request.request),
                )?;
                self.signal_changed();
            }
        }
        Ok(())
    }

    /// Reconcile one item of the pass on its own. An error or a panic is recorded as a fault on
    /// `subject` in `scope`, and the pass carries on with every other item. The next success
    /// records the item's recovery.
    fn isolate<T>(
        &self,
        scope: &str,
        subject: &str,
        item: impl FnOnce() -> Result<T>,
    ) -> Option<T> {
        let _span = crate::profile::span(scope);
        let result = caught(|| {
            if let Some(reason) = self
                .fault_injection
                .as_ref()
                .and_then(|injection| injection.fault(scope, subject))
            {
                anyhow::bail!(reason);
            }
            item()
        });
        let (value, outcome) = match result {
            Ok(value) => (Some(value), Ok(())),
            Err(error) => (None, Err(error)),
        };
        #[cfg(test)]
        if let (Err(error), Some(raised)) = (&outcome, self.raised_faults.lock().unwrap().as_mut())
        {
            raised.push(format!("{subject} {scope}: {error:#}"));
        }
        if let Err(error) = self.record_fault(subject, scope, outcome) {
            self.unrecorded_faults
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .push(format!("{subject} {scope}: {error:#}"));
        }
        value
    }

    /// Record a fault when it first appears or its cause changes, and its recovery once. A fault
    /// that lasts [`FAULT_ATTENTION_AFTER_MS`] raises one attention item for its subject and
    /// cause. A new cause replaces that item, and recovery closes it.
    fn record_fault(&self, subject: &str, scope: &str, outcome: Result<()>) -> Result<()> {
        match outcome {
            Err(error) => {
                let reason = format!("{error:#}");
                let mut faults = self.open_faults()?;
                let open = faults.get_or_insert_with(BTreeMap::new);
                let key = (subject.to_owned(), scope.to_owned());
                if open.get(&key) == Some(&reason) {
                    drop(faults);
                    return Ok(());
                }
                drop(faults);
                self.append_fault(subject, scope, "faulted", &reason)?;
                self.open_faults()?
                    .get_or_insert_with(BTreeMap::new)
                    .insert(key, reason);
                Ok(())
            }
            Ok(()) => self.close_fault(subject, scope, "the item reconciled successfully"),
        }
    }

    fn close_fault(&self, subject: &str, scope: &str, reason: &str) -> Result<()> {
        let key = (subject.to_owned(), scope.to_owned());
        if !self
            .open_faults()?
            .get_or_insert_with(BTreeMap::new)
            .contains_key(&key)
        {
            return Ok(());
        }
        self.append_fault(subject, scope, "recovered", reason)?;
        self.open_faults()?
            .get_or_insert_with(BTreeMap::new)
            .remove(&key);
        Ok(())
    }

    fn open_faults(
        &self,
    ) -> Result<std::sync::MutexGuard<'_, Option<BTreeMap<(String, String), String>>>> {
        let mut faults = self.faults.lock().unwrap_or_else(PoisonError::into_inner);
        if faults.is_none() {
            *faults = Some(self.store.open_reconcile_faults(&self.host)?);
        }
        Ok(faults)
    }

    fn append_fault(&self, subject: &str, scope: &str, status: &str, reason: &str) -> Result<()> {
        self.store.append_claim(&ClaimInput {
            subject: subject.into(),
            kind: "reconcile.fault".into(),
            actor: None,
            fields: BTreeMap::from([
                ("scope".into(), Value::String(scope.into())),
                ("status".into(), Value::String(status.into())),
                ("reason".into(), Value::String(reason.into())),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: None,
        })?;
        Ok(())
    }

    /// [`Self::next_reconcile_deadline`], for the quiet-pass benchmark.
    #[doc(hidden)]
    pub fn next_deadline(&self) -> Option<u128> {
        self.next_reconcile_deadline()
    }

    /// The earliest time the reconciler must wake. Each deadline source is read on its own. One
    /// that fails records a fault on the daemon and asks to be read again shortly, so the other
    /// sources keep their deadlines.
    fn next_reconcile_deadline(&self) -> Option<u128> {
        let daemon = format!("daemon/{}", self.host);
        let retry = now_ms().saturating_add(DEADLINE_SOURCE_RETRY_MS);
        let read = |scope: &str, source: &dyn Fn() -> Result<Option<u128>>| {
            self.isolate(scope, &daemon, source).unwrap_or(Some(retry))
        };
        [
            read("deadline/missions", &|| {
                self.store.next_active_mission_deadline(&self.host)
            }),
            // Skipping passes keep each wake's and capacity retry's due time, so these need
            // no scan of every local agent's work and diagnostics after every pass. The next
            // full pass bounds what a missing due time could delay.
            read("deadline/work-wakes", &|| {
                if self.skip_unneeded {
                    Ok(self.incremental.next_due("wake:"))
                } else {
                    self.next_work_wake_deadline()
                }
            }),
            read("deadline/provider-capacity-retries", &|| {
                if self.skip_unneeded {
                    Ok(self.incremental.next_due("capacity:"))
                } else {
                    self.next_provider_capacity_retry_deadline()
                }
            }),
            self.skip_unneeded
                .then(|| self.incremental.next_full_pass())
                .flatten(),
            read("deadline/subscription-retries", &|| {
                self.store.next_subscription_mission_retry_deadline()
            }),
            self.delayed_restarts
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .values()
                .copied()
                .min(),
            self.batch_deadlines
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .values()
                .copied()
                .min(),
        ]
        .into_iter()
        .flatten()
        .min()
    }

    fn next_work_wake_deadline(&self) -> Result<Option<u128>> {
        let mut work = self.store.work_for_reconcile_all()?;
        let local_agents = self
            .store
            .desired_subjects()?
            .into_iter()
            .filter(|subject| {
                subject.kind == "agent"
                    && subject
                        .member
                        .as_ref()
                        .is_some_and(|member| member.host == self.host)
            })
            .map(|subject| subject.subject)
            .collect::<BTreeSet<_>>();
        let run_orders = self.wake_run_orders(&local_agents, &work)?;
        let candidates = local_agents
            .iter()
            .filter_map(|agent| {
                let order = run_orders.get(agent).map(Vec::as_slice).unwrap_or_default();
                next_work_wake_for_agent(agent, &work, order).map(str::to_owned)
            })
            .collect::<BTreeSet<_>>();
        let now = now_ms();
        for step in &mut work {
            if candidates.contains(step.subject.as_str()) {
                // A step whose wake cannot be read keeps no wake, so it loses only its own
                // deadline.
                let subject = step.subject.clone();
                self.isolate("wake-deadline", &subject, || {
                    self.store.populate_work_wake_for_reconcile(step, now)
                });
            }
        }
        Ok(work_wake_deadline(&work, &local_agents, &run_orders, now))
    }

    /// Seat orders for the local seats whose next wake depends on run order.
    /// Reading an order replays the seat's moves, so a seat that holds work, has
    /// ready work in at most one run, or cannot be woken is skipped.
    fn wake_run_orders(
        &self,
        agents: &BTreeSet<String>,
        work: &[StepRunView],
    ) -> Result<BTreeMap<String, Vec<String>>> {
        let mut choosing = BTreeSet::new();
        for agent in agents {
            if seat_chooses_between_runs(agent, work)
                && self.store.current_harness(agent)?.is_some_and(|harness| {
                    matches!(harness.state.as_str(), "ready" | "working" | "idle")
                })
            {
                choosing.insert(agent.as_str());
            }
        }
        if choosing.is_empty() {
            return Ok(BTreeMap::new());
        }
        let mut orders = self.store.seat_run_orders()?;
        orders.retain(|agent, _| choosing.contains(agent.as_str()));
        Ok(orders)
    }

    /// A request that declared `until` closes on its own once every target meets that `trace
    /// Person asks are runtime dependencies fenced by their owning work. The host that accepted
    /// the request evaluates it, so it closes once.

    fn next_provider_capacity_retry_deadline(&self) -> Result<Option<u128>> {
        let mut deadline = None;
        for subject in self
            .store
            .desired_subjects()?
            .into_iter()
            .filter(|subject| {
                subject.kind == "agent"
                    && subject
                        .member
                        .as_ref()
                        .is_some_and(|member| member.host == self.host)
            })
        {
            for claim in self
                .store
                .claims_for(&subject.subject, Some("harness.diagnostic"))?
            {
                let fields = claim.body.get("fields").unwrap_or(&claim.body);
                if fields.get("code").and_then(Value::as_str) != Some("provider-capacity")
                    || fields.get("status").and_then(Value::as_str) != Some("waiting")
                    || self
                        .store
                        .operation_claim(&provider_capacity_retry_key(&claim.id))?
                        .is_some()
                {
                    continue;
                }
                let Some(due) = fields.get("retry_after_unix_ms").and_then(Value::as_u64) else {
                    continue;
                };
                deadline = Some(deadline.map_or(u128::from(due), |current: u128| {
                    current.min(u128::from(due))
                }));
            }
        }
        Ok(deadline)
    }

    pub fn reconcile_once(&self) -> Result<()> {
        self.recording_writes(|| self.reconcile_pass())
    }

    fn reconcile_pass(&self) -> Result<()> {
        let observe_span = crate::profile::span("pass/changes");
        self.incremental.observe(&self.store)?;
        drop(observe_span);
        let _runners_span = crate::profile::span("pass/gate-runners");
        for runner in self.gate_runners()? {
            if runner.retired && runner.host == self.host {
                let _ = self.isolate("gate", &runner.subject, || {
                    let runtime_id = runner.subject.replace('/', ".");
                    let observation = self.runtime.observe_exec(&runtime_id)?;
                    self.reconcile_runtime_stop(
                        &runner.subject,
                        &runtime_id,
                        false,
                        observation
                            .as_ref()
                            .and_then(|value| value.incarnation_id.as_deref()),
                        0,
                        observation.as_ref(),
                    )
                });
            }
        }
        drop(_runners_span);
        let desired_span = crate::profile::span("pass/desired");
        let mut desired = self.store.desired_subjects()?;
        let terminal_owned = self.store.terminal_owned_runtime_subjects()?;
        drop(desired_span);
        for subject in &mut desired {
            if terminal_owned.contains(&subject.subject)
                && subject
                    .member
                    .as_ref()
                    .is_some_and(|member| member.host == self.host)
            {
                subject.kind = "stop".into();
            }
        }
        let pty_span = crate::profile::span("pass/pty-snapshot");
        let ptys = self.runtime.snapshot_ptys();
        drop(pty_span);
        let ptys = match ptys {
            Ok(snapshot) => Some(
                snapshot
                    .into_iter()
                    .map(|item| (item.runtime_id.clone(), item))
                    .collect::<HashMap<_, _>>(),
            ),
            Err(error) => {
                // An unavailable snapshot is unknown, not an empty runtime set. Treating it as
                // empty could finish run cleanup while a PTY lives, so terminal members wait for
                // the next snapshot. Every other part of the pass still runs.
                self.arm_restart("runtime-snapshot", now_ms().saturating_add(1_000));
                self.record_once(
                    &format!("daemon/{}", self.host),
                    "daemon.diagnostic",
                    BTreeMap::from([
                        ("severity".into(), Value::String("error".into())),
                        (
                            "code".into(),
                            Value::String("runtime-snapshot-failed".into()),
                        ),
                        ("status".into(), Value::String("indeterminate".into())),
                        ("reason".into(), Value::String(error.to_string())),
                    ]),
                )?;
                None
            }
        };

        self.incremental.observe_ptys(ptys.as_ref().map(|ptys| {
            ptys.iter()
                .map(|(id, item)| {
                    let state = format!(
                        "{} {:?} {:?}",
                        item.status, item.incarnation_id, item.exit_code
                    );
                    (id.clone(), state)
                })
                .collect()
        }));

        let active = desired.iter().collect::<Vec<_>>();
        let mut member_errors = BTreeMap::new();
        for subject in &active {
            if self.store.owned_desired_guard(subject).is_err() {
                continue;
            }
            if subject.kind == "stop" {
                continue;
            }
            let Some(member) = subject
                .member
                .as_ref()
                .filter(|member| member.host == self.host)
            else {
                continue;
            };
            let workspace = Path::new(&member.workspace);
            let checkout = (subject.kind == "agent")
                .then(|| Checkout::from_desired(&subject.desired))
                .flatten();
            if workspace.is_dir() {
                if let Some(checkout) = &checkout
                    && let Err(error) = checkout.validate_workspace(workspace)
                {
                    member_errors.insert(subject.subject.clone(), error);
                    continue;
                }
                if subject.kind == "agent" {
                    self.observe_agent_workspace(&subject.subject, member)?;
                }
                continue;
            }
            let result = if let Some(checkout) = checkout {
                self.create_checkout(&subject.subject, &checkout, workspace)
                    .and_then(|failure| match failure {
                        Some(reason) => Err(anyhow::anyhow!(reason)),
                        None => Ok(()),
                    })
            } else if member.workspace_create {
                fs::create_dir_all(workspace).map_err(anyhow::Error::from)
            } else {
                Err(anyhow::anyhow!(
                    "the workspace does not exist and create was not requested"
                ))
            };
            if let Err(error) = result.with_context(|| format!("workspace {}", workspace.display()))
            {
                member_errors.insert(subject.subject.clone(), error);
            } else if subject.kind == "agent" {
                self.observe_agent_workspace(&subject.subject, member)?;
            }
        }
        let renderable = active
            .iter()
            .copied()
            .filter(|subject| !member_errors.contains_key(&subject.subject))
            .filter(|subject| self.store.owned_desired_guard(subject).is_ok())
            .collect::<Vec<_>>();
        // A live member is evaluated again when a claim it read, its runtime, its exec state or
        // its screen changed, when its time came, or when its workspace or render failed.
        let skip_members = self.skip_unneeded
            && ptys.is_some()
            && !self.incremental.take_full_pass("member", now_ms());
        // Render writes every member's files together (members sharing a repository share its
        // exclude file), so it runs whole or not at all: when what it read last changed, when a
        // member will be evaluated, or on a full pass. Otherwise its last failures stand; files
        // changed on disk are put back by the next full pass.
        let render_needed = !skip_members
            || self.incremental.needs("render", now_ms())
            || renderable.iter().any(|subject| {
                subject.kind != "stop"
                    && subject
                        .member
                        .as_ref()
                        .is_some_and(|member| member.host == self.host)
                    && self
                        .incremental
                        .needs(&format!("member:{}", subject.subject), now_ms())
            });
        // A render panic faults this host's members; stops never render, so they still run.
        let render_span = crate::profile::span("pass/render");
        let (rendered, render_reads) = if render_needed {
            smallclaims::touched::record(|| {
                std::panic::catch_unwind(AssertUnwindSafe(|| {
                    crate::render::apply_all_checked(
                        &self.store,
                        &renderable,
                        &self.host,
                        &|declaration| self.rollout_render_guard(declaration),
                    )
                }))
            })
        } else {
            let failed = self
                .render_failures
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .clone();
            (
                Ok(failed
                    .into_iter()
                    .map(|(subject, reason)| (subject, Err(anyhow::anyhow!(reason))))
                    .collect()),
                BTreeSet::new(),
            )
        };
        if render_needed {
            let mut reads = render_reads;
            // The members it renders come from the desired declarations.
            reads.insert("kind:intent.desired".to_owned());
            self.incremental.evaluated("render", reads, None);
        }
        let rendered = rendered.unwrap_or_else(|panic| {
            let reason = panic_message(panic.as_ref());
            renderable
                .iter()
                .filter(|subject| {
                    subject.kind != "stop"
                        && subject
                            .member
                            .as_ref()
                            .is_some_and(|member| member.host == self.host)
                })
                .map(|subject| {
                    (
                        subject.subject.clone(),
                        Err(anyhow::anyhow!("render panicked: {reason}")),
                    )
                })
                .collect()
        });
        let agents = renderable
            .iter()
            .filter(|subject| subject.kind == "agent")
            .map(|subject| subject.subject.as_str())
            .collect::<BTreeSet<_>>();
        let mut render_failed = BTreeMap::new();
        for (subject, result) in rendered {
            let result = result.and_then(|result| {
                let mut applied = BTreeMap::new();
                // Only an agent has a harness to report a diagnostic on. Another member keeps its
                // warnings on its render receipt, so a warning never faults it.
                if agents.contains(subject.as_str()) {
                    for warning in result.warnings {
                        self.record_once(
                            &subject,
                            "harness.diagnostic",
                            BTreeMap::from([
                                ("status".into(), Value::String("warning".into())),
                                ("reason".into(), Value::String(warning)),
                            ]),
                        )?;
                    }
                } else if !result.warnings.is_empty() {
                    applied.insert("warnings".into(), serde_json::to_value(result.warnings)?);
                }
                if !result.receipts.is_empty() {
                    applied.insert("writes".into(), serde_json::to_value(result.receipts)?);
                }
                if !applied.is_empty() {
                    self.record_once(&subject, "render.applied", applied)?;
                }
                Ok(())
            });
            if let Err(error) = result {
                render_failed.insert(subject.clone(), format!("{error:#}"));
                member_errors.insert(subject, error);
            }
        }
        if render_needed {
            *self
                .render_failures
                .lock()
                .unwrap_or_else(PoisonError::into_inner) = render_failed;
        }
        // A later run can declare the same workspace, so a finished run never removes a
        // checkout that a current member on this host still uses.
        let live_workspaces = active
            .iter()
            .filter(|subject| subject.kind != "stop")
            .filter_map(|subject| subject.member.as_ref())
            .filter(|member| member.host == self.host)
            .map(|member| member.workspace.as_str())
            .collect::<BTreeSet<_>>();
        drop(render_span);
        self.incremental.observe_value(
            "live-workspaces",
            live_workspaces
                .iter()
                .copied()
                .collect::<Vec<_>>()
                .join("\n"),
        );
        // A settled stop is evaluated again only when something it read changed or its time came,
        // and on every full pass. Without a PTY snapshot every stop waits on the next one anyway.
        // Seen first: what this pass already wrote, such as render receipts.
        self.incremental.observe(&self.store)?;
        let skip_stops = self.skip_unneeded
            && ptys.is_some()
            && !self.incremental.take_full_pass("stop", now_ms());
        let mut stops = BTreeSet::new();
        self.incremental.observe_execs(|runtime_id| {
            self.runtime
                .observe_exec(runtime_id)
                .ok()
                .flatten()
                .map(|observation| observation.status)
        });
        self.incremental.poll_values(
            "screen:",
            self.screen_poll_every_ms,
            now_ms(),
            |runtime_id| {
                self.runtime
                    .screen(runtime_id)
                    .ok()
                    .map(|screen| screen_digest(&screen))
            },
        );
        let mut members = BTreeSet::new();
        let mut work_message_agents = Vec::new();
        let mut deferred_member_faults = BTreeMap::new();
        let mut diagnostic_errors = Vec::new();
        let unreadable_span = crate::profile::span("pass/unreadable-members");
        self.record_unreadable_members(&active, &mut diagnostic_errors);
        drop(unreadable_span);
        let members_span = crate::profile::span("pass/members");
        for subject in &active {
            if self.store.owned_desired_guard(subject).is_err() {
                continue;
            }
            if subject.kind == "stop" {
                let _member_span = crate::profile::span("pass/member stop");
                let item = format!("stop:{}", subject.subject);
                stops.insert(item.clone());
                self.reconcile_stop_item(
                    subject,
                    &item,
                    skip_stops,
                    ptys.as_ref(),
                    &live_workspaces,
                    &mut diagnostic_errors,
                );
                continue;
            }
            let _member_span = crate::profile::span("pass/member live");
            if subject
                .member
                .as_ref()
                .is_none_or(|member| member.host != self.host)
            {
                continue;
            }
            let item = format!("member:{}", subject.subject);
            members.insert(item.clone());
            let needed = member_errors.contains_key(&subject.subject)
                || self.needs_item(&item, !skip_members);
            if skip_members && !needed {
                // Its last evaluation stands, the work wake it queued included.
                if let Some(wake) = self
                    .member_wakes
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .get(&subject.subject)
                {
                    work_message_agents.push(wake.clone());
                }
                continue;
            }
            let queued_before = work_message_agents.len();
            let cpu_started = crate::incremental::thread_cpu();
            let wrote_mark = smallclaims::touched::wrote_len();
            let ((result, due), reads) = smallclaims::touched::record(|| {
                smallclaims::touched::record_due(|| {
                    caught(|| -> Result<()> {
                        // A workspace or render failure blocks only a start or restart. A running member
                        // is still observed, checked, and given its work.
                        let mut blocked = member_errors.remove(&subject.subject);
                        let Some(member) = &subject.member else {
                            return Ok(());
                        };
                        if member.host != self.host {
                            return Ok(());
                        }
                        let observed = if member.terminal {
                            smallclaims::touched::note_read(|| {
                                format!("pty:{}", member.runtime_id)
                            });
                            // An unavailable snapshot is unknown, not an empty runtime set, so a terminal
                            // member is neither started nor judged until the snapshot returns.
                            let Some(ptys) = ptys.as_ref() else {
                                return blocked.map_or(Ok(()), Err);
                            };
                            ptys.get(&member.runtime_id).cloned()
                        } else {
                            smallclaims::touched::note_read(|| {
                                format!("exec:{}", member.runtime_id)
                            });
                            self.runtime.observe_exec(&member.runtime_id)?
                        };
                        if self.reconcile_rollout(subject, observed.as_ref(), blocked.as_ref())? {
                            return Ok(());
                        }
                        if subject.kind == "agent"
                            && let Some(suspension) =
                                crate::suspension::current(&self.store, &subject.subject)?
                            && suspension.holds_seat()
                        {
                            return self.reconcile_suspension(
                                subject,
                                member,
                                observed.as_ref(),
                                blocked,
                                &suspension,
                            );
                        }
                        if self.reconcile_requested_restart(
                            subject,
                            member,
                            observed.as_ref(),
                            blocked.as_ref(),
                        )? {
                            return Ok(());
                        }
                        match observed {
                            Some(observation) if observation.status == "running" => {
                                self.record_member(subject, &observation, true)?;
                                if let Some(changes) =
                                    self.declared_launch_changes(subject, member, &observation)?
                                {
                                    // Rendering must succeed before we shut down a still-running seat.
                                    if let Some(error) = blocked.take() {
                                        return Err(error);
                                    }
                                    self.record_once(
                                        &subject.subject,
                                        "runtime.reconcile-decision",
                                        BTreeMap::from([
                                            ("decision".into(), Value::String("restart".into())),
                                            (
                                                "reachability".into(),
                                                Value::String("reachable".into()),
                                            ),
                                            (
                                                "reason".into(),
                                                Value::String(format!(
                                                    "the declared {} changed",
                                                    changes.join(" and ")
                                                )),
                                            ),
                                        ]),
                                    )?;
                                    self.reconcile_runtime_stop(
                                        &subject.subject,
                                        &member.runtime_id,
                                        member.terminal,
                                        observation.incarnation_id.as_deref(),
                                        member.shutdown_timeout_ms,
                                        Some(&observation),
                                    )?;
                                    return Ok(());
                                }
                                self.reconcile_claude_auth_screen(subject, member, &observation)?;
                                self.reconcile_claude_trust_screen(
                                    subject,
                                    member,
                                    &observation,
                                    now_ms(),
                                )?;
                                self.reconcile_driver_readiness(
                                    subject,
                                    member,
                                    &observation,
                                    now_ms(),
                                )?;
                                if subject.kind == "agent"
                                    && let Some(incarnation) = observation.incarnation_id.as_deref()
                                {
                                    work_message_agents.push((
                                        subject.subject.clone(),
                                        incarnation.to_owned(),
                                        member.clone(),
                                    ));
                                }
                            }
                            Some(observation)
                                if matches!(observation.status.as_str(), "exited" | "vanished") =>
                            {
                                self.record_member(subject, &observation, false)?;
                                if !self
                                    .member_was_launched_for_selected_desired(&subject.subject)?
                                {
                                    if let Some(error) = blocked.take() {
                                        return Err(error);
                                    }
                                    self.perform_start(
                                        subject,
                                        member,
                                        "the desired member revision changed",
                                    )?;
                                    return Ok(());
                                }
                                let restart = match member.restart {
                                    RestartType::Always => true,
                                    RestartType::OnFailure => observation.exit_code != Some(0),
                                    RestartType::Never => false,
                                };
                                // A trust-prompt recovery stopped this incarnation in order to replace it,
                                // whatever the member's own exit policy says.
                                let recovering = self.claude_trust_recovery_stopped(
                                    &subject.subject,
                                    &observation,
                                )? || self.fresh_context_recovery_stopped(
                                    &subject.subject,
                                    &observation,
                                )?;
                                if (restart || recovering)
                                    && member.lifecycle == MemberLifecycle::Service
                                {
                                    if let Some(error) = blocked.take() {
                                        return Err(error);
                                    }
                                    self.reconcile_restart(subject, member, &observation)?;
                                }
                            }
                            Some(observation) => {
                                self.record_member(subject, &observation, false)?;
                            }
                            None if member.lifecycle == MemberLifecycle::AdoptOnly => {
                                self.record_once(
                                    &subject.subject,
                                    "runtime.observed",
                                    member_fields(member, "absent", None, false),
                                )?;
                            }
                            None => {
                                let prior = self.store.latest_actual_value(&subject.subject)?;
                                if prior.is_some()
                                    && !self.member_was_launched_for_selected_desired(
                                        &subject.subject,
                                    )?
                                {
                                    if let Some(error) = blocked.take() {
                                        return Err(error);
                                    }
                                    self.perform_start(
                                        subject,
                                        member,
                                        "the desired member revision changed",
                                    )?;
                                    return Ok(());
                                }
                                if prior.as_ref().is_some_and(|actual| {
                                    matches!(
                                        actual_field(actual, "status").and_then(Value::as_str),
                                        Some(
                                            "running"
                                                | "ready"
                                                | "working"
                                                | "idle"
                                                | "starting"
                                                | "exited"
                                                | "vanished"
                                        )
                                    )
                                }) {
                                    let observation = RuntimeObservation {
                                        runtime_id: member.runtime_id.clone(),
                                        terminal: member.terminal,
                                        status: "vanished".into(),
                                        exit_code: prior
                                            .as_ref()
                                            .and_then(|actual| actual_field(actual, "exit_code"))
                                            .and_then(Value::as_i64),
                                        incarnation_id: prior
                                            .as_ref()
                                            .and_then(|actual| {
                                                actual_field(actual, "incarnation_id")
                                            })
                                            .and_then(Value::as_str)
                                            .map(str::to_owned),
                                    };
                                    self.record_member(subject, &observation, false)?;
                                    let restart = match member.restart {
                                        RestartType::Always => true,
                                        RestartType::OnFailure => observation.exit_code != Some(0),
                                        RestartType::Never => false,
                                    };
                                    if restart
                                        || self.fresh_context_recovery_stopped(
                                            &subject.subject,
                                            &observation,
                                        )?
                                    {
                                        if let Some(error) = blocked.take() {
                                            return Err(error);
                                        }
                                        self.reconcile_restart(subject, member, &observation)?;
                                    }
                                } else {
                                    if let Some(error) = blocked.take() {
                                        return Err(error);
                                    }
                                    self.perform_start(
                                        subject,
                                        member,
                                        "the desired member is absent",
                                    )?;
                                }
                            }
                        }
                        blocked.map_or(Ok(()), Err)
                    })
                })
            });
            crate::performance::record_evaluation(
                "member",
                needed,
                crate::incremental::thread_cpu().saturating_sub(cpu_started),
            );
            if !needed {
                let wrote = smallclaims::touched::wrote_since(wrote_mark);
                if !wrote.is_empty() {
                    self.incremental_correction("member", &item, &reads, &wrote);
                }
            }
            {
                let mut wakes = self
                    .member_wakes
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner);
                match work_message_agents[queued_before..].last() {
                    Some(wake) => wakes.insert(subject.subject.clone(), wake.clone()),
                    None => wakes.remove(&subject.subject),
                };
            }
            // A failed member is evaluated again on the next pass, as before.
            if result.is_ok() {
                self.incremental.evaluated(&item, reads, due);
            }
            // A running agent's member pass also includes deferred work delivery, so its result
            // is recorded with that delivery.
            let deferred = work_message_agents
                .last()
                .is_some_and(|(agent, _, _)| agent == &subject.subject);
            if deferred {
                if let Err(error) = result {
                    deferred_member_faults.insert(subject.subject.clone(), error);
                }
            } else if let Err(error) = self.record_member_reconcile_result(&subject.subject, result)
            {
                diagnostic_errors.push(format!("{}: {error:#}", subject.subject));
            }
        }
        drop(members_span);
        self.incremental.retain("stop:", &stops);
        self.incremental.retain("member:", &members);
        self.member_wakes
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .retain(|subject, _| members.contains(&format!("member:{subject}")));
        // Each later stage runs on its own. A stage that fails records a fault on this daemon and
        // the stages after it still run, so no intake item can hold back mission evaluation, run
        // cleanup, or work delivery on this host.
        let daemon = format!("daemon/{}", self.host);
        // Intake left by a terminal owner or a superseded generation must not observe, deliver,
        // or start work. A stopped declaration still runs so it can settle its own state.
        let intake = self.isolate("stage/intake", &daemon, || {
            let retired_intake = self.store.retired_owned_intake_subjects()?;
            Ok(desired
                .iter()
                .filter(|subject| {
                    matches!(
                        subject.kind.as_str(),
                        "observer" | "subscription" | "schedule"
                    )
                })
                .filter(|subject| {
                    !retired_intake.contains(&subject.subject)
                        || intake_is_stopped(subject, &self.host)
                })
                .cloned()
                .collect::<Vec<_>>())
        });
        if let Some(intake) = intake {
            self.isolate("stage/observers", &daemon, || {
                self.reconcile_resource_observers(&intake, &desired)
            });
            self.isolate("stage/schedules", &daemon, || {
                self.reconcile_schedules(&intake)
            });
            self.isolate("stage/scheduled-work", &daemon, || {
                self.reconcile_scheduled_work(&intake)
            });
            self.isolate("stage/subscriptions", &daemon, || {
                self.reconcile_subscription_missions(&intake)
            });
        }
        self.isolate("stage/provider-capacity-retries", &daemon, || {
            self.reconcile_provider_capacity_retries(&desired)
        });
        self.isolate("stage/person-asks", &daemon, || {
            self.store.reconcile_person_asks()
        });
        self.isolate("stage/disk-space", &daemon, || {
            self.reconcile_disk_space(&desired)
        });
        self.isolate("stage/faults", &daemon, || self.deliver_faults(&desired));
        self.isolate("stage/subagents", &daemon, || self.end_stale_subagents());
        self.isolate("stage/github-watches", &daemon, || {
            self.reconcile_github_watches(&desired)
        });
        self.file_watchers_used
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .clear();
        self.isolate("stage/missions", &daemon, || self.evaluate_mission_runs());
        self.release_unused_file_watchers();

        // Mission state is the primary control-plane projection. Evaluate it before
        // wake-message bookkeeping so a large mailbox or work history cannot starve
        // newly-created runs of their first readiness pass.
        let _work_messages_span = crate::profile::span("pass/work-messages");
        // Earlier stages of this pass can change what a wake reads, such as a step a mission
        // cancelled, so see their changes first.
        self.incremental.observe(&self.store)?;
        let skip_wakes = self.skip_unneeded && !self.incremental.take_full_pass("wake", now_ms());
        let mut wakes = BTreeSet::new();
        for (agent, incarnation, member) in work_message_agents {
            let item = format!("wake:{agent}@{incarnation}");
            wakes.insert(item.clone());
            let result = self.reconcile_item("wake", &item, skip_wakes, || {
                self.reconcile_work_messages(&agent, &incarnation, Some(&member))
            });
            let result = match deferred_member_faults.remove(&agent) {
                Some(error) => Err(error),
                None => result,
            };
            if let Err(error) = self.record_member_reconcile_result(&agent, result) {
                diagnostic_errors.push(format!("{agent}: {error:#}"));
            }
        }
        self.incremental.retain("wake:", &wakes);
        diagnostic_errors.append(
            &mut self
                .unrecorded_faults
                .lock()
                .unwrap_or_else(PoisonError::into_inner),
        );
        if !diagnostic_errors.is_empty() {
            // Each of these items was already skipped on its own and the pass carried on. Only
            // the record of its fault is missing, so the host is faulted, not unreachable.
            let reason = format!("unrecorded item faults: {}", diagnostic_errors.join("; "));
            #[cfg(test)]
            if let Some(raised) = self.raised_faults.lock().unwrap().as_mut() {
                raised.push(reason.clone());
            }
            self.record_once(
                &daemon,
                "daemon.diagnostic",
                BTreeMap::from([
                    ("severity".into(), Value::String("error".into())),
                    ("code".into(), Value::String("fault-record-failed".into())),
                    ("status".into(), Value::String("faulted".into())),
                    ("reason".into(), Value::String(reason)),
                ]),
            )?;
        }
        #[cfg(test)]
        if let Some(raised) = self.raised_faults.lock().unwrap().as_mut() {
            let raised = std::mem::take(raised);
            anyhow::ensure!(raised.is_empty(), "reconcile faults: {}", raised.join("; "));
        }
        Ok(())
    }

    /// A member declaration this build cannot read has no member, so the member loop would
    /// pass over it without a word: never observed, started or stopped. The host that published
    /// it records the fault on it instead, until a build that can read it takes it up.
    fn record_unreadable_members(
        &self,
        active: &[&DesiredSubject],
        diagnostic_errors: &mut Vec<String>,
    ) {
        let candidates = active
            .iter()
            .filter(|subject| subject.member.is_none() && subject.kind != "stop")
            .map(|subject| subject.subject.as_str())
            .collect::<Vec<_>>();
        let unreadable = match self.store.unreadable_members(&candidates) {
            Ok(unreadable) => unreadable,
            Err(error) => {
                diagnostic_errors.push(format!("read member declarations: {error:#}"));
                return;
            }
        };
        for (subject, reason) in unreadable {
            let result = self
                .store
                .selected_desired_origin(&subject)
                .and_then(|origin| {
                    if origin.as_deref() != Some(self.host.as_str()) {
                        return Ok(());
                    }
                    self.record_member_reconcile_result(
                        &subject,
                        Err(anyhow::anyhow!(
                            "this build cannot read the member declaration: {reason}"
                        )),
                    )
                });
            if let Err(error) = result {
                diagnostic_errors.push(format!("{subject}: {error:#}"));
            }
        }
    }

    fn record_member_reconcile_result(&self, subject: &str, result: Result<()>) -> Result<()> {
        let previous = self.store.member_reconcile_fault(subject, None)?;
        let (decision, reason) = match result {
            Err(error) => {
                let reason = format!("{error:#}");
                if previous.as_deref() == Some(reason.as_str()) {
                    return Ok(());
                }
                ("member-fault", reason)
            }
            Ok(()) if previous.is_some() => (
                "member-recovered",
                "the member reconciled successfully".to_owned(),
            ),
            Ok(()) => return Ok(()),
        };
        self.record_once(
            subject,
            "runtime.reconcile-decision",
            BTreeMap::from([
                ("key".into(), Value::String("member-reconcile".into())),
                ("decision".into(), Value::String(decision.into())),
                ("reason".into(), Value::String(reason)),
            ]),
        )?;
        Ok(())
    }

    fn reconcile_provider_capacity_retries(&self, desired: &[DesiredSubject]) -> Result<()> {
        self.recording_writes(|| self.reconcile_provider_capacity_retries_pass(desired))
    }

    fn reconcile_provider_capacity_retries_pass(&self, desired: &[DesiredSubject]) -> Result<()> {
        self.incremental.observe(&self.store)?;
        let now = now_ms();
        let skip = self.skip_unneeded && !self.incremental.take_full_pass("capacity", now);
        let mut items = BTreeSet::new();
        for subject in desired.iter().filter(|subject| {
            subject.kind == "agent"
                && subject
                    .member
                    .as_ref()
                    .is_some_and(|member| member.host == self.host)
        }) {
            let item = format!("capacity:{}", subject.subject);
            items.insert(item.clone());
            self.reconcile_item("capacity", &item, skip, || {
                self.reconcile_provider_capacity_retry(subject, now)
            })?;
        }
        self.incremental.retain("capacity:", &items);
        Ok(())
    }

    /// Retry the provider-capacity backoffs of one local agent that have elapsed.
    fn reconcile_provider_capacity_retry(&self, subject: &DesiredSubject, now: u128) -> Result<()> {
        for claim in self
            .store
            .claims_for(&subject.subject, Some("harness.diagnostic"))?
        {
            let fields = claim.body.get("fields").unwrap_or(&claim.body);
            if fields.get("code").and_then(Value::as_str) != Some("provider-capacity")
                || fields.get("status").and_then(Value::as_str) != Some("waiting")
            {
                continue;
            }
            let Some(due) = fields.get("retry_after_unix_ms").and_then(Value::as_u64) else {
                continue;
            };
            let retry_key = provider_capacity_retry_key(&claim.id);
            if u128::from(due) > now {
                if self.store.operation_claim(&retry_key)?.is_none() {
                    smallclaims::touched::note_due(u128::from(due));
                }
                continue;
            }
            if self.store.operation_claim(&retry_key)?.is_some() {
                continue;
            }
            let incarnation = fields
                .get("incarnation_id")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let same_capacity_session =
                self.store
                    .current_harness(&subject.subject)?
                    .is_some_and(|harness| {
                        harness.incarnation_id == incarnation
                            && harness.state == "idle"
                            && harness.reason.as_deref() == Some("providerCapacity")
                    });
            if !same_capacity_session {
                self.store.append_claim(&ClaimInput {
                    subject: subject.subject.clone(),
                    kind: "publication.operation".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        (
                            "operation".into(),
                            Value::String("provider-capacity-retry".into()),
                        ),
                        (
                            "action".into(),
                            Value::String("skip-stale-incarnation".into()),
                        ),
                        ("status".into(), Value::String("accepted".into())),
                    ]),
                    evidence: vec![claim.id],
                    expected_subject: None,
                    idempotency_key: Some(retry_key),
                })?;
                self.signal_changed();
                continue;
            }
            let attempt = fields
                .get("retry_attempt")
                .and_then(Value::as_u64)
                .unwrap_or(1);
            let step = fields.get("step_run").and_then(Value::as_str);
            let message_id = &hex::encode(sha2::Sha256::digest(retry_key.as_bytes()))[..16];
            let message_subject = format!("message/{message_id}");
            let work_context = step
                .map(|step| format!(" Continue the claimed work `{step}`."))
                .unwrap_or_default();
            self.store.append_claim(&ClaimInput {
                subject: message_subject,
                kind: "message.sent".into(),
                actor: Some("daemon/runtime".into()),
                fields: BTreeMap::from([
                    ("from".into(), Value::String("daemon/runtime".into())),
                    ("to".into(), Value::String(subject.subject.clone())),
                    (
                        "content".into(),
                        Value::String(format!(
                            "The provider-capacity backoff elapsed.{work_context} Resume in this existing session; do not create a replacement worker."
                        )),
                    ),
                    (
                        "status".into(),
                        Value::String("sent".into()),
                    ),
                    (
                        "title".into(),
                        Value::String(format!(
                            "Provider capacity retry {attempt}"
                        )),
                    ),
                    ("in_reply_to".into(), Value::Null),
                    (
                        "tags".into(),
                        Value::Array(vec![
                            Value::String("st3-provider-capacity-retry".into()),
                            Value::String(format!("st3-retry-attempt:{attempt}")),
                            Value::String(format!("diagnostic-claim:{}", claim.id)),
                        ]),
                    ),
                ]),
                evidence: vec![claim.id],
                expected_subject: None,
                idempotency_key: Some(retry_key),
            })?;
            self.signal_changed();
        }
        Ok(())
    }

    fn reconcile_driver_readiness(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        observation: &RuntimeObservation,
        now: u128,
    ) -> Result<()> {
        if subject.kind != "agent" {
            return Ok(());
        }
        let Some(driver) = member.driver.as_deref() else {
            return Ok(());
        };
        let Some(incarnation) = observation.incarnation_id.as_deref() else {
            return Ok(());
        };
        let attention_key = format!("harness-readiness:{0}:{incarnation}", subject.subject);
        let attention_digest = hex::encode(sha2::Sha256::digest(attention_key.as_bytes()));
        let attention_subject = format!("attention/{}", &attention_digest[..32]);
        let harness_ready = self
            .store
            .current_harness(&subject.subject)?
            .is_some_and(|harness| harness.incarnation_id == incarnation && harness.is_ready());
        if harness_ready {
            if driver == "claude" {
                self.resolve_superseded_claude_auth_attention(&subject.subject, incarnation)?;
            }
            self.resolve_recovered_seat_attention(&subject.subject, incarnation)?;
            self.resolve_pending_alert(
                &attention_key,
                "the same runtime incarnation became ready",
            )?;
            return Ok(());
        }

        // This deadline describes startup only. A harness that was ready and later lost
        // observation needs a delivery/health diagnosis, not a false startup failure.
        if self
            .store
            .harness_was_ready(&subject.subject, incarnation)?
        {
            return Ok(());
        }

        let Some(runtime_claim) = self.running_runtime_claim(&subject.subject, incarnation)? else {
            return Ok(());
        };
        let deadline = runtime_claim
            .accepted_at_unix_ms
            .saturating_add(HARNESS_READINESS_DEADLINE_MS);
        if now < deadline {
            self.arm_restart(
                &format!("readiness:{}:{incarnation}", subject.subject),
                deadline,
            );
            return Ok(());
        }

        let reason = format!(
            "the {driver} harness did not become ready within {} seconds",
            HARNESS_READINESS_DEADLINE_MS / 1_000
        );
        let deadline_recorded = self
            .store
            .observations_for(&subject.subject, "runtime.readiness-deadline-reached")?
            .iter()
            .any(|claim| {
                claim
                    .body
                    .pointer("/fields/incarnation_id")
                    .and_then(Value::as_str)
                    == Some(incarnation)
            });
        let attention_recorded = self
            .store
            .operational_failure(&attention_subject)?
            .is_some();
        let mut changed = false;
        if !deadline_recorded {
            self.store.append_claim(&ClaimInput {
                subject: subject.subject.clone(),
                kind: "runtime.readiness-deadline-reached".into(),
                actor: None,
                fields: BTreeMap::from([
                    (
                        "runtime_id".into(),
                        Value::String(observation.runtime_id.clone()),
                    ),
                    ("driver".into(), Value::String(driver.into())),
                    ("incarnation_id".into(), Value::String(incarnation.into())),
                    (
                        "deadline_unix_ms".into(),
                        Value::String(deadline.to_string()),
                    ),
                    ("reason".into(), Value::String(reason.clone())),
                ]),
                evidence: vec![runtime_claim.id],
                expected_subject: None,
                idempotency_key: Some(format!("{attention_key}:deadline")),
            })?;
            changed = true;
        }
        if !attention_recorded {
            self.store.record_runtime_failure(
                &attention_subject,
                &AttentionRequest {
                    reviewer: "person/operator".into(),
                    title: "An agent harness did not become ready".into(),
                    reason,
                    severity: "error".into(),
                    targets: vec![subject.subject.clone()],
                    actor: "agent/st3/reconciler".into(),
                    idempotency_key: format!("{attention_key}:requested"),
                },
                "readiness",
            )?;
            changed = true;
        }
        if changed {
            self.signal_changed();
        }
        Ok(())
    }

    fn resolve_superseded_claude_auth_attention(
        &self,
        subject: &str,
        current_incarnation: &str,
    ) -> Result<()> {
        for claim in self.store.claims_for(subject, Some("harness.diagnostic"))? {
            if claim.body.pointer("/fields/code").and_then(Value::as_str)
                != Some("provider-auth-expired")
            {
                continue;
            }
            let Some(old_incarnation) = claim
                .body
                .pointer("/fields/incarnation_id")
                .and_then(Value::as_str)
            else {
                continue;
            };
            if old_incarnation == current_incarnation {
                continue;
            }
            self.resolve_pending_alert(
                &format!("claude-auth-expired:{subject}:{old_incarnation}"),
                "a new Claude runtime incarnation became ready",
            )?;
        }
        Ok(())
    }

    /// Startup and crash-loop alerts name one incarnation or desired token. Once another
    /// incarnation of the seat is ready, those alerts describe a runtime that is gone.
    fn resolve_recovered_seat_attention(
        &self,
        subject: &str,
        current_incarnation: &str,
    ) -> Result<()> {
        for claim in self
            .store
            .observations_for(subject, "runtime.readiness-deadline-reached")?
        {
            let Some(old_incarnation) = claim_incarnation(&claim) else {
                continue;
            };
            if old_incarnation == current_incarnation {
                continue;
            }
            self.resolve_pending_alert(
                &format!("harness-readiness:{subject}:{old_incarnation}"),
                "a later runtime incarnation became ready",
            )?;
        }
        Ok(())
    }

    /// Alerts this host raised about an agent that is no longer desired, or is desired stopped,
    /// have nothing left to fix. Alerts with any other target stay with their reviewer.

    fn resolve_pending_alert(&self, key: &str, reason: &str) -> Result<()> {
        let digest = hex::encode(sha2::Sha256::digest(key.as_bytes()));
        let attention_subject = format!("attention/{}", &digest[..32]);
        if self
            .store
            .operational_failure(&attention_subject)?
            .is_some_and(|attention| attention.status == "pending")
        {
            self.store.recover_operational_failure(
                &attention_subject,
                reason,
                &format!("{key}:resolved"),
            )?;
            self.signal_changed();
        }
        Ok(())
    }

    /// A member's terminal screen, read as an input: a later pass looks at it again (see
    /// [`SCREEN_POLL_EVERY_MS`]) and evaluates the member when it changed.
    fn member_screen(&self, runtime_id: &str) -> Result<String> {
        let screen = self.runtime.screen(runtime_id)?;
        let key = format!("screen:{runtime_id}");
        smallclaims::touched::note_read(|| key.clone());
        self.incremental
            .saw_value(&key, screen_digest(&screen), now_ms());
        Ok(screen)
    }

    fn reconcile_claude_auth_screen(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        observation: &RuntimeObservation,
    ) -> Result<()> {
        if subject.kind != "agent" || member.driver.as_deref() != Some("claude") || !member.terminal
        {
            return Ok(());
        }
        let Some(incarnation) = observation.incarnation_id.as_deref() else {
            return Ok(());
        };
        // Claude's login prompt does not emit a StopFailure hook. The initialized MCP channel
        // remains alive, so hook-only observation incorrectly reports this session as ready.
        let Ok(screen) = self.member_screen(&member.runtime_id) else {
            return Ok(());
        };
        let (fence, key) = self.claude_auth_fence(&subject.subject, incarnation)?;
        let Some(matched_line) = claude_login_expired(&screen) else {
            // The prompt is gone: a person ran /login, or the match was false. Either way the
            // incarnation can take work again, so its fence and the person's request end.
            if let Some(fence) = fence {
                self.store.append_claim(&ClaimInput {
                    subject: subject.subject.clone(),
                    kind: "harness.diagnostic".into(),
                    actor: Some(subject.subject.clone()),
                    fields: BTreeMap::from([
                        ("status".into(), Value::String("authenticated".into())),
                        (
                            "code".into(),
                            Value::String("provider-auth-restored".into()),
                        ),
                        (
                            "reason".into(),
                            Value::String("Claude no longer shows its expired-login prompt".into()),
                        ),
                        ("incarnation_id".into(), Value::String(incarnation.into())),
                    ]),
                    evidence: vec![fence],
                    expected_subject: None,
                    idempotency_key: Some(format!("{key}:restored")),
                })?;
                self.resolve_pending_alert(
                    &key,
                    "Claude no longer shows its expired-login prompt",
                )?;
                self.signal_changed();
            }
            return Ok(());
        };
        if fence.is_some() {
            return Ok(());
        }
        let digest = hex::encode(sha2::Sha256::digest(key.as_bytes()));
        let attention_subject = format!("attention/{}", &digest[..32]);
        if self
            .store
            .operational_failure(&attention_subject)?
            .is_some()
        {
            return Ok(());
        }
        self.store.append_claim(&ClaimInput {
                subject: subject.subject.clone(),
                kind: "harness.diagnostic".into(),
                actor: Some(subject.subject.clone()),
                fields: BTreeMap::from([
                    ("severity".into(), Value::String("error".into())),
                    ("status".into(), Value::String("unauthenticated".into())),
                    ("code".into(), Value::String("provider-auth-expired".into())),
                    ("reason".into(), Value::String("Claude reports an expired login; a person must run /login in this terminal and restart the harness".into())),
                    ("incarnation_id".into(), Value::String(incarnation.into())),
                    ("matched_line".into(), Value::String(matched_line.into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some(key.clone()),
        })?;
        self.store.record_runtime_failure(&attention_subject, &AttentionRequest {
                reviewer: "person/alex".into(),
                title: "Claude login expired".into(),
                reason: format!("{} on {} is unauthenticated. Run /login in its terminal, then restart this harness; work delivery is held until a new authenticated incarnation.", subject.subject, self.host),
                severity: "error".into(),
                targets: vec![subject.subject.clone()],
                actor: "agent/st3/reconciler".into(),
                idempotency_key: format!("{key}:attention"),
        }, "provider-auth")?;
        self.signal_changed();
        Ok(())
    }

    /// The login fence of one Claude incarnation: the claim that fences it, if it is fenced now,
    /// and the key of that fence, or of the next one. A fence lifted once can fence the same
    /// incarnation again, so a fence after a lift is keyed by that lift.
    fn claude_auth_fence(
        &self,
        subject: &str,
        incarnation: &str,
    ) -> Result<(Option<String>, String)> {
        let mut fence = None;
        let mut key = format!("claude-auth-expired:{subject}:{incarnation}");
        for claim in self.store.claims_for(subject, Some("harness.diagnostic"))? {
            if claim
                .body
                .pointer("/fields/incarnation_id")
                .and_then(Value::as_str)
                != Some(incarnation)
            {
                continue;
            }
            match claim.body.pointer("/fields/code").and_then(Value::as_str) {
                Some("provider-auth-expired") => fence = Some(claim.id),
                Some("provider-auth-restored") => {
                    fence = None;
                    key = format!("claude-auth-expired:{subject}:{incarnation}:{}", claim.id);
                }
                _ => {}
            }
        }
        Ok((fence, key))
    }

    /// Claude's workspace trust prompt appears before any hook or channel can report the session,
    /// so the terminal screen is the only evidence of it. The prompt fences the incarnation as not
    /// ready with its reason. Recovery stops that exact incarnation so its replacement's driver
    /// admits the workspace again; nobody types into the terminal. Repeated prompts go to a person.
    fn reconcile_claude_trust_screen(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        observation: &RuntimeObservation,
        now: u128,
    ) -> Result<()> {
        if subject.kind != "agent" || member.driver.as_deref() != Some("claude") || !member.terminal
        {
            return Ok(());
        }
        let Some(incarnation) = observation.incarnation_id.as_deref() else {
            return Ok(());
        };
        let mut prompts = self.claude_trust_prompts(&subject.subject)?;
        if !prompts
            .iter()
            .any(|claim| claim_incarnation(claim) == Some(incarnation))
        {
            // The prompt precedes readiness, and a ready session may be quoting it.
            if self
                .store
                .harness_was_ready(&subject.subject, incarnation)?
            {
                return Ok(());
            }
            let Some(runtime_claim) = self.running_runtime_claim(&subject.subject, incarnation)?
            else {
                return Ok(());
            };
            let Ok(screen) = self.member_screen(&member.runtime_id) else {
                return Ok(());
            };
            if !claude_trust_prompt(&screen) {
                let deadline = runtime_claim
                    .accepted_at_unix_ms
                    .saturating_add(HARNESS_READINESS_DEADLINE_MS);
                if now < deadline {
                    // One grid point per interval, so repeated passes share a single timer.
                    let next =
                        (now / CLAUDE_TRUST_SCREEN_RECHECK_MS + 1) * CLAUDE_TRUST_SCREEN_RECHECK_MS;
                    self.arm_restart(&format!("trust-screen:{}", subject.subject), next);
                }
                return Ok(());
            }
            prompts.push(self.store.append_claim(&ClaimInput {
                subject: subject.subject.clone(),
                kind: "harness.diagnostic".into(),
                actor: Some(subject.subject.clone()),
                fields: BTreeMap::from([
                    ("severity".into(), Value::String("error".into())),
                    ("status".into(), Value::String("blocked".into())),
                    ("code".into(), Value::String("provider-trust-prompt".into())),
                    ("reason".into(), Value::String("Claude is waiting at its workspace trust prompt and cannot accept work; st replaces this incarnation so its driver admits the workspace again".into())),
                    ("incarnation_id".into(), Value::String(incarnation.into())),
                ]),
                evidence: vec![runtime_claim.id],
                expected_subject: None,
                idempotency_key: Some(format!(
                    "claude-trust-prompt:{}:{incarnation}",
                    subject.subject
                )),
            })?);
            self.signal_changed();
        }
        let recent = prompts
            .iter()
            .filter(|claim| {
                now.saturating_sub(claim.accepted_at_unix_ms) < CLAUDE_TRUST_RECOVERY_WINDOW_MS
            })
            .count();
        if recent > CLAUDE_TRUST_RECOVERY_ATTEMPTS {
            let key = format!(
                "claude-trust-prompt-repeated:{}:{incarnation}",
                subject.subject
            );
            let digest = hex::encode(sha2::Sha256::digest(key.as_bytes()));
            let attention_subject = format!("attention/{}", &digest[..32]);
            if self
                .store
                .operational_failure(&attention_subject)?
                .is_none()
            {
                self.store.record_runtime_failure(
                    &attention_subject,
                    &AttentionRequest {
                        reviewer: "person/operator".into(),
                        title: "Claude keeps stopping at its workspace trust prompt".into(),
                        reason: format!(
                            "{} on {} reached Claude's workspace trust prompt {recent} times in {} minutes, so st stopped replacing it. Check that its driver can record the workspace trust in the Claude config, then restart the seat.",
                            subject.subject,
                            self.host,
                            CLAUDE_TRUST_RECOVERY_WINDOW_MS / 60_000
                        ),
                        severity: "error".into(),
                        targets: vec![subject.subject.clone()],
                        actor: "agent/st3/reconciler".into(),
                        idempotency_key: format!("{key}:requested"),
                    }, "provider-trust",
            )?;
                self.signal_changed();
            }
            return Ok(());
        }
        self.reconcile_runtime_stop(
            &subject.subject,
            &member.runtime_id,
            member.terminal,
            Some(incarnation),
            member.shutdown_timeout_ms,
            Some(observation),
        )?;
        Ok(())
    }

    /// Whether a trust-prompt recovery stopped this exited incarnation.
    fn claude_trust_recovery_stopped(
        &self,
        subject: &str,
        observation: &RuntimeObservation,
    ) -> Result<bool> {
        let Some(incarnation) = observation.incarnation_id.as_deref() else {
            return Ok(false);
        };
        if !self
            .claude_trust_prompts(subject)?
            .iter()
            .any(|claim| claim_incarnation(claim) == Some(incarnation))
        {
            return Ok(false);
        }
        Ok(self
            .store
            .observations_for(subject, "runtime.action.requested")?
            .iter()
            .any(|claim| {
                claim.body.pointer("/fields/action").and_then(Value::as_str) == Some("terminate")
                    && claim_incarnation(claim) == Some(incarnation)
            }))
    }

    fn claude_trust_prompts(&self, subject: &str) -> Result<Vec<crate::model::ClaimRecord>> {
        Ok(self
            .store
            .claims_for(subject, Some("harness.diagnostic"))?
            .into_iter()
            .filter(|claim| {
                claim.body.pointer("/fields/code").and_then(Value::as_str)
                    == Some("provider-trust-prompt")
            })
            .collect())
    }

    fn fresh_context_recovery_stopped(
        &self,
        subject: &str,
        observation: &RuntimeObservation,
    ) -> Result<bool> {
        let Some(incarnation) = observation.incarnation_id.as_deref() else {
            return Ok(false);
        };
        Ok(self
            .store
            .observations_for(subject, "runtime.action.requested")?
            .iter()
            .any(|claim| {
                claim.body.pointer("/fields/action").and_then(Value::as_str)
                    == Some("fresh-context")
                    && claim_incarnation(claim) == Some(incarnation)
            }))
    }

    fn running_runtime_claim(
        &self,
        subject: &str,
        incarnation: &str,
    ) -> Result<Option<crate::model::ClaimRecord>> {
        Ok(self
            .store
            .claims_for(subject, Some("runtime.observed"))?
            .into_iter()
            .rev()
            .find(|claim| {
                claim_incarnation(claim) == Some(incarnation)
                    && claim.body.pointer("/fields/status").and_then(Value::as_str)
                        == Some("running")
            }))
    }

    fn prepare_fresh_context(
        &self,
        agent: &str,
        incarnation: &str,
        step: &StepRunView,
        member: &MemberSpec,
    ) -> Result<bool> {
        if !step.fresh_context
            && member.tags.get("st3.fresh_context").map(String::as_str) != Some("true")
        {
            return Ok(true);
        }
        let operation = crate::model::fresh_context_operation(step);
        let matches_operation = |claim: &crate::model::ClaimRecord| {
            claim.body.pointer("/fields/action").and_then(Value::as_str) == Some("fresh-context")
                && claim
                    .body
                    .pointer("/fields/operation")
                    .and_then(Value::as_str)
                    == Some(operation.as_str())
        };
        if self
            .store
            .observations_for(agent, "runtime.action.succeeded")?
            .iter()
            .any(|claim| matches_operation(claim) && claim_incarnation(claim) == Some(incarnation))
        {
            return Ok(true);
        }
        let request = self
            .store
            .observations_for(agent, "runtime.action.requested")?
            .into_iter()
            .rev()
            .find(&matches_operation);
        if let Some(request) = request {
            if claim_incarnation(&request) != Some(incarnation) {
                self.store.append_claim(&ClaimInput {
                    subject: agent.into(),
                    kind: "runtime.action.succeeded".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("action".into(), Value::String("fresh-context".into())),
                        ("operation".into(), Value::String(operation.clone())),
                        ("incarnation_id".into(), Value::String(incarnation.into())),
                    ]),
                    evidence: vec![request.id],
                    expected_subject: None,
                    idempotency_key: Some(format!("{operation}:ready:{incarnation}")),
                })?;
                self.signal_changed();
                return Ok(true);
            }
        } else {
            self.store.append_claim(&ClaimInput {
                subject: agent.into(),
                kind: "runtime.action.requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("action".into(), Value::String("fresh-context".into())),
                    ("operation".into(), Value::String(operation.clone())),
                    (
                        "runtime_id".into(),
                        Value::String(member.runtime_id.clone()),
                    ),
                    ("incarnation_id".into(), Value::String(incarnation.into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some(format!("{operation}:request")),
            })?;
            self.signal_changed();
        }
        let observation = RuntimeObservation {
            runtime_id: member.runtime_id.clone(),
            terminal: member.terminal,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some(incarnation.into()),
        };
        self.reconcile_runtime_stop(
            agent,
            &member.runtime_id,
            member.terminal,
            Some(incarnation),
            member.shutdown_timeout_ms,
            Some(&observation),
        )?;
        Ok(false)
    }

    /// Evaluate one item of `section` (a running agent's work wakes, a subscription), or skip
    /// it when `skip` and nothing it read changed and nothing is due. A write by an item that was
    /// not marked is counted as an incremental correction.
    fn reconcile_item(
        &self,
        section: &'static str,
        item: &str,
        skip: bool,
        work: impl FnOnce() -> Result<()>,
    ) -> Result<()> {
        let needed = self.needs_item(item, !skip);
        if skip && !needed {
            return Ok(());
        }
        let cpu_started = crate::incremental::thread_cpu();
        let wrote_mark = smallclaims::touched::wrote_len();
        let ((result, due), reads) =
            smallclaims::touched::record(|| smallclaims::touched::record_due(|| caught(work)));
        crate::performance::record_evaluation(
            section,
            needed,
            crate::incremental::thread_cpu().saturating_sub(cpu_started),
        );
        if !needed {
            let wrote = smallclaims::touched::wrote_since(wrote_mark);
            if !wrote.is_empty() {
                self.incremental_correction(section, item, &reads, &wrote);
            }
        }
        // A failed delivery is tried again on the next pass, as before.
        if result.is_ok() {
            self.incremental.evaluated(item, reads, due);
        }
        result
    }

    fn reconcile_work_messages(
        &self,
        agent: &str,
        incarnation: &str,
        member: Option<&MemberSpec>,
    ) -> Result<()> {
        let incarnation_key = harness_incarnation_key(incarnation);
        // Closed work wakes still count as attempts. A closed wake can mean the
        // harness started a turn but could not claim this independent step yet;
        // forgetting it would replay attempt 1 and notify this reconciler forever.
        let messages = self.store.work_wake_messages_for_reconcile(agent)?;
        let work = self.store.work_for_reconcile(agent)?;
        let harness = self.store.current_harness(agent)?;
        let now = now_ms();
        for step in &work {
            if let Some(due) = crate::incremental::step_due(step, now) {
                smallclaims::touched::note_due(due);
            }
        }

        if !harness.as_ref().is_some_and(CurrentHarnessView::is_ready) {
            return Ok(());
        }

        let mut message_errors = Vec::new();
        for message in messages.iter().filter(|message| message.status != "closed") {
            // One message whose close fails does not keep the agent's other messages open or
            // hold back its next wake.
            let closed = (|| -> Result<()> {
                let Some((step_subject, attempt, readiness_epoch, message_incarnation)) =
                    work_message_target(message)
                else {
                    return Ok(());
                };
                let turn_acknowledged = work
                    .iter()
                    .find(|step| step.subject == step_subject)
                    .is_some_and(|step| {
                        message_sent_at(&self.store, message).is_some_and(|requested| {
                            harness.as_ref().is_some_and(|harness| {
                                step.status == "ready"
                                    && harness.state == "working"
                                    && harness.observed_at_unix_ms >= requested
                            })
                        })
                    });
                if !work_message_should_close(
                    &work,
                    step_subject,
                    attempt,
                    readiness_epoch,
                    message_incarnation,
                    &incarnation_key,
                    turn_acknowledged,
                ) {
                    return Ok(());
                }
                if message.status == "delivered" {
                    self.store.append_claim(&ClaimInput {
                        subject: message.subject.clone(),
                        kind: "message.read".into(),
                        actor: Some(agent.into()),
                        fields: BTreeMap::from([("status".into(), Value::String("read".into()))]),
                        evidence: Vec::new(),
                        expected_subject: None,
                        idempotency_key: Some(format!("work-message-read:{}", message.subject)),
                    })?;
                }
                if message.status == "sent" && turn_acknowledged {
                    return Ok(());
                }
                self.store.append_claim(&ClaimInput {
                    subject: message.subject.clone(),
                    kind: "message.closed".into(),
                    actor: Some(
                        if matches!(message.status.as_str(), "sent" | "staged") {
                            "daemon/runtime"
                        } else {
                            agent
                        }
                        .into(),
                    ),
                    fields: BTreeMap::from([("status".into(), Value::String("closed".into()))]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: Some(format!("message-close:{}", message.subject)),
                })?;
                self.signal_changed();
                Ok(())
            })();
            if let Err(error) = closed {
                message_errors.push(format!("{}: {error:#}", message.subject));
            }
        }

        let run_order = if seat_chooses_between_runs(agent, &work) {
            self.store.seat_run_order(agent)?
        } else {
            Vec::new()
        };
        let next_wake = next_work_wake_for_agent(agent, &work, &run_order);
        for step in work
            .iter()
            .filter(|step| Some(step.subject.as_str()) == next_wake)
        {
            if defers_inherited_work_wake(step, &work, harness.as_ref()) {
                continue;
            }
            if let Some(member) = member
                && !self.prepare_fresh_context(agent, incarnation, step, member)?
            {
                continue;
            }
            let tag_value = format!(
                "{}@{}@{}@{}",
                step.subject, step.attempt, step.readiness_epoch, incarnation_key
            );
            let mut attempts = messages
                .iter()
                .filter(|message| {
                    !message
                        .tags
                        .iter()
                        .any(|tag| tag == "st3-wake-source:manual")
                })
                .filter(|message| {
                    work_message_target(message).is_some_and(
                        |(subject, attempt, readiness_epoch, message_incarnation)| {
                            subject == step.subject
                                && attempt == step.attempt
                                && readiness_epoch == step.readiness_epoch
                                && message_incarnation == incarnation_key
                        },
                    )
                })
                .filter_map(|message| message_sent_at(&self.store, message).map(|at| (at, message)))
                .collect::<Vec<_>>();
            attempts.sort_by_key(|(at, _)| *at);
            let acknowledged = work_wake_acknowledged(&attempts, harness.as_ref());
            if acknowledged {
                continue;
            }
            let attempt_count = u32::try_from(attempts.len()).unwrap_or(u32::MAX);
            match work_wake_decision(
                attempt_count,
                attempts.last().map(|(last, _)| *last),
                attempts.first().map(|(first, _)| *first),
                acknowledged,
                now_ms(),
            ) {
                WorkWakeDecision::Request(wake_attempt) => {
                    append_work_wake_message(
                        &self.store,
                        step,
                        agent,
                        incarnation,
                        wake_attempt,
                        "automatic",
                        "daemon/runtime",
                        "ready assigned work",
                        format!("work-wake:{agent}:{tag_value}:{wake_attempt}"),
                    )?;
                    self.signal_changed();
                }
                WorkWakeDecision::Exhaust => {
                    let reason = format!(
                        "`{agent}` did not start a turn or claim `{}` after {attempt_count} supported driver wake attempts",
                        step.subject
                    );
                    let diagnostic_key =
                        format!("work-wake-exhausted:{agent}:{tag_value}:{attempt_count}");
                    if self.store.operation_claim(&diagnostic_key)?.is_none() {
                        let evidence = work_wake_attempt_evidence(&self.store, &attempts)?;
                        self.store.append_claim(&ClaimInput {
                            subject: agent.into(),
                            kind: "harness.diagnostic".into(),
                            actor: None,
                            fields: BTreeMap::from([
                                ("severity".into(), Value::String("error".into())),
                                ("status".into(), Value::String("failed".into())),
                                ("code".into(), Value::String("work-wake-exhausted".into())),
                                ("reason".into(), Value::String(reason)),
                                ("incarnation_id".into(), Value::String(incarnation.into())),
                                ("step_run".into(), Value::String(step.subject.clone())),
                                ("wake_attempts".into(), Value::from(attempt_count)),
                                ("attempt".into(), Value::from(step.attempt)),
                                ("readiness_epoch".into(), Value::from(step.readiness_epoch)),
                            ]),
                            evidence,
                            expected_subject: None,
                            idempotency_key: Some(diagnostic_key),
                        })?;
                        self.signal_changed();
                    }
                }
                WorkWakeDecision::Wait => {
                    // The next attempt, or the end of the grace before exhaustion.
                    let next = if attempt_count < WORK_WAKE_MAX_ATTEMPTS {
                        attempts
                            .last()
                            .map(|(last, _)| last.saturating_add(WORK_WAKE_RETRY_MS))
                    } else {
                        attempts
                            .first()
                            .map(|(first, _)| first.saturating_add(WORK_WAKE_EXHAUST_GRACE_MS))
                    };
                    if let Some(next) = next {
                        smallclaims::touched::note_due(next);
                    }
                }
            }
        }
        anyhow::ensure!(
            message_errors.is_empty(),
            "close work messages: {}",
            message_errors.join("; ")
        );
        Ok(())
    }

    /// The desired revision whose launch configuration is current. Launch records, restart
    /// budgets, and crash-loop parking key on it, so a label-only revision inherits them.
    fn launch_token(&self, subject: &str) -> Result<String> {
        Ok(self.store.launch_lineage(subject)?.pop().unwrap_or_default())
    }

    /// Whether the latest launch was for the selected declaration, or for a revision it only
    /// relabels. Older launches do not count: after A → B → A the seat runs A again.
    /// What a running seat's declaration changed about how it launches since its running
    /// incarnation started, when that matters: its host, workspace, harness, terminal, command,
    /// model or arguments. A seat st did not launch, or whose launch it no longer has, has
    /// nothing to compare and keeps running.
    fn declared_launch_changes(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        observation: &RuntimeObservation,
    ) -> Result<Option<Vec<&'static str>>> {
        if subject.kind != "agent" || member.lifecycle != MemberLifecycle::Service {
            return Ok(None);
        }
        let Some(incarnation) = observation.incarnation_id.as_deref() else {
            return Ok(None);
        };
        let mut launched = self
            .launched_members
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        let launched = match launched.get(&subject.subject) {
            Some((known, launched)) if known == incarnation => launched.clone(),
            _ => {
                // The latest start this node made launched the running incarnation; an adopted
                // runtime it did not start has none, or an older one it then outlived.
                let read = self
                    .store
                    .observations_for(&subject.subject, "runtime.action.succeeded")?
                    .iter()
                    .rev()
                    .find_map(|claim| {
                        claim
                            .body
                            .pointer("/fields/desired_token")
                            .and_then(Value::as_str)
                            .map(str::to_owned)
                    })
                    .map(|token| self.store.claim_by_id(&token))
                    .transpose()?
                    .flatten()
                    .and_then(|claim| serde_json::from_value::<DesiredSubject>(claim.body).ok())
                    .and_then(|desired| desired.member);
                launched.insert(
                    subject.subject.clone(),
                    (incarnation.to_owned(), read.clone()),
                );
                read
            }
        };
        Ok(launched
            .map(|launched| member.launch_changes(&launched))
            .filter(|changes| !changes.is_empty()))
    }

    fn member_was_launched_for_selected_desired(&self, subject: &str) -> Result<bool> {
        let lineage = self.store.launch_lineage(subject)?;
        Ok(self
            .store
            .observations_for(subject, "runtime.action.succeeded")?
            .iter()
            .rev()
            .find_map(|claim| {
                claim
                    .body
                    .pointer("/fields/desired_token")
                    .and_then(Value::as_str)
            })
            .is_some_and(|token| lineage.iter().any(|candidate| candidate == token)))
    }

    #[cfg(test)]
    fn reconcile_stop(
        &self,
        subject: &DesiredSubject,
        ptys: Option<&HashMap<String, RuntimeObservation>>,
    ) -> Result<()> {
        self.reconcile_stop_with_origin(subject, ptys, None)
    }

    /// Reconcile a stop. `actual_origin` is the subject's selected actual origin when the caller
    /// already read it in this pass.
    /// Run `work` with this thread recording the claims it writes, unless an enclosing pass
    /// already does, so a correction lists only what an item itself wrote.
    fn recording_writes<T>(&self, work: impl FnOnce() -> T) -> T {
        if smallclaims::touched::recording_wrote() {
            work()
        } else {
            smallclaims::touched::record_wrote(work).0
        }
    }

    /// Whether `item` needs evaluating. When it is evaluated anyway (`evaluated_anyway`: a full
    /// pass, or skipping off), the change feed is read again first: a write that landed after
    /// the pass read it, such as a request through the API, is what the evaluation acts on, not
    /// a change the skipping passes missed.
    fn needs_item(&self, item: &str, evaluated_anyway: bool) -> bool {
        if self.incremental.needs(item, now_ms()) {
            return true;
        }
        if !evaluated_anyway {
            return false;
        }
        let _ = self.incremental.observe(&self.store);
        self.incremental.needs(item, now_ms())
    }

    /// Gate runners, read again only when a request, a runner's stop, or an owner's state
    /// changed, and on each full pass. A full pass that finds the kept list stale although
    /// nothing marked it counts an incremental correction.
    fn gate_runners(&self) -> Result<Vec<crate::store::MissionGateRunner>> {
        const ITEM: &str = "gate-runners";
        let now = now_ms();
        let full = !self.skip_unneeded || self.incremental.take_full_pass(ITEM, now);
        let needed = self.needs_item(ITEM, full);
        let mut kept = self
            .gate_runners
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        if !full
            && !needed
            && let Some(kept) = kept.as_ref()
        {
            return Ok(kept.clone());
        }
        let (fresh, reads) = smallclaims::touched::record(|| self.store.mission_gate_runners());
        let fresh = fresh?;
        if !needed && kept.as_ref().is_some_and(|kept| *kept != fresh) {
            self.incremental_correction(ITEM, ITEM, &reads, &["a changed runner list".into()]);
        }
        self.incremental.evaluated(ITEM, reads, None);
        *kept = Some(fresh.clone());
        Ok(fresh)
    }

    /// Evaluate one stop this host owns, or skip it when `skip` and nothing it read changed and
    /// its time has not come. As with mission runs, an evaluation that writes a claim although its
    /// stop was not marked is counted as an incremental correction.
    fn reconcile_stop_item(
        &self,
        subject: &DesiredSubject,
        item: &str,
        skip: bool,
        ptys: Option<&HashMap<String, RuntimeObservation>>,
        live_workspaces: &BTreeSet<&str>,
        diagnostic_errors: &mut Vec<String>,
    ) {
        let needed = self.needs_item(item, !skip);
        if skip && !needed {
            return;
        }
        let cpu_started = crate::incremental::thread_cpu();
        let wrote_mark = smallclaims::touched::wrote_len();
        let ((outcome, due), reads) = smallclaims::touched::record(|| {
            smallclaims::touched::record_due(|| -> Result<Option<Result<()>>> {
                // A stop's actual origin is read once here and reused by `reconcile_stop`.
                let (owner, actual_origin) = match &subject.member {
                    Some(member) => (Some(member.host.clone()), None),
                    None => {
                        let origin = self.store.selected_actual_origin(&subject.subject)?;
                        let owner = match origin.clone() {
                            Some(origin) => Some(origin),
                            None => self.store.selected_desired_origin(&subject.subject)?,
                        };
                        (owner, Some(origin))
                    }
                };
                if owner.as_deref() != Some(self.host.as_str()) {
                    return Ok(None);
                }
                Ok(Some(caught(|| -> Result<()> {
                    self.reconcile_stop_with_origin(subject, ptys, actual_origin)?;
                    self.remove_checkout_after_run(subject, live_workspaces)
                })))
            })
        });
        crate::performance::record_evaluation(
            "stop",
            needed,
            crate::incremental::thread_cpu().saturating_sub(cpu_started),
        );
        if !needed {
            let wrote = smallclaims::touched::wrote_since(wrote_mark);
            if !wrote.is_empty() {
                self.incremental_correction("stop", item, &reads, &wrote);
            }
        }
        match outcome {
            Err(error) => diagnostic_errors.push(format!(
                "{}: determine member owner: {error:#}",
                subject.subject
            )),
            Ok(None) => self.incremental.evaluated(item, reads, due),
            Ok(Some(result)) => {
                // A failed stop is tried again on the next pass, as before.
                if result.is_ok() {
                    self.incremental.evaluated(item, reads, due);
                }
                if let Err(error) = self.record_member_reconcile_result(&subject.subject, result) {
                    diagnostic_errors.push(format!("{}: {error:#}", subject.subject));
                }
            }
        }
    }

    fn reconcile_stop_with_origin(
        &self,
        subject: &DesiredSubject,
        ptys: Option<&HashMap<String, RuntimeObservation>>,
        actual_origin: Option<Option<String>>,
    ) -> Result<()> {
        self.store.owned_desired_guard(subject)?;
        let Some(actual) = self.store.latest_actual_value(&subject.subject)? else {
            // A stop-only declaration with no observed runtime is already satisfied.
            // Only its declaring host may project that fact. Otherwise every peer
            // creates a concurrent runtime observation for the same subject.
            if subject.kind == "stop"
                && subject.member.is_none()
                && self
                    .store
                    .selected_desired_origin(&subject.subject)?
                    .as_deref()
                    == Some(self.host.as_str())
            {
                self.record_once(
                    &subject.subject,
                    "runtime.observed",
                    BTreeMap::from([
                        ("status".into(), Value::String("absent".into())),
                        ("reachability".into(), Value::String("reachable".into())),
                    ]),
                )?;
            }
            return Ok(());
        };
        let fields = actual.get("fields").unwrap_or(&actual);
        let selected_origin = match actual_origin {
            Some(origin) => origin,
            None => self.store.selected_actual_origin(&subject.subject)?,
        };
        let owner_host = subject
            .member
            .as_ref()
            .map(|member| member.host.as_str())
            .or_else(|| fields.get("host").and_then(Value::as_str))
            .or(selected_origin.as_deref());
        if owner_host != Some(self.host.as_str()) {
            // A stop intent is fleet-visible, but only the runtime's owner can
            // observe or terminate its process. A remote empty PTY snapshot is
            // not evidence that the owner's process stopped.
            return Ok(());
        }
        let Some(runtime_id) = fields.get("runtime_id").and_then(Value::as_str) else {
            return Ok(());
        };
        let terminal = fields
            .get("terminal")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        let observation = if terminal {
            smallclaims::touched::note_read(|| format!("pty:{runtime_id}"));
            // Without a snapshot the PTY may still run, so the stop waits for the next one.
            let Some(ptys) = ptys else {
                return Ok(());
            };
            ptys.get(runtime_id).cloned()
        } else {
            smallclaims::touched::note_read(|| format!("exec:{runtime_id}"));
            self.runtime.observe_exec(runtime_id)?
        };
        if self.reconcile_rollout(subject, observation.as_ref(), None)? {
            return Ok(());
        }
        // A stopped projection is only a record of the last observation. The same
        // runtime ID can be live again (or a stop can have raced with a restart),
        // so fence the observed process before allowing run cleanup to finish.
        if let Some(observation) = observation.as_ref().filter(|item| item.status == "running") {
            let mut observed_fields = BTreeMap::from([
                ("status".into(), Value::String("running".into())),
                ("runtime_id".into(), Value::String(runtime_id.into())),
                ("terminal".into(), Value::Bool(terminal)),
                ("reachability".into(), Value::String("reachable".into())),
            ]);
            if let Some(incarnation) = &observation.incarnation_id {
                observed_fields.insert("incarnation_id".into(), Value::String(incarnation.clone()));
            }
            if let Some(timeout) = fields.get("shutdown_timeout_ms") {
                observed_fields.insert("shutdown_timeout_ms".into(), timeout.clone());
            }
            self.record_once(&subject.subject, "runtime.observed", observed_fields)?;
        }
        // A run's end never stops a seat that still has someone's mail or another run's work.
        if observation
            .as_ref()
            .is_some_and(|item| item.status == "running")
            && let Some(run) = subject.owner_run.as_deref()
            && let Some(reason) = self.seat_retention(&subject.subject, run)?
        {
            self.record_once(
                &subject.subject,
                "harness.diagnostic",
                BTreeMap::from([
                    ("severity".into(), Value::String("warning".into())),
                    ("status".into(), Value::String("waiting".into())),
                    ("code".into(), Value::String("stop-deferred".into())),
                    ("reason".into(), Value::String(reason)),
                ]),
            )?;
            return Ok(());
        }
        let incarnation = observation
            .as_ref()
            .and_then(|value| value.incarnation_id.as_deref())
            .or_else(|| fields.get("incarnation_id").and_then(Value::as_str));
        let timeout = fields
            .get("shutdown_timeout_ms")
            .and_then(Value::as_u64)
            .unwrap_or(5_000);
        self.reconcile_runtime_stop(
            &subject.subject,
            runtime_id,
            terminal,
            incarnation,
            timeout,
            observation.as_ref(),
        )?;
        Ok(())
    }

    fn observe_agent_workspace(&self, subject: &str, member: &MemberSpec) -> Result<()> {
        let mut fields = BTreeMap::from([
            ("host".into(), Value::String(self.host.clone())),
            ("workspace".into(), Value::String(member.workspace.clone())),
        ]);
        if let Some(repository) =
            crate::repositories::workspace_repository(Path::new(&member.workspace))
        {
            fields.insert(
                "repository".into(),
                Value::String(repository.display().to_string()),
            );
        }
        self.record_once(subject, "workspace.observed", fields)
    }

    /// Create a declared checkout before its agent starts. Returns why the workspace is still
    /// unavailable. After a failure, Git runs again only after `CHECKOUT_RETRY_MS`.
    fn create_checkout(
        &self,
        subject: &str,
        checkout: &Checkout,
        workspace: &Path,
    ) -> Result<Option<String>> {
        let declaration = self.store.newest_claim_index(subject, "intent.desired")?;
        {
            let mut conflicts = self
                .checkout_conflicts
                .lock()
                .unwrap_or_else(PoisonError::into_inner);
            if let Some((revision, prior, path, failure)) = conflicts.get(subject) {
                if *revision == declaration && prior == checkout && path == workspace {
                    return Ok(Some(failure.clone()));
                }
                conflicts.remove(subject);
                self.checkout_retries
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .remove(subject);
            }
        }
        let now = now_ms();
        if let Some((_, failure)) = self
            .checkout_retries
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .get(subject)
            .filter(|(retry_at, _)| *retry_at > now)
        {
            return Ok(Some(failure.clone()));
        }
        match checkout.create(workspace) {
            Ok(warnings) => {
                self.checkout_retries
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .remove(subject);
                for warning in warnings {
                    self.record_once(
                        subject,
                        "harness.diagnostic",
                        BTreeMap::from([
                            ("severity".into(), Value::String("warning".into())),
                            ("status".into(), Value::String("warning".into())),
                            ("code".into(), Value::String("checkout-fetch-failed".into())),
                            ("reason".into(), Value::String(warning)),
                        ]),
                    )?;
                }
                Ok(None)
            }
            Err(error) => {
                let failure = format!(
                    "checkout of {} failed: {error:#}",
                    checkout.repository.display()
                );
                if error
                    .downcast_ref::<crate::checkout::BranchInUse>()
                    .is_some()
                {
                    self.checkout_conflicts
                        .lock()
                        .unwrap_or_else(PoisonError::into_inner)
                        .insert(
                            subject.into(),
                            (
                                declaration,
                                checkout.clone(),
                                workspace.to_path_buf(),
                                failure.clone(),
                            ),
                        );
                    return Ok(Some(failure));
                }
                let retry_at = now.saturating_add(CHECKOUT_RETRY_MS);
                self.checkout_retries
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .insert(subject.into(), (retry_at, failure.clone()));
                self.arm_restart(&format!("checkout:{subject}"), retry_at);
                Ok(Some(failure))
            }
        }
    }

    /// Remove a finished run's checkout once its runtime has stopped, when the agent asked for
    /// `remove-at-run-end`.
    fn remove_checkout_after_run(
        &self,
        subject: &DesiredSubject,
        live_workspaces: &BTreeSet<&str>,
    ) -> Result<()> {
        let Some((checkout, workspace)) = self.finished_run_checkout(subject)? else {
            return Ok(());
        };
        smallclaims::touched::note_read(|| "live-workspaces".to_owned());
        self.remove_finished_checkout(
            &subject.subject,
            &checkout,
            Path::new(&workspace),
            live_workspaces,
        )
    }

    /// The checkout and workspace of an explicitly stopped top-level seat or a stopped mission
    /// agent whose run has ended. The checkout comes from the last agent declaration.
    fn finished_run_checkout(
        &self,
        subject: &DesiredSubject,
    ) -> Result<Option<(Checkout, String)>> {
        let Some((checkout, workspace)) = self.declared_run_end_checkout(&subject.subject)? else {
            return Ok(None);
        };
        // A run stops its owned agents in its cleanup phase, before it becomes terminal.
        let run_ended = match subject.owner_run.as_deref() {
            None => subject.kind == "stop",
            Some(run) => self.store.mission_run(run)?.is_some_and(|run| {
                matches!(run.status.as_str(), "completed" | "failed" | "cancelled")
                    || run.phase == "terminal"
                    || run.phase.starts_with("cleanup-")
            }),
        };
        let stopped = self
            .store
            .latest_actual_value(&subject.subject)?
            .is_some_and(|actual| {
                matches!(
                    actual_field(&actual, "status").and_then(Value::as_str),
                    Some("stopped" | "absent")
                )
            });
        Ok((run_ended && stopped).then_some((checkout, workspace)))
    }

    /// The run-end checkout and workspace of the subject's last agent declaration for this host.
    /// Every stop subject asks on every pass. Declarations are append-only claims, so the parsed
    /// answer holds until another `intent.desired` claim arrives for the subject.
    fn declared_run_end_checkout(&self, subject: &str) -> Result<Option<(Checkout, String)>> {
        let newest = self.store.newest_claim_index(subject, "intent.desired")?;
        if let Some((index, declared)) = self
            .declared_checkouts
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .get(subject)
            && *index == newest
        {
            return Ok(declared.clone());
        }
        #[cfg(test)]
        DECLARATION_PARSES.with(|parses| parses.set(parses.get() + 1));
        let declared = self
            .store
            .claims_for(subject, Some("intent.desired"))?
            .into_iter()
            .rev()
            .find(|claim| claim.body.get("kind").and_then(Value::as_str) == Some("agent"))
            .and_then(|declaration| {
                let checkout = declaration
                    .body
                    .get("desired")
                    .and_then(Checkout::from_desired)
                    .filter(|checkout| checkout.remove_at_run_end)?;
                let member = declaration
                    .body
                    .get("member")
                    .and_then(|member| serde_json::from_value::<MemberSpec>(member.clone()).ok())
                    .filter(|member| member.host == self.host)?;
                Some((checkout, member.workspace))
            });
        let mut declared_checkouts = self
            .declared_checkouts
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        if declared_checkouts.len() >= DECLARED_CHECKOUT_LIMIT
            && !declared_checkouts.contains_key(subject)
        {
            declared_checkouts.clear();
        }
        declared_checkouts.insert(subject.to_owned(), (newest, declared.clone()));
        Ok(declared)
    }

    /// Remove a finished checkout unless a current member uses its workspace. A worktree with
    /// changes stays, with one warning, and is tried again after `CHECKOUT_RETRY_MS`.
    fn remove_finished_checkout(
        &self,
        subject: &str,
        checkout: &Checkout,
        workspace: &Path,
        live_workspaces: &BTreeSet<&str>,
    ) -> Result<()> {
        if live_workspaces.contains(workspace.to_string_lossy().as_ref()) || !workspace.exists() {
            return Ok(());
        }
        let now = now_ms();
        if let Some((retry_at, _)) = self
            .checkout_retries
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .get(subject)
            .filter(|(retry_at, _)| *retry_at > now)
        {
            smallclaims::touched::note_due(*retry_at);
            return Ok(());
        }
        if let Err(error) = checkout.remove(workspace) {
            smallclaims::touched::note_due(now.saturating_add(CHECKOUT_RETRY_MS));
            let reason = format!("kept worktree {}: {error:#}", workspace.display());
            self.checkout_retries
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .insert(
                    subject.into(),
                    (now.saturating_add(CHECKOUT_RETRY_MS), reason.clone()),
                );
            self.record_once(
                subject,
                "harness.diagnostic",
                BTreeMap::from([
                    ("severity".into(), Value::String("warning".into())),
                    ("status".into(), Value::String("warning".into())),
                    ("code".into(), Value::String("checkout-kept".into())),
                    ("reason".into(), Value::String(reason)),
                ]),
            )?;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn reconcile_runtime_stop(
        &self,
        subject: &str,
        runtime_id: &str,
        terminal: bool,
        incarnation: Option<&str>,
        timeout_ms: u64,
        observation: Option<&RuntimeObservation>,
    ) -> Result<bool> {
        // A runtime whose state could not be read may still run. Wait for a readable observation.
        if observation.is_some_and(|observation| observation.status == "unknown") {
            return Ok(false);
        }
        if observation.is_none_or(|observation| observation.status != "running") {
            // A harness that ended before the stop, or a stop that could not finish, can leave
            // processes in the runtime's work scope. They end with it.
            self.runtime.end_leftovers(runtime_id, terminal);
            self.record_once(
                subject,
                "runtime.observed",
                BTreeMap::from([
                    ("status".into(), Value::String("stopped".into())),
                    ("runtime_id".into(), Value::String(runtime_id.into())),
                    ("terminal".into(), Value::Bool(terminal)),
                    ("reachability".into(), Value::String("reachable".into())),
                    ("reason".into(), Value::Null),
                ]),
            )?;
            return Ok(true);
        }
        let incarnation = incarnation.unwrap_or("unknown");
        let requests = self
            .store
            .observations_for(subject, "runtime.action.requested")?;
        let request = requests.into_iter().rev().find(|claim| {
            claim.body.pointer("/fields/action").and_then(Value::as_str) == Some("terminate")
                && claim
                    .body
                    .pointer("/fields/incarnation_id")
                    .and_then(Value::as_str)
                    == Some(incarnation)
        });
        let Some(request) = request else {
            let deadline = now_ms().saturating_add(timeout_ms as u128);
            let request = self.store.append_claim(&ClaimInput {
                subject: subject.into(),
                kind: "runtime.action.requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("action".into(), Value::String("terminate".into())),
                    ("runtime_id".into(), Value::String(runtime_id.into())),
                    ("terminal".into(), Value::Bool(terminal)),
                    ("incarnation_id".into(), Value::String(incarnation.into())),
                    (
                        "deadline_unix_ms".into(),
                        Value::String(deadline.to_string()),
                    ),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some(format!("terminate:{subject}:{incarnation}")),
            })?;
            if let Err(error) = self.runtime.stop(runtime_id, terminal, Some(incarnation)) {
                self.store.append_claim(&ClaimInput {
                    subject: subject.into(),
                    kind: "runtime.action.failed".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("action".into(), Value::String("terminate".into())),
                        ("reason".into(), Value::String(error.to_string())),
                    ]),
                    evidence: vec![request.id],
                    expected_subject: None,
                    idempotency_key: Some(format!("terminate-failed:{subject}:{incarnation}")),
                })?;
                return Err(error);
            }
            self.arm_restart(&format!("stop:{subject}"), now_ms().saturating_add(100));
            return Ok(false);
        };
        let deadline = request
            .body
            .pointer("/fields/deadline_unix_ms")
            .and_then(Value::as_str)
            .and_then(|value| value.parse::<u128>().ok())
            .unwrap_or(
                request
                    .accepted_at_unix_ms
                    .saturating_add(timeout_ms as u128),
            );
        if now_ms() < deadline {
            self.arm_restart(&format!("stop:{subject}"), deadline);
            return Ok(false);
        }
        let deadline_key = format!("stop-deadline:{subject}:{incarnation}");
        let deadline_record = self.store.append_claim(&ClaimInput {
            subject: subject.into(),
            kind: "runtime.action.deadline-reached".into(),
            actor: None,
            fields: BTreeMap::from([
                ("action".into(), Value::String("terminate".into())),
                ("incarnation_id".into(), Value::String(incarnation.into())),
            ]),
            evidence: vec![request.id],
            expected_subject: None,
            idempotency_key: Some(deadline_key.clone()),
        })?;
        if self
            .store
            .observations_for(subject, "runtime.action.succeeded")?
            .iter()
            .any(|claim| {
                claim
                    .body
                    .pointer("/fields/deadline_key")
                    .and_then(Value::as_str)
                    == Some(deadline_key.as_str())
            })
        {
            self.record_once(
                subject,
                "runtime.reconcile-decision",
                BTreeMap::from([
                    ("decision".into(), Value::String("raise".into())),
                    ("reachability".into(), Value::String("unreachable".into())),
                    (
                        "reason".into(),
                        Value::String("the recorded incarnation survived SIGKILL".into()),
                    ),
                ]),
            )?;
            return Ok(false);
        }
        self.runtime.kill(runtime_id, terminal, Some(incarnation))?;
        self.store.append_claim(&ClaimInput {
            subject: subject.into(),
            kind: "runtime.action.succeeded".into(),
            actor: None,
            fields: BTreeMap::from([
                ("action".into(), Value::String("kill".into())),
                ("deadline_key".into(), Value::String(deadline_key)),
                ("incarnation_id".into(), Value::String(incarnation.into())),
            ]),
            evidence: vec![deadline_record.id],
            expected_subject: None,
            idempotency_key: Some(format!("kill:{subject}:{incarnation}")),
        })?;
        self.arm_restart(&format!("stop:{subject}"), now_ms().saturating_add(100));
        Ok(false)
    }

    fn perform_start(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        reason: &str,
    ) -> Result<()> {
        self.store.owned_desired_guard(subject)?;
        // A member whose start keeps failing waits between attempts and then parks with one
        // attention request, instead of spawning again on every pass. A gate runner fails its gate.
        if matches!(subject.kind.as_str(), "agent" | "exec" | "pty")
            && member.driver.as_deref() != Some("codex")
            && self.defer_or_park_failed_start(subject)?
        {
            return Ok(());
        }
        if member.driver.as_deref() == Some("codex") {
            let token = self.launch_token(&subject.subject)?;
            if self.codex_crash_loop_raised(&subject.subject, &token)? {
                self.raise_codex_crash_loop(
                    &subject.subject,
                    &token,
                    "the prior Codex crash loop remains stopped",
                )?;
                return Ok(());
            }
            let recent_failures = self
                .store
                .observations_for(&subject.subject, "runtime.action.failed")?
                .into_iter()
                .filter(|claim| {
                    claim.body.pointer("/fields/action").and_then(Value::as_str) == Some("start")
                        && claim
                            .body
                            .pointer("/fields/desired_token")
                            .and_then(Value::as_str)
                            == Some(token.as_str())
                        && now_ms().saturating_sub(claim.accepted_at_unix_ms)
                            < CODEX_CRASH_LOOP_INTERVAL_MS
                })
                .collect::<Vec<_>>();
            if recent_failures.len() >= CODEX_CRASH_LOOP_ATTEMPTS {
                let detail = recent_failures
                    .last()
                    .and_then(|claim| claim.body.pointer("/fields/reason"))
                    .and_then(Value::as_str)
                    .unwrap_or("the runtime start failed");
                self.raise_codex_crash_loop(
                    &subject.subject,
                    &token,
                    &format!("Codex failed to launch three times: {detail}"),
                )?;
                return Ok(());
            }
        }
        let workspace = Path::new(&member.workspace);
        if workspace.exists() {
            anyhow::ensure!(
                workspace.is_dir(),
                "workspace {} is not a directory",
                workspace.display()
            );
        } else if member.workspace_create {
            std::fs::create_dir_all(workspace)
                .with_context(|| format!("create workspace {}", workspace.display()))?;
        } else {
            anyhow::bail!(
                "workspace {} does not exist; add create=#true to its workspace declaration to create it",
                workspace.display()
            );
        }
        let mut launch_member = member.clone();
        for (key, value) in &self.runtime_environment {
            launch_member
                .environment
                .entry(key.clone())
                .or_insert_with(|| value.clone());
        }
        self.bind_account(subject, member, &mut launch_member)?;
        if let Some(id) = member.environment.get(crate::rollout::OPERATION_ENV) {
            let operation = self.store.rollout(&subject.subject)?.context("rollout disappeared before account selection")?;
            anyhow::ensure!(operation.id == *id && operation.native_account.as_deref() == launch_member.environment.get("ST3_ACCOUNT").map(String::as_str),
                "strict rollout cannot carry a conversation between native login accounts");
        }
        for variable in [
            crate::rollout::OPERATION_ENV,
            crate::rollout::PREDECESSOR_ENV,
            crate::rollout::RESUME_PATH_ENV,
        ] {
            if !member.environment.contains_key(variable) {
                launch_member.environment.remove(variable);
            }
        }
        // Only a resume names a native session. A daemon started inside a resumed seat inherits
        // that seat's, and must not hand it to every seat it launches.
        if !member
            .environment
            .contains_key(crate::suspension::RESUME_ENV)
        {
            launch_member
                .environment
                .remove(crate::suspension::RESUME_ENV);
        }
        // Every other relaunch of a seat continues the native session its harness last bound,
        // so a restart, a hangup or a changed declaration never loses the conversation.
        launch_member
            .environment
            .remove(crate::suspension::CONTINUE_ENV);
        launch_member
            .environment
            .remove(crate::suspension::CONTINUE_PATH_ENV);
        let continued = if subject.kind == "agent"
            && !member
                .environment
                .contains_key(crate::suspension::RESUME_ENV)
            && let Some(harness) = member.driver.as_deref()
        {
            crate::suspension::continue_session(
                &self.store,
                &subject.subject,
                harness,
                launch_member.environment.get("ST3_ACCOUNT").map(String::as_str),
            )?
        } else {
            None
        };
        if let Some((session, path)) = continued {
            launch_member
                .environment
                .insert(crate::suspension::CONTINUE_ENV.into(), session);
            if let Some(path) = path {
                launch_member
                    .environment
                    .insert(crate::suspension::CONTINUE_PATH_ENV.into(), path);
            }
        }
        launch_member
            .environment
            .insert("ST3_ENDPOINT".into(), self.endpoint.clone());
        launch_member.environment.insert(
            "ST3_DRIVER_STATE_DIR".into(),
            self.driver_state_dir.to_string_lossy().into_owned(),
        );
        launch_member
            .environment
            .insert("ST3_SUBJECT".into(), subject.subject.clone());
        if subject.kind == "agent" {
            launch_member
                .environment
                .insert("ST_AGENT".into(), subject.subject.clone());
            launch_member
                .environment
                .insert("ST3_MAILBOX_TRANSPORT".into(), "push".into());
        } else if let Some(owner) = member.tags.get("st3.agent") {
            launch_member
                .environment
                .insert("ST_AGENT".into(), owner.clone());
        } else {
            launch_member.environment.remove("ST_AGENT");
        }
        let executable = launch_executable()?;
        let st_binary = self.st_binary.as_ref().unwrap_or(&executable);
        launch_member
            .environment
            .insert("ST3_BIN".into(), st_binary.to_string_lossy().into_owned());
        if let crate::model::LaunchSpec::Argv(argv) = &mut launch_member.launch
            && argv.first().map(String::as_str) == Some("st3")
        {
            argv[0] = executable.to_string_lossy().into_owned();
        }
        if !launch_member.terminal {
            let original = match &launch_member.launch {
                crate::model::LaunchSpec::Shell(source) => {
                    vec!["sh".into(), "-c".into(), source.clone()]
                }
                crate::model::LaunchSpec::Argv(argv) => argv.clone(),
            };
            let mut wrapper = vec![
                executable.to_string_lossy().into_owned(),
                "driver".into(),
                "exec".into(),
                "--subject".into(),
                subject.subject.clone(),
                "--".into(),
            ];
            wrapper.extend(original);
            launch_member.launch = crate::model::LaunchSpec::Argv(wrapper);
        }
        let operation = format!("{}:start", subject.subject);
        self.record_once(
            &subject.subject,
            "runtime.action.requested",
            BTreeMap::from([
                ("action".into(), Value::String("start".into())),
                ("operation".into(), Value::String(operation.clone())),
            ]),
        )?;
        self.store.owned_desired_guard(subject)?;
        if let Some(operation) = member.environment.get(crate::rollout::OPERATION_ENV) {
            anyhow::ensure!(
                self.store
                    .rollout(&subject.subject)?
                    .is_some_and(|o| o.id == *operation && o.phase == "starting"),
                "rollout target or policy changed before start"
            );
        }
        // Capture the token before starting; a publication during start must not relabel the launch.
        let desired_token = self.launch_token(&subject.subject)?;
        let guard = || -> Result<()> {
            self.store.owned_desired_guard(subject)?;
            if let Some(operation) = member.environment.get(crate::rollout::OPERATION_ENV) {
                anyhow::ensure!(
                    self.store
                        .rollout(&subject.subject)?
                        .is_some_and(|o| o.id == *operation && o.phase == "starting"),
                    "rollout target or policy changed at spawn boundary"
                );
            }
            Ok(())
        };
        if let Err(error) = self.runtime.start_guarded(&launch_member, &guard) {
            let reason = error.to_string();
            let prior_failures = self.start_failures(&subject.subject, &desired_token)?;
            self.store.append_claim(&ClaimInput {
                subject: subject.subject.clone(),
                kind: "runtime.action.failed".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("action".into(), Value::String("start".into())),
                    ("operation".into(), Value::String(operation)),
                    ("reason".into(), Value::String(reason)),
                    ("desired_token".into(), Value::String(desired_token.clone())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some(format!(
                    "start-failed:{}:{desired_token}:{}",
                    subject.subject,
                    prior_failures.len() + 1
                )),
            })?;
            self.record_once(
                &subject.subject,
                "runtime.observed",
                member_fields(member, "absent", None, false),
            )?;
            return Err(error).context("start member runtime");
        }
        let incarnation = if member.terminal {
            self.runtime.snapshot_ptys().ok().and_then(|items| {
                items.into_iter().find(|item| item.runtime_id == member.runtime_id)
            })
        } else {
            self.runtime.observe_exec(&member.runtime_id).ok().flatten()
        }
        .and_then(|item| item.incarnation_id);
        let mut fields = BTreeMap::from([
            ("action".into(), Value::String("start".into())),
            ("desired_token".into(), Value::String(desired_token)),
            ("runtime_id".into(), Value::String(member.runtime_id.clone())),
            ("reason".into(), Value::String(reason.into())),
        ]);
        if let Some(operation) = member.environment.get(crate::rollout::OPERATION_ENV) {
            fields.insert("rollout_operation".into(), serde_json::json!(operation));
        }
        if let Some(incarnation) = incarnation {
            fields.insert("incarnation_id".into(), Value::String(incarnation));
        }
        self.store.append_claim(&ClaimInput {
            subject: subject.subject.clone(),
            kind: "runtime.action.succeeded".into(),
            actor: None,
            fields,
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: None,
        })?;
        self.record_once(
            &subject.subject,
            "runtime.observed",
            member_fields(member, "starting", None, false),
        )?;
        self.record_once(
            &subject.subject,
            "runtime.action.succeeded",
            BTreeMap::from([
                ("reason".into(), Value::String(reason.into())),
                (
                    "runtime_id".into(),
                    Value::String(member.runtime_id.clone()),
                ),
            ]),
        )?;
        self.signal_changed();
        Ok(())
    }

    /// Point a seat whose harness block binds an account (or a pool) at that account's login
    /// directory, and name the account so the seat's usage and limits are read against it. A seat
    /// with no binding keeps the harness's default login: nothing here touches its environment.
    fn bind_account(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        launch: &mut MemberSpec,
    ) -> Result<()> {
        launch.environment.remove("ST3_ACCOUNT");
        if subject.kind != "agent" {
            return Ok(());
        }
        let Some(binding) = crate::accounts::harness_binding(&subject.desired) else {
            return Ok(());
        };
        let variable = crate::accounts::login_environment_name(&binding.driver)
            .context("an account binding needs a harness with a login directory")?;
        let seat = self
            .store
            .account_for_start(&subject.subject, &binding, &member.host, now_ms())
            .map_err(|reason| anyhow::anyhow!("{}: {reason}", subject.subject))?;
        let home = std::env::var_os("HOME").map(PathBuf::from);
        let directory =
            crate::accounts::expand_login(&seat.login, home.as_deref()).with_context(|| {
                format!(
                    "account `{}` login `{}` needs HOME",
                    seat.account.name, seat.login
                )
            })?;
        anyhow::ensure!(
            directory.is_dir(),
            "account `{}` has no login directory at {}; sign in there first with {variable}={} {}",
            seat.account.name,
            directory.display(),
            directory.display(),
            binding.driver,
        );
        launch
            .environment
            .insert(variable.into(), directory.to_string_lossy().into_owned());
        launch
            .environment
            .insert("ST3_ACCOUNT".into(), seat.account.name);
        Ok(())
    }

    /// Record one phase of a suspend or resume as its requester, so it replicates.
    fn record_suspension_phase(
        &self,
        subject: &str,
        suspension: &crate::suspension::Suspension,
        kind: &str,
        key: String,
        mut fields: BTreeMap<String, Value>,
    ) -> Result<()> {
        fields.insert("action".into(), Value::String(suspension.action.clone()));
        self.store.append_claim(&ClaimInput {
            subject: subject.into(),
            kind: kind.into(),
            actor: suspension.requested_by.clone(),
            fields,
            evidence: vec![suspension.operation_id.clone()],
            expected_subject: None,
            idempotency_key: Some(key),
        })?;
        self.signal_changed();
        Ok(())
    }

    fn fail_suspension(
        &self,
        subject: &str,
        suspension: &crate::suspension::Suspension,
        code: &str,
        reason: String,
        blocking: Vec<String>,
    ) -> Result<()> {
        let key = if suspension.action == "suspend" {
            crate::suspension::suspend_failed_key(&suspension.operation_id)
        } else {
            crate::suspension::resume_failed_key(&suspension.operation_id)
        };
        self.record_suspension_phase(
            subject,
            suspension,
            "runtime.action.failed",
            key,
            BTreeMap::from([
                ("code".into(), Value::String(code.into())),
                ("reason".into(), Value::String(reason)),
                (
                    "blocking".into(),
                    Value::Array(blocking.into_iter().map(Value::String).collect()),
                ),
            ]),
        )
    }

    /// Drive a seat's suspend or resume one step. A suspended seat has no process, and nothing
    /// but its resume starts one: not its restart policy, not a restart request.
    fn reconcile_suspension(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        observation: Option<&RuntimeObservation>,
        blocked: Option<anyhow::Error>,
        suspension: &crate::suspension::Suspension,
    ) -> Result<()> {
        use crate::suspension as suspended;
        let agent = subject.subject.as_str();
        let status = observation.map(|item| item.status.as_str());
        let running = observation.filter(|item| item.status == "running");
        let ended = matches!(status, None | Some("exited" | "vanished" | "stopped"));
        let stop = |observation: &RuntimeObservation| {
            self.reconcile_runtime_stop(
                agent,
                &member.runtime_id,
                member.terminal,
                observation.incarnation_id.as_deref(),
                member.shutdown_timeout_ms,
                Some(observation),
            )
        };
        match suspension.phase.as_str() {
            "quiescing" => {
                let Some(observation) = running.filter(|item| {
                    item.incarnation_id.is_some()
                        && item.incarnation_id == suspension.incarnation_id
                }) else {
                    if ended || running.is_some() {
                        return self.fail_suspension(
                            agent,
                            suspension,
                            "not-running",
                            "the seat is not running the incarnation the suspend named".into(),
                            Vec::new(),
                        );
                    }
                    return Ok(());
                };
                self.record_member(subject, observation, true)?;
                let incarnation = observation.incarnation_id.as_deref().unwrap_or_default();
                let blocking = suspended::blockers(&self.store, agent, incarnation)?;
                if !blocking.is_empty() {
                    return self.fail_suspension(
                        agent,
                        suspension,
                        "not-quiescent",
                        format!("the seat is not quiet: {}", blocking.join(", ")),
                        blocking,
                    );
                }
                let Some((harness, session)) =
                    suspended::bound_session(&self.store, agent, incarnation)?
                else {
                    unreachable!("blockers require a bound native session");
                };
                self.record_suspension_phase(
                    agent,
                    suspension,
                    "runtime.action.succeeded",
                    suspended::suspend_snapshot_key(&suspension.operation_id),
                    BTreeMap::from([
                        (
                            "operation_status".into(),
                            Value::String("snapshotting".into()),
                        ),
                        ("harness".into(), Value::String(harness)),
                        ("native_session_id".into(), Value::String(session)),
                        ("incarnation_id".into(), Value::String(incarnation.into())),
                        (
                            "runtime_id".into(),
                            Value::String(member.runtime_id.clone()),
                        ),
                    ]),
                )?;
                stop(observation)?;
                Ok(())
            }
            "snapshotting" => {
                if let Some(observation) = running {
                    self.record_member(subject, observation, true)?;
                    stop(observation)?;
                    return Ok(());
                }
                if !ended {
                    return Ok(());
                }
                if let Some(observation) = observation {
                    self.record_member(subject, observation, false)?;
                }
                self.reconcile_runtime_stop(
                    agent,
                    &member.runtime_id,
                    member.terminal,
                    None,
                    member.shutdown_timeout_ms,
                    None,
                )?;
                self.record_suspension_phase(
                    agent,
                    suspension,
                    "runtime.action.succeeded",
                    suspended::suspend_completed_key(&suspension.operation_id),
                    BTreeMap::from([
                        ("operation_status".into(), Value::String("suspended".into())),
                        (
                            "harness".into(),
                            suspension
                                .harness
                                .clone()
                                .map_or(Value::Null, Value::String),
                        ),
                        (
                            "native_session_id".into(),
                            suspension
                                .native_session_id
                                .clone()
                                .map_or(Value::Null, Value::String),
                        ),
                    ]),
                )
            }
            "suspended" => {
                // A resume that failed after its launch leaves a process to end.
                if let Some(observation) = running {
                    self.record_member(subject, observation, true)?;
                    stop(observation)?;
                } else if ended {
                    self.reconcile_runtime_stop(
                        agent,
                        &member.runtime_id,
                        member.terminal,
                        None,
                        member.shutdown_timeout_ms,
                        None,
                    )?;
                }
                Ok(())
            }
            "restoring" => {
                if running.is_some() || !ended {
                    // A launch from an earlier pass is already under way; verify it.
                    return self.record_suspension_phase(
                        agent,
                        suspension,
                        "runtime.action.succeeded",
                        suspended::resume_started_key(&suspension.operation_id),
                        BTreeMap::from([(
                            "operation_status".into(),
                            Value::String("verifying".into()),
                        )]),
                    );
                }
                if let Some(error) = blocked {
                    return self.fail_suspension(
                        agent,
                        suspension,
                        "start-blocked",
                        format!("{error:#}"),
                        Vec::new(),
                    );
                }
                let Some(session) = suspension.native_session_id.clone() else {
                    return self.fail_suspension(
                        agent,
                        suspension,
                        "snapshot-incomplete",
                        "the suspension recorded no native session".into(),
                        Vec::new(),
                    );
                };
                let mut resumed = member.clone();
                resumed
                    .environment
                    .insert(suspended::RESUME_ENV.into(), session);
                let before = self
                    .store
                    .latest_observation(agent, "runtime.action.succeeded")?
                    .map(|claim| claim.id);
                if let Err(error) =
                    self.perform_start(subject, &resumed, "a suspended seat was resumed")
                {
                    return self.fail_suspension(
                        agent,
                        suspension,
                        "start-failed",
                        format!("{error:#}"),
                        Vec::new(),
                    );
                }
                let after = self
                    .store
                    .latest_observation(agent, "runtime.action.succeeded")?
                    .map(|claim| claim.id);
                if after == before {
                    return Ok(());
                }
                self.record_suspension_phase(
                    agent,
                    suspension,
                    "runtime.action.succeeded",
                    suspended::resume_started_key(&suspension.operation_id),
                    BTreeMap::from([(
                        "operation_status".into(),
                        Value::String("verifying".into()),
                    )]),
                )
            }
            "verifying" => {
                let overdue = now_ms().saturating_sub(suspension.updated_at_unix_ms)
                    > suspended::VERIFY_TIMEOUT_MS;
                if let Some(observation) = running {
                    self.record_member(subject, observation, true)?;
                    let incarnation = observation.incarnation_id.as_deref().unwrap_or_default();
                    match suspended::bound_session(&self.store, agent, incarnation)? {
                        Some((_, live)) if Some(&live) == suspension.native_session_id.as_ref() => {
                            self.record_suspension_phase(
                                agent,
                                suspension,
                                "runtime.action.succeeded",
                                suspended::resume_completed_key(&suspension.operation_id),
                                BTreeMap::from([
                                    ("operation_status".into(), Value::String("resumed".into())),
                                    ("native_session_id".into(), Value::String(live)),
                                    ("incarnation_id".into(), Value::String(incarnation.into())),
                                ]),
                            )
                        }
                        Some((_, live)) => self.fail_suspension(
                            agent,
                            suspension,
                            "native-session-mismatch",
                            format!(
                                "the harness bound native session {live}, not the suspended {}",
                                suspension.native_session_id.as_deref().unwrap_or("session")
                            ),
                            Vec::new(),
                        ),
                        None if overdue => self.fail_suspension(
                            agent,
                            suspension,
                            "native-session-unbound",
                            format!(
                                "the resumed harness bound no native session within {} s",
                                suspended::VERIFY_TIMEOUT_MS / 1000
                            ),
                            Vec::new(),
                        ),
                        None => Ok(()),
                    }
                } else if ended {
                    if let Some(observation) = observation {
                        self.record_member(subject, observation, false)?;
                    }
                    let diagnostic = self
                        .store
                        .claims_for(agent, Some("harness.diagnostic"))?
                        .into_iter()
                        .rev()
                        .find(|claim| {
                            // The driver can refuse before this owner records the launch.
                            let incarnation =
                                observation.and_then(|item| item.incarnation_id.as_deref());
                            claim.body.pointer("/fields/code").and_then(Value::as_str)
                                == Some(suspended::RESUME_UNAVAILABLE_CODE)
                                && match incarnation {
                                    Some(incarnation) => {
                                        claim_incarnation(claim) == Some(incarnation)
                                    }
                                    None => {
                                        claim.accepted_at_unix_ms >= suspension.requested_at_unix_ms
                                    }
                                }
                        });
                    // A driver records why it could not resume as it ends; give that record a
                    // moment to land after the harness's last observation.
                    if diagnostic.is_none()
                        && self
                            .store
                            .latest_observation(agent, "harness.observed")?
                            .is_some_and(|claim| {
                                now_ms().saturating_sub(claim.accepted_at_unix_ms)
                                    < RESUME_REFUSAL_GRACE_MS
                            })
                    {
                        self.arm_restart(
                            &format!("resume-refusal:{agent}"),
                            now_ms().saturating_add(1_000),
                        );
                        return Ok(());
                    }
                    let (code, reason) = match diagnostic {
                        Some(claim) => (
                            claim
                                .body
                                .pointer("/fields/status")
                                .and_then(Value::as_str)
                                .unwrap_or(suspended::RESUME_UNAVAILABLE_CODE)
                                .to_owned(),
                            claim
                                .body
                                .pointer("/fields/reason")
                                .and_then(Value::as_str)
                                .unwrap_or("the driver could not resume the native session")
                                .to_owned(),
                        ),
                        // Without the driver's refusal, the harness's own last word says why it
                        // ended: its driver reports the reason on `harness.observed`.
                        None => match self
                            .store
                            .latest_observation(agent, "harness.observed")?
                            .filter(|claim| {
                                claim.accepted_at_unix_ms >= suspension.requested_at_unix_ms
                                    && claim.body.pointer("/fields/state").and_then(Value::as_str)
                                        == Some("ended")
                            })
                            .and_then(|claim| {
                                claim
                                    .body
                                    .pointer("/fields/reason")
                                    .and_then(Value::as_str)
                                    .filter(|reason| !reason.is_empty())
                                    .map(str::to_owned)
                            }) {
                            Some(reason) => (
                                "harness-refused".into(),
                                format!("the harness ended before it bound the session: {reason}"),
                            ),
                            None => (
                                "resume-exited".into(),
                                "the resumed seat exited before it bound its native session"
                                    .into(),
                            ),
                        },
                    };
                    self.fail_suspension(agent, suspension, &code, reason, Vec::new())
                } else if overdue {
                    self.fail_suspension(
                        agent,
                        suspension,
                        "native-session-unbound",
                        "the resumed seat did not start running".into(),
                        Vec::new(),
                    )
                } else {
                    Ok(())
                }
            }
            _ => Ok(()),
        }
    }

    /// A requester-authored action replicates to the runtime owner. The declaration and old
    /// incarnation fence it, so a delayed request cannot stop a replacement or revive a stop.
    fn reconcile_requested_restart(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        observation: Option<&RuntimeObservation>,
        blocked: Option<&anyhow::Error>,
    ) -> Result<bool> {
        if subject.kind != "agent" {
            return Ok(false);
        }
        let Some(request) = self
            .store
            .claims_for(&subject.subject, Some("runtime.action.requested"))?
            .into_iter()
            .rev()
            .find(|claim| {
                claim.actor.is_some()
                    && claim.body.pointer("/fields/action").and_then(Value::as_str)
                        == Some("restart")
            })
        else {
            return Ok(false);
        };
        if self
            .store
            .selected_desired_token(&subject.subject)?
            .as_deref()
            != request.body.pointer("/evidence/0").and_then(Value::as_str)
        {
            return Ok(false);
        }
        let completion = format!("agent-restart-completed:{}", request.id);
        if self.store.operation_claim(&completion)?.is_some() {
            return Ok(false);
        }
        let previous = request.body["fields"]["incarnation_id"]
            .as_str()
            .unwrap_or("");
        if let Some(observation) = observation
            && observation.status != "unknown"
            && observation
                .incarnation_id
                .as_deref()
                .is_some_and(|value| value != previous)
        {
            self.store.append_claim(&ClaimInput {
                subject: subject.subject.clone(),
                kind: "runtime.action.succeeded".into(),
                actor: request.actor.clone(),
                fields: BTreeMap::from([
                    ("action".into(), Value::String("restart".into())),
                    (
                        "incarnation_id".into(),
                        Value::String(observation.incarnation_id.clone().unwrap()),
                    ),
                ]),
                evidence: vec![request.id],
                expected_subject: None,
                idempotency_key: Some(completion),
            })?;
            self.signal_changed();
            return Ok(false);
        }
        if let Some(observation) = observation.filter(|item| item.status == "running") {
            // Rendering must succeed before we shut down a still-running seat.
            if let Some(error) = blocked {
                anyhow::bail!("restart blocked: {error:#}");
            }
            self.record_member(subject, observation, true)?;
            self.reconcile_runtime_stop(
                &subject.subject,
                &member.runtime_id,
                member.terminal,
                observation.incarnation_id.as_deref(),
                member.shutdown_timeout_ms,
                Some(observation),
            )?;
            return Ok(true);
        }
        if observation
            .is_some_and(|item| !matches!(item.status.as_str(), "exited" | "vanished" | "stopped"))
        {
            return Ok(true);
        }
        if let Some(error) = blocked {
            anyhow::bail!("restart blocked: {error:#}");
        }
        let before = self
            .store
            .latest_observation(&subject.subject, "runtime.action.succeeded")?
            .map(|claim| claim.id);
        self.perform_start(subject, member, "an explicit seat restart was requested")?;
        let after = self
            .store
            .latest_observation(&subject.subject, "runtime.action.succeeded")?
            .map(|claim| claim.id);
        if after != before {
            self.store.append_claim(&ClaimInput {
                subject: subject.subject.clone(),
                kind: "runtime.action.succeeded".into(),
                actor: request.actor.clone(),
                fields: BTreeMap::from([("action".into(), Value::String("restart".into()))]),
                evidence: vec![request.id],
                expected_subject: None,
                idempotency_key: Some(completion),
            })?;
            self.signal_changed();
        }
        Ok(true)
    }

    fn reconcile_restart(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        observation: &RuntimeObservation,
    ) -> Result<()> {
        if subject.kind == "agent"
            && member.lifecycle == MemberLifecycle::Service
            && member.driver.as_deref() != Some("codex")
            && !self.claude_trust_recovery_stopped(&subject.subject, observation)?
            && self.park_unready_crash_loop(subject)?
        {
            return Ok(());
        }
        if member.driver.as_deref() == Some("codex") {
            let token = self.launch_token(&subject.subject)?;
            if self.codex_crash_loop_raised(&subject.subject, &token)? {
                self.raise_codex_crash_loop(
                    &subject.subject,
                    &token,
                    "the prior Codex crash loop remains stopped",
                )?;
                return Ok(());
            }
        }
        match self.restart_decision(subject, member, observation)? {
            RestartDecision::Start => {
                self.delayed_restarts
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .remove(&subject.subject);
                self.perform_start(subject, member, "the prior generation exited")
            }
            RestartDecision::Wait { until, reason } => {
                self.record_once(
                    &subject.subject,
                    "runtime.reconcile-decision",
                    BTreeMap::from([
                        ("decision".into(), Value::String("wait".into())),
                        ("reachability".into(), Value::String("reachable".into())),
                        ("reason".into(), Value::String(reason)),
                        (
                            "restart_at_unix_ms".into(),
                            Value::String(until.to_string()),
                        ),
                    ]),
                )?;
                self.arm_restart(&subject.subject, until);
                Ok(())
            }
            RestartDecision::Fail { reason } => {
                if member.driver.as_deref() == Some("codex") {
                    let token = self.launch_token(&subject.subject)?;
                    let diagnostic = self
                        .store
                        .claims_for(&subject.subject, Some("harness.diagnostic"))?
                        .into_iter()
                        .rev()
                        .find(|claim| {
                            claim.body.pointer("/fields/code").and_then(Value::as_str)
                                == Some("codex-driver-failed")
                                && claim
                                    .body
                                    .pointer("/fields/incarnation_id")
                                    .and_then(Value::as_str)
                                    == observation.incarnation_id.as_deref()
                        })
                        .and_then(|claim| {
                            claim
                                .body
                                .pointer("/fields/reason")
                                .and_then(Value::as_str)
                                .map(str::to_owned)
                        });
                    let detail = diagnostic
                        .or_else(|| {
                            observation
                                .exit_code
                                .map(|code| format!("last exit code {code}"))
                        })
                        .map_or(reason.clone(), |detail| format!("{reason}; {detail}"));
                    self.raise_codex_crash_loop(&subject.subject, &token, &detail)
                } else {
                    self.record_once(
                        &subject.subject,
                        "runtime.reconcile-decision",
                        BTreeMap::from([
                            ("decision".into(), Value::String("raise".into())),
                            ("reachability".into(), Value::String("unreachable".into())),
                            ("reason".into(), Value::String(reason)),
                        ]),
                    )
                }
            }
        }
    }

    fn codex_crash_loop_raised(&self, subject: &str, token: &str) -> Result<bool> {
        let decision_key = format!("codex-crash-loop:{token}");
        Ok(self
            .store
            .claims_for(subject, Some("runtime.reconcile-decision"))?
            .iter()
            .any(|claim| {
                claim.body.pointer("/fields/key").and_then(Value::as_str)
                    == Some(decision_key.as_str())
            }))
    }

    fn start_failures(&self, subject: &str, token: &str) -> Result<Vec<crate::model::ClaimRecord>> {
        Ok(self
            .store
            .observations_for(subject, "runtime.action.failed")?
            .into_iter()
            .filter(|claim| {
                claim.body.pointer("/fields/action").and_then(Value::as_str) == Some("start")
                    && claim
                        .body
                        .pointer("/fields/desired_token")
                        .and_then(Value::as_str)
                        == Some(token)
            })
            .collect())
    }

    /// Keep a failed durable launch from turning each graph write into another PTY spawn.
    fn defer_or_park_failed_start(&self, subject: &DesiredSubject) -> Result<bool> {
        let token = self.launch_token(&subject.subject)?;
        if self.runtime_crash_loop_raised(&subject.subject, &token)? {
            return Ok(true);
        }
        let last_success_index = self
            .store
            .observations_for(&subject.subject, "runtime.action.succeeded")?
            .into_iter()
            .filter(|claim| {
                claim
                    .body
                    .pointer("/fields/desired_token")
                    .and_then(Value::as_str)
                    == Some(token.as_str())
            })
            .map(|claim| claim.store_index)
            .max()
            .unwrap_or(0);
        let now = now_ms();
        let recent = self
            .start_failures(&subject.subject, &token)?
            .into_iter()
            .filter(|claim| {
                claim.store_index > last_success_index
                    && now.saturating_sub(claim.accepted_at_unix_ms) < CODEX_CRASH_LOOP_INTERVAL_MS
            })
            .collect::<Vec<_>>();
        if recent.len() >= CODEX_CRASH_LOOP_ATTEMPTS {
            let detail = recent
                .last()
                .and_then(|claim| claim.body.pointer("/fields/reason"))
                .and_then(Value::as_str)
                .unwrap_or("the runtime start failed");
            self.raise_runtime_crash_loop(
                &subject.subject,
                &token,
                &format!("the runtime failed to start three times: {detail}"),
            )?;
            return Ok(true);
        }
        if let Some(last) = recent.last() {
            let until = last.accepted_at_unix_ms.saturating_add(15_000);
            if until > now {
                self.arm_restart(&subject.subject, until);
                return Ok(true);
            }
        }
        self.delayed_restarts
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .remove(&subject.subject);
        Ok(false)
    }

    fn park_unready_crash_loop(&self, subject: &DesiredSubject) -> Result<bool> {
        let token = self.launch_token(&subject.subject)?;
        if self.runtime_crash_loop_raised(&subject.subject, &token)? {
            return Ok(true);
        }
        let first_launch = self
            .store
            .observations_for(&subject.subject, "runtime.action.succeeded")?
            .into_iter()
            .filter(|claim| {
                claim
                    .body
                    .pointer("/fields/desired_token")
                    .and_then(Value::as_str)
                    == Some(token.as_str())
            })
            .map(|claim| claim.accepted_at_unix_ms)
            .min();
        let Some(first_launch) = first_launch else {
            return Ok(false);
        };
        let ready = self
            .store
            .claims_for(&subject.subject, Some("harness.observed"))?
            .into_iter()
            .filter(|claim| {
                matches!(
                    claim.body.pointer("/fields/state").and_then(Value::as_str),
                    Some("ready" | "idle" | "working")
                )
            })
            .filter_map(|claim| claim_incarnation(&claim).map(str::to_owned))
            .collect::<BTreeSet<_>>();
        let trust_recovery = self
            .claude_trust_prompts(&subject.subject)?
            .iter()
            .filter_map(|claim| claim_incarnation(claim).map(str::to_owned))
            .collect::<BTreeSet<_>>();
        let now = now_ms();
        let exits = self
            .store
            .claims_for(&subject.subject, Some("runtime.observed"))?
            .into_iter()
            .filter(|claim| {
                matches!(
                    claim.body.pointer("/fields/status").and_then(Value::as_str),
                    Some("exited" | "vanished")
                ) && claim.accepted_at_unix_ms >= first_launch
                    && now.saturating_sub(claim.accepted_at_unix_ms) < CODEX_CRASH_LOOP_INTERVAL_MS
            })
            .filter_map(|claim| claim_incarnation(&claim).map(str::to_owned))
            .filter(|incarnation| {
                !ready.contains(incarnation) && !trust_recovery.contains(incarnation)
            })
            .collect::<BTreeSet<_>>();
        if exits.len() >= CODEX_CRASH_LOOP_ATTEMPTS {
            self.raise_runtime_crash_loop(
                &subject.subject,
                &token,
                "the runtime exited three times before the harness became ready",
            )?;
            return Ok(true);
        }
        Ok(false)
    }

    fn runtime_crash_loop_raised(&self, subject: &str, token: &str) -> Result<bool> {
        let key = format!("runtime-crash-loop:{token}");
        Ok(self
            .store
            .claims_for(subject, Some("runtime.reconcile-decision"))?
            .iter()
            .any(|claim| {
                claim.body.pointer("/fields/key").and_then(Value::as_str) == Some(key.as_str())
            }))
    }

    fn raise_runtime_crash_loop(&self, subject: &str, token: &str, reason: &str) -> Result<()> {
        let key = format!("runtime-crash-loop:{subject}:{token}");
        let decision_key = format!("runtime-crash-loop:{token}");
        let mut changed = false;
        if !self.runtime_crash_loop_raised(subject, token)? {
            self.store.append_claim(&ClaimInput {
                subject: subject.into(),
                kind: "runtime.reconcile-decision".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("decision".into(), Value::String("raise".into())),
                    ("reachability".into(), Value::String("unreachable".into())),
                    ("key".into(), Value::String(decision_key)),
                    ("reason".into(), Value::String(reason.into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some(format!("{key}:raised")),
            })?;
            changed = true;
        }
        if changed {
            self.signal_changed();
        }
        Ok(())
    }

    fn raise_codex_crash_loop(&self, subject: &str, token: &str, reason: &str) -> Result<()> {
        let key = format!("codex-crash-loop:{subject}:{token}");
        let decision_key = format!("codex-crash-loop:{token}");
        let existing = self
            .store
            .claims_for(subject, Some("runtime.reconcile-decision"))?
            .into_iter()
            .find(|claim| {
                claim.body.pointer("/fields/key").and_then(Value::as_str)
                    == Some(decision_key.as_str())
            });
        let mut changed = false;
        if existing.is_none() {
            self.store.append_claim(&ClaimInput {
                subject: subject.into(),
                kind: "runtime.reconcile-decision".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("decision".into(), Value::String("raise".into())),
                    ("reachability".into(), Value::String("unreachable".into())),
                    ("key".into(), Value::String(decision_key.clone())),
                    ("reason".into(), Value::String(reason.into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some(format!("{key}:raised")),
            })?;
            changed = true;
        }
        if changed {
            self.signal_changed();
        }
        Ok(())
    }

    fn restart_decision(
        &self,
        subject: &DesiredSubject,
        member: &MemberSpec,
        observation: &RuntimeObservation,
    ) -> Result<RestartDecision> {
        let intensity = if member.driver.as_deref() == Some("codex") {
            RestartIntensity {
                attempts: CODEX_CRASH_LOOP_ATTEMPTS as u32,
                interval_ms: CODEX_CRASH_LOOP_INTERVAL_MS as u64,
                delay_ms: member.restart_intensity.delay_ms,
                mode: "fail".into(),
            }
        } else {
            member.restart_intensity.clone()
        };
        let now = now_ms();
        let desired_token = self.launch_token(&subject.subject)?;
        let mut launches = self
            .store
            .observations_for(&subject.subject, "runtime.action.succeeded")?
            .into_iter()
            .filter(|claim| {
                claim
                    .body
                    .pointer("/fields/desired_token")
                    .and_then(Value::as_str)
                    == Some(desired_token.as_str())
            })
            .collect::<Vec<_>>();
        let resets = self
            .store
            .claims_for(&subject.subject, Some("runtime.restart-window-reset"))?;
        let incarnation = observation.incarnation_id.as_deref().unwrap_or("unknown");
        let reset_index = resets
            .iter()
            .filter(|claim| {
                claim
                    .body
                    .pointer("/fields/desired_token")
                    .and_then(Value::as_str)
                    == Some(desired_token.as_str())
                    && claim
                        .body
                        .pointer("/fields/incarnation_id")
                        .and_then(Value::as_str)
                        == Some(incarnation)
            })
            .map(|claim| claim.store_index)
            .max()
            .unwrap_or(0);
        launches.retain(|claim| {
            launch_in_restart_window(
                claim.store_index,
                claim.accepted_at_unix_ms,
                reset_index,
                now,
                intensity.interval_ms,
                &intensity.mode,
            )
        });

        if intensity.mode == "fail" {
            if let Some(last) = launches.last()
                && now.saturating_sub(last.accepted_at_unix_ms) >= intensity.interval_ms as u128
            {
                self.store.append_claim(&ClaimInput {
                    subject: subject.subject.clone(),
                    kind: "runtime.restart-window-reset".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("desired_token".into(), Value::String(desired_token.clone())),
                        ("incarnation_id".into(), Value::String(incarnation.into())),
                        (
                            "reason".into(),
                            Value::String("the stable interval cleared the restart window".into()),
                        ),
                    ]),
                    evidence: vec![last.id.clone()],
                    expected_subject: None,
                    idempotency_key: Some(format!(
                        "restart-reset:{}:{desired_token}:{incarnation}",
                        subject.subject
                    )),
                })?;
                launches.clear();
            }
            if launches.len() >= intensity.attempts as usize {
                return Ok(RestartDecision::Fail {
                    reason: format!(
                        "the member used {} launches without a stable {}ms interval",
                        intensity.attempts, intensity.interval_ms
                    ),
                });
            }
        }

        let mut wait_until = now;
        let mut reasons = Vec::new();
        if intensity.delay_ms > 0 {
            let observed_at = self
                .store
                .claims_for(&subject.subject, Some("runtime.observed"))?
                .into_iter()
                .rev()
                .find(|claim| {
                    matches!(
                        claim.body.pointer("/fields/status").and_then(Value::as_str),
                        Some("exited" | "vanished")
                    ) && observation
                        .incarnation_id
                        .as_deref()
                        .is_none_or(|incarnation| {
                            claim
                                .body
                                .pointer("/fields/incarnation_id")
                                .and_then(Value::as_str)
                                == Some(incarnation)
                        })
                })
                .map(|claim| claim.accepted_at_unix_ms)
                .unwrap_or(now);
            let delayed = observed_at.saturating_add(intensity.delay_ms as u128);
            if delayed > wait_until {
                wait_until = delayed;
                reasons.push(format!("the restart delay is {}ms", intensity.delay_ms));
            }
        }
        if intensity.mode == "delay" {
            let window_start = now.saturating_sub(intensity.interval_ms as u128);
            let recent = launches
                .iter()
                .filter(|claim| claim.accepted_at_unix_ms > window_start)
                .collect::<Vec<_>>();
            if recent.len() >= intensity.attempts as usize {
                let available = recent[0]
                    .accepted_at_unix_ms
                    .saturating_add(intensity.interval_ms as u128);
                if available > wait_until {
                    wait_until = available;
                    reasons.push(format!(
                        "the {} launch limit applies for {}ms",
                        intensity.attempts, intensity.interval_ms
                    ));
                }
            }
        }
        if wait_until > now {
            Ok(RestartDecision::Wait {
                until: wait_until,
                reason: reasons.join("; "),
            })
        } else {
            Ok(RestartDecision::Start)
        }
    }

    fn arm_restart(&self, subject: &str, until: u128) {
        smallclaims::touched::note_due(until);
        let mut armed = self
            .delayed_restarts
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        if armed.get(subject).is_some_and(|current| *current == until) {
            return;
        }
        armed.insert(subject.into(), until);
        let Ok(handle) = tokio::runtime::Handle::try_current() else {
            return;
        };
        let notify = self.notify.clone();
        let delayed = self.delayed_restarts.clone();
        let subject = subject.to_owned();
        handle.spawn(async move {
            let delay = until.saturating_sub(now_ms()).min(u64::MAX as u128) as u64;
            tokio::time::sleep(Duration::from_millis(delay)).await;
            delayed
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .remove(&subject);
            crate::performance::record_wake("timer restart", Some(restart_wake_kind(&subject)));
            notify.notify_one();
        });
    }

    fn record_member(
        &self,
        subject: &DesiredSubject,
        observation: &RuntimeObservation,
        adopted: bool,
    ) -> Result<()> {
        let member = subject
            .member
            .as_ref()
            .context("member observation lacks member")?;
        let mut fields = member_fields(
            member,
            &observation.status,
            observation.incarnation_id.as_deref(),
            adopted,
        );
        if let Some(exit_code) = observation.exit_code {
            fields.insert("exit_code".into(), Value::from(exit_code));
        }
        let mut evidence = Vec::new();
        if member.kind == MemberKind::Exec {
            // Launch receipts stay on the runtime's node. Carry the launched declaration as
            // evidence on its durable observation so predicates read the same proof everywhere.
            if let Some(token) = self
                .store
                .observations_for(&subject.subject, "runtime.action.succeeded")?
                .iter()
                .rev()
                .find_map(|claim| {
                    let fields = &claim.body["fields"];
                    if observation
                        .incarnation_id
                        .as_deref()
                        .zip(fields["incarnation_id"].as_str())
                        .is_some_and(|(observed, launched)| observed != launched)
                    {
                        return None;
                    }
                    fields["desired_token"].as_str().map(str::to_owned)
                })
            {
                evidence.push(token);
            } else if let Some(prior) = self
                .store
                .latest_claim(&subject.subject, Some("runtime.observed"))?
                && prior.body["fields"]["incarnation_id"].as_str()
                    == observation.incarnation_id.as_deref()
            {
                // Retention can trim a long-running exec's local launch receipt.
                evidence = prior.body["evidence"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter_map(Value::as_str)
                    .map(str::to_owned)
                    .collect();
            }
        }
        self.record_once_with_evidence(&subject.subject, "runtime.observed", fields, evidence)
    }

    fn record_once(
        &self,
        subject: &str,
        kind: &str,
        fields: BTreeMap<String, Value>,
    ) -> Result<()> {
        self.record_once_with_evidence(subject, kind, fields, Vec::new())
    }

    fn record_once_with_evidence(
        &self,
        subject: &str,
        kind: &str,
        fields: BTreeMap<String, Value>,
        evidence: Vec<String>,
    ) -> Result<()> {
        if self
            .store
            .latest_observation(subject, kind)?
            .is_some_and(|claim| {
                claim.body.get("fields")
                    == Some(&serde_json::to_value(&fields).unwrap_or(Value::Null))
                    && claim.body.get("evidence") == Some(&serde_json::json!(evidence))
            })
        {
            return Ok(());
        }
        let record = self.store.append_claim(&ClaimInput {
            subject: subject.into(),
            kind: kind.into(),
            actor: None,
            fields,
            evidence,
            expected_subject: None,
            idempotency_key: None,
        })?;
        if crate::store::local_observation_position(&record).is_some() {
            // Only this node reads a local observation, and it cannot advance a mission.
            self.event_notify
                .send_modify(|generation| *generation = generation.saturating_add(1));
        } else {
            self.signal_changed();
        }
        Ok(())
    }

    /// Evaluate each active run on its own. A run that fails records a fault on that run, and
    /// every other run, including runs in cleanup, is still evaluated in the same pass.
    fn evaluate_mission_runs(&self) -> Result<()> {
        self.recording_writes(|| self.evaluate_mission_runs_pass())
    }

    fn evaluate_mission_runs_pass(&self) -> Result<()> {
        self.incremental.observe(&self.store)?;
        // A gate runner's exit is not a claim: look again at the runners evaluations wait on.
        self.incremental.observe_execs(|runtime_id| {
            self.runtime
                .observe_exec(runtime_id)
                .ok()
                .flatten()
                .map(|observation| observation.status)
        });
        let ids = self.store.active_mission_run_ids_for_origin(&self.host)?;
        let mut active_generations = BTreeSet::new();
        let mut active_steps = BTreeSet::new();
        let mut changed = false;
        let full = !self.skip_unneeded || self.incremental.take_full_pass("mission-run", now_ms());
        for id in &ids {
            let subject = format!("mission-run/{id}");
            let needed = self.needs_item(&subject, full);
            if !full && !needed {
                // Nothing it read changed and nothing is due. It stays active: keep its caches,
                // faults and file watchers as its last evaluation left them.
                for key in self.incremental.reads_of(&subject) {
                    if key.starts_with("run-generation/") {
                        active_generations.insert(key);
                    } else if key.starts_with("step-run/") {
                        active_steps.insert(key);
                    } else if key.starts_with("file/") {
                        self.file_watchers_used
                            .lock()
                            .unwrap_or_else(PoisonError::into_inner)
                            .insert(key);
                    }
                }
                continue;
            }
            let cpu_started = crate::incremental::thread_cpu();
            let wrote_mark = smallclaims::touched::wrote_len();
            let mut due = None;
            let ((evaluated, armed), reads) = smallclaims::touched::record(|| {
                smallclaims::touched::record_due(|| {
                    self.isolate("mission-run", &subject, || {
                        let run = self.store.mission_run_for_reconcile(id)?;
                        active_generations.insert(run.generation.clone());
                        active_steps.extend(run.steps.iter().map(|step| step.subject.clone()));
                        // From the view the evaluation started with: a write it makes changes subjects
                        // it read, so the next pass evaluates it again and takes the new times.
                        due = crate::incremental::run_due(&run, now_ms());
                        self.evaluate_active_mission_run(&run)
                    })
                })
            });
            due = match (due, armed) {
                (Some(a), Some(b)) => Some(a.min(b)),
                (a, b) => a.or(b),
            };
            changed |= evaluated.unwrap_or(false);
            crate::performance::record_evaluation(
                "mission-run",
                needed,
                crate::incremental::thread_cpu().saturating_sub(cpu_started),
            );
            if !needed {
                let wrote = smallclaims::touched::wrote_since(wrote_mark);
                // Rows that are not claims or observations (caches, capabilities) change no
                // graph state a later pass would have to catch up with.
                if !wrote.is_empty() {
                    self.incremental_correction("mission-run", &subject, &reads, &wrote);
                }
            }
            self.incremental.evaluated(&subject, reads, due);
        }
        self.incremental.retain(
            "mission-run/",
            &ids.iter().map(|id| format!("mission-run/{id}")).collect(),
        );
        self.materialized_mission_generations
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .retain(|generation| active_generations.contains(generation.as_str()));
        self.retired_predecessor_generations
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .retain(|generation| active_generations.contains(generation.as_str()));
        // A run or step that left the active set while faulted has nothing left to fail.
        let active = ids
            .iter()
            .map(|id| format!("mission-run/{id}"))
            .collect::<BTreeSet<_>>();
        let inactive = self
            .open_faults()?
            .iter()
            .flatten()
            .filter(|((subject, scope), _)| match scope.as_str() {
                "mission-run" => !active.contains(subject),
                "step" => !active_steps.contains(subject),
                _ => false,
            })
            .map(|((subject, scope), _)| (subject.clone(), scope.clone()))
            .collect::<Vec<_>>();
        for (subject, scope) in inactive {
            self.close_fault(&subject, &scope, "it is no longer active")?;
        }
        if changed {
            self.signal_changed();
        }
        Ok(())
    }

    /// An evaluation of `subject` wrote although nothing it read had changed and nothing was due:
    /// an incremental pass would have missed this write. Counted, and in tests a failure.
    fn incremental_correction(
        &self,
        item: &str,
        subject: &str,
        reads: &BTreeSet<String>,
        wrote: &[String],
    ) {
        crate::performance::record_correction(item);
        eprintln!(
            "st3: incremental correction: {subject} wrote {wrote:?} with no change among {} reads",
            reads.len()
        );
        assert!(
            !self.strict_incremental,
            "an incremental pass would have missed a write by {subject}: it wrote {wrote:?}; its reads: {reads:?}"
        );
    }

    fn evaluate_active_mission_run(&self, run: &MissionRunView) -> Result<bool> {
        if run
            .deadline_at_unix_ms
            .is_some_and(|deadline| deadline <= now_ms())
            && !run.phase.starts_with("cleanup-")
        {
            let timeout = run.timeout_ms.unwrap_or_default();
            let reason = format!("the mission timeout expired after {timeout}ms");
            let mut changed = self
                .store
                .terminate_mission_run_descendants(&run.id, &reason)?;
            changed |= self.store.set_mission_run_state(
                &run.id,
                "running",
                if run.phase == "final-cancelled" {
                    "cleanup-cancelled"
                } else {
                    "cleanup-failed"
                },
                Some(&reason),
            )?;
            return Ok(changed);
        }
        if run.phase == "revision-draining" {
            if self.store.apply_drained_revision(&run.id)?.is_some() {
                return Ok(true);
            }
            // A replica can receive the old proposal's draining claim after the
            // successor generation. Recover the persisted run phase when no
            // draining proposal still targets its current generation.
            if !self
                .store
                .revision_proposal_for_run(&run.id)?
                .is_some_and(|proposal| proposal.status == "draining")
            {
                return self
                    .store
                    .set_mission_run_state(&run.id, &run.status, "normal", None);
            }
        }
        // Cleanup reads only the run's owned declarations. It never waits for the mission
        // revision or its steps, so a run whose revision is unavailable still stops its runtimes.
        if run.phase.starts_with("cleanup-") {
            return self.reconcile_mission_run_cleanup(run);
        }
        let mission_id = run.mission.strip_prefix("mission/").unwrap_or(&run.mission);
        let Some(mission) = self.store.mission_spec(mission_id, Some(&run.revision))? else {
            return self.store.set_mission_run_state(
                &run.id,
                "blocked",
                &run.phase,
                Some("the selected mission revision is unavailable"),
            );
        };
        let mission = match crate::mission::run_mission(mission, run.after.as_deref()) {
            Ok(mission) => mission,
            Err(error) => {
                return self.store.set_mission_run_state(
                    &run.id,
                    "blocked",
                    &run.phase,
                    Some(&error.message),
                );
            }
        };
        self.evaluate_mission_run(run, &mission)
    }

    fn evaluate_mission_run(&self, run: &MissionRunView, mission: &MissionSpec) -> Result<bool> {
        if run.phase.starts_with("cleanup-") {
            return self.reconcile_mission_run_cleanup(run);
        }
        let mut changed = false;
        let flat = flatten_mission_steps(mission);
        let normal_paths = flat
            .iter()
            .filter(|step| !step.spec.finally)
            .map(|step| step.spec.path.as_str())
            .collect::<BTreeSet<_>>();
        let views = run
            .steps
            .iter()
            .map(|step| (step.step.as_str(), step))
            .collect::<HashMap<_, _>>();
        if run.phase == "normal" {
            let admitted = flat.iter().filter(|step| !step.spec.finally).any(|step| {
                views.get(step.spec.path.as_str()).is_some_and(|view| {
                    view.attempt > 1
                        || matches!(
                            view.status.as_str(),
                            "ready"
                                | "claimed"
                                | "working"
                                | "verifying"
                                | "completed"
                                | "failed"
                                | "cancelled"
                        )
                })
            });
            if !admitted {
                let variables = crate::store::mission_run_variables(run, &run.revision);
                for baseline in &mission.baselines {
                    for gate in &baseline.gates {
                        if !matches!(
                            self.evaluate_context_gate(
                                run,
                                &run.subject,
                                &mission.id,
                                &mission.revision,
                                1,
                                gate,
                                &variables,
                            )?,
                            GateOutcome::Pass
                        ) {
                            changed |= self.store.set_mission_run_state(
                                &run.id,
                                "blocked",
                                "normal",
                                Some(&format!(
                                    "mission baseline `{}` does not hold",
                                    baseline.name
                                )),
                            )?;
                            return Ok(changed);
                        }
                    }
                }
            }
            let blocked_by_baseline = run.status == "blocked"
                && self
                    .store
                    .latest_claim(&run.subject, Some("mission-run.state"))?
                    .and_then(|claim| {
                        claim
                            .body
                            .pointer("/fields/reason")
                            .and_then(Value::as_str)
                            .map(str::to_owned)
                    })
                    .is_some_and(|reason| reason.starts_with("mission baseline `"));
            if blocked_by_baseline {
                changed |= self
                    .store
                    .set_mission_run_state(&run.id, "running", "normal", None)?;
            }
        }
        if mission.declarations_kdl.is_some() {
            let already_materialized = self
                .materialized_mission_generations
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .contains(&run.generation);
            if !already_materialized {
                changed |= self.materialize_mission_declarations(run, mission)?;
                self.materialized_mission_generations
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .insert(run.generation.clone());
            }
        }
        let predecessor_retired = self
            .retired_predecessor_generations
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .contains(&run.generation);
        if !predecessor_retired {
            let (retired, complete) = self.retire_predecessor_generation(run)?;
            changed |= retired;
            if complete {
                self.retired_predecessor_generations
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .insert(run.generation.clone());
            }
        }
        let mut normal_failed = flat.iter().any(|step| {
            !step.spec.finally
                && views.get(step.spec.path.as_str()).is_some_and(|view| {
                    (view.status == "failed" && view.attempt >= step.spec.retry.attempts)
                        || view.status == "cancelled"
                })
        });
        let mut normal_failure_reason = normal_failed.then(|| "a normal step failed".to_owned());
        let completion_selected = run.phase == "normal"
            && ((normal_failed && mission.completion.is_some())
                || self.mission_completion_selected(run, mission, &views)?);
        if completion_selected && !normal_failed {
            let variables = crate::store::mission_run_variables(run, &run.revision);
            if !self.products_hold_with_variables(&mission.products, &variables)? {
                return Ok(changed);
            }
            for gate in &mission.gates {
                match self.evaluate_context_gate(
                    run,
                    &run.subject,
                    &mission.id,
                    &mission.revision,
                    1,
                    gate,
                    &variables,
                )? {
                    GateOutcome::Pass => {}
                    // A broken mission gate waits for a revision, as a pending one waits.
                    GateOutcome::Pending | GateOutcome::NotYet | GateOutcome::Broken(_) => {
                        return Ok(changed);
                    }
                    GateOutcome::Fail(reason) => {
                        normal_failed = true;
                        normal_failure_reason = Some(reason);
                        break;
                    }
                }
            }
        }
        if completion_selected {
            for step in flat.iter().filter(|step| !step.spec.finally) {
                // A step whose run has not reached this host yet has nothing to cancel.
                let Some(view) = views.get(step.spec.path.as_str()) else {
                    continue;
                };
                if !matches!(view.status.as_str(), "completed" | "failed" | "cancelled") {
                    changed |= self.store.set_step_state(
                        &view.subject,
                        "cancelled",
                        Some(if normal_failed {
                            "another step failed"
                        } else {
                            "the normal phase completed"
                        }),
                    )?;
                }
            }
            if flat.iter().any(|step| step.spec.finally) {
                changed |= self.store.set_mission_run_state(
                    &run.id,
                    "running",
                    "final",
                    normal_failure_reason.as_deref(),
                )?;
            } else {
                changed |= self.store.set_mission_run_state(
                    &run.id,
                    "running",
                    if normal_failed {
                        "cleanup-failed"
                    } else {
                        "cleanup-completed"
                    },
                    normal_failure_reason.as_deref(),
                )?;
            }
            return Ok(changed);
        }

        if matches!(run.phase.as_str(), "final" | "final-cancelled") {
            let final_terminal = flat.iter().filter(|step| step.spec.finally).all(|step| {
                views.get(step.spec.path.as_str()).is_some_and(|view| {
                    matches!(view.status.as_str(), "completed" | "failed" | "cancelled")
                })
            });
            if final_terminal {
                let final_failed = flat.iter().filter(|step| step.spec.finally).any(|step| {
                    views
                        .get(step.spec.path.as_str())
                        .is_some_and(|view| view.status == "failed")
                });
                let failed = run.phase != "final-cancelled"
                    && run.steps.iter().any(|step| {
                        normal_paths.contains(step.step.as_str())
                            && matches!(step.status.as_str(), "failed" | "cancelled")
                    });
                // A run's outcome follows its work. A finally step that fails after the work
                // went well is a fault on the run, shown as one, and does not fail the run.
                let terminal_status = if run.phase == "final-cancelled" {
                    "cancelled"
                } else if failed {
                    "failed"
                } else {
                    "completed"
                };
                let failures = final_step_failures(&flat, &views);
                // A cancelled run keeps the failure in its reason, since cancellation is already
                // its outcome and says nothing about cleanup.
                let failure_reason = if final_failed && terminal_status == "cancelled" {
                    Some(format!("finally steps failed: {}", failures.join("; ")))
                } else {
                    failed.then(|| "one or more mission steps failed".to_owned())
                };
                if final_failed && terminal_status != "cancelled" {
                    changed |= self.record_final_step_faults(run, &failures)?;
                }
                changed |= self.store.set_mission_run_state(
                    &run.id,
                    "running",
                    &format!("cleanup-{terminal_status}"),
                    failure_reason.as_deref(),
                )?;
                return Ok(changed);
            }
        }

        for step in flat {
            let Some(view) = views.get(step.spec.path.as_str()).copied() else {
                continue;
            };
            // One step that fails records a fault on that step. The run's other steps and its
            // status are still evaluated.
            changed |= self
                .isolate("step", &view.subject, || -> Result<bool> {
                    let mut changed = false;
                    let eligible_phase = ((run.phase == "normal"
                        || run.phase == "revision-draining")
                        && !step.spec.finally)
                        || (matches!(run.phase.as_str(), "final" | "final-cancelled")
                            && step.spec.finally);
                    if !eligible_phase {
                        return Ok(changed);
                    }
                    if run.phase == "revision-draining"
                        && matches!(
                            view.status.as_str(),
                            "pending" | "ready" | "blocked" | "failed" | "completed" | "cancelled"
                        )
                    {
                        return Ok(changed);
                    }
                    if view.status == "failed" {
                        if view.attempt < step.spec.retry.attempts {
                            changed |= self.store.retry_step(
                                &view.subject,
                                "the step repeat policy permits another attempt",
                                step.spec.retry.backoff_ms,
                            )?;
                        }
                        return Ok(changed);
                    }
                    if matches!(
                        view.status.as_str(),
                        "completed" | "cancelled" | "waiting-person"
                    ) {
                        return Ok(changed);
                    }
                    if view.status == "orphaned" {
                        changed |= self.store.set_step_state(
                            &view.subject,
                            "ready",
                            Some("the prior worker incarnation ended"),
                        )?;
                        return Ok(changed);
                    }
                    if matches!(
                        view.status.as_str(),
                        "claimed" | "working" | "verifying" | "blocked"
                    ) && self.store.work_claim_is_orphaned(view)?
                    {
                        changed |= self.store.set_step_state(
                            &view.subject,
                            "orphaned",
                            Some("the exact worker incarnation ended"),
                        )?;
                        return Ok(changed);
                    }
                    if view.status == "ready"
                        && view.blocked_reason.as_deref() == Some("the worker lease expired")
                    {
                        if self.step_timed_out(view, &step)? {
                            changed |= self.expire_step_timeout(view, &step)?;
                            return Ok(changed);
                        }
                        changed |= self.store.set_step_state(
                            &view.subject,
                            "ready",
                            Some("the worker lease expired"),
                        )?;
                        return Ok(changed);
                    }
                    if let Some(expiry) = view.claim_expires_at_unix_ms
                        && expiry <= now_ms()
                        && matches!(
                            view.status.as_str(),
                            "claimed" | "working" | "verifying" | "blocked"
                        )
                    {
                        changed |= self.store.set_step_state(
                            &view.subject,
                            "ready",
                            Some("the worker lease expired"),
                        )?;
                        return Ok(changed);
                    }
                    let assignment_blocked = view.status == "blocked"
                        && view.blocked_reason.as_deref().is_some_and(|reason| {
                            reason.starts_with("no eligible agent is present")
                        });
                    let baseline_blocked = view.status == "blocked"
                        && view
                            .blocked_reason
                            .as_deref()
                            .is_some_and(|reason| reason.starts_with("step baseline `"));
                    if view.status == "pending" || assignment_blocked || baseline_blocked {
                        if view
                            .not_before_unix_ms
                            .is_some_and(|not_before| not_before > now_ms())
                        {
                            return Ok(changed);
                        }
                        if !self.step_dependencies_hold(run, &step, &views)? {
                            return Ok(changed);
                        }
                        let mut baseline_holds = true;
                        for baseline in &step.spec.baselines {
                            for gate in &baseline.gates {
                                if !matches!(
                                    self.evaluate_mission_gate(run, &step, view, gate)?,
                                    GateOutcome::Pass
                                ) {
                                    changed |= self.store.set_step_state(
                                        &view.subject,
                                        "blocked",
                                        Some(&format!(
                                            "step baseline `{}` does not hold",
                                            baseline.name
                                        )),
                                    )?;
                                    baseline_holds = false;
                                    break;
                                }
                            }
                            if !baseline_holds {
                                break;
                            }
                        }
                        if !baseline_holds {
                            return Ok(changed);
                        }
                        if baseline_blocked {
                            changed |= self.store.set_step_state(&view.subject, "pending", None)?;
                        }
                        let eligible_agent = || -> Result<bool> {
                            Ok(view
                                .assigned_to
                                .iter()
                                .chain(view.available_to.iter())
                                .map(|agent| self.store.selected_desired_kind(agent))
                                .collect::<Result<Vec<_>>>()?
                                .iter()
                                .any(|kind| kind.as_deref() == Some("agent")))
                        };
                        let mut eligible = view.agentless
                            || view
                                .assigned_to
                                .as_deref()
                                .is_some_and(|actor| actor.starts_with("person/"))
                            || eligible_agent()?;
                        if !eligible {
                            // A step can declare its own assigned agent. Create only that agent before
                            // checking eligibility; other declarations still wait for active execution.
                            changed |=
                                self.materialize_step_declarations(run, &step, view, true)?;
                            eligible = eligible_agent()?;
                        }
                        if !eligible {
                            let eligible = view
                                .assigned_to
                                .iter()
                                .chain(view.available_to.iter())
                                .map(|agent| format!("`{agent}`"))
                                .collect::<Vec<_>>()
                                .join(", ");
                            changed |= self.store.set_step_state(
                                &view.subject,
                                "blocked",
                                Some(&format!(
                                    "no eligible agent is present in the desired graph: {eligible}"
                                )),
                            )?;
                            return Ok(changed);
                        }
                        changed |= self.store.set_step_state(&view.subject, "ready", None)?;
                        return Ok(changed);
                    }
                    if !matches!(
                        view.status.as_str(),
                        "ready" | "claimed" | "working" | "verifying" | "blocked"
                    ) {
                        return Ok(changed);
                    }
                    // Agentless work has no worker claim to open its execution interval. Admit every
                    // eligible agentless step automatically before materializing declarations or waiting
                    // on gates, so its timeout and lifecycle are real instead of remaining `ready`
                    // forever. Nested missions need the persisted parent transition before their children
                    // can be evaluated; other agentless work can materialize in this same pass.
                    if view.status == "ready" && view.agentless {
                        let reason = awaited_run(run, &step, view)?
                            .map(|after| format!("waiting for `{after}` to complete"));
                        changed |= self.store.set_step_state(
                            &view.subject,
                            "working",
                            reason.as_deref(),
                        )?;
                        if step.spec.nested_mission.is_some() {
                            return Ok(changed);
                        }
                    }
                    changed |= self.materialize_step_declarations(run, &step, view, false)?;
                    if let Some(reason) = self.step_declaration_failure(&view.subject)? {
                        changed |=
                            self.store
                                .set_step_state(&view.subject, "failed", Some(&reason))?;
                        return Ok(changed);
                    }
                    if self.step_timed_out(view, &step)? {
                        // A worker's step that runs out of time is a fault for that worker to
                        // extend, complete or fail. Only a step with no worker fails here, and a
                        // step already submitted for verification has used its time.
                        if view.agentless
                            || matches!(view.status.as_str(), "claimed" | "working" | "ready")
                        {
                            changed |= self.expire_step_timeout(view, &step)?;
                            return Ok(changed);
                        }
                    }
                    if !self.step_declarations_hold(&view.subject)? {
                        return Ok(changed);
                    }
                    if !view.agentless && !view.worker_reported {
                        return Ok(changed);
                    }
                    if let Some(loop_spec) = &step.spec.loop_spec {
                        if self.evaluate_loop_step(run, &step, view, loop_spec)? {
                            changed = true;
                        }
                        return Ok(changed);
                    }
                    if let Some(nested) = &step.spec.nested_mission {
                        let nested_prefix = format!("{}/{}/", step.spec.path, nested.id);
                        if !views
                            .iter()
                            .filter(|(path, _)| path.starts_with(&nested_prefix))
                            .all(|(_, child)| child.status == "completed")
                        {
                            return Ok(changed);
                        }
                    }
                    if step.spec.produces_mission.is_some()
                        && !self.produced_mission_holds(step.spec, view)?
                    {
                        return Ok(changed);
                    }
                    if step.spec.uses_mission.is_some() {
                        let (use_changed, outcome) =
                            self.evaluate_used_mission(run, &step, view, &views)?;
                        changed |= use_changed;
                        match outcome {
                            UsedMissionOutcome::Pending => return Ok(changed),
                            UsedMissionOutcome::Completed => {}
                            UsedMissionOutcome::Failed(reason) => {
                                changed |= self.store.set_step_state(
                                    &view.subject,
                                    "failed",
                                    Some(&reason),
                                )?;
                                return Ok(changed);
                            }
                        }
                    }
                    if let Some(after) = awaited_run(run, &step, view)? {
                        match self.store.mission_run_status(&after)?.as_deref() {
                            Some("completed") => {}
                            Some(status @ ("failed" | "cancelled")) => {
                                changed |= self.store.set_step_state(
                                    &view.subject,
                                    "failed",
                                    Some(&format!("the awaited mission run `{after}` is {status}")),
                                )?;
                                return Ok(changed);
                            }
                            _ => return Ok(changed),
                        }
                    }
                    if let Some(missing) = self.missing_product(run, &step, view)? {
                        changed |= self.notify_missing_product(view, &missing)?;
                        return Ok(changed);
                    }
                    let mut gates_pass = true;
                    for gate in &step.spec.gates {
                        match self.evaluate_mission_gate(run, &step, view, gate)? {
                            GateOutcome::Pass => {}
                            GateOutcome::Pending | GateOutcome::NotYet => {
                                gates_pass = false;
                                break;
                            }
                            // A broken gate holds its step for a revision. A finally step cannot
                            // take one, so it fails as before, with the gate's reason.
                            GateOutcome::Broken(reason) if step.spec.finally => {
                                changed |= self.store.set_step_state(
                                    &view.subject,
                                    "failed",
                                    Some(&reason),
                                )?;
                                gates_pass = false;
                                break;
                            }
                            GateOutcome::Broken(_) => {
                                gates_pass = false;
                                break;
                            }
                            GateOutcome::Fail(reason) => {
                                changed |= self.store.set_step_state(
                                    &view.subject,
                                    "failed",
                                    Some(&reason),
                                )?;
                                gates_pass = false;
                                break;
                            }
                        }
                    }
                    if gates_pass {
                        changed |= self
                            .store
                            .set_step_state(&view.subject, "completed", None)?;
                    }
                    Ok(changed)
                })
                .unwrap_or(false);
        }
        if run.phase == "normal" {
            let refreshed = self
                .store
                .mission_run(&run.id)?
                .context("the active mission run disappeared")?;
            let normal = refreshed
                .steps
                .iter()
                .filter(|view| normal_paths.contains(view.step.as_str()))
                .collect::<Vec<_>>();
            let advancing = normal.iter().any(|view| {
                matches!(
                    view.status.as_str(),
                    "ready" | "claimed" | "working" | "verifying"
                )
            });
            let failed = normal
                .iter()
                .any(|view| matches!(view.status.as_str(), "failed" | "cancelled"));
            let (status, reason) = if advancing {
                ("running", None)
            } else if failed {
                ("blocked", Some("the mission has no available step"))
            } else if mission.completion.is_none() && !changed {
                ("standing", Some("the open mission has no available step"))
            } else {
                ("running", None)
            };
            changed |= self
                .store
                .set_mission_run_state(&run.id, status, "normal", reason)?;
        }
        Ok(changed)
    }

    fn reconcile_mission_run_cleanup(&self, run: &MissionRunView) -> Result<bool> {
        let owner_runs = if run.mode == "eval" {
            self.store
                .mission_runs_for_root(&run.id)?
                .into_iter()
                .map(|owned_run| owned_run.subject)
                .collect::<BTreeSet<_>>()
        } else {
            BTreeSet::from([run.subject.clone()])
        };
        let mut owned = owner_runs
            .iter()
            .map(|owner| self.store.desired_subjects_for_owner_run(owner))
            .collect::<Result<Vec<_>>>()?
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        owned.extend(
            self.store
                .mission_gate_runners()?
                .into_iter()
                .filter(|runner| owner_runs.contains(&runner.owner_run))
                .map(|runner| DesiredSubject {
                    subject: runner.subject,
                    kind: "stop".into(),
                    desired: Value::Null,
                    member: None,
                    owner_run: Some(runner.owner_run),
                    owner_generation: None,
                    owner_step: None,
                }),
        );
        let intake_stopped = self.stop_owned_intake(
            &owned.iter().collect::<Vec<_>>(),
            None,
            &format!("cleanup-mission-run-intake:{}", run.generation),
        )?;
        let owned = owned
            .into_iter()
            .filter(|subject| subject.member.is_some() || subject.kind == "stop")
            .collect::<Vec<_>>();
        let mut live = Vec::new();
        for subject in &owned {
            let actual = self.store.latest_actual_value(&subject.subject)?;
            // A stop declaration for a runtime that never existed has no process
            // to await. Otherwise cleanup can remain pending forever.
            if subject.kind == "stop" && actual.is_none() {
                continue;
            }
            let status = actual
                .as_ref()
                .and_then(|actual| actual_field(actual, "status"))
                .and_then(Value::as_str)
                .map(str::to_owned);
            if !matches!(status.as_deref(), Some("stopped" | "absent" | "exited")) {
                // A seat kept for unread mail or another run's work does not hold this run
                // open. Its stop declaration stays and takes effect once it is free.
                if subject.kind == "stop"
                    && self
                        .seat_retention(&subject.subject, &run.subject)?
                        .is_some()
                {
                    continue;
                }
                live.push(subject);
            }
        }
        let running = live
            .iter()
            .filter(|subject| subject.kind != "stop")
            .map(|subject| format!("  stop {:?}", subject.subject))
            .collect::<Vec<_>>();
        if !running.is_empty() {
            // Stop each owned subject exactly. Execution parsing would scope a
            // top-level seat that an eval owns under the run, and that stop
            // would never reach the seat.
            let source = format!("version 2\n\n{}\n", running.join("\n"));
            let mut intent = crate::graph::parse_internal_intent(&source, &self.host)?;
            for stop in intent.subjects.values_mut() {
                stop.owner_run = live
                    .iter()
                    .find(|subject| subject.subject == stop.subject)
                    .and_then(|subject| subject.owner_run.clone());
            }
            let response = self
                .store
                .apply_internal(&intent, &format!("cleanup-mission-run:{}", run.generation))?;
            return Ok(response.changed || intake_stopped);
        }
        // Cleanup waits for each owned runtime to stop, but not forever. A runtime on a host that
        // never answers, or one that cannot be killed, would otherwise hold the run and its slot.
        // Its stop declaration stays, so stopping continues after the run ends.
        let mut unstopped = None;
        if !live.is_empty() {
            let since = self
                .store
                .latest_claim(&run.subject, Some("mission-run.state"))?
                .filter(|claim| {
                    claim.body.pointer("/fields/phase").and_then(Value::as_str)
                        == Some(run.phase.as_str())
                })
                .map_or_else(now_ms, |claim| claim.accepted_at_unix_ms);
            let deadline = since.saturating_add(self.cleanup_deadline.as_millis());
            if now_ms() < deadline {
                self.arm_restart(&format!("cleanup:{}", run.subject), deadline);
                return Ok(intake_stopped);
            }
            unstopped = Some(format!(
                "cleanup ended at its deadline with runtimes still live: {}",
                live.iter()
                    .map(|subject| subject.subject.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        }
        let mut status = run.phase.strip_prefix("cleanup-").unwrap_or("failed");
        let mut changed = intake_stopped;
        if run.mode == "eval" {
            let run_failure_reason = self
                .store
                .latest_claim(&run.subject, Some("mission-run.state"))?
                .and_then(|claim| {
                    claim
                        .body
                        .pointer("/fields/reason")
                        .and_then(Value::as_str)
                        .map(str::to_owned)
                });
            let mut runtime_cleanup_errors = unstopped.iter().cloned().collect::<Vec<_>>();
            match self.store.eval_runtime_records(&run.subject) {
                Ok(records) => {
                    for (runtime_id, terminal) in records {
                        if let Err(error) = self.runtime.remove(&runtime_id, terminal) {
                            runtime_cleanup_errors.push(format!("{runtime_id}: {error}"));
                        }
                    }
                }
                Err(error) => {
                    runtime_cleanup_errors.push(error.to_string());
                }
            }
            let (verdict, reason, residue) = match (
                runtime_cleanup_errors.is_empty(),
                self.store.retire_eval_owned_desired(&run.subject),
            ) {
                (false, retired) => {
                    status = "cancelled";
                    let mut reasons = runtime_cleanup_errors;
                    if let Err(error) = retired {
                        reasons.push(error.to_string());
                    }
                    (
                        "void",
                        Some(format!(
                            "eval cleanup infrastructure failed: {}",
                            reasons.join("; ")
                        )),
                        Vec::new(),
                    )
                }
                (true, Ok(residue)) if residue.is_empty() => (
                    match status {
                        "completed" => "pass",
                        "failed" => "fail",
                        _ => "void",
                    },
                    (status == "failed").then_some(run_failure_reason).flatten(),
                    residue,
                ),
                (true, Ok(residue)) => {
                    status = "failed";
                    (
                        "fail",
                        Some("the eval left subjects in its owned graph".to_owned()),
                        residue,
                    )
                }
                (true, Err(error)) => {
                    status = "cancelled";
                    (
                        "void",
                        Some(format!("eval cleanup infrastructure failed: {error}")),
                        Vec::new(),
                    )
                }
            };
            let mut fields = BTreeMap::from([("verdict".into(), Value::String(verdict.into()))]);
            if let Some(reason) = reason {
                fields.insert("reason".into(), Value::String(reason));
            }
            if !residue.is_empty() {
                fields.insert(
                    "residue".into(),
                    Value::Array(residue.into_iter().map(Value::String).collect()),
                );
            }
            self.record_once(&run.subject, "eval.verdict", fields)?;
            changed = true;
        }
        let failure_reason = self
            .store
            .latest_claim(&run.subject, Some("mission-run.state"))?
            .and_then(|claim| {
                claim
                    .body
                    .pointer("/fields/reason")
                    .and_then(Value::as_str)
                    .map(str::to_owned)
            });
        changed |= self.store.set_mission_run_state(
            &run.id,
            status,
            "terminal",
            unstopped.as_deref().or(failure_reason.as_deref()),
        )?;
        Ok(changed)
    }

    fn mission_completion_selected(
        &self,
        run: &MissionRunView,
        mission: &MissionSpec,
        views: &HashMap<&str, &crate::model::StepRunView>,
    ) -> Result<bool> {
        let Some(completion) = &mission.completion else {
            return Ok(false);
        };
        match completion {
            crate::model::CompletionSpec::AllStepsExhausted => Ok(flatten_mission_steps(mission)
                .into_iter()
                .filter(|step| !step.spec.finally)
                .all(|step| {
                    views.get(step.spec.path.as_str()).is_some_and(|view| {
                        view.status == "completed"
                            || view.status == "cancelled"
                            || (view.status == "failed" && view.attempt >= step.spec.retry.attempts)
                    })
                })),
            crate::model::CompletionSpec::Dependencies { dependencies } => {
                let variables = crate::store::mission_run_variables(run, &run.revision);
                for dependency in dependencies {
                    let holds = match dependency {
                        DependencySpec::Step { step, state } => views
                            .get(step.as_str())
                            .is_some_and(|view| match state.as_str() {
                                "completed" => view.status == "completed",
                                "failed" => view.status == "failed",
                                "terminal" => matches!(
                                    view.status.as_str(),
                                    "completed" | "failed" | "cancelled"
                                ),
                                _ => false,
                            }),
                        DependencySpec::Predicate { gate } => matches!(
                            self.evaluate_context_gate(
                                run,
                                &run.subject,
                                &mission.id,
                                &mission.revision,
                                1,
                                gate,
                                &variables,
                            )?,
                            GateOutcome::Pass
                        ),
                    };
                    if !holds {
                        return Ok(false);
                    }
                }
                Ok(true)
            }
        }
    }

    fn produced_mission_holds(
        &self,
        step: &StepSpec,
        view: &crate::model::StepRunView,
    ) -> Result<bool> {
        let Some(expected) = &step.produces_mission else {
            return Ok(true);
        };
        let Some(output) =
            self.store
                .mission_output(&view.subject, view.attempt, &view.definition_hash)?
        else {
            return Ok(false);
        };
        if output
            .mission
            .strip_prefix("mission/")
            .unwrap_or(&output.mission)
            != expected
        {
            return Ok(false);
        }
        Ok(self
            .store
            .mission_spec(expected, Some(&output.revision))?
            .is_some_and(|mission| mission.state == MissionState::Ready))
    }

    fn evaluate_used_mission(
        &self,
        run: &MissionRunView,
        step: &RuntimeStep<'_>,
        view: &crate::model::StepRunView,
        views: &HashMap<&str, &crate::model::StepRunView>,
    ) -> Result<(bool, UsedMissionOutcome)> {
        let (mission, revision) = match step
            .spec
            .uses_mission
            .as_ref()
            .expect("a used mission was checked")
        {
            UsedMissionSpec::Revision { mission, revision } => (mission.clone(), revision.clone()),
            UsedMissionSpec::StepOutput { step: producer } => {
                let path = if step.dependency_prefix.is_empty() {
                    producer.clone()
                } else {
                    format!("{}/{}", step.dependency_prefix, producer)
                };
                let Some(producer) = views.get(path.as_str()).copied() else {
                    return Ok((false, UsedMissionOutcome::Pending));
                };
                let Some(output) = self.store.mission_output(
                    &producer.subject,
                    producer.attempt,
                    &producer.definition_hash,
                )?
                else {
                    return Ok((false, UsedMissionOutcome::Pending));
                };
                (
                    output
                        .mission
                        .strip_prefix("mission/")
                        .unwrap_or(&output.mission)
                        .to_owned(),
                    output.revision,
                )
            }
        };
        let Some(selected) = self.store.mission_spec(&mission, Some(&revision))? else {
            return Ok((
                false,
                UsedMissionOutcome::Failed(format!(
                    "the exact used mission `mission/{mission}@{revision}` is unavailable"
                )),
            ));
        };
        if selected.state != MissionState::Ready {
            return Ok((
                false,
                UsedMissionOutcome::Failed(format!(
                    "the exact used mission `mission/{mission}@{revision}` is not ready"
                )),
            ));
        }
        let (child, changed) =
            if let Some(child) = self.store.mission_run_for_parent_step(&view.subject)? {
                (child, false)
            } else {
                let selector = step_run_selector(view);
                let child = match self.store.create_child_mission_run(
                    &MissionRunRequest {
                        mission: mission.clone(),
                        revision: Some(revision.clone()),
                        workspace: run.workspace.clone(),
                        requester: Some(run.requester.clone()),
                        mode: Some(run.mode.clone()),
                        inputs: BTreeMap::new(),
                        idempotency_key: format!(
                            "uses-mission:{}:{}:mission/{mission}@{revision}",
                            view.subject, view.attempt
                        ),
                    },
                    run,
                    &view.subject,
                    Some(&selector),
                ) {
                    Ok(child) => child,
                    Err(error) if error.code == "mission-run-capacity" => {
                        return Ok((false, UsedMissionOutcome::Pending));
                    }
                    Err(error) => return Err(error.into()),
                };
                (child, true)
            };
        if child.mission != format!("mission/{mission}") || child.revision != revision {
            return Ok((
                changed,
                UsedMissionOutcome::Failed(
                    "the step already started a different exact mission revision".into(),
                ),
            ));
        }
        let outcome = match child.status.as_str() {
            "completed" => UsedMissionOutcome::Completed,
            "failed" | "cancelled" => UsedMissionOutcome::Failed(format!(
                "the used mission run `{}` is {}",
                child.subject, child.status
            )),
            _ => UsedMissionOutcome::Pending,
        };
        Ok((changed, outcome))
    }

    fn evaluate_loop_step(
        &self,
        run: &MissionRunView,
        step: &RuntimeStep<'_>,
        view: &crate::model::StepRunView,
        loop_spec: &LoopSpec,
    ) -> Result<bool> {
        let loop_subject = format!(
            "loop-run/{}/{}",
            run.generation
                .strip_prefix("run-generation/")
                .unwrap_or(&run.generation),
            loop_spec.path
        );
        let mut variables = run_variables(run, step, view);
        variables.insert("ST_LOOP_ROUND".into(), view.attempt.to_string());
        variables.insert("loop.round".into(), view.attempt.to_string());
        let prior_feedback = self
            .store
            .claims_for(&loop_subject, Some("loop.round-result"))?
            .last()
            .and_then(|claim| claim.body.pointer("/fields/feedback"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned();
        variables.insert("ST_LOOP_FEEDBACK".into(), prior_feedback.clone());
        variables.insert("loop.feedback".into(), prior_feedback.clone());
        variables.insert("ST_LOOP_ITEM_ID".into(), String::new());
        // Every pass enters here. A later write in the same round (a gate wait, a winner, a
        // reschedule) already says the round is running, so a bare entry claim would only
        // replace it, and the next pass would write that later claim again.
        let round_running = self
            .store
            .latest_claim(&loop_subject, Some("loop.state"))?
            .is_some_and(|claim| {
                claim.body.pointer("/fields/status").and_then(Value::as_str) == Some("running")
                    && claim.body.pointer("/fields/round").and_then(Value::as_u64)
                        == Some(u64::from(view.attempt))
            });
        if !round_running {
            self.record_once(
                &loop_subject,
                "loop.state",
                BTreeMap::from([
                    ("status".into(), Value::String("running".into())),
                    ("round".into(), Value::from(view.attempt)),
                ]),
            )?;
        }
        let first_execution = self.loop_first_execution_at(run, view)?;
        let timed_out = loop_spec.timeout_ms.is_some_and(|timeout| {
            first_execution
                .is_some_and(|started| now_ms().saturating_sub(started) >= timeout as u128)
        });
        if timed_out {
            return self.finish_exhausted_loop(
                run,
                view,
                loop_spec,
                &loop_subject,
                &variables,
                "the loop timeout expired",
            );
        }
        if loop_spec.for_each.is_some() {
            return self.evaluate_for_each_loop(run, view, loop_spec, &loop_subject, &variables);
        }
        if loop_spec.candidates.is_some() {
            return self.evaluate_candidate_loop(run, view, loop_spec, &loop_subject, &variables);
        }
        let dispatch = self.loop_dispatch_count(&loop_subject, view.attempt, None, None)?;
        let base_key = format!("loop-round:{}:{}", view.subject, view.attempt);
        let key = if dispatch == 0 {
            base_key
        } else {
            format!("{base_key}:dispatch-{dispatch}")
        };
        let expected = self.store.mission_run_subject_for_idempotency_key(&key);
        let existed = self.store.mission_run(&expected)?.is_some();
        let mut inputs: BTreeMap<String, String> = run
            .inputs
            .iter()
            .map(|(name, input)| {
                let value = match input.kind {
                    MissionInputKind::Text => input.value.clone(),
                    MissionInputKind::Resource => match (&input.subject, &input.claim_id) {
                        (Some(subject), Some(claim)) => format!("{subject}@{claim}"),
                        _ => input.value.clone(),
                    },
                };
                (name.clone(), value)
            })
            .collect();
        inputs.insert(LOOP_ROUND_INPUT.into(), view.attempt.to_string());
        inputs.insert(LOOP_FEEDBACK_INPUT.into(), prior_feedback);
        inputs.insert(LOOP_ITEM_INPUT.into(), "null".into());
        inputs.insert(CANDIDATE_INDEX_INPUT.into(), String::new());
        let child = if existed {
            self.store
                .mission_run(&expected)?
                .context("the existing loop round disappeared")?
        } else {
            match self.store.create_child_mission_run(
                &MissionRunRequest {
                    mission: loop_spec.round.id.clone(),
                    revision: Some(loop_spec.round.revision.clone()),
                    workspace: run.workspace.clone(),
                    requester: Some(run.requester.clone()),
                    mode: Some(run.mode.clone()),
                    inputs,
                    idempotency_key: key,
                },
                run,
                &view.subject,
                None,
            ) {
                Ok(_) => return Ok(true),
                Err(error) if error.code == "mission-run-capacity" => return Ok(false),
                Err(error) => return Err(error.into()),
            }
        };
        match child.status.as_str() {
            "running" | "standing" | "blocked" => Ok(false),
            "failed" | "cancelled" => {
                if self.loop_child_timed_out_without_claim(&child)? {
                    return self.reschedule_unclaimed_loop_child(
                        &loop_subject,
                        view.attempt,
                        dispatch,
                        &child,
                        None,
                        None,
                    );
                }
                let token_usage = self.mission_run_token_usage(&child)?;
                let structural = self.loop_child_failure_is_structural(&child)?;
                let failure_reason = if structural {
                    "the loop round mission had a structural failure"
                } else {
                    "the loop round mission failed"
                };
                self.record_loop_round(
                    &loop_subject,
                    view.attempt,
                    &child,
                    "failed",
                    &BTreeMap::new(),
                    None,
                    None,
                    None,
                    token_usage,
                    Some(failure_reason),
                )?;
                if structural {
                    self.record_once(
                        &loop_subject,
                        "loop.state",
                        BTreeMap::from([
                            ("status".into(), Value::String("failed".into())),
                            ("round".into(), Value::from(view.attempt)),
                            ("reason".into(), Value::String(failure_reason.into())),
                        ]),
                    )?;
                    return self.store.set_step_state(
                        &view.subject,
                        "cancelled",
                        Some(failure_reason),
                    );
                }
                if self.repeated_loop_failures(&loop_subject)?
                    >= loop_spec.stop.repeated_failure.unwrap_or(u32::MAX)
                {
                    return self.finish_exhausted_loop(
                        run,
                        view,
                        loop_spec,
                        &loop_subject,
                        &variables,
                        "the repeated-failure limit was reached",
                    );
                }
                if view.attempt >= loop_spec.max_rounds {
                    self.finish_exhausted_loop(
                        run,
                        view,
                        loop_spec,
                        &loop_subject,
                        &variables,
                        "the last loop round failed",
                    )
                } else {
                    self.store.set_step_state(
                        &view.subject,
                        "failed",
                        Some("the loop round failed and another round is available"),
                    )
                }
            }
            "completed" => {
                let metrics = match self.evaluate_loop_metrics(
                    run,
                    view,
                    loop_spec,
                    &loop_subject,
                    &variables,
                ) {
                    Ok(Some(metrics)) => metrics,
                    Ok(None) => return Ok(false),
                    Err(error) => {
                        return self.store.set_step_state(
                            &view.subject,
                            "cancelled",
                            Some(&format!("the loop metric failed: {error:#}")),
                        );
                    }
                };
                let keep = self.loop_round_improves(&loop_subject, loop_spec, &metrics)?;
                let feedback = self.write_loop_feedback(
                    &loop_subject,
                    view.attempt,
                    &child,
                    &metrics,
                    keep,
                    None,
                )?;
                match self
                    .evaluate_loop_branch(run, view, loop_spec, keep, &feedback, None, None)?
                {
                    LoopBranchOutcome::Pending => return Ok(false),
                    LoopBranchOutcome::Failed(reason) => {
                        self.record_loop_round(
                            &loop_subject,
                            view.attempt,
                            &child,
                            "failed",
                            &metrics,
                            Some(&feedback),
                            None,
                            None,
                            self.mission_run_token_usage(&child)?,
                            Some(&reason),
                        )?;
                        return self.store.set_step_state(
                            &view.subject,
                            "cancelled",
                            Some(&reason),
                        );
                    }
                    LoopBranchOutcome::Completed => {}
                }
                let round_status = if keep { "completed" } else { "discarded" };
                let token_usage = self.mission_run_token_usage(&child)?;
                self.record_loop_round(
                    &loop_subject,
                    view.attempt,
                    &child,
                    round_status,
                    &metrics,
                    Some(&feedback),
                    None,
                    None,
                    token_usage,
                    None,
                )?;
                let (best_round, best_metrics) = self.loop_best(&loop_subject, loop_spec)?;
                self.record_once(
                    &loop_subject,
                    "loop.state",
                    BTreeMap::from([
                        ("status".into(), Value::String("running".into())),
                        ("round".into(), Value::from(view.attempt)),
                        ("best_round".into(), Value::from(best_round)),
                        ("best_metrics".into(), serde_json::to_value(&best_metrics)?),
                        ("feedback".into(), Value::String(feedback.clone())),
                    ]),
                )?;
                let mut passed = !loop_spec.until.is_empty();
                let mut waiting = false;
                for gate in &loop_spec.until {
                    match self.evaluate_context_gate(
                        run,
                        &loop_subject,
                        &loop_spec.id,
                        &view.definition_hash,
                        view.attempt,
                        gate,
                        &variables,
                    )? {
                        GateOutcome::Pass => {}
                        GateOutcome::Pending
                            if matches!(
                                gate,
                                GateSpec::Mechanical { .. }
                                    | GateSpec::Llm { .. }
                                    | GateSpec::Human { .. }
                            ) =>
                        {
                            waiting = true;
                            passed = false;
                            break;
                        }
                        // A broken gate holds the loop for a revision.
                        GateOutcome::Broken(_) => {
                            waiting = true;
                            passed = false;
                            break;
                        }
                        GateOutcome::Pending | GateOutcome::NotYet | GateOutcome::Fail(_) => {
                            passed = false
                        }
                    }
                }
                if waiting {
                    return Ok(false);
                }
                if passed {
                    self.record_once(
                        &loop_subject,
                        "loop.state",
                        BTreeMap::from([
                            ("status".into(), Value::String("completed".into())),
                            ("round".into(), Value::from(view.attempt)),
                            ("best_round".into(), Value::from(best_round)),
                            ("best_metrics".into(), serde_json::to_value(&best_metrics)?),
                            ("feedback".into(), Value::String(feedback)),
                        ]),
                    )?;
                    return self.store.set_step_state(&view.subject, "completed", None);
                }
                if self.loop_stop_reason(&loop_subject, loop_spec)?.is_some() {
                    let reason = self
                        .loop_stop_reason(&loop_subject, loop_spec)?
                        .expect("the stop reason was present");
                    return self.finish_exhausted_loop(
                        run,
                        view,
                        loop_spec,
                        &loop_subject,
                        &variables,
                        &reason,
                    );
                }
                if view.attempt >= loop_spec.max_rounds {
                    self.finish_exhausted_loop(
                        run,
                        view,
                        loop_spec,
                        &loop_subject,
                        &variables,
                        "the loop reached max-rounds without satisfying until",
                    )
                } else {
                    self.store.set_step_state(
                        &view.subject,
                        "failed",
                        Some("the loop exit gates did not pass"),
                    )
                }
            }
            _ => Ok(false),
        }
    }

    fn evaluate_loop_metrics(
        &self,
        run: &MissionRunView,
        view: &crate::model::StepRunView,
        loop_spec: &LoopSpec,
        loop_subject: &str,
        variables: &BTreeMap<String, String>,
    ) -> Result<Option<BTreeMap<String, f64>>> {
        let mut values = BTreeMap::new();
        for metric in &loop_spec.metrics {
            let value = match &metric.source {
                MetricSource::Gate { gate } => {
                    let gate = loop_spec
                        .until
                        .iter()
                        .find(|candidate| crate::graph::gate_name(candidate) == gate)
                        .with_context(|| {
                            format!("metric `{}` names an unavailable gate", metric.name)
                        })?;
                    match self.evaluate_context_gate(
                        run,
                        loop_subject,
                        &loop_spec.id,
                        &view.definition_hash,
                        view.attempt,
                        gate,
                        variables,
                    )? {
                        GateOutcome::Pass => 1.0,
                        GateOutcome::Pending
                            if matches!(
                                gate,
                                GateSpec::Mechanical { .. }
                                    | GateSpec::Llm { .. }
                                    | GateSpec::Human { .. }
                            ) =>
                        {
                            return Ok(None);
                        }
                        GateOutcome::Broken(_) => return Ok(None),
                        GateOutcome::Pending | GateOutcome::NotYet | GateOutcome::Fail(_) => 0.0,
                    }
                }
                MetricSource::Field { subject, path } => {
                    let subject = crate::mission::interpolate(subject, variables)?;
                    let path = crate::mission::interpolate(path, variables)?;
                    let Some(actual) = self.subject_value(&subject)? else {
                        return Ok(None);
                    };
                    actual_field(&actual, &path)
                        .and_then(Value::as_f64)
                        .filter(|value| value.is_finite())
                        .with_context(|| {
                            format!(
                                "metric `{}` did not find a finite number at `{path}` on `{subject}`",
                                metric.name
                            )
                        })?
                }
                MetricSource::Exec { .. } => {
                    let Some(value) =
                        self.evaluate_exec_metric(run, view, loop_subject, metric, variables)?
                    else {
                        return Ok(None);
                    };
                    value
                }
            };
            values.insert(metric.name.clone(), value);
        }
        Ok(Some(values))
    }

    fn evaluate_exec_metric(
        &self,
        run: &MissionRunView,
        view: &crate::model::StepRunView,
        loop_subject: &str,
        metric: &crate::model::MetricSpec,
        variables: &BTreeMap<String, String>,
    ) -> Result<Option<f64>> {
        let MetricSource::Exec {
            command,
            host,
            workspace,
            environment,
            time_limit_ms,
        } = &metric.source
        else {
            unreachable!("the caller selected an exec metric")
        };
        let digest = hex::encode(sha2::Sha256::digest(
            format!("{loop_subject}:{}:{}", view.attempt, metric.name).as_bytes(),
        ));
        let subject = format!("gate-operation/loop-metric/{}", &digest[..32]);
        if let Some(result) = self.store.latest_claim(&subject, Some("gate.result"))? {
            return result
                .body
                .pointer("/fields/value")
                .and_then(Value::as_f64)
                .map(Some)
                .context("a completed loop metric has no numeric value");
        }
        let command = crate::mission::interpolate(command, variables)?;
        let host = crate::mission::interpolate(host, variables)?;
        let mut workspace = crate::mission::interpolate(workspace, variables)?;
        if Path::new(&workspace).is_relative() {
            workspace = Path::new(&run.workspace)
                .join(&workspace)
                .to_string_lossy()
                .into_owned();
        }
        let mut environment = environment
            .iter()
            .map(|(name, value)| Ok((name.clone(), crate::mission::interpolate(value, variables)?)))
            .collect::<Result<BTreeMap<_, _>>>()?;
        environment.extend(variables.clone());
        if host != self.host {
            return Ok(None);
        }
        let runtime_id = subject.replace('/', ".");
        if let Some(request) = self.store.latest_claim(&subject, Some("gate.requested"))? {
            if now_ms().saturating_sub(request.accepted_at_unix_ms) >= *time_limit_ms as u128 {
                self.stop_gate_runner(&subject, true)?;
                anyhow::bail!("metric `{}` exceeded {}ms", metric.name, time_limit_ms);
            }
            smallclaims::touched::note_read(|| format!("exec:{runtime_id}"));
            match self.runtime.observe_exec(&runtime_id)? {
                Some(observation) if observation.status == "running" => {
                    self.arm_gate_poll(&runtime_id);
                    return Ok(None);
                }
                Some(observation) if observation.status == "exited" => {
                    if self.gate_exit_code(&subject, &observation)? != Some(0) {
                        anyhow::bail!("metric `{}` exited unsuccessfully", metric.name);
                    }
                    let log = self
                        .runtime
                        .read_exec_log(&runtime_id)?
                        .context("the metric command has no output")?;
                    let value = log
                        .trim()
                        .parse::<f64>()
                        .ok()
                        .filter(|value| value.is_finite())
                        .context("the metric command did not print one finite number")?;
                    self.record_once(
                        &subject,
                        "gate.result",
                        BTreeMap::from([
                            ("verdict".into(), Value::String("pass".into())),
                            ("value".into(), Value::from(value)),
                        ]),
                    )?;
                    return Ok(Some(value));
                }
                _ => {
                    self.arm_gate_poll(&runtime_id);
                    return Ok(None);
                }
            }
        }
        self.record_once(
            &subject,
            "gate.requested",
            BTreeMap::from([
                ("status".into(), Value::String("requested".into())),
                ("runner".into(), Value::String("loop-metric".into())),
                ("owner".into(), Value::String(view.subject.clone())),
            ]),
        )?;
        let member = MemberSpec {
            kind: MemberKind::Exec,
            host,
            runtime_id,
            workspace: workspace.clone(),
            workspace_create: false,
            cwd: workspace,
            terminal: false,
            launch: LaunchSpec::Shell(command),
            environment,
            tags: BTreeMap::new(),
            display_name: Some(format!("loop metric {}", metric.name)),
            lifecycle: MemberLifecycle::Service,
            restart: RestartType::Never,
            restart_intensity: RestartIntensity::default(),
            shutdown_timeout_ms: 5_000,
            driver: Some("loop-metric".into()),
        };
        self.perform_start(
            &DesiredSubject {
                subject: subject.clone(),
                kind: "gate".into(),
                desired: Value::Null,
                member: Some(member.clone()),
                owner_run: Some(run.subject.clone()),
                owner_generation: Some(run.generation.clone()),
                owner_step: Some(view.subject.clone()),
            },
            &member,
            "the loop metric was requested",
        )?;
        self.arm_gate_poll(&member.runtime_id);
        Ok(None)
    }

    fn loop_round_improves(
        &self,
        loop_subject: &str,
        loop_spec: &LoopSpec,
        metrics: &BTreeMap<String, f64>,
    ) -> Result<bool> {
        let Some(metric_name) = &loop_spec.keep_metric else {
            return Ok(true);
        };
        let metric = loop_spec
            .metrics
            .iter()
            .find(|metric| &metric.name == metric_name)
            .context("the keep metric disappeared")?;
        let Some(current) = metrics.get(metric_name) else {
            anyhow::bail!("the keep metric has no current value");
        };
        let prior = self
            .store
            .claims_for(loop_subject, Some("loop.round-result"))?
            .into_iter()
            .filter(|claim| {
                claim.body.pointer("/fields/status").and_then(Value::as_str) == Some("completed")
            })
            .filter_map(|claim| {
                claim
                    .body
                    .pointer(&format!("/fields/metrics/{metric_name}"))
                    .and_then(Value::as_f64)
            })
            .next_back();
        Ok(prior.is_none_or(|prior| {
            if metric.direction == "higher" {
                current - prior >= metric.min_improvement
            } else {
                prior - current >= metric.min_improvement
            }
        }))
    }

    fn write_loop_feedback(
        &self,
        loop_subject: &str,
        round: u32,
        child: &MissionRunView,
        metrics: &BTreeMap<String, f64>,
        keep: bool,
        candidate: Option<u32>,
    ) -> Result<String> {
        let suffix = candidate.map_or_else(String::new, |value| format!("/candidate-{value}"));
        let name = format!(
            "doc/loop-feedback/{}/{round}{suffix}",
            loop_subject
                .strip_prefix("loop-run/")
                .unwrap_or(loop_subject),
        );
        let body = serde_json::to_vec_pretty(&serde_json::json!({
            "loop": loop_subject,
            "round": round,
            "mission_run": child.subject,
            "metrics": metrics,
            "decision": if keep { "keep" } else { "discard" },
            "candidate": candidate,
        }))?;
        let document = self.store.put_document(
            &name,
            &body,
            &None,
            &format!("loop-feedback:{loop_subject}:{round}:{candidate:?}"),
        )?;
        Ok(format!("{}@{}", document.name, document.hash))
    }

    #[allow(clippy::too_many_arguments)]
    fn evaluate_loop_branch(
        &self,
        run: &MissionRunView,
        view: &crate::model::StepRunView,
        loop_spec: &LoopSpec,
        keep: bool,
        feedback: &str,
        candidate: Option<u32>,
        item: Option<&Value>,
    ) -> Result<LoopBranchOutcome> {
        let branch = if keep {
            loop_spec.on_keep.as_deref()
        } else {
            loop_spec.on_discard.as_deref()
        };
        let Some(branch) = branch else {
            return Ok(LoopBranchOutcome::Completed);
        };
        let label = if keep { "keep" } else { "discard" };
        let key = format!(
            "loop-{label}:{}:{}:{}",
            view.subject,
            view.attempt,
            candidate.map_or_else(|| "round".into(), |value| format!("candidate-{value}"))
        );
        let subject = self.store.mission_run_subject_for_idempotency_key(&key);
        if let Some(child) = self.store.mission_run(&subject)? {
            return Ok(match child.status.as_str() {
                "completed" => LoopBranchOutcome::Completed,
                "failed" | "cancelled" => LoopBranchOutcome::Failed(format!(
                    "the loop {label} branch failed in `{}`",
                    child.subject
                )),
                _ => LoopBranchOutcome::Pending,
            });
        }
        let mut inputs = self.child_loop_inputs(run);
        inputs.insert(LOOP_ROUND_INPUT.into(), view.attempt.to_string());
        inputs.insert(LOOP_FEEDBACK_INPUT.into(), feedback.into());
        inputs.insert(
            CANDIDATE_INDEX_INPUT.into(),
            candidate.map_or_else(String::new, |value| value.to_string()),
        );
        inputs.insert(
            LOOP_ITEM_INPUT.into(),
            item.map_or_else(|| "null".into(), Value::to_string),
        );
        self.store.create_child_mission_run(
            &MissionRunRequest {
                mission: branch.id.clone(),
                revision: Some(branch.revision.clone()),
                workspace: run.workspace.clone(),
                requester: Some(run.requester.clone()),
                mode: Some(run.mode.clone()),
                inputs,
                idempotency_key: key,
            },
            run,
            &view.subject,
            None,
        )?;
        Ok(LoopBranchOutcome::Pending)
    }

    fn child_loop_inputs(&self, run: &MissionRunView) -> BTreeMap<String, String> {
        let mut inputs = run
            .inputs
            .iter()
            .filter(|(name, _)| !name.starts_with("__st3_"))
            .map(|(name, input)| {
                let value = match input.kind {
                    MissionInputKind::Text => input.value.clone(),
                    MissionInputKind::Resource => match (&input.subject, &input.claim_id) {
                        (Some(subject), Some(claim)) => format!("{subject}@{claim}"),
                        _ => input.value.clone(),
                    },
                };
                (name.clone(), value)
            })
            .collect::<BTreeMap<_, _>>();
        inputs.insert(LOOP_ROUND_INPUT.into(), String::new());
        inputs.insert(LOOP_FEEDBACK_INPUT.into(), String::new());
        inputs.insert(LOOP_ITEM_INPUT.into(), "null".into());
        inputs.insert(CANDIDATE_INDEX_INPUT.into(), String::new());
        inputs
    }

    #[allow(clippy::too_many_arguments)]
    fn ensure_loop_child(
        &self,
        run: &MissionRunView,
        view: &crate::model::StepRunView,
        mission: &MissionSpec,
        key: String,
        round: u32,
        feedback: &str,
        item: Option<&Value>,
        candidate: Option<u32>,
    ) -> Result<(MissionRunView, bool)> {
        let subject = self.store.mission_run_subject_for_idempotency_key(&key);
        if let Some(child) = self.store.mission_run(&subject)? {
            return Ok((child, false));
        }
        let mut inputs = self.child_loop_inputs(run);
        inputs.insert(LOOP_ROUND_INPUT.into(), round.to_string());
        inputs.insert(LOOP_FEEDBACK_INPUT.into(), feedback.into());
        inputs.insert(
            LOOP_ITEM_INPUT.into(),
            item.map_or_else(|| "null".into(), Value::to_string),
        );
        inputs.insert(
            CANDIDATE_INDEX_INPUT.into(),
            candidate.map_or_else(String::new, |value| value.to_string()),
        );
        let child = self.store.create_child_mission_run(
            &MissionRunRequest {
                mission: mission.id.clone(),
                revision: Some(mission.revision.clone()),
                workspace: run.workspace.clone(),
                requester: Some(run.requester.clone()),
                mode: Some(run.mode.clone()),
                inputs,
                idempotency_key: key,
            },
            run,
            &view.subject,
            None,
        )?;
        Ok((child, true))
    }

    fn loop_result_claim(
        &self,
        loop_subject: &str,
        round: u32,
        candidate: Option<u32>,
    ) -> Result<Option<crate::model::ClaimRecord>> {
        Ok(self
            .store
            .claims_for(loop_subject, Some("loop.round-result"))?
            .into_iter()
            .find(|claim| {
                claim.body.pointer("/fields/round").and_then(Value::as_u64)
                    == Some(u64::from(round))
                    && claim
                        .body
                        .pointer("/fields/candidate")
                        .and_then(Value::as_u64)
                        == candidate.map(u64::from)
            }))
    }

    fn evaluate_for_each_loop(
        &self,
        run: &MissionRunView,
        view: &crate::model::StepRunView,
        loop_spec: &LoopSpec,
        loop_subject: &str,
        base_variables: &BTreeMap<String, String>,
    ) -> Result<bool> {
        let for_each = loop_spec
            .for_each
            .as_ref()
            .expect("the caller selected a for-each loop");
        let snapshot = self
            .store
            .claims_for(loop_subject, Some("loop.state"))?
            .into_iter()
            .find_map(|claim| claim.body.pointer("/fields/items").cloned());
        let items = if let Some(Value::Array(items)) = snapshot {
            items
        } else {
            let resource = crate::mission::interpolate(&for_each.resource, base_variables)?;
            let field = crate::mission::interpolate(&for_each.field, base_variables)?;
            let Some(actual) = self.subject_value(&resource)? else {
                return Ok(false);
            };
            let Some(items) = actual_field(&actual, &field)
                .and_then(Value::as_array)
                .cloned()
            else {
                return self.store.set_step_state(
                    &view.subject,
                    "cancelled",
                    Some("a for-each field must contain an array"),
                );
            };
            if items.len() > 100 || items.len() > loop_spec.max_rounds as usize {
                return self.store.set_step_state(
                    &view.subject,
                    "cancelled",
                    Some("the for-each snapshot exceeds max-rounds or 100 items"),
                );
            }
            let mut ids = BTreeSet::new();
            for item in &items {
                let Some(id) = item.get("id").and_then(Value::as_str) else {
                    return self.store.set_step_state(
                        &view.subject,
                        "cancelled",
                        Some("each for-each item needs a string id"),
                    );
                };
                if !ids.insert(id.to_owned()) {
                    return self.store.set_step_state(
                        &view.subject,
                        "cancelled",
                        Some("the for-each snapshot contains duplicate item IDs"),
                    );
                }
            }
            self.record_once(
                loop_subject,
                "loop.state",
                BTreeMap::from([
                    ("status".into(), Value::String("running".into())),
                    ("round".into(), Value::from(0)),
                    ("items".into(), Value::Array(items.clone())),
                ]),
            )?;
            return Ok(true);
        };
        let mut active = 0_u32;
        let mut completed = 0_usize;
        for (index, item) in items.iter().enumerate() {
            let round = index as u32 + 1;
            if self.loop_result_claim(loop_subject, round, None)?.is_some() {
                completed += 1;
                continue;
            }
            let Some(id) = item.get("id").and_then(Value::as_str) else {
                return self.store.set_step_state(
                    &view.subject,
                    "cancelled",
                    Some("the stored for-each item has no ID"),
                );
            };
            let dispatch = self.loop_dispatch_count(loop_subject, round, None, Some(id))?;
            let base_key = format!("loop-item:{}:{id}", view.subject);
            let key = if dispatch == 0 {
                base_key
            } else {
                format!("{base_key}:dispatch-{dispatch}")
            };
            let subject = self.store.mission_run_subject_for_idempotency_key(&key);
            if let Some(child) = self.store.mission_run(&subject)? {
                match child.status.as_str() {
                    "running" | "standing" | "blocked" => active += 1,
                    "failed" | "cancelled" => {
                        if self.loop_child_timed_out_without_claim(&child)? {
                            return self.reschedule_unclaimed_loop_child(
                                loop_subject,
                                round,
                                dispatch,
                                &child,
                                None,
                                Some(id),
                            );
                        }
                        return self.store.set_step_state(
                            &view.subject,
                            "cancelled",
                            Some(&format!("the for-each item `{id}` failed")),
                        );
                    }
                    "completed" => {
                        let mut item_view = view.clone();
                        item_view.attempt = round;
                        let mut variables = base_variables.clone();
                        variables.insert("ST_LOOP_ROUND".into(), round.to_string());
                        variables.insert("loop.round".into(), round.to_string());
                        if let Some(fields) = item.as_object() {
                            for (name, value) in fields {
                                variables.insert(
                                    format!("loop.item.{name}"),
                                    value
                                        .as_str()
                                        .map(str::to_owned)
                                        .unwrap_or_else(|| value.to_string()),
                                );
                            }
                        }
                        variables.insert("ST_LOOP_ITEM_ID".into(), id.into());
                        let metrics = match self.evaluate_loop_metrics(
                            run,
                            &item_view,
                            loop_spec,
                            &format!("{loop_subject}/item/{id}"),
                            &variables,
                        ) {
                            Ok(Some(metrics)) => metrics,
                            Ok(None) => return Ok(false),
                            Err(error) => {
                                return self.store.set_step_state(
                                    &view.subject,
                                    "cancelled",
                                    Some(&format!("the loop metric failed: {error:#}")),
                                );
                            }
                        };
                        let feedback = self.write_loop_feedback(
                            loop_subject,
                            round,
                            &child,
                            &metrics,
                            true,
                            None,
                        )?;
                        match self.evaluate_loop_branch(
                            run,
                            &item_view,
                            loop_spec,
                            true,
                            &feedback,
                            None,
                            Some(item),
                        )? {
                            LoopBranchOutcome::Pending => return Ok(false),
                            LoopBranchOutcome::Failed(reason) => {
                                return self.store.set_step_state(
                                    &view.subject,
                                    "cancelled",
                                    Some(&reason),
                                );
                            }
                            LoopBranchOutcome::Completed => {}
                        }
                        self.record_loop_round(
                            loop_subject,
                            round,
                            &child,
                            "completed",
                            &metrics,
                            Some(&feedback),
                            None,
                            Some(item),
                            self.mission_run_token_usage(&child)?,
                            None,
                        )?;
                        if let Some(reason) = self.loop_stop_reason(loop_subject, loop_spec)? {
                            return self.finish_exhausted_loop(
                                run,
                                view,
                                loop_spec,
                                loop_subject,
                                &variables,
                                &reason,
                            );
                        }
                        completed += 1;
                    }
                    _ => {}
                }
                continue;
            }
            if active < for_each.max_parallel {
                self.ensure_loop_child(
                    run,
                    view,
                    &loop_spec.round,
                    key,
                    round,
                    "",
                    Some(item),
                    None,
                )?;
                active += 1;
            }
        }
        if completed != items.len() {
            return Ok(false);
        }
        self.record_once(
            loop_subject,
            "loop.state",
            BTreeMap::from([
                ("status".into(), Value::String("completed".into())),
                ("round".into(), Value::from(items.len() as u64)),
                ("items".into(), Value::Array(items)),
            ]),
        )?;
        self.store.set_step_state(&view.subject, "completed", None)
    }

    fn evaluate_candidate_loop(
        &self,
        run: &MissionRunView,
        view: &crate::model::StepRunView,
        loop_spec: &LoopSpec,
        loop_subject: &str,
        base_variables: &BTreeMap<String, String>,
    ) -> Result<bool> {
        let candidates = loop_spec
            .candidates
            .as_ref()
            .expect("the caller selected a candidate loop");
        let mut active = 0_u32;
        let mut completed = Vec::new();
        for candidate in 1..=candidates.count {
            if let Some(result) =
                self.loop_result_claim(loop_subject, view.attempt, Some(candidate))?
            {
                if result
                    .body
                    .pointer("/fields/status")
                    .and_then(Value::as_str)
                    != Some("failed")
                {
                    completed.push((candidate, result));
                }
                continue;
            }
            let dispatch =
                self.loop_dispatch_count(loop_subject, view.attempt, Some(candidate), None)?;
            let base_key = format!(
                "loop-candidate:{}:{}:{candidate}",
                view.subject, view.attempt
            );
            let key = if dispatch == 0 {
                base_key
            } else {
                format!("{base_key}:dispatch-{dispatch}")
            };
            let subject = self.store.mission_run_subject_for_idempotency_key(&key);
            if let Some(child) = self.store.mission_run(&subject)? {
                match child.status.as_str() {
                    "running" | "standing" | "blocked" => active += 1,
                    "failed" | "cancelled" => {
                        if self.loop_child_timed_out_without_claim(&child)? {
                            return self.reschedule_unclaimed_loop_child(
                                loop_subject,
                                view.attempt,
                                dispatch,
                                &child,
                                Some(candidate),
                                None,
                            );
                        }
                        let structural = self.loop_child_failure_is_structural(&child)?;
                        let reason = if structural {
                            "the candidate mission had a structural failure"
                        } else {
                            "the candidate mission failed"
                        };
                        self.record_loop_round(
                            loop_subject,
                            view.attempt,
                            &child,
                            "failed",
                            &BTreeMap::new(),
                            None,
                            Some(candidate),
                            None,
                            self.mission_run_token_usage(&child)?,
                            Some(reason),
                        )?;
                        if structural {
                            self.record_once(
                                loop_subject,
                                "loop.state",
                                BTreeMap::from([
                                    ("status".into(), Value::String("failed".into())),
                                    ("round".into(), Value::from(view.attempt)),
                                    ("reason".into(), Value::String(reason.into())),
                                ]),
                            )?;
                            return self.store.set_step_state(
                                &view.subject,
                                "cancelled",
                                Some(reason),
                            );
                        }
                    }
                    "completed" => {
                        let mut variables = base_variables.clone();
                        variables.insert("ST_CANDIDATE_INDEX".into(), candidate.to_string());
                        variables.insert("candidate.index".into(), candidate.to_string());
                        let metrics = match self.evaluate_loop_metrics(
                            run,
                            view,
                            loop_spec,
                            &format!(
                                "{loop_subject}/round/{}/candidate/{candidate}",
                                view.attempt
                            ),
                            &variables,
                        ) {
                            Ok(Some(metrics)) => metrics,
                            Ok(None) => return Ok(false),
                            Err(error) => {
                                return self.store.set_step_state(
                                    &view.subject,
                                    "cancelled",
                                    Some(&format!("the candidate metric failed: {error:#}")),
                                );
                            }
                        };
                        let feedback = self.write_loop_feedback(
                            loop_subject,
                            view.attempt,
                            &child,
                            &metrics,
                            true,
                            Some(candidate),
                        )?;
                        self.record_loop_round(
                            loop_subject,
                            view.attempt,
                            &child,
                            "completed",
                            &metrics,
                            Some(&feedback),
                            Some(candidate),
                            None,
                            self.mission_run_token_usage(&child)?,
                            None,
                        )?;
                    }
                    _ => {}
                }
                continue;
            }
            if active < candidates.max_parallel {
                self.ensure_loop_child(
                    run,
                    view,
                    &loop_spec.round,
                    key,
                    view.attempt,
                    "",
                    None,
                    Some(candidate),
                )?;
                active += 1;
            }
        }
        let all_results = self
            .store
            .claims_for(loop_subject, Some("loop.round-result"))?
            .into_iter()
            .filter(|claim| {
                claim.body.pointer("/fields/round").and_then(Value::as_u64)
                    == Some(u64::from(view.attempt))
                    && claim.body.pointer("/fields/candidate").is_some()
            })
            .collect::<Vec<_>>();
        if all_results.len() < candidates.count as usize {
            return Ok(false);
        }
        completed = all_results
            .iter()
            .filter(|&claim| {
                claim.body.pointer("/fields/status").and_then(Value::as_str) == Some("completed")
            })
            .cloned()
            .filter_map(|claim| {
                let candidate = claim
                    .body
                    .pointer("/fields/candidate")
                    .and_then(Value::as_u64)? as u32;
                Some((candidate, claim))
            })
            .collect();
        if completed.is_empty() {
            if let Some(child) = self.loop_result_child(&all_results)? {
                self.record_loop_round(
                    loop_subject,
                    view.attempt,
                    &child,
                    "failed",
                    &BTreeMap::new(),
                    None,
                    None,
                    None,
                    0,
                    Some("all candidate missions failed"),
                )?;
            }
            if self.repeated_loop_failures(loop_subject)?
                >= loop_spec.stop.repeated_failure.unwrap_or(u32::MAX)
            {
                return self.finish_exhausted_loop(
                    run,
                    view,
                    loop_spec,
                    loop_subject,
                    base_variables,
                    "the repeated-failure limit was reached",
                );
            }
            if view.attempt >= loop_spec.max_rounds {
                return self.finish_exhausted_loop(
                    run,
                    view,
                    loop_spec,
                    loop_subject,
                    base_variables,
                    "all candidate missions failed",
                );
            }
            return self.store.set_step_state(
                &view.subject,
                "failed",
                Some("all candidate missions failed"),
            );
        }
        let selection = self.select_loop_candidate(
            run,
            view,
            loop_spec,
            loop_subject,
            base_variables,
            &completed,
        )?;
        let winner = match selection {
            LoopCandidateSelection::Winner(winner) => winner,
            LoopCandidateSelection::Pending => return Ok(false),
            LoopCandidateSelection::NoWinner => {
                if let Some(child) = self.loop_result_child(
                    &completed
                        .iter()
                        .map(|(_, claim)| claim.clone())
                        .collect::<Vec<_>>(),
                )? {
                    self.record_loop_round(
                        loop_subject,
                        view.attempt,
                        &child,
                        "failed",
                        &BTreeMap::new(),
                        None,
                        None,
                        None,
                        0,
                        Some("the candidate selector rejected every candidate"),
                    )?;
                }
                if view.attempt >= loop_spec.max_rounds {
                    return self.finish_exhausted_loop(
                        run,
                        view,
                        loop_spec,
                        loop_subject,
                        base_variables,
                        "the candidate selector rejected every candidate",
                    );
                }
                return self.store.set_step_state(
                    &view.subject,
                    "failed",
                    Some("the candidate selector rejected every candidate"),
                );
            }
        };
        for (candidate, result) in &completed {
            let feedback = result
                .body
                .pointer("/fields/feedback")
                .and_then(Value::as_str)
                .unwrap_or_default();
            match self.evaluate_loop_branch(
                run,
                view,
                loop_spec,
                *candidate == winner,
                feedback,
                Some(*candidate),
                None,
            )? {
                LoopBranchOutcome::Pending => return Ok(false),
                LoopBranchOutcome::Failed(reason) => {
                    return self
                        .store
                        .set_step_state(&view.subject, "cancelled", Some(&reason));
                }
                LoopBranchOutcome::Completed => {}
            }
        }
        let winner_result = completed
            .iter()
            .find(|(candidate, _)| *candidate == winner)
            .map(|(_, claim)| claim)
            .expect("the selected candidate exists");
        let best_metrics = winner_result
            .body
            .pointer("/fields/metrics")
            .cloned()
            .unwrap_or_else(|| Value::Object(Default::default()));
        let winner_feedback = winner_result
            .body
            .pointer("/fields/feedback")
            .and_then(Value::as_str);
        let winner_child = self
            .loop_result_child(std::slice::from_ref(winner_result))?
            .context("the selected candidate mission disappeared")?;
        let winner_metrics = best_metrics
            .as_object()
            .map(|values| {
                values
                    .iter()
                    .filter_map(|(name, value)| value.as_f64().map(|value| (name.clone(), value)))
                    .collect::<BTreeMap<_, _>>()
            })
            .unwrap_or_default();
        self.record_loop_round(
            loop_subject,
            view.attempt,
            &winner_child,
            "completed",
            &winner_metrics,
            winner_feedback,
            None,
            None,
            0,
            Some(&format!("candidate {winner} was selected")),
        )?;
        let mut winner_variables = base_variables.clone();
        winner_variables.insert("ST_CANDIDATE_INDEX".into(), winner.to_string());
        winner_variables.insert("candidate.index".into(), winner.to_string());
        let mut passed = true;
        for gate in &loop_spec.until {
            match self.evaluate_context_gate(
                run,
                loop_subject,
                &loop_spec.id,
                &view.definition_hash,
                view.attempt,
                gate,
                &winner_variables,
            )? {
                GateOutcome::Pass => {}
                GateOutcome::Pending
                    if matches!(
                        gate,
                        GateSpec::Mechanical { .. } | GateSpec::Llm { .. } | GateSpec::Human { .. }
                    ) =>
                {
                    return Ok(false);
                }
                GateOutcome::Broken(_) => return Ok(false),
                GateOutcome::Pending | GateOutcome::NotYet | GateOutcome::Fail(_) => passed = false,
            }
        }
        self.record_once(
            loop_subject,
            "loop.state",
            BTreeMap::from([
                (
                    "status".into(),
                    Value::String(if passed { "completed" } else { "running" }.into()),
                ),
                ("round".into(), Value::from(view.attempt)),
                ("winner".into(), Value::from(winner)),
                ("best_metrics".into(), best_metrics),
            ]),
        )?;
        if passed {
            return self.store.set_step_state(&view.subject, "completed", None);
        }
        if let Some(reason) = self.loop_stop_reason(loop_subject, loop_spec)? {
            return self.finish_exhausted_loop(
                run,
                view,
                loop_spec,
                loop_subject,
                &winner_variables,
                &reason,
            );
        }
        if view.attempt >= loop_spec.max_rounds {
            return self.finish_exhausted_loop(
                run,
                view,
                loop_spec,
                loop_subject,
                &winner_variables,
                "the candidate rounds did not satisfy the exit gates",
            );
        }
        self.store.set_step_state(
            &view.subject,
            "failed",
            Some("the selected candidate did not satisfy the exit gates"),
        )
    }

    fn select_loop_candidate(
        &self,
        run: &MissionRunView,
        view: &crate::model::StepRunView,
        loop_spec: &LoopSpec,
        loop_subject: &str,
        base_variables: &BTreeMap<String, String>,
        results: &[(u32, crate::model::ClaimRecord)],
    ) -> Result<LoopCandidateSelection> {
        let candidates = loop_spec
            .candidates
            .as_ref()
            .expect("the caller selected candidates");
        match &candidates.select {
            LoopCandidateSelector::Metric { metric } => {
                let spec = loop_spec
                    .metrics
                    .iter()
                    .find(|spec| &spec.name == metric)
                    .context("the candidate metric disappeared")?;
                Ok(results
                    .iter()
                    .filter_map(|(candidate, claim)| {
                        claim
                            .body
                            .pointer(&format!("/fields/metrics/{metric}"))
                            .and_then(Value::as_f64)
                            .map(|value| (*candidate, value))
                    })
                    .max_by(|left, right| {
                        let order = left.1.total_cmp(&right.1);
                        if spec.direction == "higher" {
                            order
                        } else {
                            order.reverse()
                        }
                    })
                    .map_or(LoopCandidateSelection::NoWinner, |(candidate, _)| {
                        LoopCandidateSelection::Winner(candidate)
                    }))
            }
            LoopCandidateSelector::Llm { gate } | LoopCandidateSelector::Human { gate } => {
                for (candidate, _) in results {
                    let mut variables = base_variables.clone();
                    variables.insert("ST_CANDIDATE_INDEX".into(), candidate.to_string());
                    variables.insert("candidate.index".into(), candidate.to_string());
                    match self.evaluate_context_gate(
                        run,
                        &format!(
                            "{loop_subject}/round/{}/candidate/{candidate}",
                            view.attempt
                        ),
                        &format!("select candidate {candidate}"),
                        &view.definition_hash,
                        view.attempt,
                        gate,
                        &variables,
                    )? {
                        GateOutcome::Pass => {
                            return Ok(LoopCandidateSelection::Winner(*candidate));
                        }
                        GateOutcome::Pending | GateOutcome::Broken(_) => {
                            return Ok(LoopCandidateSelection::Pending);
                        }
                        GateOutcome::NotYet | GateOutcome::Fail(_) => {}
                    }
                }
                Ok(LoopCandidateSelection::NoWinner)
            }
        }
    }

    fn loop_result_child(
        &self,
        results: &[crate::model::ClaimRecord],
    ) -> Result<Option<MissionRunView>> {
        let Some(subject) = results.iter().find_map(|claim| {
            claim
                .body
                .pointer("/fields/mission_run")
                .and_then(Value::as_str)
        }) else {
            return Ok(None);
        };
        self.store.mission_run(subject)
    }

    fn loop_first_execution_at(
        &self,
        run: &MissionRunView,
        view: &crate::model::StepRunView,
    ) -> Result<Option<u128>> {
        let root = run
            .root_mission_run
            .strip_prefix("mission-run/")
            .unwrap_or(&run.root_mission_run);
        let mut started = None;
        for child in self
            .store
            .mission_runs_for_root(root)?
            .into_iter()
            .filter(|child| child.parent_step_run.as_deref() == Some(view.subject.as_str()))
        {
            let has_claimable_work = child.steps.iter().any(|step| !step.agentless);
            if !has_claimable_work {
                started = Some(started.map_or(child.created_at_unix_ms, |current: u128| {
                    current.min(child.created_at_unix_ms)
                }));
                continue;
            }
            for step in &child.steps {
                for claim in self.store.claims_for(&step.subject, Some("work.claimed"))? {
                    started = Some(started.map_or(claim.accepted_at_unix_ms, |current: u128| {
                        current.min(claim.accepted_at_unix_ms)
                    }));
                }
            }
        }
        Ok(started)
    }

    fn loop_child_timed_out_without_claim(&self, child: &MissionRunView) -> Result<bool> {
        if !child.steps.iter().any(|step| !step.agentless) {
            return Ok(false);
        }
        let timed_out = self
            .store
            .claims_for(&child.subject, Some("mission-run.state"))?
            .iter()
            .any(|claim| {
                claim
                    .body
                    .pointer("/fields/reason")
                    .and_then(Value::as_str)
                    .is_some_and(|reason| reason.contains("timeout expired"))
            });
        if !timed_out {
            return Ok(false);
        }
        for step in &child.steps {
            if !self
                .store
                .claims_for(&step.subject, Some("work.claimed"))?
                .is_empty()
            {
                return Ok(false);
            }
        }
        Ok(true)
    }

    fn loop_dispatch_count(
        &self,
        loop_subject: &str,
        round: u32,
        candidate: Option<u32>,
        item_id: Option<&str>,
    ) -> Result<u32> {
        Ok(self
            .store
            .claims_for(loop_subject, Some("loop.round-dispatch"))?
            .into_iter()
            .filter(|claim| {
                let fields = claim.body.get("fields").unwrap_or(&claim.body);
                fields.get("round").and_then(Value::as_u64) == Some(u64::from(round))
                    && fields.get("candidate").and_then(Value::as_u64) == candidate.map(u64::from)
                    && fields.get("item_id").and_then(Value::as_str) == item_id
            })
            .filter_map(|claim| {
                claim
                    .body
                    .pointer("/fields/dispatch")
                    .and_then(Value::as_u64)
                    .and_then(|dispatch| u32::try_from(dispatch).ok())
            })
            .max()
            .unwrap_or(0))
    }

    #[allow(clippy::too_many_arguments)]
    fn reschedule_unclaimed_loop_child(
        &self,
        loop_subject: &str,
        round: u32,
        dispatch: u32,
        child: &MissionRunView,
        candidate: Option<u32>,
        item_id: Option<&str>,
    ) -> Result<bool> {
        let next_dispatch = dispatch.saturating_add(1);
        let reason = "the round mission timeout expired before any worker claimed its work; rescheduled without consuming max-rounds";
        let mut fields = BTreeMap::from([
            ("round".into(), Value::from(round)),
            ("dispatch".into(), Value::from(next_dispatch)),
            ("status".into(), Value::String("rescheduled".into())),
            ("mission_run".into(), Value::String(child.subject.clone())),
            ("reason".into(), Value::String(reason.into())),
        ]);
        if let Some(candidate) = candidate {
            fields.insert("candidate".into(), Value::from(candidate));
        }
        if let Some(item_id) = item_id {
            fields.insert("item_id".into(), Value::String(item_id.into()));
        }
        self.store.append_claim(&ClaimInput {
            subject: loop_subject.into(),
            kind: "loop.round-dispatch".into(),
            actor: None,
            fields,
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(format!(
                "loop-round-dispatch:{loop_subject}:{round}:{next_dispatch}:{}:{}",
                candidate.map_or_else(|| "round".into(), |value| value.to_string()),
                item_id.unwrap_or("none")
            )),
        })?;
        self.record_once(
            loop_subject,
            "loop.state",
            BTreeMap::from([
                ("status".into(), Value::String("running".into())),
                ("round".into(), Value::from(round)),
                ("reason".into(), Value::String(reason.into())),
            ]),
        )?;
        self.signal_changed();
        Ok(true)
    }

    fn loop_child_failure_is_structural(&self, child: &MissionRunView) -> Result<bool> {
        if child.status == "cancelled" || child.steps.iter().any(|step| step.status == "cancelled")
        {
            return Ok(true);
        }
        Ok(self
            .store
            .latest_claim(&child.subject, Some("mission-run.state"))?
            .and_then(|claim| {
                claim
                    .body
                    .pointer("/fields/reason")
                    .and_then(Value::as_str)
                    .map(str::to_owned)
            })
            .is_some_and(|reason| {
                reason.contains("revision is unavailable")
                    || reason.contains("structural")
                    || reason.contains("invalid")
            }))
    }

    #[allow(clippy::too_many_arguments)]
    fn record_loop_round(
        &self,
        loop_subject: &str,
        round: u32,
        child: &MissionRunView,
        status: &str,
        metrics: &BTreeMap<String, f64>,
        feedback: Option<&str>,
        candidate: Option<u32>,
        item: Option<&Value>,
        token_usage: u64,
        reason: Option<&str>,
    ) -> Result<()> {
        let mut fields = BTreeMap::from([
            ("round".into(), Value::from(round)),
            ("status".into(), Value::String(status.into())),
            ("mission_run".into(), Value::String(child.subject.clone())),
            ("metrics".into(), serde_json::to_value(metrics)?),
            ("token_usage".into(), Value::from(token_usage)),
        ]);
        if let Some(feedback) = feedback {
            fields.insert("feedback".into(), Value::String(feedback.into()));
        }
        if let Some(candidate) = candidate {
            fields.insert("candidate".into(), Value::from(candidate));
        }
        if let Some(item) = item {
            fields.insert("item".into(), item.clone());
        }
        if let Some(reason) = reason {
            fields.insert("reason".into(), Value::String(reason.into()));
        }
        self.store.append_claim(&ClaimInput {
            subject: loop_subject.into(),
            kind: "loop.round-result".into(),
            actor: None,
            fields,
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(format!(
                "loop-round-result:{loop_subject}:{round}:{}",
                candidate.map_or_else(|| "round".into(), |value| format!("candidate-{value}"))
            )),
        })?;
        self.signal_changed();
        Ok(())
    }

    fn repeated_loop_failures(&self, loop_subject: &str) -> Result<u32> {
        Ok(self
            .store
            .claims_for(loop_subject, Some("loop.round-result"))?
            .iter()
            .rev()
            .filter(|claim| claim.body.pointer("/fields/candidate").is_none())
            .filter(|claim| claim.body.pointer("/fields/item").is_none())
            .take_while(|claim| {
                claim.body.pointer("/fields/status").and_then(Value::as_str) == Some("failed")
            })
            .count() as u32)
    }

    fn mission_run_token_usage(&self, run: &MissionRunView) -> Result<u64> {
        let desired = self.store.desired_subjects()?;
        desired
            .iter()
            .filter(|subject| subject.owner_run.as_deref() == Some(run.subject.as_str()))
            .try_fold(0_u64, |total, subject| {
                Ok(total.saturating_add(
                    self.store
                        .usage_summary_at(&subject.subject, None, None)?
                        .map(|usage| usage.total_tokens)
                        .unwrap_or_default(),
                ))
            })
    }

    fn loop_best(
        &self,
        loop_subject: &str,
        loop_spec: &LoopSpec,
    ) -> Result<(u64, BTreeMap<String, f64>)> {
        let claims = self
            .store
            .claims_for(loop_subject, Some("loop.round-result"))?;
        let selected = if let Some(metric_name) = &loop_spec.keep_metric {
            let metric = loop_spec
                .metrics
                .iter()
                .find(|metric| &metric.name == metric_name)
                .context("the keep metric disappeared")?;
            claims
                .iter()
                .filter(|claim| claim.body.pointer("/fields/candidate").is_none())
                .filter(|claim| claim.body.pointer("/fields/item").is_none())
                .filter(|claim| {
                    claim.body.pointer("/fields/status").and_then(Value::as_str)
                        == Some("completed")
                })
                .filter_map(|claim| {
                    let round = claim.body.pointer("/fields/round")?.as_u64()?;
                    let value = claim
                        .body
                        .pointer(&format!("/fields/metrics/{metric_name}"))?
                        .as_f64()?;
                    Some((claim, round, value))
                })
                .max_by(|left, right| {
                    let order = left.2.total_cmp(&right.2);
                    if metric.direction == "higher" {
                        order
                    } else {
                        order.reverse()
                    }
                })
                .map(|(claim, round, _)| (claim, round))
        } else {
            claims
                .iter()
                .rfind(|claim| {
                    claim.body.pointer("/fields/candidate").is_none()
                        && claim.body.pointer("/fields/item").is_none()
                        && claim.body.pointer("/fields/status").and_then(Value::as_str)
                            == Some("completed")
                })
                .and_then(|claim| {
                    claim
                        .body
                        .pointer("/fields/round")
                        .and_then(Value::as_u64)
                        .map(|round| (claim, round))
                })
        };
        let Some((claim, round)) = selected else {
            return Ok((0, BTreeMap::new()));
        };
        let metrics = claim
            .body
            .pointer("/fields/metrics")
            .and_then(Value::as_object)
            .map(|values| {
                values
                    .iter()
                    .filter_map(|(name, value)| value.as_f64().map(|value| (name.clone(), value)))
                    .collect()
            })
            .unwrap_or_default();
        Ok((round, metrics))
    }

    fn loop_stop_reason(&self, loop_subject: &str, loop_spec: &LoopSpec) -> Result<Option<String>> {
        let results = self
            .store
            .claims_for(loop_subject, Some("loop.round-result"))?;
        if let Some(limit) = loop_spec.stop.token_budget {
            let used = results
                .iter()
                .filter_map(|claim| {
                    claim
                        .body
                        .pointer("/fields/token_usage")
                        .and_then(Value::as_u64)
                })
                .sum::<u64>();
            if used >= limit {
                return Ok(Some(format!(
                    "the loop token budget of {limit} was reached"
                )));
            }
        }
        if let (Some(metric_name), Some(rounds)) = (
            &loop_spec.stop.plateau_metric,
            loop_spec.stop.plateau_rounds,
        ) {
            let metric = loop_spec
                .metrics
                .iter()
                .find(|metric| &metric.name == metric_name)
                .context("the plateau metric disappeared")?;
            let mut best: Option<f64> = None;
            let mut stalled = 0_u32;
            for value in results
                .iter()
                .filter(|claim| claim.body.pointer("/fields/candidate").is_none())
                .filter(|claim| claim.body.pointer("/fields/item").is_none())
                .filter_map(|claim| {
                    claim
                        .body
                        .pointer(&format!("/fields/metrics/{metric_name}"))
                        .and_then(Value::as_f64)
                })
            {
                let improves = best.is_none_or(|prior| {
                    if metric.direction == "higher" {
                        value - prior >= metric.min_improvement
                    } else {
                        prior - value >= metric.min_improvement
                    }
                });
                if improves {
                    best = Some(value);
                    stalled = 0;
                } else {
                    stalled += 1;
                }
            }
            if stalled >= rounds {
                return Ok(Some(format!(
                    "the loop metric did not improve for {rounds} rounds"
                )));
            }
        }
        Ok(None)
    }

    fn finish_exhausted_loop(
        &self,
        run: &MissionRunView,
        view: &crate::model::StepRunView,
        loop_spec: &LoopSpec,
        loop_subject: &str,
        variables: &BTreeMap<String, String>,
        reason: &str,
    ) -> Result<bool> {
        match &loop_spec.on_exhausted {
            LoopExhaustionSpec::Fail => {
                self.record_once(
                    loop_subject,
                    "loop.state",
                    BTreeMap::from([
                        ("status".into(), Value::String("failed".into())),
                        ("round".into(), Value::from(view.attempt)),
                        ("reason".into(), Value::String(reason.into())),
                    ]),
                )?;
                self.store
                    .set_step_state(&view.subject, "failed", Some(reason))
            }
            LoopExhaustionSpec::Succeed => {
                self.record_once(
                    loop_subject,
                    "loop.state",
                    BTreeMap::from([
                        ("status".into(), Value::String("exhausted".into())),
                        ("round".into(), Value::from(view.attempt)),
                        ("reason".into(), Value::String(reason.into())),
                    ]),
                )?;
                self.store.set_step_state(
                    &view.subject,
                    "completed",
                    Some("the loop accepted its best result at exhaustion"),
                )
            }
            LoopExhaustionSpec::Human { gate } => match self.evaluate_context_gate(
                run,
                loop_subject,
                &loop_spec.id,
                &view.definition_hash,
                view.attempt,
                gate,
                variables,
            )? {
                GateOutcome::Pass => {
                    self.record_once(
                        loop_subject,
                        "loop.state",
                        BTreeMap::from([
                            ("status".into(), Value::String("exhausted".into())),
                            ("round".into(), Value::from(view.attempt)),
                            ("reason".into(), Value::String(reason.into())),
                        ]),
                    )?;
                    self.store.set_step_state(
                        &view.subject,
                        "completed",
                        Some("the human reviewer accepted the exhausted loop result"),
                    )
                }
                GateOutcome::Fail(review_reason) => {
                    self.record_once(
                        loop_subject,
                        "loop.state",
                        BTreeMap::from([
                            ("status".into(), Value::String("failed".into())),
                            ("round".into(), Value::from(view.attempt)),
                            ("reason".into(), Value::String(review_reason.clone())),
                        ]),
                    )?;
                    self.store
                        .set_step_state(&view.subject, "failed", Some(&review_reason))
                }
                GateOutcome::Pending | GateOutcome::NotYet | GateOutcome::Broken(_) => Ok(false),
            },
        }
    }

    fn step_dependencies_hold(
        &self,
        run: &MissionRunView,
        step: &RuntimeStep<'_>,
        views: &HashMap<&str, &crate::model::StepRunView>,
    ) -> Result<bool> {
        if let Some(parent) = &step.parent {
            let Some(parent) = views.get(parent.as_str()) else {
                return Ok(false);
            };
            if !matches!(parent.status.as_str(), "claimed" | "working" | "verifying") {
                return Ok(false);
            }
        }
        for dependency in &step.spec.dependencies {
            match dependency {
                DependencySpec::Step {
                    step: target,
                    state,
                } => {
                    let path = if step.dependency_prefix.is_empty() {
                        target.clone()
                    } else {
                        format!("{}/{target}", step.dependency_prefix)
                    };
                    let Some(target) = views.get(path.as_str()) else {
                        return Ok(false);
                    };
                    let holds = match state.as_str() {
                        "completed" => target.status == "completed",
                        "failed" => target.status == "failed",
                        "terminal" => {
                            matches!(target.status.as_str(), "completed" | "failed" | "cancelled")
                        }
                        _ => false,
                    };
                    if !holds {
                        return Ok(false);
                    }
                }
                DependencySpec::Predicate { gate } => {
                    let fake = crate::model::StepRunView {
                        subject: format!(
                            "step-run/{}/{}",
                            run.generation
                                .strip_prefix("run-generation/")
                                .unwrap_or(&run.generation),
                            step.spec.path
                        ),
                        run: run.subject.clone(),
                        generation: run.generation.clone(),
                        step: step.spec.path.clone(),
                        fresh_context: step.spec.fresh_context,
                        queue: None,
                        queue_position: None,
                        definition_hash: step.spec.definition_hash.clone(),
                        status: "pending".into(),
                        attempt: 1,
                        assigned_to: None,
                        available_to: Vec::new(),
                        agentless: true,
                        title: None,
                        goals: Vec::new(),
                        constraints: Vec::new(),
                        under: Vec::new(),
                        worker_reported: false,
                        claimant: None,
                        claim_incarnation: None,
                        claim_expires_at_unix_ms: None,
                        carried_claimant: None,
                        execution_started_at_unix_ms: None,
                        execution_elapsed_ms: 0,
                        timeout_ms: None,
                        timeout_extension_ms: 0,
                        ready_age_ms: None,
                        wake: None,
                        progress_summary: None,
                        progress_at_unix_ms: None,
                        completion_summary: None,
                        readiness_epoch: 0,
                        blocked_reason: None,
                        blockers: Vec::new(),
                        not_before_unix_ms: None,
                        created_at_unix_ms: run.created_at_unix_ms,
                        updated_at_unix_ms: run.updated_at_unix_ms,
                        person_answers: Vec::new(),
                    };
                    if !matches!(
                        self.evaluate_mission_gate(run, step, &fake, gate)?,
                        GateOutcome::Pass
                    ) {
                        return Ok(false);
                    }
                }
            }
        }
        Ok(true)
    }

    fn materialize_step_declarations(
        &self,
        run: &MissionRunView,
        step: &RuntimeStep<'_>,
        view: &crate::model::StepRunView,
        assigned_agents_only: bool,
    ) -> Result<bool> {
        let Some(source) = &step.spec.declarations_kdl else {
            return Ok(false);
        };
        let variables = run_variables(run, step, view);
        let source = crate::mission::interpolate_kdl(source, &variables)?;
        let mut intent = crate::graph::parse_execution_intent(&source, &self.host, &run.id)?;
        if assigned_agents_only {
            intent.subjects.retain(|subject, desired| {
                desired.kind == "agent"
                    && (view.assigned_to.as_deref() == Some(subject.as_str())
                        || view.available_to.iter().any(|agent| agent == subject))
            });
        }
        self.keep_stops_by_hand(&mut intent, run)?;
        if assigned_agents_only && intent.subjects.is_empty() {
            return Ok(false);
        }
        for subject in intent.subjects.values_mut() {
            subject.owner_run = Some(run.subject.clone());
            subject.owner_generation = Some(run.generation.clone());
            subject.owner_step = Some(view.subject.clone());
            if let Some(member) = subject.member.as_mut() {
                let workspace = PathBuf::from(&member.workspace);
                if workspace.is_relative() {
                    member.workspace = Path::new(&run.workspace)
                        .join(&workspace)
                        .to_string_lossy()
                        .into_owned();
                }
                let cwd = PathBuf::from(&member.cwd);
                if cwd.is_relative() {
                    member.cwd = Path::new(&run.workspace)
                        .join(&cwd)
                        .to_string_lossy()
                        .into_owned();
                }
                member.environment.extend(variables.clone());
                member
                    .environment
                    .insert("ST3_RUN_DIR".into(), run.workspace.clone());
                member
                    .environment
                    .insert("ST3_ENDPOINT".into(), self.endpoint.clone());
            }
        }
        self.reject_runtime_collisions(&intent, run, Some(&view.subject))?;
        let response = self.store.apply_internal(
            &intent,
            &format!("materialize:{}:{}", view.subject, view.attempt),
        )?;
        Ok(response.changed)
    }

    /// Retire the declarations an earlier generation materialized. The second value is false
    /// while an active step still holds some of them, so a later pass retires them once the
    /// step leaves without re-owning them.
    fn retire_predecessor_generation(&self, run: &MissionRunView) -> Result<(bool, bool)> {
        // An active step re-owns its own declarations when it next materializes them, so a
        // claim carried into this generation keeps its step's members.
        let active_steps = run
            .steps
            .iter()
            .filter(|step| {
                matches!(
                    step.status.as_str(),
                    "ready" | "claimed" | "working" | "verifying" | "blocked"
                )
            })
            .map(|step| step.step.as_str())
            .collect::<BTreeSet<_>>();
        let (held, retired): (Vec<_>, Vec<_>) = self
            .store
            .desired_subjects_for_owner_run(&run.subject)?
            .into_iter()
            .filter(|subject| subject.owner_run.as_deref() == Some(run.subject.as_str()))
            // Only a subject materialized by another generation is retired. An
            // eval owns its top-level seats for the whole run, not one generation.
            .filter(|subject| {
                subject
                    .owner_generation
                    .as_deref()
                    .is_some_and(|generation| generation != run.generation)
            })
            .partition(|subject| {
                subject
                    .owner_step
                    .as_deref()
                    .and_then(step_path_of_subject)
                    .is_some_and(|path| active_steps.contains(path))
            });
        let complete = held.is_empty();
        let mut changed = self.stop_owned_intake(
            &retired.iter().collect::<Vec<_>>(),
            Some(&run.generation),
            &format!("retire-generation-intake:{}", run.generation),
        )?;
        let stops = retired
            .iter()
            .filter(|subject| subject.member.is_some() && subject.kind != "stop")
            .map(|subject| format!("stop {:?}", subject.subject))
            .collect::<Vec<_>>()
            .join("\n");
        if stops.is_empty() {
            return Ok((changed, complete));
        }
        let source = format!("version 2\n\n{stops}\n");
        let mut intent = crate::graph::parse_execution_intent(&source, &self.host, &run.id)?;
        for subject in intent.subjects.values_mut() {
            subject.owner_generation = Some(run.generation.clone());
        }
        let response = self
            .store
            .apply_internal(&intent, &format!("retire-generation:{}", run.generation))?;
        changed |= response.changed;
        Ok((changed, complete))
    }

    /// Stop owned lanes, observers, subscriptions, and schedules durably. Each one remains a
    /// stopped declaration of its own kind, so it settles its state and starts no more work, and a
    /// stopped lane is no longer listed.
    fn stop_owned_intake(
        &self,
        subjects: &[&DesiredSubject],
        generation: Option<&str>,
        key: &str,
    ) -> Result<bool> {
        let mut by_owner = BTreeMap::<&str, Vec<String>>::new();
        for subject in subjects {
            if !matches!(
                subject.kind.as_str(),
                "lane" | "observer" | "subscription" | "schedule"
            ) || intake_is_stopped(subject, &self.host)
            {
                continue;
            }
            let Some(owner) = subject.owner_run.as_deref() else {
                continue;
            };
            let owner_id = owner.strip_prefix("mission-run/").unwrap_or(owner);
            let Some(name) = subject
                .subject
                .strip_prefix(&format!("{}/{owner_id}/", subject.kind))
            else {
                continue;
            };
            by_owner
                .entry(owner_id)
                .or_default()
                .push(format!("{} {name:?} {{ stop }}", subject.kind));
        }
        let mut changed = false;
        for (owner_id, stops) in by_owner {
            let source = format!("version 2\n\n{}\n", stops.join("\n"));
            let mut intent = crate::graph::parse_execution_intent(&source, &self.host, owner_id)?;
            for subject in intent.subjects.values_mut() {
                subject.owner_generation = generation.map(str::to_owned);
            }
            changed |= self
                .store
                .apply_internal(&intent, &format!("{key}:{owner_id}"))?
                .changed;
        }
        Ok(changed)
    }

    /// Leave out of `intent` each seat a person or an agent stopped while this generation of
    /// `run` declared it. Declaring it again would undo that stop on the next daemon start,
    /// or on the next pass for a step's seat; `st agents start` starts it again.
    fn keep_stops_by_hand(
        &self,
        intent: &mut crate::model::NormalizedIntent,
        run: &MissionRunView,
    ) -> Result<()> {
        let agents = intent
            .subjects
            .iter()
            .filter(|(_, desired)| desired.kind == "agent")
            .map(|(subject, _)| subject.clone())
            .collect::<Vec<_>>();
        if agents.is_empty() {
            return Ok(());
        }
        let stopped = self
            .store
            .stopped_by_hand(&agents, &run.subject, &run.generation)?;
        intent
            .subjects
            .retain(|subject, _| !stopped.contains(subject));
        Ok(())
    }

    fn materialize_mission_declarations(
        &self,
        run: &MissionRunView,
        mission: &MissionSpec,
    ) -> Result<bool> {
        let Some(source) = &mission.declarations_kdl else {
            return Ok(false);
        };
        let variables = crate::store::mission_run_variables(run, &mission.revision);
        let source = crate::mission::interpolate_kdl(source, &variables)?;
        #[cfg(test)]
        self.mission_declaration_parses
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let mut intent = crate::graph::parse_execution_intent(&source, &self.host, &run.id)?;
        let selected = self
            .store
            .desired_subjects_for_owner_run(&run.subject)?
            .into_iter()
            .map(|subject| (subject.subject.clone(), subject))
            .collect::<BTreeMap<_, _>>();
        // A stop declared by a step is authoritative for the remainder of its generation.
        // Re-materializing the mission-level agent on the next final-phase pass would otherwise
        // replace that stop for one reconciliation cycle, launch a fresh incarnation, and then
        // stop it again during terminal cleanup.
        intent.subjects.retain(|subject, _| {
            !selected.get(subject).is_some_and(|current| {
                current.kind == "stop"
                    && current.owner_run.as_deref() == Some(run.subject.as_str())
                    && current.owner_generation.as_deref() == Some(run.generation.as_str())
            })
        });
        self.keep_stops_by_hand(&mut intent, run)?;
        for subject in intent.subjects.values_mut() {
            subject.owner_run = Some(run.subject.clone());
            subject.owner_generation = Some(run.generation.clone());
            subject.owner_step = None;
            if let Some(member) = subject.member.as_mut() {
                let workspace = PathBuf::from(&member.workspace);
                if workspace.is_relative() {
                    member.workspace = Path::new(&run.workspace)
                        .join(&workspace)
                        .to_string_lossy()
                        .into_owned();
                }
                let cwd = PathBuf::from(&member.cwd);
                if cwd.is_relative() {
                    member.cwd = Path::new(&run.workspace)
                        .join(&cwd)
                        .to_string_lossy()
                        .into_owned();
                }
                member.environment.extend(variables.clone());
                member
                    .environment
                    .insert("ST3_RUN_DIR".into(), run.workspace.clone());
                member
                    .environment
                    .insert("ST3_ENDPOINT".into(), self.endpoint.clone());
            }
        }
        self.reject_runtime_collisions(&intent, run, None)?;
        let response = self
            .store
            .apply_internal(&intent, &format!("materialize:{}", run.generation))?;
        // A subscription to a repository's standing observer declares it here, before a
        // superseded generation's own observer of the repository stops, so the standing observer
        // takes that observer's resource and nothing between their polls goes unobserved.
        let standing = intent
            .subjects
            .values()
            .filter(|subject| subject.kind == "subscription")
            .filter_map(|subject| crate::graph::subscription_spec(&subject.desired))
            .filter(|spec| !spec.stopped)
            .filter_map(|spec| crate::github_watch::standing_locator(&spec.observer))
            .collect::<BTreeSet<_>>();
        let mut changed = response.changed;
        if !standing.is_empty() {
            let observers = self.store.repository_observers()?;
            for locator in standing {
                changed |= self.store.ensure_standing_observer(&locator, &observers)?;
            }
        }
        Ok(changed)
    }

    fn reject_runtime_collisions(
        &self,
        intent: &crate::model::NormalizedIntent,
        run: &MissionRunView,
        owner_step: Option<&str>,
    ) -> Result<()> {
        let existing = self
            .store
            .desired_subjects_for_owner_run(&run.subject)?
            .into_iter()
            .map(|subject| (subject.subject.clone(), subject))
            .collect::<BTreeMap<_, _>>();
        for subject in intent.subjects.values().filter(|subject| {
            matches!(
                subject.kind.as_str(),
                "agent" | "exec" | "pty" | "observer" | "subscription" | "schedule"
            )
        }) {
            let Some(current) = existing.get(&subject.subject) else {
                continue;
            };
            if current.kind != "stop"
                && current.owner_run.as_deref() == Some(run.subject.as_str())
                && current.owner_generation.as_deref() == Some(run.generation.as_str())
                && current.owner_step.as_deref() != owner_step
            {
                return Err(crate::model::St3Error::new(
                    "duplicate-runtime-subject",
                    format!(
                        "mission run `{}` declares runtime `{}` in more than one mission or step",
                        run.subject, subject.subject
                    ),
                )
                .into());
            }
        }
        Ok(())
    }

    fn step_declarations_hold(&self, step_subject: &str) -> Result<bool> {
        for subject in self
            .store
            .desired_subjects_for_owner_step(step_subject)?
            .into_iter()
            .filter(|subject| subject.owner_step.as_deref() == Some(step_subject))
        {
            let status = self
                .store
                .latest_actual_value(&subject.subject)?
                .as_ref()
                .and_then(|actual| actual_field(actual, "status"))
                .and_then(Value::as_str)
                .map(str::to_owned);
            let harness = self.store.current_harness(&subject.subject)?;
            let holds = match subject.kind.as_str() {
                "stop" => {
                    matches!(status.as_deref(), Some("stopped" | "absent" | "exited"))
                        || self.stop_is_settled(&subject)?
                }
                "message" => matches!(status.as_deref(), Some("delivered" | "read" | "closed")),
                _ => match subject.member.as_ref() {
                    Some(member) if member.driver.is_some() => {
                        harness.as_ref().is_some_and(|harness| harness.is_ready())
                    }
                    Some(_) => matches!(
                        status.as_deref(),
                        Some("running" | "ready" | "working" | "idle" | "exited")
                    ),
                    None => true,
                },
            };
            if !holds {
                return Ok(false);
            }
        }
        Ok(true)
    }

    /// Whether a stop that has not yet reached a stopped runtime asks nothing more of its step.
    /// A seat that was never observed is gone. A seat the stop already set going is stopping, and
    /// the stop's own deadline kills it. A seat kept for unread mail or another run's work stops
    /// once it is free, as it does for the run's cleanup. Holding the step for any of these ran
    /// it into its execution timeout, which failed the run's final step and so the run.
    fn stop_is_settled(&self, subject: &DesiredSubject) -> Result<bool> {
        let Some(actual) = self.store.latest_actual_value(&subject.subject)? else {
            return Ok(true);
        };
        let fields = actual.get("fields").unwrap_or(&actual);
        let incarnation = fields.get("incarnation_id").and_then(Value::as_str);
        if self
            .store
            .observations_for(&subject.subject, "runtime.action.requested")?
            .iter()
            .any(|claim| {
                claim.body.pointer("/fields/action").and_then(Value::as_str) == Some("terminate")
                    && claim
                        .body
                        .pointer("/fields/incarnation_id")
                        .and_then(Value::as_str)
                        == incarnation.or(Some("unknown"))
            })
        {
            return Ok(true);
        }
        let Some(run) = subject.owner_run.as_deref() else {
            return Ok(false);
        };
        Ok(self.seat_retention(&subject.subject, run)?.is_some())
    }

    /// Return the first produced native driver that cannot still satisfy this step.
    ///
    /// A driver with no restart policy has no path from a terminal runtime back to readiness. A
    /// restartable driver remains pending until its policy either succeeds or publishes an
    /// explicit `raise` decision. Without this check, a dead `restart "never"` agent leaves its
    /// producing step parked until the step timeout, hiding an immediate failure for minutes.
    fn step_declaration_failure(&self, step_subject: &str) -> Result<Option<String>> {
        for subject in self
            .store
            .desired_subjects_for_owner_step(step_subject)?
            .into_iter()
            .filter(|subject| subject.owner_step.as_deref() == Some(step_subject))
        {
            let Some(member) = subject
                .member
                .as_ref()
                .filter(|member| member.driver.is_some())
            else {
                continue;
            };
            let actual = self.store.latest_actual_value(&subject.subject)?;
            let status = actual
                .as_ref()
                .and_then(|actual| actual_field(actual, "status"))
                .and_then(Value::as_str);
            let harness = self.store.current_harness(&subject.subject)?;
            let harness_state = harness.as_ref().map(|harness| harness.state.as_str());
            if harness.as_ref().is_some_and(|harness| harness.is_ready()) {
                continue;
            }

            let raised = self
                .store
                .latest_claim(&subject.subject, Some("runtime.reconcile-decision"))?
                .filter(|claim| {
                    claim
                        .body
                        .pointer("/fields/decision")
                        .and_then(Value::as_str)
                        == Some("raise")
                });
            let terminal_without_restart = member.restart == RestartType::Never
                && (matches!(status, Some("absent" | "exited" | "vanished" | "stopped"))
                    || harness_state == Some("ended"));
            if !terminal_without_restart && raised.is_none() {
                continue;
            }

            let action_failure = self
                .store
                .latest_observation(&subject.subject, "runtime.action.failed")?
                .and_then(|claim| {
                    claim
                        .body
                        .pointer("/fields/reason")
                        .and_then(Value::as_str)
                        .map(str::to_owned)
                });
            let raised_reason = raised.and_then(|claim| {
                claim
                    .body
                    .pointer("/fields/reason")
                    .and_then(Value::as_str)
                    .map(str::to_owned)
            });
            let exit = actual
                .as_ref()
                .and_then(|actual| actual_field(actual, "exit_code"))
                .and_then(Value::as_i64)
                .map(|code| format!(" with exit code {code}"))
                .unwrap_or_default();
            let detail = action_failure.or(raised_reason).unwrap_or_else(|| {
                format!("runtime status was {}{exit}", status.unwrap_or("ended"))
            });
            return Ok(Some(format!(
                "required driver `{}` could not become ready: {detail}",
                subject.subject
            )));
        }
        Ok(None)
    }

    fn missing_product(
        &self,
        run: &MissionRunView,
        step: &RuntimeStep<'_>,
        view: &crate::model::StepRunView,
    ) -> Result<Option<MissingProduct>> {
        let variables = run_variables(run, step, view);
        self.first_missing_product(&step.spec.products, &variables)
    }

    fn products_hold_with_variables(
        &self,
        products: &[crate::model::ProductSpec],
        variables: &BTreeMap<String, String>,
    ) -> Result<bool> {
        Ok(self.first_missing_product(products, variables)?.is_none())
    }

    fn first_missing_product(
        &self,
        products: &[crate::model::ProductSpec],
        variables: &BTreeMap<String, String>,
    ) -> Result<Option<MissingProduct>> {
        for product in products {
            let subject = crate::mission::interpolate(&product.subject, variables)?;
            let mut fields = Vec::with_capacity(product.fields.len());
            for (field, expected) in &product.fields {
                let expected = match expected {
                    Value::String(value) => {
                        Value::String(crate::mission::interpolate(value, variables)?)
                    }
                    value => value.clone(),
                };
                fields.push((field.clone(), expected));
            }
            let holds = self.subject_value(&subject)?.is_some_and(|actual| {
                fields
                    .iter()
                    .all(|(field, expected)| actual_field(&actual, field) == Some(expected))
            });
            if !holds {
                return Ok(Some(MissingProduct { subject, fields }));
            }
        }
        Ok(None)
    }

    /// A worker that submits before its declared product exists leaves the step verifying with no
    /// further prompt. Once that turn has ended, tell the worker exactly which subject and fields
    /// the step waits for. The message is sent once per step attempt and readiness epoch.
    fn notify_missing_product(
        &self,
        view: &crate::model::StepRunView,
        missing: &MissingProduct,
    ) -> Result<bool> {
        if view.agentless || !view.worker_reported || view.status != "verifying" {
            return Ok(false);
        }
        let Some(agent) = view.claimant.as_deref().or(view.assigned_to.as_deref()) else {
            return Ok(false);
        };
        if self
            .store
            .current_harness(agent)?
            .is_some_and(|harness| harness.state == "working")
        {
            return Ok(false);
        }
        let idempotency_key = format!(
            "product-wait:{}@{}@{}",
            view.subject, view.attempt, view.readiness_epoch
        );
        let message_id = &hex::encode(sha2::Sha256::digest(idempotency_key.as_bytes()))[..16];
        let message_subject = format!("message/{message_id}");
        if self
            .store
            .latest_claim(&message_subject, Some("message.sent"))?
            .is_some()
        {
            return Ok(false);
        }
        let expected = missing
            .fields
            .iter()
            .map(|(field, value)| match value {
                Value::String(value) => format!("{field}={value}"),
                value => format!("{field}={value}"),
            })
            .collect::<Vec<_>>();
        let example = expected
            .iter()
            .map(|field| format!(" --field {field}"))
            .collect::<String>();
        let content = format!(
            "`{}` was submitted, but its declared product `{}` has not been observed{}. Record that exact subject, for example `st claim {} resource.observed --actor {agent}{example}`, or fail the step with the reason. No action is needed if another actor produces it.",
            view.subject,
            missing.subject,
            if expected.is_empty() {
                String::new()
            } else {
                format!(" with {}", expected.join(", "))
            },
            missing.subject,
        );
        let title = format!(
            "Declared product missing: {}",
            view.title.as_deref().unwrap_or(&view.step)
        );
        self.store.append_claim(&ClaimInput {
            subject: message_subject,
            kind: "message.sent".into(),
            actor: Some("daemon/runtime".into()),
            fields: BTreeMap::from([
                ("from".into(), Value::String("daemon/runtime".into())),
                ("to".into(), Value::String(agent.into())),
                ("content".into(), Value::String(content)),
                ("status".into(), Value::String("sent".into())),
                ("title".into(), Value::String(title)),
                ("in_reply_to".into(), Value::Null),
                (
                    "tags".into(),
                    Value::Array(vec![
                        Value::String(format!("mission-run:{}", view.run)),
                        Value::String(format!("st3-product-wait:{}", view.subject)),
                    ]),
                ),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(idempotency_key),
        })?;
        Ok(true)
    }

    fn evaluate_mission_gate(
        &self,
        run: &MissionRunView,
        step: &RuntimeStep<'_>,
        view: &crate::model::StepRunView,
        gate: &GateSpec,
    ) -> Result<GateOutcome> {
        let variables = run_variables(run, step, view);
        self.evaluate_context_gate(
            run,
            &view.subject,
            step.spec.title.as_deref().unwrap_or(&step.spec.path),
            &view.definition_hash,
            view.attempt,
            gate,
            &variables,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn evaluate_context_gate(
        &self,
        run: &MissionRunView,
        subject: &str,
        title: &str,
        definition_hash: &str,
        attempt: u32,
        gate: &GateSpec,
        variables: &BTreeMap<String, String>,
    ) -> Result<GateOutcome> {
        let mut gate = gate.clone();
        expand_gate(&mut gate, variables, &run.workspace)?;
        if let GateSpec::Human {
            reviewer,
            mode,
            question,
            review_targets,
            ..
        } = &gate
        {
            return self.evaluate_mission_human_gate(
                run,
                subject,
                title,
                definition_hash,
                attempt,
                reviewer,
                mode.as_deref().unwrap_or("approve"),
                question.as_deref(),
                review_targets,
            );
        }
        let stage = GateContext {
            subject: subject.to_owned(),
            name: title.to_owned(),
            started_at_unix_ms: run
                .steps
                .iter()
                .find(|step| step.subject == subject)
                .map_or(run.created_at_unix_ms, |step| step.created_at_unix_ms),
            attempt,
            run: run.subject.clone(),
            generation: run.generation.clone(),
            eval: run.mode == "eval",
        };
        let outcome = self.evaluate_gate(&stage, &gate)?;
        // An eval's judges decide its verdict and nobody revises an eval run, so there an exec
        // gate that says not yet or is broken fails its boundary, as every status but 0 did.
        Ok(match outcome {
            GateOutcome::NotYet if stage.eval => GateOutcome::Fail(format!(
                "exec gate `{}` exited 1",
                crate::graph::gate_name(&gate)
            )),
            GateOutcome::Broken(reason) if stage.eval => GateOutcome::Fail(reason),
            outcome => outcome,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn evaluate_mission_human_gate(
        &self,
        run: &MissionRunView,
        subject: &str,
        title: &str,
        definition_hash: &str,
        attempt: u32,
        reviewer: &str,
        mode: &str,
        question: Option<&str>,
        review_targets: &[String],
    ) -> Result<GateOutcome> {
        let question = question
            .map(str::to_owned)
            .unwrap_or_else(|| format!("Approve {title}?"));
        let mut fields = BTreeMap::from([
            ("owner".into(), Value::String(subject.to_owned())),
            ("reviewer".into(), Value::String(reviewer.into())),
            ("mode".into(), Value::String(mode.into())),
            ("question".into(), Value::String(question)),
            (
                "review_targets".into(),
                Value::Array(review_targets.iter().cloned().map(Value::String).collect()),
            ),
            (
                "decisions".into(),
                Value::Array(
                    if mode == "feedback" {
                        ["approved", "changes-requested"]
                    } else {
                        ["approved", "rejected"]
                    }
                    .into_iter()
                    .map(|value| Value::String(value.into()))
                    .collect(),
                ),
            ),
            (
                "mission_revision".into(),
                Value::String(run.revision.clone()),
            ),
            (
                "step_definition".into(),
                Value::String(definition_hash.to_owned()),
            ),
            ("attempt".into(), Value::from(attempt)),
        ]);
        let request_hash = hex::encode(sha2::Sha256::digest(serde_json::to_vec(&fields)?));
        let operation = format!(
            "gate-operation/{}/{}",
            subject.replace('/', "."),
            &request_hash[..24]
        );
        fields.insert("operation".into(), Value::String(operation.clone()));
        let request = self.store.append_claim(&ClaimInput {
            subject: operation.clone(),
            kind: "gate.requested".into(),
            actor: None,
            fields,
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(format!(
                "review-request:{}:{}",
                subject,
                &request_hash[..24]
            )),
        })?;
        // The reviewer's answer, read by the rule that takes an answered review off the
        // reviewers' list: a later result on the operation (another actor's, an unbound one)
        // cannot hide it and leave a gate nobody can answer.
        let decision = self.store.human_review_answer(&request.id)?;
        match decision.as_ref().and_then(|claim| {
            claim
                .body
                .pointer("/fields/verdict")
                .and_then(Value::as_str)
        }) {
            Some("pass") => Ok(GateOutcome::Pass),
            Some("feedback") if mode == "feedback" => {
                let decision = decision.as_ref().expect("a feedback decision exists");
                let reason = decision
                    .body
                    .pointer("/fields/reason")
                    .and_then(Value::as_str)
                    .filter(|reason| !reason.trim().is_empty())
                    .context("a request for changes has no feedback text")?;
                self.apply_human_feedback(subject, attempt, reviewer, reason, &decision.id)?;
                Ok(GateOutcome::Pending)
            }
            Some("fail") => Ok(GateOutcome::Fail(human_review_failure_reason(
                decision.as_ref().expect("a failed decision exists"),
            ))),
            _ => Ok(GateOutcome::Pending),
        }
    }

    fn apply_human_feedback(
        &self,
        subject: &str,
        attempt: u32,
        reviewer: &str,
        reason: &str,
        decision_id: &str,
    ) -> Result<()> {
        let step = self
            .store
            .step_run(subject)?
            .context("the feedback step disappeared")?;
        if step.attempt != attempt {
            return Ok(());
        }
        let claimant = self
            .store
            .claims_for(subject, Some("work.claimed"))?
            .into_iter()
            .rev()
            .find(|claim| {
                claim
                    .body
                    .pointer("/fields/attempt")
                    .and_then(Value::as_u64)
                    == Some(u64::from(attempt))
            })
            .and_then(|claim| {
                claim
                    .body
                    .pointer("/fields/claimant")
                    .and_then(Value::as_str)
                    .map(str::to_owned)
            })
            .or(step.claimant)
            .or(step.carried_claimant)
            .or(step.assigned_to)
            .context("a feedback step has no claimant or assignee")?;
        let key = format!("human-feedback:{decision_id}:{claimant}");
        let message_id = hex::encode(sha2::Sha256::digest(key.as_bytes()));
        self.store.append_claim(&ClaimInput {
            subject: format!("message/{}", &message_id[..16]),
            kind: "message.sent".into(),
            actor: Some(reviewer.into()),
            fields: BTreeMap::from([
                ("from".into(), Value::String(reviewer.into())),
                ("to".into(), Value::String(claimant)),
                (
                    "content".into(),
                    Value::String(format!(
                        "Reviewer requested changes to `{subject}`: {reason}. Claim the new attempt and address this feedback."
                    )),
                ),
                ("status".into(), Value::String("sent".into())),
                (
                    "title".into(),
                    Value::String("Human review requested changes".into()),
                ),
                ("in_reply_to".into(), Value::Null),
                (
                    "tags".into(),
                    Value::Array(vec![Value::String(format!("st3-feedback:{subject}"))]),
                ),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(key),
        })?;
        if self
            .store
            .retry_step_for_feedback(subject, attempt, reason, reviewer)?
        {
            self.signal_changed();
        }
        Ok(())
    }

    fn step_timed_out(
        &self,
        view: &crate::model::StepRunView,
        step: &RuntimeStep<'_>,
    ) -> Result<bool> {
        let Some(timeout) = step.spec.timeout_ms else {
            return Ok(false);
        };
        let timeout = timeout.saturating_add(view.timeout_extension_ms);
        let elapsed = view.execution_elapsed_ms;
        if elapsed >= timeout as u128 {
            return Ok(true);
        }
        if !matches!(view.status.as_str(), "claimed" | "working")
            || view.execution_started_at_unix_ms.is_none()
        {
            return Ok(false);
        }
        if let Ok(handle) = tokio::runtime::Handle::try_current() {
            let timeout_remaining = (timeout as u128).saturating_sub(elapsed);
            let lease_remaining = view
                .claim_expires_at_unix_ms
                .map_or(timeout_remaining, |expiry| expiry.saturating_sub(now_ms()));
            let remaining = timeout_remaining.min(lease_remaining).max(1) as u64;
            self.arm_step_deadline(&handle, &view.subject, remaining);
        }
        Ok(false)
    }

    /// Wake the reconciler in `remaining` ms for `step`, unless the step already armed a wake at
    /// or before then. Every pass asks again for every running step; arming a new timer each time
    /// left every pass a wake per running step minutes later, so passes kept themselves going
    /// (1,585 wakes in five minutes on a member with fourteen running steps).
    fn arm_step_deadline(&self, handle: &tokio::runtime::Handle, step: &str, remaining: u64) {
        self.arm_deadline(handle, step, remaining, "timer step-timeout");
    }

    /// Wake the reconciler in `remaining` ms for `key`, unless `key` already armed a wake at or
    /// before then; `wake` names the timer in wake accounting.
    fn arm_deadline(
        &self,
        handle: &tokio::runtime::Handle,
        key: &str,
        remaining: u64,
        wake: &'static str,
    ) {
        let now = now_ms();
        let deadline = now.saturating_add(u128::from(remaining));
        smallclaims::touched::note_due(deadline);
        {
            let mut armed = self
                .step_deadlines
                .lock()
                .unwrap_or_else(PoisonError::into_inner);
            if armed
                .get(key)
                .is_some_and(|at| *at > now && *at <= deadline)
            {
                return;
            }
            armed.insert(key.to_owned(), deadline);
        }
        let notify = self.notify.clone();
        let armed = self.step_deadlines.clone();
        let key = key.to_owned();
        handle.spawn(async move {
            tokio::time::sleep(Duration::from_millis(remaining)).await;
            {
                let mut armed = armed.lock().unwrap_or_else(PoisonError::into_inner);
                if armed.get(&key) == Some(&deadline) {
                    armed.remove(&key);
                }
            }
            crate::performance::record_wake(wake, None);
            notify.notify_one();
        });
    }

    /// Why a run-owned stop must wait for `seat`: it holds a message nobody has read, or work in a
    /// run other than the one that is ending. The stop declaration stays, so the seat stops once
    /// both are gone. Read at most every [`SEAT_RETENTION_CHECK_MS`] per seat.
    fn seat_retention(&self, seat: &str, owner_run: &str) -> Result<Option<String>> {
        if !seat.starts_with("agent/") {
            return Ok(None);
        }
        let now = now_ms();
        if let Some((at, reason, reads)) = self
            .seat_retention
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .get(seat)
            && now.saturating_sub(*at) < SEAT_RETENTION_CHECK_MS
        {
            // The cached answer stands until the next check, and depends on what that check read.
            for key in reads {
                smallclaims::touched::note_read(|| key.clone());
            }
            if reason.is_some() {
                smallclaims::touched::note_due(at.saturating_add(SEAT_RETENTION_CHECK_MS));
            }
            return Ok(reason.clone());
        }
        let (reason, reads) = smallclaims::touched::record(|| -> Result<Option<String>> {
            let unread = self
                .store
                .messages(Some(seat), false)?
                .into_iter()
                .any(|message| {
                    matches!(message.status.as_str(), "sent" | "staged" | "delivered")
                        && !message.tags.iter().any(|tag| {
                            tag.starts_with("st3-work:") || tag.starts_with("st3-wake-source:")
                        })
                });
            Ok(if unread {
                Some("the seat holds a message nobody has read".to_owned())
            } else if !self
                .store
                .seat_work_in_other_runs(seat, owner_run)?
                .is_empty()
            {
                Some("the seat holds work for another run".to_owned())
            } else {
                None
            })
        });
        let reason = reason?;
        self.seat_retention
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .insert(seat.to_owned(), (now, reason.clone(), reads));
        if reason.is_some() {
            self.arm_restart(
                &format!("retain:{seat}"),
                now.saturating_add(SEAT_RETENTION_CHECK_MS),
            );
        }
        Ok(reason)
    }

    /// A step has used its execution budget. A step with a worker raises one fault for its owner,
    /// who extends it with `st work extend`, completes it or fails it; the mission goes on. A step
    /// with no worker has no one to ask and fails.
    fn expire_step_timeout(
        &self,
        view: &crate::model::StepRunView,
        step: &RuntimeStep<'_>,
    ) -> Result<bool> {
        if view.agentless {
            return self.store.set_step_state(
                &view.subject,
                "failed",
                Some("the active execution timeout expired"),
            );
        }
        let episode = crate::store::step_timeout_episode(
            &view.subject,
            view.attempt,
            view.timeout_extension_ms,
        );
        {
            let mut raised = self
                .step_timeout_faults
                .lock()
                .unwrap_or_else(PoisonError::into_inner);
            if !raised.insert(episode.clone()) {
                return Ok(false);
            }
        }
        let budget = step
            .spec
            .timeout_ms
            .unwrap_or_default()
            .saturating_add(view.timeout_extension_ms);
        let owner = view
            .claimant
            .as_deref()
            .or(view.assigned_to.as_deref())
            .unwrap_or("AGENT");
        let step_id = &view.subject;
        let key = format!(
            "step-timeout:{step_id}:{}:{}",
            view.attempt, view.timeout_extension_ms
        );
        self.store.record_operational_failure(
            &episode,
            &AttentionRequest {
                reviewer: "person/operator".into(),
                title: "A step ran out of time".into(),
                reason: format!(
                    "`{step_id}` used its execution budget of {budget}ms. Nothing failed: the mission goes on and the step stays yours. If its goals are met, `st work complete {step_id} --as {owner} --summary TEXT`. If it needs more time, `st work extend {step_id} --as {owner} --by 2h --reason TEXT`. If it cannot finish, `st work fail {step_id} --as {owner} --reason TEXT`."
                ),
                severity: "error".into(),
                targets: vec![view.subject.clone()],
                actor: RECONCILER_ACTOR.into(),
                idempotency_key: key,
            },
        )?;
        Ok(true)
    }

    /// Raise one fault on `run` for its failed finally steps. It names each step and why it failed.
    fn record_final_step_faults(&self, run: &MissionRunView, failures: &[String]) -> Result<bool> {
        if failures.is_empty() {
            return Ok(false);
        }
        self.store.record_operational_failure(
            &format!("final-steps:{}", run.generation),
            &AttentionRequest {
                reviewer: "person/operator".into(),
                title: "A run's cleanup failed".into(),
                reason: format!(
                    "`{}` finished its work, so its outcome is not changed. Its finally steps failed: {}.",
                    run.subject,
                    failures.join("; ")
                ),
                severity: "warning".into(),
                targets: vec![run.subject.clone()],
                actor: RECONCILER_ACTOR.into(),
                idempotency_key: format!("final-steps:{}", run.generation),
            },
        )?;
        Ok(true)
    }

    fn reconcile_schedules(&self, desired: &[DesiredSubject]) -> Result<()> {
        for schedule in desired.iter().filter(|item| item.kind == "schedule") {
            self.isolate("schedule", &schedule.subject, || {
                self.reconcile_schedule(schedule)
            });
        }
        Ok(())
    }

    fn schedules_caught_up(&self) -> Result<bool> {
        schedule_admission_ready(
            &self.store,
            &self.host,
            &self.schedule_peers,
            self.started_at_unix_ms,
        )
    }

    /// Record this schedule's next occurrence and arm its timer.
    fn reconcile_schedule(&self, schedule: &DesiredSubject) -> Result<()> {
        self.store
            .owned_desired_guard(schedule)
            .map_err(anyhow::Error::new)?;
        let Some(spec) = crate::graph::schedule_spec(&schedule.desired, &self.host) else {
            return Ok(());
        };
        if spec.stopped || spec.host != self.host {
            return Ok(());
        }
        if self.schedule_has_open_work(&schedule.subject)? {
            return Ok(());
        }
        if !self.schedules_caught_up()? {
            self.arm_restart("stage/schedule-sync", now_ms().saturating_add(DEADLINE_SOURCE_RETRY_MS));
            return Ok(());
        }
        let Some(revision) = self.store.selected_desired_revision(&schedule.subject)? else {
            return Ok(());
        };
        let reached = self
            .store
            .claims_for(&schedule.subject, Some("schedule.occurrence-reached"))?;
        let last = reached
            .iter()
            .filter_map(|claim| {
                claim
                    .body
                    .pointer("/fields/occurrence")
                    .and_then(Value::as_u64)
            })
            .max();
        let now = now_ms() as i64;
        let (occurrence, scheduled_at) = if let Some(at) = spec.at_unix_ms {
            if last.is_some() {
                return Ok(());
            }
            (0_u64, at)
        } else if let Some(calendar) = &spec.calendar {
            calendar_occurrence(calendar, last, now, &spec.catch_up, spec.max_catch_up)?
        } else {
            let Some(interval) = spec.every_ms else {
                return Ok(());
            };
            let Some(anchor) = spec.anchor_unix_ms else {
                return Ok(());
            };
            let current = if now < anchor {
                0
            } else {
                ((now - anchor) as u64) / interval
            };
            let mut next = last.map_or(0, |value| value.saturating_add(1));
            if now >= anchor && next <= current {
                match spec.catch_up.as_str() {
                    "latest" => next = current,
                    "skip" => next = current.saturating_add(1),
                    "all" => {
                        let remaining = current.saturating_sub(next).saturating_add(1);
                        let max = spec.max_catch_up.unwrap_or(0);
                        if remaining > max as u64 {
                            self.record_once(
                                &schedule.subject,
                                "runtime.reconcile-decision",
                                BTreeMap::from([
                                    ("decision".into(), Value::String("raise".into())),
                                    ("reachability".into(), Value::String("unreachable".into())),
                                    (
                                        "reason".into(),
                                        Value::String("the schedule exceeds max-catch-up".into()),
                                    ),
                                ]),
                            )?;
                            // The schedule holds instead of starting a burst of missed work. That
                            // is a fault on the schedule, so it is seen rather than silently frozen.
                            anyhow::bail!(
                                "the missed occurrences exceed max-catch-up {max}; raise max-catch-up \
                                 or choose catch-up \"latest\" or \"skip\""
                            );
                        }
                    }
                    _ => return Ok(()),
                }
            }
            let offset = interval
                .checked_mul(next)
                .context("schedule occurrence overflow")?;
            let scheduled = anchor
                .checked_add(offset as i64)
                .context("schedule timestamp overflow")?;
            (next, scheduled)
        };
        let scheduled_at = if spec.calendar.is_some() {
            self.store
                .claims_for(&schedule.subject, Some("schedule.occurrence-scheduled"))?
                .into_iter()
                .find(|claim| {
                    claim.body["fields"]["revision"].as_str() == Some(revision.as_str())
                        && claim.body["fields"]["occurrence"].as_u64() == Some(occurrence)
                })
                .map(|claim| -> Result<i64> {
                    Ok(claim.body["fields"]["scheduled_at_unix_ms"]
                        .as_str()
                        .context("scheduled occurrence has no instant")?
                        .parse()?)
                })
                .transpose()?
                .unwrap_or(scheduled_at)
        } else {
            scheduled_at
        };
        let operation = format!("{}:{revision}:{occurrence}", schedule.subject);
        if !self
            .armed_schedules
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .insert(operation.clone())
        {
            return Ok(());
        }
        let request = self.store.append_claim(&ClaimInput {
            subject: schedule.subject.clone(),
            kind: "schedule.occurrence-scheduled".into(),
            actor: None,
            fields: BTreeMap::from([
                ("revision".into(), Value::String(revision.clone())),
                ("occurrence".into(), Value::from(occurrence)),
                (
                    "scheduled_at_unix_ms".into(),
                    Value::String(scheduled_at.to_string()),
                ),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(format!("clock-wake:{operation}")),
        })?;
        // The claim's instant remains authoritative when tzdata changes after arming.
        let scheduled_at = request
            .body
            .pointer("/fields/scheduled_at_unix_ms")
            .and_then(Value::as_str)
            .context("scheduled occurrence has no instant")?
            .parse::<i64>()?;
        self.event_notify
            .send_modify(|generation| *generation = generation.saturating_add(1));
        let work = spec.work.clone();
        let store = self.store.clone();
        let notify = self.notify.clone();
        let event_notify = self.event_notify.clone();
        let armed = self.armed_schedules.clone();
        let schedule_subject = schedule.subject.clone();
        let schedule_peers = self.schedule_peers.clone();
        let host = self.host.clone();
        let started_at = self.started_at_unix_ms;
        if let Ok(handle) = tokio::runtime::Handle::try_current() {
            handle.spawn(async move {
                let delay = scheduled_at.saturating_sub(now_ms() as i64).max(0) as u64;
                tokio::time::sleep(Duration::from_millis(delay)).await;
                if store
                    .selected_desired_revision(&schedule_subject)
                    .ok()
                    .flatten()
                    .as_deref()
                    != Some(revision.as_str())
                {
                    let _ = store.append_claim(&ClaimInput {
                        subject: schedule_subject.clone(),
                        kind: "schedule.occurrence-cancelled".into(),
                        actor: None,
                        fields: BTreeMap::from([
                            ("revision".into(), Value::String(revision.clone())),
                            ("occurrence".into(), Value::from(occurrence)),
                            (
                                "reason".into(),
                                Value::String("the schedule revision changed".into()),
                            ),
                        ]),
                        evidence: vec![request.id.clone()],
                        expected_subject: None,
                        idempotency_key: Some(format!("clock-cancel:{operation}")),
                    });
                    armed
                        .lock()
                        .unwrap_or_else(PoisonError::into_inner)
                        .remove(&operation);
                    signal_changed(&notify, &event_notify);
                    return;
                }
                // A timer can outlive a replication catch-up or another armed wake. Check at
                // admission as well as arming, including reached facts from older revisions.
                let ready = schedule_admission_ready(&store, &host, &schedule_peers, started_at)
                    .unwrap_or(false);
                let already_reached = store
                    .claims_for(&schedule_subject, Some("schedule.occurrence-reached"))
                    .map(|claims| {
                        claims.iter().any(|claim| {
                            claim.body["fields"]["occurrence"]
                                .as_u64()
                                .is_some_and(|value| value >= occurrence)
                        })
                    })
                    .unwrap_or(true);
                if !ready || already_reached {
                    armed
                        .lock()
                        .unwrap_or_else(PoisonError::into_inner)
                        .remove(&operation);
                    signal_changed(&notify, &event_notify);
                    return;
                }
                let reached = store.append_claim(&ClaimInput {
                    subject: schedule_subject.clone(),
                    kind: "schedule.occurrence-reached".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("revision".into(), Value::String(revision.clone())),
                        ("occurrence".into(), Value::from(occurrence)),
                        (
                            "scheduled_at_unix_ms".into(),
                            Value::String(scheduled_at.to_string()),
                        ),
                    ]),
                    evidence: vec![request.id],
                    expected_subject: None,
                    idempotency_key: Some(format!("clock-reached:{operation}")),
                });
                if let (Ok(reached), Some(work)) = (reached, work) {
                    let (selected_revision, failure_code, failure_reason) =
                        match scheduled_work_revision(&store, &work) {
                            Ok(Some(revision)) => (Some(revision), "", String::new()),
                            Ok(None) => (
                                None,
                                "no-ready-mission-revision",
                                format!(
                                    "mission/{} has no ready published head on schedule host",
                                    work.mission
                                ),
                            ),
                            Err(error) => (
                                None,
                                "mission-head-unavailable",
                                format!("cannot read mission/{} head: {error}", work.mission),
                            ),
                        };
                    let Some(selected_revision) = selected_revision else {
                        let _ = store.append_claim(&ClaimInput {
                            subject: schedule_subject.clone(),
                            kind: "schedule.work-failed".into(),
                            actor: None,
                            fields: BTreeMap::from([
                                ("request".into(), Value::String(reached.id.clone())),
                                ("code".into(), Value::String(failure_code.into())),
                                ("reason".into(), Value::String(failure_reason.clone())),
                            ]),
                            evidence: vec![reached.id.clone()],
                            expected_subject: None,
                            idempotency_key: Some(format!("schedule-work-failed:{operation}")),
                        });
                        if failure_code == "no-ready-mission-revision" {
                            let _ = request_schedule_head_attention(
                                &store,
                                &schedule_subject,
                                &reached.id,
                                &failure_reason,
                            );
                        }
                        armed
                            .lock()
                            .unwrap_or_else(PoisonError::into_inner)
                            .remove(&operation);
                        signal_changed(&notify, &event_notify);
                        return;
                    };
                    let _ = store.append_claim(&ClaimInput {
                        subject: schedule_subject.clone(),
                        kind: "schedule.work-requested".into(),
                        actor: None,
                        fields: BTreeMap::from([
                            ("revision".into(), Value::String(revision.clone())),
                            ("occurrence".into(), Value::from(occurrence)),
                            (
                                "mission".into(),
                                Value::String(format!("mission/{}", work.mission)),
                            ),
                            ("mission_revision".into(), Value::String(selected_revision)),
                            ("workspace".into(), Value::String(work.workspace)),
                            (
                                "inputs".into(),
                                serde_json::to_value(work.inputs).unwrap_or_default(),
                            ),
                        ]),
                        evidence: vec![reached.id],
                        expected_subject: None,
                        idempotency_key: Some(format!("schedule-work-request:{operation}")),
                    });
                }
                armed
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .remove(&operation);
                signal_changed(&notify, &event_notify);
            });
        } else {
            self.armed_schedules
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .remove(&operation);
        }
        Ok(())
    }

    fn schedule_has_open_work(&self, schedule: &str) -> Result<bool> {
        Ok(!self
            .store
            .pending_schedule_work_requests(schedule)?
            .is_empty()
            || self.store.schedule_has_active_started_run(schedule)?)
    }

    fn reconcile_scheduled_work(&self, desired: &[DesiredSubject]) -> Result<()> {
        for schedule in desired.iter().filter(|item| item.kind == "schedule") {
            self.isolate("schedule-work", &schedule.subject, || {
                self.reconcile_schedule_work(schedule)
            });
        }
        Ok(())
    }

    /// Start the work that this schedule's occurrences requested. A request that cannot start
    /// for a lasting reason is failed so the schedule can fire again. A request that waits for
    /// something this host has not received yet stays pending, and the schedule records why.
    fn reconcile_schedule_work(&self, schedule: &DesiredSubject) -> Result<()> {
        self.store
            .owned_desired_guard(schedule)
            .map_err(anyhow::Error::new)?;
        // Every peer replicates the same requests. Only the host that requested the work starts it.
        let requests = self
            .store
            .pending_schedule_work_requests(&schedule.subject)?
            .into_iter()
            .filter(|request| request.origin == self.host)
            .collect::<Vec<_>>();
        if requests.is_empty() {
            return Ok(());
        }
        if !self.schedules_caught_up()? {
            self.arm_restart("stage/schedule-sync", now_ms().saturating_add(DEADLINE_SOURCE_RETRY_MS));
            return Ok(());
        }
        // A stopped schedule's queued work is cancelled, so declaring the schedule again does not
        // start work that was requested before it stopped.
        if intake_is_stopped(schedule, &self.host) {
            for request in requests {
                self.fail_schedule_work(
                    schedule,
                    &request.id,
                    "schedule-stopped",
                    "the schedule stopped before this work started",
                )?;
            }
            return Ok(());
        }
        if self.store.schedule_has_active_started_run(&schedule.subject)?
        {
            return Ok(());
        }
        let mut waiting = Vec::new();
        for request in requests {
            if self
                .store
                .schedule_has_active_started_run(&schedule.subject)?
            {
                break;
            }
            let fields = request.body.get("fields").unwrap_or(&request.body);
            let field = |name: &str| fields.get(name).and_then(Value::as_str);
            let (Some(mission), Some(revision), Some(root), Some(occurrence)) = (
                field("mission"),
                field("mission_revision"),
                field("workspace"),
                fields.get("occurrence").and_then(Value::as_u64),
            ) else {
                self.fail_schedule_work(
                    schedule,
                    &request.id,
                    "invalid-request",
                    "the request names no mission, revision, workspace, or occurrence",
                )?;
                continue;
            };
            let occurrence_subject =
                Store::scheduled_mission_run_subject(&schedule.subject, occurrence);
            let suffix = &occurrence_subject.trim_start_matches("mission-run/")[..16];
            let workspace = Path::new(root).join(suffix);
            if let Err(error) = fs::create_dir_all(&workspace) {
                self.record_once(
                    &format!("daemon/{}", self.host),
                    "daemon.diagnostic",
                    BTreeMap::from([
                        ("severity".into(), Value::String("error".into())),
                        ("status".into(), Value::String("unavailable".into())),
                        ("code".into(), Value::String("workspace-unavailable".into())),
                        (
                            "reason".into(),
                            Value::String(format!(
                                "schedule {} workspace {}: {error}",
                                schedule.subject,
                                workspace.display()
                            )),
                        ),
                    ]),
                )?;
                continue;
            }
            let inputs = serde_json::from_value(fields.get("inputs").cloned().unwrap_or_default())
                .unwrap_or_default();
            let request_value = MissionRunRequest {
                mission: mission.into(),
                revision: Some(revision.into()),
                workspace: workspace.to_string_lossy().into_owned(),
                requester: Some(format!("daemon/{}", self.host)),
                mode: None,
                inputs,
                idempotency_key: format!("schedule-work:{}", request.id),
            };
            // Preserve a run created by an older daemon just before it could acknowledge this
            // request. New requests use the member-independent occurrence identity.
            let legacy_subject = self
                .store
                .mission_run_subject_for_idempotency_key(&request_value.idempotency_key);
            let created = if let Some(run) = self.store.mission_run(&legacy_subject)? {
                Ok(run)
            } else {
                match &schedule.owner_run {
                    Some(owner) => match self.store.mission_run(owner)? {
                        Some(parent) => self.store.create_scheduled_mission_run(
                            &request_value,
                            Some(&parent),
                            &schedule.subject,
                            occurrence,
                        ),
                        None => {
                            waiting.push(format!(
                                "request {}: its owner run {owner} is not stored here yet",
                                request.id
                            ));
                            continue;
                        }
                    },
                    None => self.store.create_scheduled_mission_run(
                        &request_value,
                        None,
                        &schedule.subject,
                        occurrence,
                    ),
                }
            };
            let run = match created {
                Ok(run) => run,
                Err(error) if error.code == "mission-run-capacity" => continue,
                Err(error) if start_waits_for_replication(&error) => {
                    waiting.push(format!("request {}: {error}", request.id));
                    continue;
                }
                Err(error) => {
                    self.fail_schedule_work(schedule, &request.id, error.code, &error.to_string())?;
                    continue;
                }
            };
            self.store.append_claim(&ClaimInput {
                subject: schedule.subject.clone(),
                kind: "schedule.work-started".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("request".into(), Value::String(request.id.clone())),
                    ("mission_run".into(), Value::String(run.subject)),
                ]),
                evidence: vec![request.id.clone()],
                expected_subject: None,
                idempotency_key: Some(format!("schedule-work-started:{}", request.id)),
            })?;
            let attention = schedule_head_attention_subject(&schedule.subject);
            if self
                .store
                .operational_failure(&attention)?
                .is_some_and(|item| item.status == "pending")
            {
                self.store.recover_operational_failure(
                    &attention,
                    "A subsequent schedule occurrence started successfully.",
                    &format!("schedule-head-ready:{}", run.id),
                )?;
            }
        }
        anyhow::ensure!(waiting.is_empty(), "{}", waiting.join("; "));
        Ok(())
    }

    fn fail_schedule_work(
        &self,
        schedule: &DesiredSubject,
        request: &str,
        code: &str,
        reason: &str,
    ) -> Result<()> {
        self.store.append_claim(&ClaimInput {
            subject: schedule.subject.clone(),
            kind: "schedule.work-failed".into(),
            actor: None,
            fields: BTreeMap::from([
                ("request".into(), Value::String(request.into())),
                ("code".into(), Value::String(code.into())),
                ("reason".into(), Value::String(reason.into())),
            ]),
            evidence: vec![request.into()],
            expected_subject: None,
            idempotency_key: Some(format!("schedule-work-failed:{request}")),
        })?;
        Ok(())
    }

    fn reconcile_subscription_missions(&self, desired: &[DesiredSubject]) -> Result<()> {
        self.recording_writes(|| self.reconcile_subscription_missions_pass(desired))
    }

    fn reconcile_subscription_missions_pass(&self, desired: &[DesiredSubject]) -> Result<()> {
        self.incremental.observe(&self.store)?;
        // Read once for every subscription: it lists the whole host's open attention requests.
        let held = self
            .store
            .pending_attention_requests_raised_by(RECONCILER_ACTOR, &self.host)?
            .into_iter()
            .filter(|request| request.title == "A subscription is holding mission requests")
            .collect::<Vec<_>>();
        let skip = self.skip_unneeded && !self.incremental.take_full_pass("subscription", now_ms());
        let mut items = BTreeSet::new();
        for item in desired.iter().filter(|item| item.kind == "subscription") {
            let key = format!("subscription:{}", item.subject);
            items.insert(key.clone());
            self.isolate("subscription", &item.subject, || {
                self.reconcile_item("subscription", &key, skip, || {
                    self.reconcile_subscription_mission(item, &held)
                })
            });
        }
        self.incremental.retain("subscription:", &items);
        Ok(())
    }

    /// Start the missions that this subscription's deliveries requested.
    fn reconcile_subscription_mission(
        &self,
        item: &DesiredSubject,
        held: &[crate::model::AttentionRequestView],
    ) -> Result<()> {
        let Some(spec) = crate::graph::subscription_spec(&item.desired) else {
            return Ok(());
        };
        // Every peer replicates the same requests. Only the declaring host starts their runs.
        if self
            .store
            .selected_desired_origin(&item.subject)?
            .as_deref()
            != Some(self.host.as_str())
        {
            return Ok(());
        }
        self.retire_legacy_held_subscription_attention(&item.subject, held)?;
        if spec.stopped {
            self.cancel_unstarted_subscription_requests(&item.subject)?;
            return Ok(());
        }
        if spec.delivery == "message"
            && let Some(every_ms) = spec.batch_every_ms
        {
            return self.send_subscription_batch(item, &spec, every_ms);
        }
        if spec.delivery != "mission" {
            return Ok(());
        }
        let requests = self
            .store
            .pending_subscription_mission_requests(&item.subject)?;
        if requests.is_empty() {
            return Ok(());
        }
        let mut latest_ref_requests = BTreeMap::new();
        for resource in requests.iter().filter_map(|request|
            request.body.pointer("/fields/resource").and_then(Value::as_str)).collect::<BTreeSet<_>>() {
            if self.store.latest_actual_value(resource)?.is_some_and(|actual|
                actual["kind"] == "vcs.ref" && actual["facts"]["head"].is_string()) {
                if let Some(request) = requests.iter().rev().find(|request|
                    request.body.pointer("/fields/resource").and_then(Value::as_str) == Some(resource)) {
                    latest_ref_requests.insert(resource.to_owned(), request.id.clone());
                }
            }
        }
        let is_held = |request: &crate::model::ClaimRecord| {
            request
                .body
                .pointer("/fields/held")
                .and_then(Value::as_bool)
                == Some(true)
        };
        let released = if requests.iter().any(is_held) {
            self.store
                .claims_for(&item.subject, Some("subscription.mission-request-released"))?
                .into_iter()
                .filter_map(|claim| {
                    claim
                        .body
                        .pointer("/fields/request")
                        .and_then(Value::as_str)
                        .map(str::to_owned)
                })
                .collect::<BTreeSet<_>>()
        } else {
            BTreeSet::new()
        };
        let mut capacity_waiting = BTreeSet::new();
        let mut waiting = Vec::new();
        for request in requests {
            // A queued review runs only for the current head of an open
            // pull request.
            let pull_request = request
                .body
                .pointer("/fields/resource")
                .and_then(Value::as_str)
                .filter(|resource| resource.contains("/pull-request/"))
                .zip(
                    request
                        .body
                        .pointer("/fields/discovery")
                        .and_then(Value::as_str),
                );
            if let Some((resource, discovery)) = pull_request
                && let Some(reason) = self.store.stale_pull_request_request(resource, discovery)?
            {
                self.store.append_claim(&ClaimInput {
                    subject: item.subject.clone(),
                    kind: "subscription.mission-request-cancelled".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("request".into(), Value::String(request.id.clone())),
                        ("reason".into(), Value::String(reason)),
                    ]),
                    evidence: vec![request.id.clone()],
                    expected_subject: None,
                    idempotency_key: Some(format!(
                        "subscription-stale-pull-request:{}",
                        request.id
                    )),
                })?;
                continue;
            }
            if let Some((resource, discovery)) = request.body.pointer("/fields/resource").and_then(Value::as_str)
                .zip(request.body.pointer("/fields/discovery").and_then(Value::as_str))
                && let Some(reason) = match latest_ref_requests.get(resource) {
                    Some(newest) if newest != &request.id => Some(format!("newer ref delivery {newest} supersedes this queued request")),
                    _ => self.store.stale_ref_request(resource, discovery)?,
                } {
                self.store.append_claim(&ClaimInput {
                    subject: item.subject.clone(), kind: "subscription.mission-request-cancelled".into(), actor: None,
                    fields: BTreeMap::from([("request".into(), Value::String(request.id.clone())), ("reason".into(), Value::String(reason))]),
                    evidence: vec![request.id.clone()], expected_subject: None,
                    idempotency_key: Some(format!("subscription-stale-ref:{}", request.id)),
                })?;
                continue;
            }
            // Older builds held excess deliveries for a person. Migrate current requests into
            // the automatic queue, even when their mission is still waiting for capacity.
            if is_held(&request) && !released.contains(&request.id) {
                self.store.append_claim(&ClaimInput {
                    subject: item.subject.clone(),
                    kind: "subscription.mission-request-released".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("request".into(), Value::String(request.id.clone())),
                        (
                            "reason".into(),
                            Value::String("migrated held request to the automatic queue".into()),
                        ),
                    ]),
                    evidence: vec![request.id.clone()],
                    expected_subject: None,
                    idempotency_key: Some(format!("subscription-request-queued:{}", request.id)),
                })?;
            }
            let fields = request.body.get("fields").unwrap_or(&request.body);
            let field = |name: &str| fields.get(name).and_then(Value::as_str);
            let (Some(mission), Some(resource), Some(discovery), Some(input), Some(root)) = (
                field("mission"),
                field("resource"),
                field("discovery"),
                field("resource_input"),
                field("workspace"),
            ) else {
                self.fail_subscription_request(
                    item,
                    &request.id,
                    "invalid-request",
                    "the request lacks a mission, resource, discovery, input, or workspace",
                )?;
                continue;
            };
            if resource.contains("/pull-request/") {
                if let Some(owner) = self.store.authoring_review_owner(discovery)? {
                    self.store.append_claim(&ClaimInput {
                        subject: item.subject.clone(),
                        kind: "subscription.mission-request-cancelled".into(),
                        actor: None,
                        fields: BTreeMap::from([
                            ("request".into(), Value::String(request.id.clone())),
                            (
                                "reason".into(),
                                Value::String(format!("{owner} owns the pull request review")),
                            ),
                        ]),
                        evidence: vec![request.id.clone()],
                        expected_subject: None,
                        idempotency_key: Some(format!(
                            "subscription-authoring-review:{}",
                            request.id
                        )),
                    })?;
                    continue;
                }
            }
            // A younger request must not pass an older capacity retry. Keep examining the
            // rest of the queue so stale requests are cancelled and legacy holds are migrated.
            if capacity_waiting.contains(mission) {
                continue;
            }
            let deferral = self
                .store
                .subscription_mission_deferral(&item.subject, &request.id)?;
            if let Some((deadline, _)) = deferral
                && deadline > now_ms()
            {
                smallclaims::touched::note_due(deadline);
                capacity_waiting.insert(mission.to_owned());
                continue;
            }
            let requester = field("requester")
                .map(str::to_owned)
                .unwrap_or_else(|| format!("daemon/{}", self.host));
            let suffix = &hex::encode(sha2::Sha256::digest(request.id.as_bytes()))[..16];
            let workspace = Path::new(root).join(suffix).to_string_lossy().into_owned();
            let request_value = MissionRunRequest {
                mission: mission.into(),
                revision: field("mission_revision").map(str::to_owned),
                workspace,
                requester: Some(requester),
                mode: None,
                inputs: BTreeMap::from([(input.into(), format!("{resource}@{discovery}"))])
                    .into_iter()
                    .chain(
                        field("text_input")
                            .zip(field("text"))
                            .map(|(name, text)| (name.to_owned(), text.to_owned())),
                    )
                    .collect(),
                idempotency_key: format!("subscription-mission:{}", request.id),
            };
            let parent = match &item.owner_run {
                Some(owner) => match self.store.mission_run(owner)? {
                    Some(parent) => Some(parent),
                    None => { waiting.push(format!("request {}: its owner run {owner} is not stored here yet", request.id)); continue; }
                },
                None => None,
            };
            let created = self.store.create_subscription_mission_run(&request_value, parent.as_ref(), &item.subject, resource, discovery);
            let run = match created {
                Ok(run) => run,
                Err(error) if error.code == "stale-ref-head" => {
                    self.store.append_claim(&ClaimInput {
                        subject: item.subject.clone(), kind: "subscription.mission-request-cancelled".into(), actor: None,
                        fields: BTreeMap::from([("request".into(), Value::String(request.id.clone())), ("reason".into(), Value::String(error.message))]),
                        evidence: vec![request.id.clone()], expected_subject: None,
                        idempotency_key: Some(format!("subscription-stale-ref:{}", request.id)),
                    })?;
                    continue;
                }
                Err(error) if error.code == "mission-run-capacity" => {
                    capacity_waiting.insert(mission.to_owned());
                    let attempt =
                        deferral.map_or(1_u32, |(_, attempts)| attempts.saturating_add(1));
                    let delay_ms =
                        1_000_u128.saturating_mul(1_u128 << attempt.saturating_sub(1).min(6));
                    let not_before = now_ms().saturating_add(delay_ms);
                    self.store.record_subscription_mission_deferral(
                        &item.subject,
                        &request.id,
                        not_before,
                        attempt,
                    )?;
                    smallclaims::touched::note_due(not_before);
                    continue;
                }
                // The request stays pending and starts once replication delivers what it names.
                Err(error) if start_waits_for_replication(&error) => {
                    waiting.push(format!("request {}: {error}", request.id));
                    continue;
                }
                Err(error) => {
                    self.fail_subscription_request(
                        item,
                        &request.id,
                        error.code,
                        &error.to_string(),
                    )?;
                    continue;
                }
            };
            self.store.append_claim(&ClaimInput {
                subject: item.subject.clone(),
                kind: "subscription.mission-started".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("request".into(), Value::String(request.id.clone())),
                    ("mission_run".into(), Value::String(run.subject)),
                ]),
                evidence: vec![request.id],
                expected_subject: None,
                idempotency_key: Some(format!("subscription-mission-started:{}", run.id)),
            })?;
        }
        anyhow::ensure!(waiting.is_empty(), "{}", waiting.join("; "));
        Ok(())
    }

    /// Send what a batched subscription collected since its last batch as one message, at most
    /// once per interval, and nothing when nothing arrived. The message and its `batch-sent`
    /// record are keyed by the newest batch they cover, so a crash between them sends nothing twice.
    fn send_subscription_batch(
        &self,
        item: &DesiredSubject,
        spec: &SubscriptionSpec,
        every_ms: u64,
    ) -> Result<()> {
        let batches = self
            .store
            .claims_for(&item.subject, Some("subscription.batched"))?;
        let sent = self
            .store
            .claims_for(&item.subject, Some("subscription.batch-sent"))?;
        let last = sent.last();
        let after = last
            .and_then(|claim| claim.body.pointer("/fields/through"))
            .and_then(Value::as_str)
            .and_then(|through| batches.iter().position(|claim| claim.id == through))
            .map_or(0, |position| position + 1);
        let pending = &batches[after.min(batches.len())..];
        let mut deadlines = self
            .batch_deadlines
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        let Some(newest) = pending.last() else {
            deadlines.remove(&item.subject);
            return Ok(());
        };
        let due = last.map_or(0, |claim| {
            claim
                .accepted_at_unix_ms
                .saturating_add(u128::from(every_ms))
        });
        if due > now_ms() {
            smallclaims::touched::note_due(due);
            deadlines.insert(item.subject.clone(), due);
            return Ok(());
        }
        deadlines.remove(&item.subject);
        drop(deadlines);
        let entries = pending
            .iter()
            .flat_map(|claim| {
                claim
                    .body
                    .pointer("/fields/entries")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default()
            })
            .collect::<Vec<_>>();
        let text = |entry: &Value, name: &str| {
            entry
                .get(name)
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_owned()
        };
        let lines = entries
            .iter()
            .map(|entry| {
                let who = [text(entry, "by"), text(entry, "author")]
                    .into_iter()
                    .find(|who| !who.is_empty())
                    .unwrap_or_else(|| "someone".into());
                let link = [text(entry, "url"), text(entry, "item_url")]
                    .into_iter()
                    .find(|link| !link.is_empty())
                    .unwrap_or_default();
                format!(
                    "- {} #{} {}: {}\n  {link}\n  by {who}; {}; marker {}",
                    text(entry, "repository"),
                    entry
                        .get("number")
                        .map(Value::to_string)
                        .unwrap_or_default(),
                    text(entry, "kind").replace('_', " "),
                    text(entry, "title"),
                    text(entry, "why"),
                    text(entry, "marker"),
                )
            })
            .collect::<Vec<_>>();
        let key = format!("subscription-batch-message:{}", newest.id);
        let message_subject = format!(
            "message/batch-{}",
            &hex::encode(sha2::Sha256::digest(key.as_bytes()))[..20]
        );
        let count = entries.len();
        self.store.append_claim(&ClaimInput {
            subject: message_subject.clone(),
            kind: "message.sent".into(),
            actor: None,
            fields: BTreeMap::from([
                (
                    "from".into(),
                    Value::String(format!("daemon/{}", self.host)),
                ),
                ("to".into(), Value::String(spec.to.clone())),
                (
                    "title".into(),
                    Value::String(format!(
                        "{count} GitHub item{} headed for a person",
                        if count == 1 { "" } else { "s" }
                    )),
                ),
                ("content".into(), Value::String(lines.join("\n"))),
                ("status".into(), Value::String("sent".into())),
                (
                    "tags".into(),
                    serde_json::json!(["resource-batch", item.subject]),
                ),
            ]),
            evidence: pending.iter().map(|claim| claim.id.clone()).collect(),
            expected_subject: None,
            idempotency_key: Some(key),
        })?;
        self.store.append_claim(&ClaimInput {
            subject: item.subject.clone(),
            kind: "subscription.batch-sent".into(),
            actor: None,
            fields: BTreeMap::from([
                ("through".into(), Value::String(newest.id.clone())),
                ("message".into(), Value::String(message_subject)),
                ("entries".into(), Value::from(count)),
            ]),
            evidence: vec![newest.id.clone()],
            expected_subject: None,
            idempotency_key: Some(format!("subscription-batch-sent:{}", newest.id)),
        })?;
        self.signal_changed();
        Ok(())
    }

    fn fail_subscription_request(
        &self,
        item: &DesiredSubject,
        request: &str,
        code: &str,
        reason: &str,
    ) -> Result<()> {
        self.store.append_claim(&ClaimInput {
            subject: item.subject.clone(),
            kind: "subscription.mission-failed".into(),
            actor: None,
            fields: BTreeMap::from([
                ("request".into(), Value::String(request.into())),
                ("code".into(), Value::String(code.into())),
                ("reason".into(), Value::String(reason.into())),
            ]),
            evidence: vec![request.into()],
            expected_subject: None,
            idempotency_key: Some(format!("subscription-mission-failed:{request}")),
        })?;
        Ok(())
    }

    /// Close each request that a stopped subscription recorded but never started, so a later
    /// declaration of the same subscription cannot start it.
    fn cancel_unstarted_subscription_requests(&self, subscription: &str) -> Result<()> {
        for request in self
            .store
            .pending_subscription_mission_requests(subscription)?
        {
            self.store.append_claim(&ClaimInput {
                subject: subscription.into(),
                kind: "subscription.mission-request-cancelled".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("request".into(), Value::String(request.id.clone())),
                    (
                        "reason".into(),
                        Value::String("the subscription stopped".into()),
                    ),
                ]),
                evidence: vec![request.id.clone()],
                expected_subject: None,
                idempotency_key: Some(format!("subscription-request-cancelled:{}", request.id)),
            })?;
        }
        Ok(())
    }

    /// Retire stored attention from the old burst cap. Queued requests now start automatically.
    fn retire_legacy_held_subscription_attention(
        &self,
        subscription: &str,
        held: &[crate::model::AttentionRequestView],
    ) -> Result<()> {
        smallclaims::touched::note_read(|| "kind:attention.requested".to_owned());
        for request in held {
            smallclaims::touched::note_read(|| request.subject.clone());
            if request.targets == [subscription] {
                self.store.resolve_attention_automatically(
                    &request.subject,
                    "subscription requests now wait in an automatic queue",
                    &format!("held-subscription-queued:{}", request.request),
                )?;
                self.signal_changed();
            }
        }
        Ok(())
    }

    /// `agents` is every declaration, so a repository listing can name the agent whose workspace
    /// has a new pull request's branch checked out; the intake list holds only observers,
    /// subscriptions, and schedules.
    fn reconcile_resource_observers(
        &self,
        desired: &[DesiredSubject],
        agents: &[DesiredSubject],
    ) -> Result<()> {
        let observer_resources = desired
            .iter()
            .filter(|item| item.kind == "observer")
            .filter_map(|item| {
                crate::graph::observer_spec(&item.desired)
                    .filter(|spec| !spec.stopped)
                    .map(|spec| (item.subject.clone(), spec.resource))
            })
            .collect::<HashMap<_, _>>();
        let mut subscriptions_by_resource =
            HashMap::<String, Vec<(String, SubscriptionSpec)>>::new();
        for (subject, subscription) in desired
            .iter()
            .filter(|item| item.kind == "subscription")
            .filter_map(|item| {
                crate::graph::subscription_spec(&item.desired)
                    .filter(|spec| !spec.stopped)
                    .map(|spec| (item.subject.clone(), spec))
            })
        {
            if let Some(resource) = observer_resources.get(&subscription.observer) {
                subscriptions_by_resource
                    .entry(resource.clone())
                    .or_default()
                    .push((subject, subscription));
            }
        }
        // A repository listing names the agent on this host that opened each new pull request.
        let agent_workspaces = Arc::new(
            agents
                .iter()
                .filter(|item| item.kind == "agent")
                .filter_map(|item| {
                    let member = item.member.as_ref()?;
                    let workspace = PathBuf::from(&member.workspace);
                    (member.host == self.host && workspace.is_absolute()).then(|| {
                        crate::resource::AgentWorkspace {
                            agent: item.subject.clone(),
                            run: item.owner_run.clone(),
                            workspace,
                        }
                    })
                })
                .collect::<Vec<_>>(),
        );
        for observer in desired.iter().filter(|item| item.kind == "observer") {
            self.isolate("observer", &observer.subject, || {
                self.reconcile_resource_observer(
                    observer,
                    &subscriptions_by_resource,
                    &agent_workspaces,
                )
            });
        }
        Ok(())
    }

    /// Settle a stopped observer, or arm this observer's next observation.
    fn reconcile_resource_observer(
        &self,
        observer: &DesiredSubject,
        subscriptions_by_resource: &HashMap<String, Vec<(String, SubscriptionSpec)>>,
        agent_workspaces: &Arc<Vec<crate::resource::AgentWorkspace>>,
    ) -> Result<()> {
        let Some(mut spec) = crate::graph::observer_spec(&observer.desired) else {
            return Ok(());
        };
        let selected = subscriptions_by_resource
            .get(&spec.resource)
            .cloned()
            .unwrap_or_default();
        if spec.stopped {
            let is_stopped = self
                .store
                .latest_actual_value(&observer.subject)?
                .and_then(|actual| {
                    actual
                        .get("state")
                        .and_then(Value::as_str)
                        .map(str::to_owned)
                })
                .as_deref()
                == Some("stopped");
            if !is_stopped {
                self.store.append_claim(&ClaimInput {
                    subject: observer.subject.clone(),
                    kind: "observer.state".into(),
                    actor: None,
                    fields: BTreeMap::from([("state".into(), Value::String("stopped".into()))]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: None,
                })?;
            }
            return Ok(());
        }
        if self
            .store
            .selected_desired_origin(&observer.subject)?
            .as_deref()
            != Some(self.host.as_str())
        {
            return Ok(());
        }
        spec.fields.extend(
            selected
                .iter()
                .filter(|(_, subscription)| subscription.observer == observer.subject)
                .flat_map(|(_, subscription)| subscription.fields.iter().cloned()),
        );
        spec.fields.sort();
        spec.fields.dedup();
        // A live subscription is a watch of this ref. Keep explicit faster intervals,
        // and use conditional reads every thirty seconds while anyone watches it.
        let watched_ref = spec.provider == "github.ref" && selected.iter().any(|(_, subscription)|
            subscription.observer == observer.subject && !subscription.stopped);
        if watched_ref {
            spec.every_ms = Some(spec.every_ms.unwrap_or(300_000).min(crate::resource::GITHUB_REF_WATCH_MS));
        }
        let Some(revision) = self.store.selected_desired_revision(&observer.subject)? else {
            return Ok(());
        };
        let observer_actual = self.store.latest_actual_value(&observer.subject)?;
        let refresh_attempt = self
            .store
            .pending_observer_refresh_attempt(&observer.subject)?;
        // A permanent error is not polled again on the same revision. A refresh request still
        // polls it once, so the observer and its subscriptions can recover without a new revision.
        if refresh_attempt.is_none()
            && observer_actual.as_ref().is_some_and(|actual| {
                actual.get("state").and_then(Value::as_str) == Some("degraded")
                    && actual.get("revision").and_then(Value::as_str) == Some(revision.as_str())
                    && actual
                        .get("error_code")
                        .and_then(Value::as_str)
                        .is_some_and(permanent_observation_error)
            })
        {
            return Ok(());
        }
        let deadline_key = format!("{}:{revision}", observer.subject);
        let mut next_check = refresh_attempt
            .as_ref()
            .map(|_| now_ms())
            .unwrap_or_else(|| {
                self.observer_deadlines
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .get(&deadline_key)
                    .copied()
                    .or_else(|| {
                        observer_actual
                            .as_ref()
                            .and_then(|actual| actual.get("next_check_unix_ms"))
                            .and_then(Value::as_str)
                            .and_then(|value| value.parse().ok())
                    })
                    .unwrap_or_else(now_ms)
            });
        // A changed cadence retires the old sleeping poll; its result cannot overwrite
        // a newer watcher observation if it was already in flight.
        if watched_ref && refresh_attempt.is_none() && observer_actual.as_ref().is_none_or(|actual|
            actual["error_code"] != "rate-limited") {
            next_check = next_check.min(now_ms().saturating_add(u128::from(spec.every_ms.unwrap())));
        }
        let operation_prefix = format!("{}:{revision}:{}:", observer.subject,
            refresh_attempt.as_deref().unwrap_or("scheduled"));
        let cadence_prefix = format!("{operation_prefix}{}:", spec.every_ms.map_or("default".into(), |ms| ms.to_string()));
        let operation = format!("{cadence_prefix}{}", uuid::Uuid::now_v7());
        {
            let mut armed = self.armed_observers.lock().unwrap_or_else(PoisonError::into_inner);
            armed.retain(|key| !key.starts_with(&operation_prefix) || key.starts_with(&cadence_prefix));
            if armed.iter().any(|key| key.starts_with(&cadence_prefix)) { return Ok(()); }
            armed.insert(operation.clone());
        }
        let store = self.store.clone();
        let provider = self.resource_provider.clone();
        let notify = self.notify.clone();
        let event_notify = self.event_notify.clone();
        let armed = self.armed_observers.clone();
        let deadlines = self.observer_deadlines.clone();
        let cursors = self.observer_cursors.clone();
        let observer_subject = observer.subject.clone();
        let previous_facts = self
            .store
            .latest_actual_value(&spec.resource)?
            .and_then(|actual| actual.get("facts").cloned());
        let cursor = self
            .observer_cursors
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .get(&deadline_key)
            .cloned()
            .unwrap_or_else(|| {
                observer_actual
                    .as_ref()
                    .and_then(|actual| actual.get("cursor"))
                    .and_then(Value::as_str)
                    .map(str::to_owned)
            });
        // A repository observer that never recorded anything continues from the observer that
        // last recorded into its resource, such as the intake observer a standing observer
        // replaces, so nothing changed between their polls is missed.
        let cursor = match cursor {
            None if spec.provider == "github.repository" => self
                .store
                .inherited_observer_cursor(&spec.resource, &observer.subject)?,
            cursor => cursor,
        };
        let agent_workspaces = agent_workspaces.clone();
        if let Ok(handle) = tokio::runtime::Handle::try_current() {
            handle.spawn(async move {
                let delay = next_check.saturating_sub(now_ms()).min(u64::MAX as u128) as u64;
                tokio::time::sleep(Duration::from_millis(delay)).await;
                if store
                    .selected_desired_revision(&observer_subject)
                    .ok()
                    .flatten()
                    .as_deref()
                    != Some(revision.as_str())
                {
                    armed
                        .lock()
                        .unwrap_or_else(PoisonError::into_inner)
                        .remove(&operation);
                    signal_changed(&notify, &event_notify);
                    return;
                }
                if !armed.lock().unwrap_or_else(PoisonError::into_inner).contains(&operation) { return; }
                let request = ObservationRequest {
                    provider: spec.provider.clone(),
                    locator: spec.locator.clone(),
                    fields: spec.fields.iter().cloned().collect(),
                    cursor,
                    previous_facts: previous_facts.clone(),
                    every_ms: spec.every_ms,
                    refresh: refresh_attempt.is_some(),
                };
                let observed =
                    crate::resource::spend_as(observer_subject.clone(), provider.observe(request))
                        .await;
                let mut active = armed.lock().unwrap_or_else(PoisonError::into_inner);
                if !active.contains(&operation)
                    || store.selected_desired_revision(&observer_subject).ok().flatten().as_deref() != Some(revision.as_str()) {
                    active.remove(&operation);
                    signal_changed(&notify, &event_notify);
                    return;
                }
                match observed {
                    Ok(mut observation) => {
                        if spec.provider == "github.repository" {
                            let recorded = recorded_pull_requests(
                                &store,
                                &spec.resource,
                                &observation.facts,
                                previous_facts.as_ref(),
                            );
                            crate::resource::attach_pull_request_openers(
                                &mut observation.facts,
                                Some(&recorded),
                                &agent_workspaces,
                            );
                        }
                        // A declared interval replaces the provider's own deadline, except a
                        // provider that asks to continue at once, such as a listing longer than
                        // one read.
                        if let Some(every_ms) = spec.every_ms
                            && observation.next_check_unix_ms
                                > now_ms().saturating_add(crate::resource::PROVIDER_CONTINUE_MS)
                        {
                            observation.next_check_unix_ms =
                                now_ms().saturating_add(every_ms as u128);
                        }
                        match store.record_resource_observation(
                            &observer_subject,
                            &revision,
                            refresh_attempt.as_deref(),
                            &spec.resource,
                            observation.cursor.as_deref(),
                            &observation.facts,
                            observation.next_check_unix_ms,
                            &selected,
                        ) {
                            Ok(_) => {
                                deadlines
                                    .lock()
                                    .unwrap_or_else(PoisonError::into_inner)
                                    .insert(deadline_key.clone(), observation.next_check_unix_ms);
                                cursors
                                    .lock()
                                    .unwrap_or_else(PoisonError::into_inner)
                                    .insert(deadline_key.clone(), observation.cursor);
                            }
                            Err(error) => {
                                let retry_at = now_ms().saturating_add(60_000);
                                deadlines
                                    .lock()
                                    .unwrap_or_else(PoisonError::into_inner)
                                    .insert(deadline_key.clone(), retry_at);
                                let reason = error.to_string();
                                let failure_hash = hex::encode(sha2::Sha256::digest(
                                    format!("{revision}:{}:{reason}", error.code).as_bytes(),
                                ));
                                let mut fields = BTreeMap::from([
                                    ("state".into(), Value::String("degraded".into())),
                                    ("reason".into(), Value::String(reason)),
                                    ("error_code".into(), Value::String(error.code.into())),
                                    ("revision".into(), Value::String(revision.clone())),
                                ]);
                                if let Some(attempt) = &refresh_attempt {
                                    fields.insert("attempt".into(), Value::String(attempt.clone()));
                                }
                                // A refresh that meets the same failure still records its
                                // attempt, which serves the refresh request.
                                let key = match &refresh_attempt {
                                    Some(attempt) => format!(
                                        "observer-rejected:{}:{attempt}",
                                        &failure_hash[..20]
                                    ),
                                    None => format!("observer-rejected:{}", &failure_hash[..20]),
                                };
                                let _ = store.append_claim(&ClaimInput {
                                    subject: observer_subject.clone(),
                                    kind: "observer.state".into(),
                                    actor: None,
                                    fields,
                                    evidence: Vec::new(),
                                    expected_subject: None,
                                    idempotency_key: Some(key),
                                });
                            }
                        }
                    }
                    Err(error) => {
                        let rate_limit = error.downcast_ref::<ProviderRateLimit>();
                        let retry_at = rate_limit.map_or_else(
                            || now_ms().saturating_add(60_000),
                            |limit| limit.retry_at_unix_ms.max(now_ms().saturating_add(1_000)),
                        );
                        let reason = error.to_string();
                        deadlines
                            .lock()
                            .unwrap_or_else(PoisonError::into_inner)
                            .insert(deadline_key.clone(), retry_at);
                        let previous = store.latest_actual_value(&observer_subject).ok().flatten();
                        let condition = ObserverCondition::of(&error, previous.as_ref());
                        let unchanged_failure = previous.as_ref().is_some_and(|actual| {
                            actual.get("state").and_then(Value::as_str) == Some("unreachable")
                                && actual.get("reason").and_then(Value::as_str)
                                    == Some(reason.as_str())
                        });
                        if !unchanged_failure || refresh_attempt.is_some() {
                            let failure_hash = hex::encode(sha2::Sha256::digest(
                                format!(
                                    "{operation}:{reason}:{}",
                                    store
                                        .claims_for(&observer_subject, Some("observer.state"))
                                        .unwrap_or_default()
                                        .into_iter()
                                        .rev()
                                        .find(|claim| claim.body["fields"]["state"] == "healthy")
                                        .map_or_else(|| "first".into(), |claim| claim.id)
                                )
                                .as_bytes(),
                            ));
                            let mut fields = BTreeMap::from([
                                ("state".into(), Value::String("unreachable".into())),
                                ("reason".into(), Value::String(reason)),
                                ("error_code".into(), Value::String(condition.code().into())),
                                ("revision".into(), Value::String(revision.clone())),
                                (
                                    "next_check_unix_ms".into(),
                                    Value::String(retry_at.to_string()),
                                ),
                            ]);
                            if let Some(attempt) = &refresh_attempt {
                                fields.insert("attempt".into(), Value::String(attempt.clone()));
                            }
                            let _ = store.append_claim(&ClaimInput {
                                subject: observer_subject.clone(),
                                kind: "observer.state".into(),
                                actor: None,
                                fields,
                                evidence: Vec::new(),
                                expected_subject: None,
                                idempotency_key: Some(format!(
                                    "observer-failure:{}",
                                    &failure_hash[..20]
                                )),
                            });
                        }
                    }
                }
                active.remove(&operation);
                drop(active);
                signal_changed(&notify, &event_notify);
            });
        } else {
            self.armed_observers
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .remove(&operation);
        }
        Ok(())
    }

    fn evaluate_gate(&self, stage: &GateContext, gate: &GateSpec) -> Result<GateOutcome> {
        let outcome = match gate {
            // A document exists once any version of its name is stored, or its exact version.
            GateSpec::Exists { subject, .. } if subject.starts_with("doc/") => {
                let exists = match subject.rsplit_once('@') {
                    Some((name, hash)) => self.store.get_document(name, hash)?.is_some(),
                    None => self.store.latest_document_hash(subject)?.is_some(),
                };
                if exists {
                    GateOutcome::Pass
                } else {
                    GateOutcome::Pending
                }
            }
            GateSpec::Exists { subject, .. } => {
                self.ensure_file_observation(subject)?;
                if self.subject_value(subject)?.is_some_and(|actual| {
                    actual_field(&actual, "status").and_then(Value::as_str) != Some("unreadable")
                }) {
                    GateOutcome::Pass
                } else {
                    GateOutcome::Pending
                }
            }
            GateSpec::Empty { subject, .. } => {
                let members = self
                    .store
                    .desired_subjects()?
                    .into_iter()
                    .filter(|item| {
                        item.owner_run.as_deref() == Some(subject) && item.member.is_some()
                    })
                    .collect::<Vec<_>>();
                let mut empty = true;
                for member in members {
                    if self
                        .store
                        .latest_actual_value(&member.subject)?
                        .is_some_and(|value| {
                            !matches!(
                                actual_field(&value, "status").and_then(Value::as_str),
                                Some("absent" | "stopped" | "exited")
                            )
                        })
                    {
                        empty = false;
                    }
                }
                if empty {
                    GateOutcome::Pass
                } else {
                    GateOutcome::Pending
                }
            }
            GateSpec::Field {
                path,
                subject,
                operator,
                value,
                ..
            } => {
                self.ensure_file_observation(subject)?;
                let Some(actual) = self.subject_value(subject)? else {
                    return Ok(GateOutcome::Pending);
                };
                let found = observed_field_value(&actual, subject, path);
                if found
                    .as_ref()
                    .is_some_and(|found| compare_value(found, operator, value))
                {
                    GateOutcome::Pass
                } else if let Some(reason) =
                    terminal_exec_field_gate_failure(&self.store, gate, &actual)?
                {
                    GateOutcome::Fail(reason)
                } else {
                    GateOutcome::Pending
                }
            }
            GateSpec::Every {
                path,
                subject,
                fields,
                ..
            }
            | GateSpec::NotEvery {
                path,
                subject,
                fields,
                ..
            } => {
                self.ensure_file_observation(subject)?;
                let Some(actual) = self.subject_value(subject)? else {
                    return Ok(GateOutcome::Pending);
                };
                let Some(items) = observed_field_value(&actual, subject, path)
                    .and_then(|value| value.as_array().cloned())
                else {
                    return Ok(GateOutcome::Pending);
                };
                let every = items.iter().all(|item| {
                    fields.iter().all(|field| {
                        actual_field(item, &field.path).is_some_and(|found| {
                            compare_value(found, &field.operator, &field.value)
                        })
                    })
                });
                let pass = matches!(gate, GateSpec::Every { .. }) == every;
                if pass {
                    GateOutcome::Pass
                } else {
                    GateOutcome::Pending
                }
            }
            GateSpec::Has { subject, text, .. } | GateSpec::Lacks { subject, text, .. } => {
                self.ensure_file_observation(subject)?;
                let Some(content) = self.subject_text(subject)? else {
                    return Ok(GateOutcome::Pending);
                };
                let contains = content.contains(text);
                let pass = matches!(gate, GateSpec::Has { .. }) == contains;
                if pass {
                    GateOutcome::Pass
                } else {
                    GateOutcome::Pending
                }
            }
            GateSpec::Deadline { duration_ms, .. } => {
                let elapsed = now_ms().saturating_sub(stage.started_at_unix_ms);
                if elapsed >= *duration_ms as u128 {
                    GateOutcome::Fail(format!("deadline expired after {duration_ms}ms"))
                } else {
                    smallclaims::touched::note_due(
                        stage
                            .started_at_unix_ms
                            .saturating_add(*duration_ms as u128),
                    );
                    if let Ok(handle) = tokio::runtime::Handle::try_current() {
                        let notify = self.notify.clone();
                        let remaining = (*duration_ms as u128).saturating_sub(elapsed) as u64;
                        handle.spawn(async move {
                            tokio::time::sleep(Duration::from_millis(remaining)).await;
                            crate::performance::record_wake("timer gate", None);
                            notify.notify_one();
                        });
                    }
                    GateOutcome::Pass
                }
            }
            GateSpec::Mechanical {
                name,
                command,
                host,
                workspace,
                environment,
                time_limit_ms,
                ..
            } => self.run_mechanical(
                stage,
                name,
                command,
                host,
                workspace,
                environment,
                *time_limit_ms,
            )?,
            GateSpec::Llm {
                name,
                model,
                host,
                workspace,
                tools,
                environment,
                token_budget,
                time_limit_ms,
                prompt,
            } => self.run_llm_gate(
                stage,
                name,
                model,
                host,
                workspace,
                tools,
                environment,
                *token_budget,
                *time_limit_ms,
                prompt,
            )?,
            GateSpec::Human { reviewer, .. } => {
                let operation = gate_operation_subject(
                    stage,
                    crate::graph::gate_name(gate),
                    &serde_json::to_value(gate)?,
                )?;
                let decision = self.store.latest_claim(&operation, Some("gate.result"))?;
                match decision.as_ref().and_then(|claim| {
                    (claim.actor.as_deref() == Some(reviewer.as_str()))
                        .then(|| {
                            claim
                                .body
                                .pointer("/fields/verdict")
                                .and_then(Value::as_str)
                        })
                        .flatten()
                }) {
                    Some("pass") => GateOutcome::Pass,
                    Some("fail") => GateOutcome::Fail(human_review_failure_reason(
                        decision.as_ref().expect("a failed decision exists"),
                    )),
                    _ => GateOutcome::Pending,
                }
            }
        };
        if matches!(outcome, GateOutcome::Pass | GateOutcome::Fail(_)) {
            let name = crate::graph::gate_name(gate);
            let digest = hex::encode(sha2::Sha256::digest(
                format!("{}:{name}", stage.subject).as_bytes(),
            ));
            let (verdict, reason) = match &outcome {
                GateOutcome::Pass => ("pass", None),
                GateOutcome::Fail(reason) => ("fail", Some(reason.clone())),
                GateOutcome::Pending | GateOutcome::NotYet | GateOutcome::Broken(_) => {
                    unreachable!()
                }
            };
            let mut fields = BTreeMap::from([
                ("stage".into(), Value::String(stage.subject.clone())),
                ("gate".into(), Value::String(name.to_owned())),
                ("verdict".into(), Value::String(verdict.into())),
            ]);
            if let Some(reason) = reason {
                fields.insert("reason".into(), Value::String(reason));
            }
            let subject = format!("gate-operation/predicate/{}", &digest[..32]);
            fields.insert("operation".into(), Value::String(subject.clone()));
            self.record_once(&subject, "gate.result", fields)?;
        }
        Ok(outcome)
    }

    /// Run an exec gate. Its check's exit status is its answer: 0 passes, 1 is not yet, and the
    /// gate checks again later. Anything else breaks the gate: another status, a check that was
    /// killed or ran past its time limit, a check that could not start, or an `st` call st refused
    /// or that read part of a listing. A broken gate raises one attention item for its mission's
    /// publisher and its boundary waits for a revision.
    #[allow(clippy::too_many_arguments)]
    fn run_mechanical(
        &self,
        stage: &GateContext,
        name: &str,
        command: &str,
        host: &str,
        workspace: &str,
        environment: &BTreeMap<String, String>,
        time_limit_ms: u64,
    ) -> Result<GateOutcome> {
        let result_subject = gate_result_subject(
            stage,
            name,
            &serde_json::json!({
                "type": "mechanical",
                "command": command,
                "host": host,
                "workspace": workspace,
                "environment": environment,
                "time_limit_ms": time_limit_ms,
            }),
        )?;
        // Each check records its result on the gate's first operation, so the newest result
        // there is the gate's answer. A later check runs as its own operation.
        let latest = self
            .store
            .latest_claim(&result_subject, Some("gate.result"))?;
        let check = match latest.as_ref() {
            None => 1,
            Some(result) => match gate_check_answer(result) {
                "pass" => return Ok(GateOutcome::Pass),
                "broken" => {
                    let reason = gate_result_reason(result, "the gate is broken");
                    self.raise_broken_gate(stage, name, &result_subject, result)?;
                    return Ok(GateOutcome::Broken(reason));
                }
                "not-yet" => {
                    let previous = result
                        .body
                        .pointer("/fields/value/check")
                        .and_then(Value::as_u64)
                        .unwrap_or(1);
                    let next = previous.saturating_add(1);
                    let started = self
                        .store
                        .latest_claim(
                            &gate_check_subject(&result_subject, next),
                            Some("gate.requested"),
                        )?
                        .is_some();
                    let due = result
                        .accepted_at_unix_ms
                        .saturating_add(self.gate_recheck_delay_ms(previous));
                    let now = now_ms();
                    if !started && now < due {
                        if let Ok(handle) = tokio::runtime::Handle::try_current() {
                            self.arm_deadline(
                                &handle,
                                &result_subject,
                                (due - now).min(u128::from(u64::MAX)) as u64,
                                "timer gate-recheck",
                            );
                        }
                        return Ok(GateOutcome::NotYet);
                    }
                    next
                }
                // A result an older st recorded: any status but 0 failed the gate.
                _ => {
                    return Ok(GateOutcome::Fail(gate_result_reason(
                        result,
                        "the mechanical gate failed",
                    )));
                }
            },
        };
        if host != self.host {
            return Ok(if check == 1 {
                GateOutcome::Pending
            } else {
                GateOutcome::NotYet
            });
        }
        let operation = gate_check_subject(&result_subject, check);
        let runtime_id = operation.replace('/', ".");
        let report = self.gate_report_path(&runtime_id);
        let check_result =
            |exit_code: Option<i64>, calls: Vec<String>, reason: Option<String>| GateCheck {
                name,
                host,
                result_subject: &result_subject,
                operation: &operation,
                check,
                exit_code,
                calls,
                output: self.gate_output(&runtime_id),
                start_failure: reason,
            };
        if let Some(requested) = self
            .store
            .latest_claim(&operation, Some("gate.requested"))?
        {
            let elapsed = now_ms().saturating_sub(requested.accepted_at_unix_ms);
            if elapsed >= time_limit_ms as u128 {
                self.stop_gate_runner(&operation, true)?;
                let mut check = check_result(None, crate::gate_report::read(&report), None);
                check.start_failure = Some(format!(
                    "its check ran past its time limit of {}",
                    render_duration_ms(time_limit_ms)
                ));
                return self.record_gate_check(stage, check);
            }
            smallclaims::touched::note_read(|| format!("exec:{runtime_id}"));
            return match self.runtime.observe_exec(&runtime_id)? {
                Some(observation) if observation.status == "exited" => {
                    let exit_code = self.gate_exit_code(&operation, &observation)?;
                    let check = check_result(exit_code, crate::gate_report::read(&report), None);
                    self.record_gate_check(stage, check)
                }
                _ => {
                    self.arm_gate_poll(&runtime_id);
                    Ok(GateOutcome::Pending)
                }
            };
        }

        if let Some(directory) = report.parent() {
            std::fs::create_dir_all(directory)?;
        }
        match std::fs::remove_file(&report) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
        self.record_once(
            &operation,
            "gate.requested",
            BTreeMap::from([
                ("status".into(), Value::String("requested".into())),
                ("runner".into(), Value::String("exec".into())),
                ("owner".into(), Value::String(stage.subject.clone())),
            ]),
        )?;
        let mut environment = environment.clone();
        environment.insert(
            crate::gate_report::ENV.into(),
            report.to_string_lossy().into_owned(),
        );
        let member = MemberSpec {
            kind: MemberKind::Exec,
            host: host.into(),
            runtime_id: runtime_id.clone(),
            workspace: workspace.into(),
            workspace_create: false,
            cwd: workspace.into(),
            terminal: false,
            launch: LaunchSpec::Shell(command.into()),
            environment,
            tags: BTreeMap::new(),
            display_name: None,
            lifecycle: MemberLifecycle::Service,
            restart: RestartType::Never,
            restart_intensity: RestartIntensity::default(),
            shutdown_timeout_ms: 5_000,
            driver: Some("mechanical-gate".into()),
        };
        let desired = DesiredSubject {
            subject: operation.clone(),
            kind: "gate".into(),
            desired: Value::Null,
            member: Some(member.clone()),
            owner_run: None,
            owner_generation: None,
            owner_step: None,
        };
        // A check that cannot start, such as one whose workspace is missing, cannot answer.
        if let Err(error) =
            self.perform_start(&desired, &member, "the mechanical gate was requested")
        {
            let check = check_result(
                None,
                Vec::new(),
                Some(format!("its check could not start: {error:#}")),
            );
            return self.record_gate_check(stage, check);
        }
        self.arm_gate_poll(&member.runtime_id);
        Ok(GateOutcome::Pending)
    }

    /// Record one finished exec gate check on the gate's result subject and answer for it.
    fn record_gate_check(&self, stage: &GateContext, check: GateCheck<'_>) -> Result<GateOutcome> {
        let broken = exec_check_broken(
            check.exit_code,
            &check.calls,
            check.start_failure.as_deref(),
        );
        let (answer, reason) = match (&broken, check.exit_code) {
            (Some(reason), _) => (
                "broken",
                format!("exec gate `{}` is broken: {reason}", check.name),
            ),
            (None, Some(0)) => ("pass", format!("exec gate `{}` passed", check.name)),
            (None, _) => (
                "not-yet",
                format!(
                    "exec gate `{}` is not ready yet (check {})",
                    check.name, check.check
                ),
            ),
        };
        // The replicated verdict keeps the values every fleet build accepts; `value.answer`
        // tells a not-yet `fail` and a broken `error` apart. See `gate_check_answer`.
        let verdict = match answer {
            "pass" => "pass",
            "not-yet" => "fail",
            _ => "error",
        };
        let mut value = serde_json::Map::from_iter([
            ("answer".into(), Value::String(answer.into())),
            ("check".into(), Value::from(check.check)),
            ("host".into(), Value::String(check.host.into())),
            (
                "exit_code".into(),
                check.exit_code.map_or(Value::Null, Value::from),
            ),
        ]);
        if !check.output.is_empty() {
            value.insert("output".into(), Value::String(check.output));
        }
        if !check.calls.is_empty() {
            value.insert(
                "calls".into(),
                Value::Array(check.calls.into_iter().map(Value::String).collect()),
            );
        }
        self.record_once(
            check.result_subject,
            "gate.result",
            BTreeMap::from([
                ("verdict".into(), Value::String(verdict.into())),
                ("reason".into(), Value::String(reason.clone())),
                ("gate".into(), Value::String(check.name.into())),
                ("operation".into(), Value::String(check.operation.into())),
                ("value".into(), Value::Object(value)),
            ]),
        )?;
        Ok(match answer {
            "pass" => GateOutcome::Pass,
            "not-yet" => {
                if let Ok(handle) = tokio::runtime::Handle::try_current() {
                    let delay = self.gate_recheck_delay_ms(check.check);
                    self.arm_deadline(
                        &handle,
                        check.result_subject,
                        delay.min(u128::from(u64::MAX)) as u64,
                        "timer gate-recheck",
                    );
                }
                GateOutcome::NotYet
            }
            _ => {
                if let Some(result) = self
                    .store
                    .latest_claim(check.result_subject, Some("gate.result"))?
                {
                    self.raise_broken_gate(stage, check.name, check.result_subject, &result)?;
                }
                GateOutcome::Broken(reason)
            }
        })
    }

    /// Raise the attention item for broken exec gate `name`, once per gate result and run
    /// generation. It goes to the publisher of the run's mission revision: an agent receives it
    /// as a fault, a person in their attention. It closes when a revision replaces the generation.
    fn raise_broken_gate(
        &self,
        stage: &GateContext,
        name: &str,
        result_subject: &str,
        result: &crate::model::ClaimRecord,
    ) -> Result<()> {
        // An eval run fails on a broken gate instead; see `evaluate_context_gate`.
        if stage.run.is_empty() || stage.eval {
            return Ok(());
        }
        let episode = format!("gate-broken:{}:{result_subject}", stage.generation);
        if !self
            .raised_broken_gates
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .insert(episode.clone())
        {
            return Ok(());
        }
        // A revision st recorded without its publisher goes to whoever requested the run.
        let publisher = match self.store.mission_run_publisher(&stage.run)? {
            Some(publisher) => publisher,
            None => self
                .store
                .mission_run(&stage.run)?
                .map(|run| run.requester)
                .unwrap_or_else(|| "person/operator".into()),
        };
        let fields = &result.body["fields"];
        let host = fields["value"]["host"].as_str().unwrap_or("unknown");
        let reason = gate_result_reason(result, "the gate is broken");
        let why = reason
            .strip_prefix(&format!("exec gate `{name}` is broken: "))
            .unwrap_or(&reason);
        let owner = match gate_owner_step(&stage.subject) {
            Some(_) => format!("Step `{}` of {}", stage.name, stage.run),
            None => format!("Mission run {}", stage.run),
        };
        let mut detail =
            format!("{owner} waits on gate `{name}`, which is broken on host `{host}`: {why}.");
        if let Some(output) = fields["value"]["output"]
            .as_str()
            .filter(|output| !output.trim().is_empty())
        {
            detail.push_str(&format!("\n\nOutput:\n{}", output.trim_end()));
        }
        detail.push_str(&format!(
            "\n\nThe work waits; st does not fail it for a broken gate. Revise the mission with a gate that answers (exit 0 to pass, 1 for not yet): `st work revise {} FILE --as ACTOR --reason TEXT`. A revision that changes only gates keeps the work already submitted and checks the revised gates.",
            stage.run
        ));
        let mut targets = vec![
            stage.run.clone(),
            stage.generation.clone(),
            result_subject.to_owned(),
        ];
        if let Some(step) = gate_owner_step(&stage.subject) {
            targets.push(step);
        }
        self.store.record_runtime_failure(
            &episode,
            &AttentionRequest {
                reviewer: publisher,
                title: format!("Gate `{name}` is broken"),
                reason: detail,
                severity: "error".into(),
                targets,
                actor: RECONCILER_ACTOR.into(),
                idempotency_key: episode.clone(),
            },
            crate::store::GATE_BROKEN_CONDITION,
        )?;
        Ok(())
    }

    /// When an exec gate checks again after check `check` said not yet: a minute after the
    /// first, doubling each time, and at most every fifteen minutes.
    fn gate_recheck_delay_ms(&self, check: u64) -> u128 {
        let doublings = u32::try_from(check.saturating_sub(1))
            .unwrap_or(u32::MAX)
            .min(16);
        self.gate_recheck_base_ms
            .saturating_mul(1_u128 << doublings)
            .min(GATE_RECHECK_MAX_MS)
    }

    /// The file a gate check's `st` commands report refusals and partial listings to.
    fn gate_report_path(&self, runtime_id: &str) -> PathBuf {
        self.driver_state_dir.join("gate-reports").join(runtime_id)
    }

    /// The end of a gate check's output, for its result and attention item.
    fn gate_output(&self, runtime_id: &str) -> String {
        let log = self
            .runtime
            .read_exec_log(runtime_id)
            .ok()
            .flatten()
            .unwrap_or_default();
        output_tail(&log, GATE_OUTPUT_LINES, GATE_OUTPUT_BYTES)
    }

    /// An exited gate runner's exit code. A runner that outlived a daemon restart is no longer
    /// this daemon's child, so the exec runtime finds it gone without a status. Its
    /// `st3 driver exec` wrapper reports the status to the graph before it exits, so that report
    /// decides. With neither, the wrapper itself was killed, and the runner has no exit code.
    fn gate_exit_code(
        &self,
        subject: &str,
        observation: &RuntimeObservation,
    ) -> Result<Option<i64>> {
        if observation.exit_code.is_some() {
            return Ok(observation.exit_code);
        }
        Ok(self
            .store
            .claims_for(subject, Some("runtime.observed"))?
            .into_iter()
            .rev()
            .find(|claim| claim.actor.as_deref() == Some(subject))
            .and_then(|claim| {
                claim
                    .body
                    .pointer("/fields/exit_code")
                    .and_then(Value::as_i64)
            }))
    }

    /// Watch gate runner `runtime_id` until it stops running. The poll reads only the runners'
    /// exec state and runs a full pass when one is no longer running: a pass every ten seconds for
    /// as long as a long gate ran was most of an idle member's reconcile work.
    fn arm_gate_poll(&self, runtime_id: &str) {
        // The runner's exit is not a claim; poll the evaluation that is waiting for it.
        smallclaims::touched::note_due(now_ms().saturating_add(GATE_POLL_INTERVAL.as_millis()));
        self.gate_poll_runtimes
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .insert(runtime_id.to_owned());
        if let Ok(handle) = tokio::runtime::Handle::try_current() {
            if self.gate_poll_armed.swap(true, Ordering::AcqRel) {
                return;
            }
            let notify = self.notify.clone();
            let armed = self.gate_poll_armed.clone();
            let runtimes = self.gate_poll_runtimes.clone();
            let runtime = self.runtime.clone();
            handle.spawn(async move {
                let armed_at = tokio::time::Instant::now();
                loop {
                    tokio::time::sleep(GATE_POLL_INTERVAL).await;
                    let watched = runtimes
                        .lock()
                        .unwrap_or_else(PoisonError::into_inner)
                        .clone();
                    let runtime = runtime.clone();
                    let all_running = tokio::task::spawn_blocking(move || {
                        watched.iter().all(|runtime_id| {
                            runtime.observe_exec(runtime_id).is_ok_and(|observation| {
                                observation.is_some_and(|item| item.status == "running")
                            })
                        })
                    })
                    .await
                    .unwrap_or(false);
                    if !all_running || armed_at.elapsed() >= GATE_POLL_PASS_INTERVAL {
                        break;
                    }
                }
                runtimes
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .clear();
                armed.store(false, Ordering::Release);
                crate::performance::record_wake("timer gate-poll", None);
                notify.notify_one();
            });
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn run_llm_gate(
        &self,
        stage: &GateContext,
        name: &str,
        model: &str,
        host: &str,
        workspace: &str,
        tools: &[String],
        environment: &BTreeMap<String, String>,
        token_budget: u64,
        time_limit_ms: u64,
        prompt: &str,
    ) -> Result<GateOutcome> {
        let result_subject = gate_result_subject(
            stage,
            name,
            &serde_json::json!({
                "type": "llm",
                "model": model,
                "host": host,
                "workspace": workspace,
                "tools": tools,
                "environment": environment,
                "token_budget": token_budget,
                "time_limit_ms": time_limit_ms,
                "prompt": prompt,
            }),
        )?;
        let runtime_id = result_subject.replace('/', ".");
        if let Some(result) = self.store.latest_actual_value(&result_subject)? {
            let verdict = actual_field(&result, "verdict")
                .and_then(Value::as_str)
                .unwrap_or("fail");
            let reason = actual_field(&result, "reason")
                .and_then(Value::as_str)
                .unwrap_or("the LLM gate failed");
            if let Some(token_usage) = actual_field(&result, "token_usage").and_then(Value::as_u64)
            {
                self.stop_gate_runner(&result_subject, false)?;
                if token_usage > token_budget {
                    return Ok(GateOutcome::Fail(format!(
                        "LLM gate `{name}` used {token_usage} tokens, above its {token_budget} token budget"
                    )));
                }
                return Ok(if verdict == "pass" {
                    GateOutcome::Pass
                } else {
                    GateOutcome::Fail(reason.into())
                });
            }
            // A runner that posted its verdict but never exits still has the gate's time limit.
            let timed_out = self
                .store
                .latest_claim(&result_subject, Some("gate.requested"))?
                .is_some_and(|requested| {
                    now_ms().saturating_sub(requested.accepted_at_unix_ms)
                        >= u128::from(time_limit_ms)
                });
            smallclaims::touched::note_read(|| format!("exec:{runtime_id}"));
            match self.runtime.observe_exec(&runtime_id)? {
                Some(observation) if observation.status == "running" && !timed_out => {
                    smallclaims::touched::note_due(now_ms().saturating_add(100));
                    if let Ok(handle) = tokio::runtime::Handle::try_current() {
                        let notify = self.notify.clone();
                        handle.spawn(async move {
                            tokio::time::sleep(Duration::from_millis(100)).await;
                            crate::performance::record_wake("timer llm-gate", None);
                            notify.notify_one();
                        });
                    }
                    return Ok(GateOutcome::Pending);
                }
                Some(observation) if observation.status == "indeterminate" && !timed_out => {
                    return Ok(GateOutcome::Pending);
                }
                _ => {}
            }
            if timed_out {
                self.stop_gate_runner(&result_subject, true)?;
            }
            let token_usage = self
                .runtime
                .read_exec_log(&runtime_id)?
                .as_deref()
                .and_then(structured_token_usage);
            let (verdict, reason, token_usage) = match token_usage {
                Some(token_usage) if token_usage > token_budget => (
                    "fail",
                    format!(
                        "LLM gate `{name}` used {token_usage} tokens, above its {token_budget} token budget"
                    ),
                    token_usage,
                ),
                Some(token_usage) => (verdict, reason.into(), token_usage),
                None if timed_out => (
                    "fail",
                    format!("LLM gate `{name}` exceeded {time_limit_ms}ms"),
                    0,
                ),
                None => (
                    "fail",
                    format!("LLM gate `{name}` did not report structured token usage"),
                    0,
                ),
            };
            self.record_once(
                &result_subject,
                "gate.result",
                BTreeMap::from([
                    ("verdict".into(), Value::String(verdict.into())),
                    ("reason".into(), Value::String(reason.clone())),
                    ("token_usage".into(), Value::from(token_usage)),
                ]),
            )?;
            return Ok(if verdict == "pass" {
                GateOutcome::Pass
            } else {
                GateOutcome::Fail(reason)
            });
        }
        if host != self.host {
            return Ok(GateOutcome::Pending);
        }
        if let Some(requested) = self
            .store
            .latest_claim(&result_subject, Some("gate.requested"))?
        {
            let elapsed = now_ms().saturating_sub(requested.accepted_at_unix_ms);
            if elapsed >= time_limit_ms as u128 {
                self.stop_gate_runner(&result_subject, true)?;
                self.record_once(
                    &result_subject,
                    "gate.result",
                    BTreeMap::from([
                        ("verdict".into(), Value::String("fail".into())),
                        (
                            "reason".into(),
                            Value::String(format!("LLM gate `{name}` exceeded {time_limit_ms}ms")),
                        ),
                        ("token_usage".into(), Value::from(0)),
                    ]),
                )?;
                return Ok(GateOutcome::Fail(format!(
                    "LLM gate `{name}` exceeded {time_limit_ms}ms"
                )));
            }
            smallclaims::touched::note_due(
                requested
                    .accepted_at_unix_ms
                    .saturating_add(time_limit_ms as u128),
            );
            if let Ok(handle) = tokio::runtime::Handle::try_current() {
                let notify = self.notify.clone();
                let remaining = (time_limit_ms as u128).saturating_sub(elapsed) as u64;
                handle.spawn(async move {
                    tokio::time::sleep(Duration::from_millis(remaining)).await;
                    crate::performance::record_wake("timer llm-gate", None);
                    notify.notify_one();
                });
            }
            return Ok(GateOutcome::Pending);
        }

        let (capability, capability_expires_at) =
            self.store
                .issue_capability("gate-result", &result_subject, None, time_limit_ms)?;
        self.record_once(
            &result_subject,
            "gate.requested",
            BTreeMap::from([
                ("status".into(), Value::String("requested".into())),
                ("model".into(), Value::String(model.into())),
                ("owner".into(), Value::String(stage.subject.clone())),
                ("token_budget".into(), Value::from(token_budget)),
                (
                    "tools".into(),
                    Value::Array(tools.iter().cloned().map(Value::String).collect()),
                ),
                (
                    "capability_hash".into(),
                    Value::String(hex::encode(sha2::Sha256::digest(capability.as_bytes()))),
                ),
                (
                    "capability_expires_at".into(),
                    Value::String(capability_expires_at.to_string()),
                ),
            ]),
        )?;
        let instruction = format!(
            "{prompt}\n\nYou are a held-out st gate. Inspect only the declared workspace and tools. When you decide, run exactly one of these commands:\n  \"$ST3_BIN\" gate-result pass --reason 'REASON'\n  \"$ST3_BIN\" gate-result fail --reason 'REASON'\nDo not finish without posting a gate-result."
        );
        let argv = if model.starts_with("claude") {
            vec![
                "claude".into(),
                "-p".into(),
                "--model".into(),
                model.into(),
                "--permission-mode".into(),
                "bypassPermissions".into(),
                "--output-format".into(),
                "json".into(),
                instruction,
            ]
        } else {
            vec![
                "codex".into(),
                "exec".into(),
                "--dangerously-bypass-approvals-and-sandbox".into(),
                "--model".into(),
                model.into(),
                "--json".into(),
                instruction,
            ]
        };
        let mut environment = environment.clone();
        environment.insert("ST_GATE_SUBJECT".into(), result_subject.clone());
        environment.insert("ST_GATE_CAPABILITY".into(), capability);
        environment.insert("ST3_TOKEN_BUDGET".into(), token_budget.to_string());
        let member = MemberSpec {
            kind: MemberKind::Exec,
            host: host.into(),
            runtime_id: result_subject.replace('/', "."),
            workspace: workspace.into(),
            workspace_create: false,
            cwd: workspace.into(),
            terminal: false,
            launch: LaunchSpec::Argv(argv),
            environment,
            tags: BTreeMap::new(),
            display_name: None,
            lifecycle: MemberLifecycle::Service,
            restart: RestartType::Never,
            restart_intensity: RestartIntensity::default(),
            shutdown_timeout_ms: 5_000,
            driver: Some("llm-gate".into()),
        };
        let desired = DesiredSubject {
            subject: result_subject,
            kind: "gate".into(),
            desired: Value::Null,
            member: Some(member.clone()),
            owner_run: None,
            owner_generation: None,
            owner_step: None,
        };
        self.perform_start(&desired, &member, "the LLM gate was requested")?;
        Ok(GateOutcome::Pending)
    }

    fn stop_gate_runner(&self, subject: &str, hard: bool) -> Result<()> {
        let runtime_id = subject.replace('/', ".");
        smallclaims::touched::note_read(|| format!("exec:{runtime_id}"));
        let Some(observation) = self.runtime.observe_exec(&runtime_id)? else {
            return Ok(());
        };
        if observation.status != "running" {
            return Ok(());
        }
        let incarnation = observation.incarnation_id.as_deref();
        let action = if hard { "kill-gate" } else { "stop-gate" };
        if self
            .store
            .observations_for(subject, "runtime.action.succeeded")?
            .iter()
            .any(|claim| {
                claim.body.pointer("/fields/action").and_then(Value::as_str) == Some(action)
                    && claim
                        .body
                        .pointer("/fields/incarnation_id")
                        .and_then(Value::as_str)
                        == incarnation
            })
        {
            return Ok(());
        }
        let request = self.store.append_claim(&ClaimInput {
            subject: subject.into(),
            kind: "runtime.action.requested".into(),
            actor: None,
            fields: BTreeMap::from([
                ("action".into(), Value::String(action.into())),
                ("runtime_id".into(), Value::String(runtime_id.clone())),
                (
                    "incarnation_id".into(),
                    incarnation.map_or(Value::Null, |value| Value::String(value.into())),
                ),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(format!(
                "{action}:{subject}:{}",
                incarnation.unwrap_or("unknown")
            )),
        })?;
        if hard {
            self.runtime.kill(&runtime_id, false, incarnation)?;
        } else {
            self.runtime.stop(&runtime_id, false, incarnation)?;
        }
        self.store.append_claim(&ClaimInput {
            subject: subject.into(),
            kind: "runtime.action.succeeded".into(),
            actor: None,
            fields: BTreeMap::from([
                ("action".into(), Value::String(action.into())),
                (
                    "incarnation_id".into(),
                    incarnation.map_or(Value::Null, |value| Value::String(value.into())),
                ),
            ]),
            evidence: vec![request.id],
            expected_subject: None,
            idempotency_key: Some(format!(
                "{action}-complete:{subject}:{}",
                incarnation.unwrap_or("unknown")
            )),
        })?;
        Ok(())
    }

    fn subject_text(&self, subject: &str) -> Result<Option<String>> {
        if subject.starts_with("doc/") {
            if let Some((name, hash)) = subject.rsplit_once('@') {
                return self
                    .store
                    .get_document(name, hash)?
                    .map(|bytes| String::from_utf8(bytes).map_err(Into::into))
                    .transpose();
            }
            let Some(hash) = self.store.latest_document_hash(subject)? else {
                return Ok(None);
            };
            return self
                .store
                .get_document(subject, &hash)?
                .map(|bytes| String::from_utf8(bytes).map_err(Into::into))
                .transpose();
        }
        let Some(actual) = self.subject_value(subject)? else {
            return Ok(None);
        };
        if let Some(content) = actual_field(&actual, "content").and_then(Value::as_str) {
            return Ok(Some(content.into()));
        }
        let Some(hash) = actual_field(&actual, "blob_hash").and_then(Value::as_str) else {
            return Ok(None);
        };
        self.store
            .get_blob(hash)?
            .map(|bytes| String::from_utf8(bytes).map_err(Into::into))
            .transpose()
    }

    fn subject_value(&self, subject: &str) -> Result<Option<Value>> {
        if subject.starts_with("resource/")
            && let Some((name, claim_id)) = subject.rsplit_once('@')
        {
            return Ok(self
                .store
                .claim_by_id(claim_id)?
                .filter(|claim| claim.subject == name)
                .map(|claim| claim.body));
        }
        self.store.latest_actual_value(subject)
    }

    fn ensure_file_observation(&self, subject: &str) -> Result<()> {
        let Some(rest) = subject.strip_prefix("file/") else {
            return Ok(());
        };
        let Some((host, path)) = rest.split_once(':') else {
            return Ok(());
        };
        if host != self.host {
            return Ok(());
        }
        self.ensure_file_watch(subject, Path::new(path))?;
        let before = FileStamp::read(Path::new(path));
        if before.as_ref().is_some_and(|stamp| {
            self.file_observations
                .lock()
                .unwrap_or_else(PoisonError::into_inner)
                .get(subject)
                == Some(stamp)
        }) {
            return Ok(());
        }
        match std::fs::read(path) {
            Ok(bytes) => {
                let blob_hash = self.store.put_blob(&bytes)?;
                let content_hash = hex::encode(sha2::Sha256::digest(&bytes));
                let after = FileStamp::read(Path::new(path));
                let mode = after.as_ref().map(|stamp| stamp.mode);
                let mut fields = BTreeMap::from([
                    ("status".into(), Value::String("observed".into())),
                    ("path".into(), Value::String(path.into())),
                    ("content_hash".into(), Value::String(content_hash)),
                    ("blob_hash".into(), Value::String(blob_hash)),
                    (
                        "content".into(),
                        Value::String(String::from_utf8_lossy(&bytes).into_owned()),
                    ),
                ]);
                if let Some(mode) = mode {
                    fields.insert("mode".into(), Value::from(mode));
                }
                self.record_once(subject, "file.observed", fields)?;
                let mut observations = self
                    .file_observations
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner);
                if before == after {
                    if let Some(stamp) = after {
                        observations.insert(subject.into(), stamp);
                    }
                } else {
                    observations.remove(subject);
                }
            }
            Err(error) => {
                self.file_observations
                    .lock()
                    .unwrap_or_else(PoisonError::into_inner)
                    .remove(subject);
                self.record_once(
                    subject,
                    "file.observed",
                    BTreeMap::from([
                        ("status".into(), Value::String("unreadable".into())),
                        ("path".into(), Value::String(path.into())),
                        ("reason".into(), Value::String(error.to_string())),
                    ]),
                )?;
            }
        }
        Ok(())
    }

    fn ensure_file_watch(&self, subject: &str, path: &Path) -> Result<()> {
        self.file_watchers_used
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .insert(subject.into());
        let mut watchers = self
            .file_watchers
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        if watchers.contains_key(subject) {
            return Ok(());
        }
        let notify = self.notify.clone();
        let observations = self.file_observations.clone();
        let incremental = self.incremental.clone();
        let watched_subject = subject.to_owned();
        let mut watcher =
            notify::recommended_watcher(move |event: notify::Result<notify::Event>| {
                if event.is_ok() {
                    observations
                        .lock()
                        .unwrap_or_else(PoisonError::into_inner)
                        .remove(&watched_subject);
                    // A file change is not a claim: mark what read the file.
                    incremental.touch(&watched_subject);
                    crate::performance::record_wake("file watch", None);
                    notify.notify_one();
                }
            })?;
        let watched = path
            .ancestors()
            .find(|candidate| candidate.exists())
            .unwrap_or(path);
        watcher.watch(watched, notify::RecursiveMode::NonRecursive)?;
        watchers.insert(subject.into(), watcher);
        Ok(())
    }

    fn release_unused_file_watchers(&self) {
        let used = std::mem::take(
            &mut *self
                .file_watchers_used
                .lock()
                .unwrap_or_else(PoisonError::into_inner),
        );
        self.file_watchers
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .retain(|subject, _| used.contains(subject));
        self.file_observations
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .retain(|subject, _| used.contains(subject));
    }
}

/// What the graph knows about each pull request a repository observation saw, in the listing
/// shape `attach_pull_request_openers` compares with: each item resource's facts, or the item in
/// the repository facts that builds before item resources kept.
fn recorded_pull_requests(
    store: &Store,
    repository: &str,
    facts: &Value,
    previous: Option<&Value>,
) -> Value {
    let legacy = previous
        .and_then(|facts| facts.get("pull_requests"))
        .and_then(Value::as_array);
    let items = facts
        .get("pull_requests")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|item| item.get("number").and_then(Value::as_u64))
        .filter_map(|number| {
            let recorded = store
                .latest_actual_value(&format!("{repository}/pull-request/{number}"))
                .ok()
                .flatten()
                .and_then(|actual| actual.get("facts").cloned())
                .map(|mut facts| {
                    if let Some(head) = facts.get("head_sha").cloned() {
                        facts["head"] = head;
                    }
                    facts
                });
            recorded.or_else(|| {
                legacy?
                    .iter()
                    .find(|item| item.get("number").and_then(Value::as_u64) == Some(number))
                    .cloned()
            })
        })
        .collect();
    serde_json::json!({ "pull_requests": Value::Array(items) })
}

fn permanent_observation_error(code: &str) -> bool {
    matches!(
        code,
        "stale-observer-revision"
            | "invalid-resource-observation"
            | "invalid-claim-field"
            | "unknown-resource-field"
            | "immutable-resource-field"
            | "claim-cardinality"
    )
}

/// How often the disk stage reads free space.
const DISK_CHECK_EVERY_MS: u128 = 30_000;
/// How often a host sends new faults to the agents it runs.
const FAULT_DELIVERY_EVERY_MS: u128 = 30_000;

type DiskProbe = Arc<dyn Fn(&Path) -> std::io::Result<crate::disk::DiskSpace> + Send + Sync>;
const RECONCILER_FAILING_TITLE: &str = "The reconciler is failing";

/// How long a fault must last before it asks a person. st retries a faulted item on every pass,
/// so most faults clear sooner and never reach anyone.
#[cfg(test)]
const FAULT_ATTENTION_AFTER_MS: u128 = 120_000;

/// Why an observer cannot observe, and whether a person has to act.
pub(crate) enum ObserverCondition {
    /// GitHub rejected the token or refused access. Nothing changes until a person acts.
    Access(String),
    /// A rate limit ends at a known reset. It needs a person only when the observer was already
    /// limited and is still limited after the reset that limit named.
    RateLimited { reason: String, outlasted: bool },
    /// Any other failure. A person looks at it once it has lasted an hour.
    Unreachable(String),
    /// The daemon rejected the observation itself. It is not polled again on this revision.
    Rejected(String),
}

/// How long after a named reset a rate limit counts as outlasting it, for clock skew.
const RATE_LIMIT_RESET_GRACE_MS: u128 = 60_000;
const OBSERVER_UNREACHABLE_ATTENTION_MS: u128 = 3_600_000;

impl ObserverCondition {
    fn of(error: &anyhow::Error, previous: Option<&Value>) -> Self {
        let reason = error.to_string();
        if error.downcast_ref::<ProviderForbidden>().is_some()
            || error.downcast_ref::<ProviderUnauthenticated>().is_some()
        {
            return Self::Access(reason);
        }
        if error.downcast_ref::<ProviderRateLimit>().is_some() {
            let outlasted = previous.is_some_and(|actual| {
                actual.get("state").and_then(Value::as_str) == Some("unreachable")
                    && actual.get("error_code").and_then(Value::as_str) == Some("rate-limited")
                    && actual
                        .get("next_check_unix_ms")
                        .and_then(Value::as_str)
                        .and_then(|value| value.parse::<u128>().ok())
                        .is_some_and(|reset| {
                            reset.saturating_add(RATE_LIMIT_RESET_GRACE_MS) <= now_ms()
                        })
            });
            return Self::RateLimited { reason, outlasted };
        }
        Self::Unreachable(reason)
    }

    fn code(&self) -> &'static str {
        match self {
            Self::Access(_) => "access-denied",
            Self::RateLimited { .. } => "rate-limited",
            Self::Unreachable(_) => "unreachable",
            Self::Rejected(_) => "rejected",
        }
    }

    pub(crate) fn needs_person(&self, failing_for_ms: u128) -> bool {
        match self {
            Self::Access(_) | Self::Rejected(_) => true,
            Self::RateLimited { outlasted, .. } => *outlasted,
            Self::Unreachable(_) => failing_for_ms >= OBSERVER_UNREACHABLE_ATTENTION_MS,
        }
    }

    pub(crate) fn title(&self) -> &'static str {
        match self {
            Self::Access(_) => "An observer has no access to GitHub",
            Self::RateLimited { .. } => "A GitHub rate limit outlasted its reset",
            Self::Unreachable(_) => "An observer has failed for an hour",
            Self::Rejected(_) => "st rejects an observer's observations",
        }
    }

    /// The cause and the command that fixes it. `host` polls the observer.
    pub(crate) fn reason(&self, subject: &str, host: &str) -> String {
        let closes = "This item closes when the observer observes again.";
        match self {
            Self::Access(reason) => format!(
                "{subject} cannot observe its resource: {reason}. Give the daemon account's GitHub token access to the repository, with `gh auth login` or `gh auth refresh -h github.com -s repo` as that account. The observer tries again on its own. {closes}"
            ),
            Self::RateLimited { reason, .. } => format!(
                "{subject} is still limited after the reset GitHub named: {reason}. Something else spends the GitHub budget that every host shares; `st doctor` on {host} shows how much of it remains, how much that host's observers spent, and each observer's requests. The observer waits for each reset on its own. {closes}"
            ),
            Self::Unreachable(reason) => format!(
                "{subject} has failed to observe for over an hour: {reason}. Inspect it with `st subject {subject}`. {closes}"
            ),
            Self::Rejected(reason) => format!(
                "st rejected an observation from {subject}: {reason}. Correct the observer's declaration and apply it again; inspect it with `st subject {subject}`. {closes}"
            ),
        }
    }
}

struct RuntimeStep<'a> {
    spec: &'a StepSpec,
    dependency_prefix: String,
    parent: Option<String>,
}

/// Each failed finally step of a run with the reason it failed.
fn final_step_failures(
    flat: &[RuntimeStep<'_>],
    views: &HashMap<&str, &crate::model::StepRunView>,
) -> Vec<String> {
    flat.iter()
        .filter(|step| step.spec.finally)
        .filter_map(|step| views.get(step.spec.path.as_str()))
        .filter(|view| view.status == "failed")
        .map(|view| {
            format!(
                "{}: {}",
                view.step,
                view.blocked_reason.as_deref().unwrap_or("the step failed")
            )
        })
        .collect()
}

fn flatten_mission_steps(mission: &MissionSpec) -> Vec<RuntimeStep<'_>> {
    fn append<'a>(
        mission: &'a MissionSpec,
        dependency_prefix: String,
        parent: Option<String>,
        output: &mut Vec<RuntimeStep<'a>>,
    ) {
        for id in &mission.display_order {
            let step = &mission.steps[id];
            output.push(RuntimeStep {
                spec: step,
                dependency_prefix: dependency_prefix.clone(),
                parent: parent.clone(),
            });
            if let Some(nested) = &step.nested_mission {
                append(
                    nested,
                    format!("{}/{}", step.path, nested.id),
                    Some(step.path.clone()),
                    output,
                );
            }
        }
    }
    let mut output = Vec::new();
    append(mission, String::new(), None, &mut output);
    output
}

fn step_run_selector(view: &crate::model::StepRunView) -> WorkSelector {
    if let Some(agent) = &view.assigned_to {
        WorkSelector::Assigned {
            agent: agent.clone(),
        }
    } else if !view.available_to.is_empty() {
        WorkSelector::Available {
            agents: view.available_to.clone(),
        }
    } else {
        WorkSelector::Agentless
    }
}

/// The full subject of the run that an `after-run` step waits for.
fn awaited_run(
    run: &MissionRunView,
    step: &RuntimeStep<'_>,
    view: &crate::model::StepRunView,
) -> Result<Option<String>> {
    let Some(after) = &step.spec.after_run else {
        return Ok(None);
    };
    let after = crate::mission::interpolate(after, &run_variables(run, step, view))?;
    Ok(Some(crate::mission::after_run_subject(&after)))
}

fn run_variables(
    run: &MissionRunView,
    step: &RuntimeStep<'_>,
    view: &crate::model::StepRunView,
) -> BTreeMap<String, String> {
    let parent_step_run = step
        .parent
        .as_ref()
        .map(|path| {
            format!(
                "step-run/{}/{}",
                run.generation
                    .strip_prefix("run-generation/")
                    .unwrap_or(&run.generation),
                path
            )
        })
        .or_else(|| run.parent_step_run.clone())
        .unwrap_or_default();
    let mut variables = BTreeMap::from([
        (
            "ST_MISSION".into(),
            run.mission
                .strip_prefix("mission/")
                .unwrap_or(&run.mission)
                .into(),
        ),
        ("ST_MISSION_REVISION".into(), run.revision.clone()),
        ("ST_MISSION_RUN".into(), run.id.clone()),
        (
            "ST_RUN_GENERATION".into(),
            run.generation
                .strip_prefix("run-generation/")
                .unwrap_or(&run.generation)
                .into(),
        ),
        ("ST_WORKSPACE".into(), run.workspace.clone()),
        ("ST_STEP".into(), step.spec.path.clone()),
        ("ST_STEP_RUN".into(), view.subject.clone()),
        ("ST_ATTEMPT".into(), view.attempt.to_string()),
        (
            "ST_ASSIGNEE".into(),
            view.assigned_to.clone().unwrap_or_default(),
        ),
        ("ST_REQUESTER".into(), run.requester.clone()),
        ("ST_PARENT_STEP_RUN".into(), parent_step_run),
        ("ST_ROOT_MISSION_RUN".into(), run.root_mission_run.clone()),
        (
            "ST_ROOT_MISSION_RUN_ID".into(),
            run.root_mission_run
                .strip_prefix("mission-run/")
                .unwrap_or(&run.root_mission_run)
                .into(),
        ),
        ("PATH".into(), "${PATH}".into()),
    ]);
    variables.extend(
        run.inputs
            .iter()
            .map(|(name, input)| (format!("input.{name}"), input.value.clone())),
    );
    if let Some(round) = run.inputs.get(LOOP_ROUND_INPUT) {
        variables.insert("ST_LOOP_ROUND".into(), round.value.clone());
        variables.insert("loop.round".into(), round.value.clone());
    }
    if let Some(feedback) = run.inputs.get(LOOP_FEEDBACK_INPUT) {
        variables.insert("ST_LOOP_FEEDBACK".into(), feedback.value.clone());
        variables.insert("loop.feedback".into(), feedback.value.clone());
    }
    if let Some(candidate) = run.inputs.get(CANDIDATE_INDEX_INPUT) {
        variables.insert("ST_CANDIDATE_INDEX".into(), candidate.value.clone());
        variables.insert("candidate.index".into(), candidate.value.clone());
    }
    if let Some(item) = run.inputs.get(LOOP_ITEM_INPUT)
        && let Ok(Value::Object(fields)) = serde_json::from_str::<Value>(&item.value)
    {
        for (name, value) in fields {
            let value = value
                .as_str()
                .map(str::to_owned)
                .unwrap_or_else(|| value.to_string());
            variables.insert(format!("loop.item.{name}"), value);
        }
        let id = variables.get("loop.item.id").cloned().unwrap_or_default();
        variables.insert("ST_LOOP_ITEM_ID".into(), id);
    }
    variables
}

pub(crate) fn expand_gate(
    gate: &mut GateSpec,
    variables: &BTreeMap<String, String>,
    run_workspace: &str,
) -> Result<()> {
    let expand = |value: &mut String| -> Result<()> {
        *value = crate::mission::interpolate(value, variables)?;
        Ok(())
    };
    match gate {
        GateSpec::Exists { subject, .. } | GateSpec::Empty { subject, .. } => expand(subject)?,
        GateSpec::Field { subject, value, .. } => {
            expand(subject)?;
            if let Value::String(value) = value {
                expand(value)?;
            }
        }
        GateSpec::Every {
            subject, fields, ..
        }
        | GateSpec::NotEvery {
            subject, fields, ..
        } => {
            expand(subject)?;
            for field in fields {
                if let Value::String(value) = &mut field.value {
                    expand(value)?;
                }
            }
        }
        GateSpec::Has { subject, text, .. } | GateSpec::Lacks { subject, text, .. } => {
            expand(subject)?;
            expand(text)?;
        }
        GateSpec::Mechanical {
            name,
            command,
            host,
            workspace,
            environment,
            ..
        } => {
            expand(command)?;
            expand(host)?;
            expand(workspace)?;
            if Path::new(workspace).is_relative() {
                *workspace = Path::new(run_workspace)
                    .join(&*workspace)
                    .to_string_lossy()
                    .into_owned();
            }
            for value in environment.values_mut() {
                expand(value)?;
            }
            environment.extend(variables.clone());
            environment.insert("ST_GATE".into(), name.clone());
        }
        GateSpec::Llm {
            name,
            model,
            host,
            workspace,
            environment,
            prompt,
            ..
        } => {
            expand(model)?;
            expand(host)?;
            expand(workspace)?;
            expand(prompt)?;
            if Path::new(workspace).is_relative() {
                *workspace = Path::new(run_workspace)
                    .join(&*workspace)
                    .to_string_lossy()
                    .into_owned();
            }
            for value in environment.values_mut() {
                expand(value)?;
            }
            environment.extend(variables.clone());
            environment.insert("ST_GATE".into(), name.clone());
        }
        GateSpec::Human {
            reviewer,
            question,
            review_targets,
            ..
        } => {
            expand(reviewer)?;
            if let Some(question) = question {
                expand(question)?;
            }
            for target in review_targets {
                expand(target)?;
            }
        }
        GateSpec::Deadline { .. } => {}
    }
    Ok(())
}

fn schedule_head_attention_subject(schedule: &str) -> String {
    let digest = hex::encode(sha2::Sha256::digest(schedule.as_bytes()));
    format!("attention/schedule-head-{}", &digest[..32])
}

fn request_schedule_head_attention(
    store: &Store,
    schedule: &str,
    occurrence: &str,
    reason: &str,
) -> Result<()> {
    let attention = schedule_head_attention_subject(schedule);
    if store
        .operational_failure(&attention)?
        .is_some_and(|item| item.status == "pending")
    {
        return Ok(());
    }
    store.record_operational_failure(
        &attention,
        &AttentionRequest {
            reviewer: "person/operator".into(),
            title: "A scheduled mission has no ready head".into(),
            reason: format!("{schedule}: {reason}. Publish a ready head to resume scheduled work."),
            severity: "warning".into(),
            targets: vec![schedule.into()],
            actor: RECONCILER_ACTOR.into(),
            idempotency_key: format!("schedule-head-unready:{occurrence}"),
        },
    )?;
    Ok(())
}

/// Select the authoritative head at the occurrence request boundary, never when a queued
/// request eventually starts. `None` means the current head is not ready, not that an older
/// ready revision may be used.
fn scheduled_work_revision(
    store: &Store,
    work: &crate::model::ScheduledWork,
) -> Result<Option<String>> {
    if let Some(revision) = &work.revision {
        return Ok(Some(revision.clone()));
    }
    Ok(store
        .mission_spec(&work.mission, None)?
        .filter(|head| head.state == MissionState::Ready)
        .map(|head| head.revision))
}

/// Report whether a lane, observer, subscription, or schedule declaration is a stop.
fn intake_is_stopped(subject: &DesiredSubject, host: &str) -> bool {
    match subject.kind.as_str() {
        "lane" => crate::graph::lane_spec(&subject.desired).is_some_and(|spec| spec.stopped),
        "observer" => {
            crate::graph::observer_spec(&subject.desired).is_some_and(|spec| spec.stopped)
        }
        "subscription" => {
            crate::graph::subscription_spec(&subject.desired).is_some_and(|spec| spec.stopped)
        }
        "schedule" => {
            crate::graph::schedule_spec(&subject.desired, host).is_some_and(|spec| spec.stopped)
        }
        _ => false,
    }
}

/// Return the step path of a `step-run/GENERATION/PATH` subject.
fn step_path_of_subject(subject: &str) -> Option<&str> {
    subject
        .strip_prefix("step-run/")?
        .split_once('/')
        .map(|(_, path)| path)
}

/// Whether a mission run could not start only because this host lacks a claim that replication
/// can still deliver, such as a mission revision, an owner run, or an input's claim published on
/// another host.
fn start_waits_for_replication(error: &crate::model::St3Error) -> bool {
    matches!(
        error.code,
        "missing-mission" | "missing-mission-run" | "missing-resource-input-version" | "internal"
    )
}

/// Run `item`, turning a panic into an error so one item cannot end the reconciler task.
fn caught<T>(item: impl FnOnce() -> Result<T>) -> Result<T> {
    std::panic::catch_unwind(AssertUnwindSafe(item)).unwrap_or_else(|panic| {
        Err(anyhow::anyhow!(
            "panicked: {}",
            panic_message(panic.as_ref())
        ))
    })
}

fn panic_message(panic: &(dyn std::any::Any + Send)) -> String {
    panic
        .downcast_ref::<&str>()
        .map(|message| (*message).to_owned())
        .or_else(|| panic.downcast_ref::<String>().cloned())
        .unwrap_or_else(|| "a panic without a message".into())
}

fn signal_changed(reconcile_notify: &Notify, event_notify: &watch::Sender<u64>) {
    crate::performance::record_wake("reconciler", None);
    reconcile_notify.notify_one();
    event_notify.send_modify(|generation| *generation = generation.saturating_add(1));
}

fn harness_incarnation_key(incarnation: &str) -> String {
    hex::encode(sha2::Sha256::digest(incarnation.as_bytes()))[..12].to_owned()
}

/// A declared product subject and the fields it must carry.
struct MissingProduct {
    subject: String,
    fields: Vec<(String, Value)>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum WorkWakeDecision {
    Wait,
    Request(u32),
    Exhaust,
}

fn work_wake_decision(
    attempts: u32,
    last_attempt_at_unix_ms: Option<u128>,
    first_attempt_at_unix_ms: Option<u128>,
    acknowledged: bool,
    now_unix_ms: u128,
) -> WorkWakeDecision {
    if acknowledged {
        return WorkWakeDecision::Wait;
    }
    let due = last_attempt_at_unix_ms
        .is_none_or(|last| now_unix_ms.saturating_sub(last) >= WORK_WAKE_RETRY_MS);
    if !due {
        WorkWakeDecision::Wait
    } else if attempts < WORK_WAKE_MAX_ATTEMPTS {
        WorkWakeDecision::Request(attempts.saturating_add(1))
    } else if first_attempt_at_unix_ms
        .is_none_or(|first| now_unix_ms.saturating_sub(first) < WORK_WAKE_EXHAUST_GRACE_MS)
    {
        WorkWakeDecision::Wait
    } else {
        WorkWakeDecision::Exhaust
    }
}

fn work_wake_acknowledged(
    attempts: &[(u128, &crate::model::MessageView)],
    harness: Option<&CurrentHarnessView>,
) -> bool {
    // A native read or close is durable evidence of a consumed wake even if a
    // short turn returned to ready before the harness observation caught it.
    attempts
        .iter()
        .any(|(_, message)| matches!(message.status.as_str(), "read" | "closed"))
        || attempts.first().is_some_and(|(requested, _)| {
            harness.is_some_and(|harness| {
                harness.state == "working" && harness.observed_at_unix_ms >= *requested
            })
        })
        // Pi-family drivers steer a wake into the turn that is already running, for example the
        // boot turn, and record delivery when the provider accepts it. That turn has consumed the
        // wake even though no new `working` edge follows. Another attempt would only interrupt it.
        || harness.is_some_and(|harness| harness.state == "working")
            && attempts
                .iter()
                .any(|(_, message)| message.status == "delivered")
        || harness.is_some_and(|harness| {
            harness.state == "working"
                && matches!(harness.driver.as_deref(), Some("pi" | "omp"))
        }) && attempts.iter().any(|(_, message)| message.status == "staged")
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn append_work_wake_message(
    store: &Store,
    step: &StepRunView,
    agent: &str,
    incarnation: &str,
    wake_attempt: u32,
    source: &str,
    requested_by: &str,
    reason: &str,
    idempotency_key: String,
) -> Result<MessageView> {
    let incarnation_key = harness_incarnation_key(incarnation);
    let message_id = &hex::encode(sha2::Sha256::digest(idempotency_key.as_bytes()))[..16];
    let message_subject = format!("message/{message_id}");
    let queue = step
        .queue
        .as_deref()
        .zip(step.queue_position)
        .map(|(queue, position)| format!("\nQueue: {queue} #{position}"))
        .unwrap_or_default();
    let wake_description = if source == "manual" {
        format!("manual request ({reason})")
    } else {
        format!("{source} attempt {wake_attempt} ({reason})")
    };
    let content = format!(
        "A mission step is ready: {0}. Run `st work claim {0} --as {2}` to read and claim it.\n\nTitle: {1}{queue}\nWake: {wake_description}",
        step.subject,
        step.title.as_deref().unwrap_or(&step.step),
        agent,
    );
    let tag_value = format!(
        "{}@{}@{}@{}",
        step.subject, step.attempt, step.readiness_epoch, incarnation_key
    );
    store.append_claim(&ClaimInput {
        subject: message_subject.clone(),
        kind: "message.sent".into(),
        actor: Some("daemon/runtime".into()),
        fields: BTreeMap::from([
            ("from".into(), Value::String("daemon/runtime".into())),
            ("to".into(), Value::String(agent.into())),
            ("content".into(), Value::String(content.clone())),
            ("status".into(), Value::String("sent".into())),
            (
                "title".into(),
                Value::String(format!(
                    "Mission step ready: {}",
                    step.title.as_deref().unwrap_or(&step.step)
                )),
            ),
            ("in_reply_to".into(), Value::Null),
            (
                "tags".into(),
                Value::Array(vec![
                    Value::String(format!("st3-work:{tag_value}")),
                    Value::String(format!("mission-run:{}", step.run)),
                    Value::String(format!("st3-wake-attempt:{wake_attempt}")),
                    Value::String(format!("st3-wake-source:{source}")),
                    Value::String(format!("st3-wake-requested-by:{requested_by}")),
                ]),
            ),
        ]),
        evidence: Vec::new(),
        expected_subject: None,
        idempotency_key: Some(idempotency_key),
    })?;
    Ok(MessageView {
        subject: message_subject,
        from: "daemon/runtime".into(),
        to: agent.into(),
        content,
        status: "sent".into(),
        title: Some(format!(
            "Mission step ready: {}",
            step.title.as_deref().unwrap_or(&step.step)
        )),
        in_reply_to: None,
        tags: vec![
            format!("st3-work:{tag_value}"),
            format!("mission-run:{}", step.run),
            format!("st3-wake-attempt:{wake_attempt}"),
            format!("st3-wake-source:{source}"),
            format!("st3-wake-requested-by:{requested_by}"),
        ],
        created_index: store
            .latest_claim(&format!("message/{message_id}"), Some("message.sent"))?
            .map(|claim| claim.store_index)
            .unwrap_or_default(),
            attachments: Vec::new(),
    })
}

/// Tell `agent` about a fault it owns, once per fault episode.
pub(crate) fn append_fault_message(
    store: &Store,
    agent: &str,
    fault: &AttentionItemView,
) -> Result<()> {
    let idempotency_key = format!("st3-fault:{agent}:{}:{}", fault.subject, fault.episode);
    let message_id = &hex::encode(sha2::Sha256::digest(idempotency_key.as_bytes()))[..16];
    let subject = format!("message/{message_id}");
    if store
        .latest_claim(&subject, Some("message.sent"))?
        .is_some()
    {
        return Ok(());
    }
    let inspect = fault
        .actions
        .iter()
        .map(|action| format!("`{}`", action.argv.join(" ")))
        .collect::<Vec<_>>();
    let mut content = format!("{}\n\n{}", fault.title, fault.detail);
    if !inspect.is_empty() {
        content.push_str(&format!("\n\nInspect: {}", inspect.join(", ")));
    }
    content.push_str(&format!(
        "\n\nThis fault is yours: st sends a broken gate to the agent that published its mission, and any other fault to the agent assigned to the failed step, else to the run's requester, else to the fleet's fault agent, and never to a person's now. Retry, revise or cancel the work. If you need something only a person can give, ask with `st work ask`.\n\nSource: {}",
        fault.subject
    ));
    let mut tags = vec![
        format!("st3-fault:{}", fault.episode),
        format!("st3-fault-source:{}", fault.subject),
    ];
    if let Some(run) = &fault.mission_run {
        tags.push(format!("mission-run:{run}"));
    }
    store.append_claim(&ClaimInput {
        subject,
        kind: "message.sent".into(),
        actor: Some("daemon/runtime".into()),
        fields: BTreeMap::from([
            ("from".into(), Value::String("daemon/runtime".into())),
            ("to".into(), Value::String(agent.into())),
            ("content".into(), Value::String(content)),
            ("status".into(), Value::String("sent".into())),
            (
                "title".into(),
                Value::String(format!("Fault: {}", fault.title)),
            ),
            ("in_reply_to".into(), Value::Null),
            (
                "tags".into(),
                Value::Array(tags.into_iter().map(Value::String).collect()),
            ),
        ]),
        evidence: Vec::new(),
        expected_subject: None,
        idempotency_key: Some(idempotency_key),
    })?;
    Ok(())
}

fn message_sent_at(store: &Store, message: &MessageView) -> Option<u128> {
    store
        .claims_for(&message.subject, Some("message.sent"))
        .ok()?
        .into_iter()
        .next()
        .map(|claim| claim.accepted_at_unix_ms)
}

fn work_wake_attempt_evidence(
    store: &Store,
    attempts: &[(u128, &MessageView)],
) -> Result<Vec<String>> {
    Ok(attempts
        .iter()
        .map(|(_, message)| store.latest_claim(&message.subject, Some("message.sent")))
        .collect::<Result<Vec<_>>>()?
        .into_iter()
        .flatten()
        .map(|claim| claim.id)
        .collect())
}

fn work_wake_deadline(
    work: &[StepRunView],
    local_agents: &BTreeSet<String>,
    run_orders: &BTreeMap<String, Vec<String>>,
    now: u128,
) -> Option<u128> {
    let wakes = local_agents
        .iter()
        .filter_map(|agent| {
            let order = run_orders.get(agent).map(Vec::as_slice).unwrap_or_default();
            next_work_wake_for_agent(agent, work, order)
        })
        .collect::<BTreeSet<_>>();
    work.iter()
        .filter(|step| {
            step.assigned_to
                .as_ref()
                .is_some_and(|assignee| local_agents.contains(assignee))
        })
        .filter(|step| wakes.contains(step.subject.as_str()))
        .filter_map(|step| {
            let wake = step.wake.as_ref()?;
            if wake.assignee_state == "working" && nested_under_work(step, work) {
                return None;
            }
            Some(wake)
        })
        .filter(|wake| {
            matches!(wake.assignee_state.as_str(), "ready" | "working" | "idle")
                && wake.acknowledged_by.is_none()
                && wake.failure.is_none()
                && wake.attempts <= WORK_WAKE_MAX_ATTEMPTS
        })
        .map(|wake| {
            let delay = if wake.attempts == WORK_WAKE_MAX_ATTEMPTS {
                // Reconcile once more after startup grace to record a genuine
                // exhaustion even when no other graph event arrives.
                WORK_WAKE_EXHAUST_GRACE_MS
            } else {
                WORK_WAKE_RETRY_MS
            };
            wake.last_attempt_at_unix_ms
                .map_or(now, |last| last.saturating_add(delay))
        })
        .min()
}

/// How long to sleep before the next pass. A deadline that was already due when the last pass
/// began, and that pass changed nothing, cannot be acted on yet, so the loop backs off instead of
/// spinning. A deadline that fell due during or after that pass has not been evaluated, so it
/// runs at once: a mission timeout must not wait out the back-off.
/// What a delayed restart key is for, without the subject it names, so the performance report's
/// wake table stays small: `stop`, `checkout`, `stage/faults`, or `member` for a member's own
/// restart backoff.
fn restart_wake_kind(key: &str) -> &str {
    match key.split_once(':') {
        Some((kind, _)) => kind,
        None if key.starts_with("stage/") || !key.contains('/') => key,
        None => "member",
    }
}

/// What a polled screen is compared by.
fn screen_digest(screen: &str) -> String {
    hex::encode(sha2::Sha256::digest(screen.as_bytes()))
}

fn deadline_sleep_ms(deadline: u128, now: u128, quiet_pass_started: Option<u128>) -> u64 {
    if quiet_pass_started.is_some_and(|started| deadline <= started) {
        WORK_WAKE_RETRY_MS as u64
    } else {
        deadline.saturating_sub(now).min(u128::from(u64::MAX)) as u64
    }
}

/// True when the seat holds nothing and has ready work in more than one run.
/// Only then can its run order change what it takes next.
fn seat_chooses_between_runs(agent: &str, work: &[StepRunView]) -> bool {
    let steps = work
        .iter()
        .map(crate::seat_queue::SeatStep::from)
        .collect::<Vec<_>>();
    let selection = crate::seat_queue::select(agent, &steps, &[]);
    if !selection.held.is_empty() {
        return false;
    }
    let mut runs = steps
        .iter()
        .filter(|step| selection.ready.contains(&step.subject))
        .map(|step| step.run);
    runs.next()
        .is_some_and(|first| runs.any(|run| run != first))
}

/// A maintained harness has one work seat. A claimed step occupies it, while
/// ready steps wait in the seat's ordered queue of mission runs.
fn next_work_wake_for_agent<'a>(
    agent: &str,
    work: &'a [StepRunView],
    run_order: &[String],
) -> Option<&'a str> {
    let steps = work
        .iter()
        .map(crate::seat_queue::SeatStep::from)
        .collect::<Vec<_>>();
    crate::seat_queue::select(agent, &steps, run_order).wake()
}

/// Inherited work is woken only after an early parent submission. A turn that is still working can
/// claim it without another message interrupting that turn; an idle seat gets the wake.
fn defers_inherited_work_wake(
    step: &StepRunView,
    work: &[StepRunView],
    harness: Option<&CurrentHarnessView>,
) -> bool {
    harness.is_some_and(|harness| harness.state == "working") && nested_under_work(step, work)
}

fn nested_under_work(step: &StepRunView, work: &[StepRunView]) -> bool {
    let nested = crate::seat_queue::SeatStep::from(step);
    work.iter().any(|ancestor| {
        crate::seat_queue::nests_under(&crate::seat_queue::SeatStep::from(ancestor), &nested)
    })
}

fn work_message_target(message: &crate::model::MessageView) -> Option<(&str, u32, u32, &str)> {
    message.tags.iter().find_map(|tag| {
        let mut parts = tag.strip_prefix("st3-work:")?.rsplitn(4, '@');
        let incarnation = parts.next()?;
        let readiness_epoch = parts.next()?.parse::<u32>().ok()?;
        let attempt = parts.next()?.parse::<u32>().ok()?;
        let step_subject = parts.next()?;
        Some((step_subject, attempt, readiness_epoch, incarnation))
    })
}

fn work_message_should_close(
    work: &[crate::model::StepRunView],
    step_subject: &str,
    attempt: u32,
    readiness_epoch: u32,
    message_incarnation: &str,
    current_incarnation: &str,
    turn_acknowledged: bool,
) -> bool {
    let current = work.iter().any(|step| {
        step.subject == step_subject
            && step.attempt == attempt
            && step.readiness_epoch == readiness_epoch
    });
    let acknowledged = work.iter().any(|step| {
        step.subject == step_subject
            && step.attempt == attempt
            && step.readiness_epoch == readiness_epoch
            && matches!(
                step.status.as_str(),
                "claimed" | "working" | "completed" | "failed" | "cancelled"
            )
    });
    !current || acknowledged || message_incarnation != current_incarnation || turn_acknowledged
}

fn structured_token_usage(log: &str) -> Option<u64> {
    let mut usages = Vec::new();
    let trimmed = log.trim();
    if let Ok(value) = serde_json::from_str::<Value>(trimmed) {
        collect_token_usage(&value, &mut usages);
    } else {
        for line in log.lines().map(str::trim).filter(|line| !line.is_empty()) {
            if let Ok(value) = serde_json::from_str::<Value>(line) {
                collect_token_usage(&value, &mut usages);
            }
        }
    }
    usages.into_iter().max()
}

fn collect_token_usage(value: &Value, usages: &mut Vec<u64>) {
    match value {
        Value::Object(object) => {
            if let Some(Value::Object(usage)) = object.get("usage")
                && let Some(total) = token_usage_total(usage)
            {
                usages.push(total);
            }
            for nested in object.values() {
                collect_token_usage(nested, usages);
            }
        }
        Value::Array(values) => {
            for nested in values {
                collect_token_usage(nested, usages);
            }
        }
        _ => {}
    }
}

fn token_usage_total(usage: &serde_json::Map<String, Value>) -> Option<u64> {
    for key in ["total_tokens", "totalTokens"] {
        if let Some(total) = usage.get(key).and_then(Value::as_u64) {
            return Some(total);
        }
    }
    let keys = [
        "input_tokens",
        "inputTokens",
        "output_tokens",
        "outputTokens",
        "cache_creation_input_tokens",
        "cacheCreationInputTokens",
        "cache_read_input_tokens",
        "cacheReadInputTokens",
    ];
    let mut found = false;
    let total = keys.into_iter().fold(0_u64, |total, key| {
        usage
            .get(key)
            .and_then(Value::as_u64)
            .map_or(total, |value| {
                found = true;
                total.saturating_add(value)
            })
    });
    found.then_some(total)
}

#[derive(Debug)]
enum GateOutcome {
    Pass,
    Pending,
    /// An exec gate's check exited 1: the boundary waits, and the gate checks again later.
    NotYet,
    /// An exec gate cannot answer as written: its check exited with another status, was killed,
    /// ran past its time limit, or made an `st` call st refused or read part of a listing. Its
    /// mission's publisher has an attention item; the boundary waits for a revision.
    Broken(String),
    Fail(String),
}

fn human_review_failure_reason(decision: &crate::model::ClaimRecord) -> String {
    match decision
        .body
        .pointer("/fields/reason")
        .and_then(Value::as_str)
        .filter(|reason| !reason.trim().is_empty())
    {
        Some(reason) => format!("the human reviewer rejected the work: {reason}"),
        None => "the human reviewer rejected the work".into(),
    }
}

enum LoopBranchOutcome {
    Pending,
    Completed,
    Failed(String),
}

enum LoopCandidateSelection {
    Pending,
    NoWinner,
    Winner(u32),
}

enum UsedMissionOutcome {
    Pending,
    Completed,
    Failed(String),
}

/// The st executable members launch with. A deploy installs the new binary before it restarts
/// the daemon, and in between Linux names this process's image `PATH (deleted)`. Launching that
/// name fails every start in the window and can hold a seat in a crash loop, so use the
/// replacement installed at the original path.
pub(crate) fn launch_executable() -> Result<PathBuf> {
    let current = std::env::current_exe()?;
    Ok(replaced_executable(&current).unwrap_or(current))
}

fn replaced_executable(current: &Path) -> Option<PathBuf> {
    let original = PathBuf::from(current.to_str()?.strip_suffix(" (deleted)")?);
    original.is_file().then_some(original)
}

/// The st binary every seat follows: a link beneath the state directory that names the
/// executable the daemon runs. Seats get this path as `ST3_BIN`. Their drivers and channels
/// re-execute once the file it names changes, so a deploy that starts the daemon from a new path,
/// such as a new Nix store path, moves every seat with it, and so does a deploy that replaces the
/// daemon's executable in place. A seat given the executable's own path would watch a file that
/// never changes and keep running the old code.
pub fn st_binary_link(state_dir: &Path) -> PathBuf {
    state_dir.join("current").join("st3")
}

/// Point [`st_binary_link`] at the executable this daemon runs, replacing the link atomically.
pub fn publish_st_binary(state_dir: &Path) -> Result<PathBuf> {
    let link = st_binary_link(state_dir);
    let executable = launch_executable()?;
    // Resolve symbolic links, so a daemon started through this link cannot point it at itself.
    let target = std::fs::canonicalize(&executable)
        .with_context(|| format!("resolve the st executable {}", executable.display()))?;
    match std::fs::read_link(&link) {
        Ok(current) if current == target => return Ok(link),
        // The daemon runs this very file; it stays as it is.
        Err(_) if std::fs::canonicalize(&link).is_ok_and(|path| path == target) => {
            return Ok(link);
        }
        _ => {}
    }
    let directory = link
        .parent()
        .context("the st binary link has no directory")?;
    std::fs::create_dir_all(directory)
        .with_context(|| format!("create {}", directory.display()))?;
    let staged = directory.join(format!(".st3.{}.link", std::process::id()));
    let _ = std::fs::remove_file(&staged);
    std::os::unix::fs::symlink(&target, &staged)
        .with_context(|| format!("link {} to {}", staged.display(), target.display()))?;
    std::fs::rename(&staged, &link).with_context(|| format!("publish {}", link.display()))?;
    Ok(link)
}

fn member_fields(
    member: &MemberSpec,
    status: &str,
    incarnation_id: Option<&str>,
    adopted: bool,
) -> BTreeMap<String, Value> {
    let mut fields = BTreeMap::from([
        ("status".into(), Value::String(status.into())),
        (
            "runtime_id".into(),
            Value::String(member.runtime_id.clone()),
        ),
        ("terminal".into(), Value::Bool(member.terminal)),
        ("host".into(), Value::String(member.host.clone())),
        ("adopted".into(), Value::Bool(adopted)),
        (
            "shutdown_timeout_ms".into(),
            Value::from(member.shutdown_timeout_ms),
        ),
        ("reachability".into(), Value::String("reachable".into())),
        ("reason".into(), Value::Null),
    ]);
    if let Some(incarnation_id) = incarnation_id {
        fields.insert(
            "incarnation_id".into(),
            Value::String(incarnation_id.into()),
        );
    }
    fields
}

enum RestartDecision {
    Start,
    Wait { until: u128, reason: String },
    Fail { reason: String },
}

fn launch_in_restart_window(
    store_index: u64,
    accepted_at_unix_ms: u128,
    reset_index: u64,
    now: u128,
    interval_ms: u64,
    mode: &str,
) -> bool {
    store_index > reset_index
        && (mode != "fail" || accepted_at_unix_ms > now.saturating_sub(interval_ms as u128))
}

fn actual_field<'a>(actual: &'a Value, path: &str) -> Option<&'a Value> {
    let mut value = actual.get("fields").unwrap_or(actual);
    for segment in path.split('.') {
        value = value.get(segment)?;
    }
    Some(value)
}

fn owned_field(mut value: Value, path: &str) -> Option<Value> {
    for segment in path.split('.') {
        value = value.get(segment)?.clone();
    }
    Some(value)
}

fn observed_field_value(actual: &Value, subject: &str, path: &str) -> Option<Value> {
    if subject.starts_with("file/") {
        actual_field(actual, "content")
            .and_then(Value::as_str)
            .and_then(|content| serde_json::from_str::<Value>(content).ok())
            .and_then(|content| owned_field(content, path))
    } else {
        let actual = if subject.starts_with("resource/") {
            actual.get("facts").unwrap_or(actual)
        } else {
            actual
        };
        actual_field(actual, path).cloned()
    }
}

fn compare_value(found: &Value, operator: &str, expected: &Value) -> bool {
    match operator {
        "is" => found == expected,
        "starts-with" => found
            .as_str()
            .zip(expected.as_str())
            .is_some_and(|(found, expected)| found.starts_with(expected)),
        "contains" => match (found, expected) {
            (Value::String(found), Value::String(expected)) => found.contains(expected),
            (Value::Array(found), expected) => found.contains(expected),
            _ => false,
        },
        _ => false,
    }
}

/// An exec's exit code cannot change after its selected launch ends without a restart.
/// Read only graph observations and declarations: runtime polling and wall time must not
/// influence a predicate verdict on a replica or during replay.
fn terminal_exec_field_gate_failure(
    store: &Store,
    gate: &GateSpec,
    actual: &Value,
) -> Result<Option<String>> {
    let GateSpec::Field {
        name,
        path,
        subject,
        operator,
        value,
    } = gate
    else {
        return Ok(None);
    };
    if !subject.starts_with("exec/")
        || path != "exit_code"
        || observed_field_value(actual, subject, path)
            .as_ref()
            .is_some_and(|found| compare_value(found, operator, value))
    {
        return Ok(None);
    }
    let Some(status @ ("exited" | "vanished" | "stopped")) =
        actual_field(actual, "status").and_then(Value::as_str)
    else {
        return Ok(None);
    };
    let Some((desired, _)) = store.desired_subject_with_writer(subject)? else {
        return Ok(None);
    };
    let Some(member) = desired
        .member
        .filter(|member| member.kind == MemberKind::Exec)
    else {
        return Ok(None);
    };
    let exit_code = actual_field(actual, "exit_code").and_then(Value::as_i64);
    let restarts = member.lifecycle == MemberLifecycle::Service
        && match member.restart {
            RestartType::Always => true,
            RestartType::OnFailure => exit_code != Some(0),
            RestartType::Never => false,
        };
    if restarts {
        return Ok(None);
    }
    if member.lifecycle == MemberLifecycle::Service {
        let lineage = store.launch_lineage(subject)?;
        let observed = store.latest_claim(subject, Some("runtime.observed"))?;
        if !observed.is_some_and(|claim| {
            // An observation may arrive between reading actual state and its evidence.
            // Never combine an older exit with proof belonging to a newer observation.
            ["status", "exit_code", "incarnation_id"]
                .iter()
                .all(|path| actual_field(actual, path) == actual_field(&claim.body, path))
                && claim.body["evidence"].as_array().is_some_and(|evidence| {
                    evidence
                        .iter()
                        .filter_map(Value::as_str)
                        .any(|token| lineage.iter().any(|desired| desired == token))
                })
        }) {
            return Ok(None);
        }
    }
    let exit = exit_code.map_or_else(|| "unknown".into(), |code| code.to_string());
    Ok(Some(format!(
        "field gate `{name}` cannot pass: exec `{subject}` is {status} with exit code {exit} and will not restart; expected `{path}` {operator} {value}"
    )))
}

/// Impossible exit-code gates in an active run, including gates behind another pending gate.
/// This is a read-only diagnostic and never records a gate verdict or changes work state.
pub(crate) fn stuck_field_gates(
    store: &Store,
    run: &MissionRunView,
    mission: &MissionSpec,
) -> Result<Vec<String>> {
    if !matches!(run.status.as_str(), "running" | "standing" | "blocked") {
        return Ok(Vec::new());
    }
    let mut stuck = Vec::new();
    let mut inspect =
        |owner: &str, gates: &[GateSpec], variables: &BTreeMap<String, String>| -> Result<()> {
            for gate in gates {
                if !matches!(gate, GateSpec::Field { path, .. } if path == "exit_code") {
                    continue;
                }
                let mut gate = gate.clone();
                expand_gate(&mut gate, variables, &run.workspace)?;
                let GateSpec::Field { subject, .. } = &gate else {
                    unreachable!()
                };
                if subject.starts_with("exec/")
                    && let Some(actual) = store.latest_actual_value(subject)?
                    && let Some(reason) = terminal_exec_field_gate_failure(store, &gate, &actual)?
                {
                    stuck.push(format!("{owner}: {reason}"));
                }
            }
            Ok(())
        };
    let flat = flatten_mission_steps(mission);
    for step in &flat {
        if let Some(view) = run.steps.iter().find(|view| view.step == step.spec.path)
            && matches!(view.status.as_str(), "claimed" | "working" | "verifying")
        {
            inspect(
                &view.subject,
                &step.spec.gates,
                &run_variables(run, step, view),
            )?;
        }
    }
    if run.phase == "normal"
        && flat.iter().filter(|step| !step.spec.finally).all(|step| {
            run.steps
                .iter()
                .any(|view| view.step == step.spec.path && view.status == "completed")
        })
    {
        inspect(
            &run.subject,
            &mission.gates,
            &crate::store::mission_run_variables(run, &run.revision),
        )?;
    }
    Ok(stuck)
}

fn gate_operation_subject(stage: &GateContext, name: &str, definition: &Value) -> Result<String> {
    let bytes = serde_json::to_vec(&(stage.subject.as_str(), name, definition))?;
    let hash = hex::encode(sha2::Sha256::digest(bytes));
    Ok(format!(
        "gate-operation/{}/{}",
        stage.subject.replace('/', "."),
        &hash[..24]
    ))
}

/// A retried attempt runs its mechanical and LLM gates again instead of reusing the first
/// attempt's result. The first attempt keeps its original key, so recorded results stay valid.
fn gate_result_subject(stage: &GateContext, name: &str, definition: &Value) -> Result<String> {
    if stage.attempt <= 1 {
        return gate_operation_subject(stage, name, definition);
    }
    let mut definition = definition.clone();
    definition["attempt"] = stage.attempt.into();
    gate_operation_subject(stage, name, &definition)
}

/// The operation exec gate check `check` runs as: the gate's result subject for the first
/// check, and a subject beneath it for each later one.
fn gate_check_subject(result_subject: &str, check: u64) -> String {
    if check <= 1 {
        result_subject.to_owned()
    } else {
        format!("{result_subject}/check/{check}")
    }
}

/// The step a gate decides for: the step itself, or the step that owns a loop's round or
/// candidate. A mission gate has none.
fn gate_owner_step(subject: &str) -> Option<String> {
    if subject.starts_with("step-run/") {
        return Some(subject.to_owned());
    }
    let path = subject.strip_prefix("loop-run/")?;
    let path = path.split("/round/").next().unwrap_or(path);
    Some(format!("step-run/{path}"))
}

/// An exec gate result's answer: `pass`, `not-yet`, `broken`, or `fail` for a result an older
/// st recorded, when any status but 0 failed the gate.
fn gate_check_answer(result: &crate::model::ClaimRecord) -> &str {
    let fields = &result.body["fields"];
    match (
        fields["verdict"].as_str(),
        fields["value"]["answer"].as_str(),
    ) {
        (Some("pass"), _) => "pass",
        (_, Some(answer @ ("not-yet" | "broken"))) => answer,
        _ => "fail",
    }
}

/// A gate result's recorded reason, or `default`.
fn gate_result_reason(result: &crate::model::ClaimRecord, default: &str) -> String {
    result
        .body
        .pointer("/fields/reason")
        .and_then(Value::as_str)
        .filter(|reason| !reason.trim().is_empty())
        .unwrap_or(default)
        .to_owned()
}

/// The last `lines` lines of `output`, at most `bytes` long, cut at a character boundary.
pub(crate) fn output_tail(output: &str, lines: usize, bytes: usize) -> String {
    let trimmed = output.trim_end();
    let start = trimmed
        .char_indices()
        .rev()
        .filter(|(_, c)| *c == '\n')
        .nth(lines.saturating_sub(1))
        .map_or(0, |(index, _)| index + 1);
    let mut tail = &trimmed[start..];
    if tail.len() > bytes {
        let mut cut = tail.len() - bytes;
        while !tail.is_char_boundary(cut) {
            cut += 1;
        }
        tail = &tail[cut..];
    }
    tail.to_owned()
}

/// `ms` in the largest whole unit a person reads at a glance: `90s`, `10m`, `2h`.
pub(crate) fn render_duration_ms(ms: u64) -> String {
    match ms {
        ms if ms >= 3_600_000 && ms % 3_600_000 == 0 => format!("{}h", ms / 3_600_000),
        ms if ms >= 60_000 && ms % 60_000 == 0 => format!("{}m", ms / 60_000),
        ms if ms % 1_000 == 0 => format!("{}s", ms / 1_000),
        ms => format!("{ms}ms"),
    }
}

/// Why an exec gate check that ended this way cannot answer, or `None` when its exit status is an
/// answer: 0 passes and 1 is not yet. `start_failure` says why it never ran to an exit.
pub(crate) fn exec_check_broken(
    exit_code: Option<i64>,
    calls: &[String],
    start_failure: Option<&str>,
) -> Option<String> {
    if let Some(reason) = start_failure {
        return Some(reason.to_owned());
    }
    if !calls.is_empty() {
        return Some(format!(
            "an st call in its check was refused or read part of a listing: {}",
            calls.join("; ")
        ));
    }
    match exit_code {
        Some(0 | 1) => None,
        Some(127) => Some(
            "its check exited 127, the shell's status for a command it did not find; an exec gate exits 0 to pass and 1 for not yet"
                .into(),
        ),
        Some(code) if code > 128 => Some(format!(
            "its check exited {code}, as a process killed by signal {} does; an exec gate exits 0 to pass and 1 for not yet",
            code - 128
        )),
        Some(code) => Some(format!(
            "its check exited {code}; an exec gate exits 0 to pass and 1 for not yet"
        )),
        None => Some("its check ended without an exit status: something killed it".into()),
    }
}

/// One finished exec gate check, ready to record.
struct GateCheck<'a> {
    name: &'a str,
    host: &'a str,
    result_subject: &'a str,
    operation: &'a str,
    check: u64,
    exit_code: Option<i64>,
    /// The refusals and partial listings the check's `st` commands reported.
    calls: Vec<String>,
    output: String,
    /// Why the check could not answer at all: it could not start or ran past its time limit.
    start_failure: Option<String>,
}

fn now_ms() -> u128 {
    smallclaims::store::now_ms()
}

