    #[tokio::test(start_paused = true)]
    async fn a_running_step_arms_one_wake_however_many_passes_ask() {
        let notify = Arc::new(Notify::new());
        let reconciler = Reconciler::new(
            Arc::new(Store::open_memory("node").unwrap()),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            notify.clone(),
        );
        let handle = tokio::runtime::Handle::current();
        // Twenty passes ask for the same lease expiry; the later ones ask for a later one.
        for pass in 0..20 {
            reconciler.arm_step_deadline(&handle, "step-run/example/work", 60_000 + pass);
        }
        assert_eq!(reconciler.step_deadlines.lock().unwrap().len(), 1);
        tokio::time::timeout(Duration::from_secs(61), notify.notified())
            .await
            .expect("the step's wake fires at its deadline");
        // One wake, not twenty: nothing more is pending.
        assert!(
            tokio::time::timeout(Duration::from_secs(120), notify.notified())
                .await
                .is_err()
        );
        assert!(reconciler.step_deadlines.lock().unwrap().is_empty());
        // An earlier deadline replaces a later one.
        reconciler.arm_step_deadline(&handle, "step-run/example/work", 60_000);
        reconciler.arm_step_deadline(&handle, "step-run/example/work", 5_000);
        tokio::time::timeout(Duration::from_secs(6), notify.notified())
            .await
            .expect("an earlier deadline wakes at its own time");
    }

    #[tokio::test(start_paused = true)]
    async fn a_running_gate_runner_is_watched_without_a_pass_until_it_exits() {
        let notify = Arc::new(Notify::new());
        let runtime = Arc::new(FakeRuntime::default());
        let running = |status: &str| RuntimeObservation {
            runtime_id: "gate-runner".into(),
            terminal: false,
            status: status.into(),
            exit_code: None,
            incarnation_id: None,
        };
        runtime
            .execs
            .lock()
            .unwrap()
            .insert("gate-runner".into(), running("running"));
        let reconciler = Reconciler::new(
            Arc::new(Store::open_memory("node").unwrap()),
            runtime.clone(),
            "node".into(),
            notify.clone(),
        );
        reconciler.arm_gate_poll("gate-runner");
        // Polls at 10, 20 and 30 seconds find the runner still running and wake no pass.
        assert!(
            tokio::time::timeout(Duration::from_secs(35), notify.notified())
                .await
                .is_err()
        );
        runtime
            .execs
            .lock()
            .unwrap()
            .insert("gate-runner".into(), running("exited"));
        tokio::time::timeout(Duration::from_secs(11), notify.notified())
            .await
            .expect("the poll after the runner exited should wake reconciliation");
        // A runner that keeps running still gets a pass every minute, for its time limit.
        runtime
            .execs
            .lock()
            .unwrap()
            .insert("gate-runner".into(), running("running"));
        reconciler.arm_gate_poll("gate-runner");
        assert!(
            tokio::time::timeout(Duration::from_secs(55), notify.notified())
                .await
                .is_err()
        );
        tokio::time::timeout(Duration::from_secs(10), notify.notified())
            .await
            .expect("a long gate still gets a pass every minute");
    }

    #[test]
    fn exec_exit_code_field_gates_fail_only_after_the_selected_launch_is_terminal() {
        for (restart, status, exit_code, expected, fails, passes) in [
            ("never", "running", None, 0, false, false),
            ("never", "starting", Some(2), 0, false, false),
            ("never", "exited", Some(0), 0, false, true),
            ("never", "exited", Some(1), 0, true, false),
            ("never", "exited", Some(2), 0, true, false),
            ("never", "exited", None, 0, true, false),
            ("never", "vanished", None, 0, true, false),
            ("never", "stopped", Some(2), 0, true, false),
            ("always", "exited", Some(2), 0, false, false),
            ("on-failure", "exited", Some(2), 0, false, false),
            ("on-failure", "exited", None, 0, false, false),
            ("on-failure", "exited", Some(0), 1, true, false),
        ] {
            let store = Arc::new(Store::open_memory("node").unwrap());
            apply_source(
                &store,
                &format!(
                    "version 2\nexec \"orchid/probe\" {{ workspace \"/tmp\"; command \"true\"; restart \"{restart}\" }}"
                ),
                "exec",
            );
            let reconciler = Reconciler::new(
                store.clone(),
                Arc::new(FakeRuntime::default()),
                "node".into(),
                Arc::new(Notify::new()),
            );
            reconciler.reconcile_once().unwrap();
            let desired = store
                .desired_subject_with_writer("exec/orchid/probe")
                .unwrap()
                .unwrap()
                .0;
            reconciler
                .record_member(
                    &desired,
                    &RuntimeObservation {
                        runtime_id: desired.member.as_ref().unwrap().runtime_id.clone(),
                        terminal: false,
                        status: status.into(),
                        exit_code,
                        incarnation_id: None,
                    },
                    false,
                )
                .unwrap();
            let gate = GateSpec::Field {
                name: "prepared".into(),
                path: "exit_code".into(),
                subject: "exec/orchid/probe".into(),
                operator: "is".into(),
                value: serde_json::json!(expected),
            };
            let stage = GateContext {
                subject: "step-run/orchid/prepare".into(),
                name: "prepare".into(),
                started_at_unix_ms: 0,
                attempt: 1,
                run: "mission-run/orchid".into(),
                generation: "run-generation/orchid".into(),
                eval: false,
            };
            let outcome = reconciler.evaluate_gate(&stage, &gate).unwrap();
            assert_eq!(
                matches!(outcome, GateOutcome::Fail(_)),
                fails,
                "{restart} {status} {exit_code:?}: {outcome:?}"
            );
            assert_eq!(matches!(outcome, GateOutcome::Pass), passes, "{outcome:?}");
            // A replica has no local launch receipt. Replaying the replicated observation
            // and its declaration evidence must still give the same predicate decision.
            let replica = Store::open_memory("replica").unwrap();
            let batch = store.export_replication(0).unwrap();
            replica.import_replication("node", &batch).unwrap();
            assert!(
                replica
                    .observations_for("exec/orchid/probe", "runtime.action.succeeded")
                    .unwrap()
                    .is_empty()
            );
            let reason = |store: &Store| {
                terminal_exec_field_gate_failure(
                    store,
                    &gate,
                    &store
                        .latest_actual_value("exec/orchid/probe")
                        .unwrap()
                        .unwrap(),
                )
                .unwrap()
            };
            assert_eq!(reason(&store), reason(&replica));
            replica.import_replication("node", &batch).unwrap();
            assert_eq!(reason(&store), reason(&replica));
            if let GateOutcome::Fail(reason) = outcome {
                assert!(reason.contains("exec/orchid/probe"), "{reason}");
                assert!(
                    reason.contains(&format!(
                        "exit code {}",
                        exit_code.map_or_else(|| "unknown".into(), |code| code.to_string())
                    )),
                    "{reason}"
                );
            }
            let mut status_gate = gate.clone();
            if let GateSpec::Field { path, value, .. } = &mut status_gate {
                *path = "status".into();
                *value = serde_json::json!("waiting-for-a-different-state");
            }
            assert!(matches!(
                reconciler.evaluate_gate(&stage, &status_gate).unwrap(),
                GateOutcome::Pending
            ));
            let previous_actual = store
                .latest_actual_value("exec/orchid/probe")
                .unwrap()
                .unwrap();
            // A revised declaration must be allowed to launch again, even with restart never.
            apply_source(
                &store,
                &format!(
                    "version 2\nexec \"orchid/probe\" {{ workspace \"/tmp\"; command \"exit 0\"; restart \"{restart}\" }}"
                ),
                "revised-exec",
            );
            if !passes {
                assert!(matches!(
                    reconciler.evaluate_gate(&stage, &gate).unwrap(),
                    GateOutcome::Pending
                ));
            }
            reconciler.reconcile_once().unwrap();
            let revised = store
                .desired_subject_with_writer("exec/orchid/probe")
                .unwrap()
                .unwrap()
                .0;
            reconciler
                .record_member(
                    &revised,
                    &RuntimeObservation {
                        runtime_id: revised.member.as_ref().unwrap().runtime_id.clone(),
                        terminal: false,
                        status: "running".into(),
                        exit_code: None,
                        incarnation_id: None,
                    },
                    false,
                )
                .unwrap();
            assert!(
                terminal_exec_field_gate_failure(&store, &gate, &previous_actual)
                    .unwrap()
                    .is_none(),
                "an older exit must not use a newer launch's evidence"
            );
        }
    }

    #[test]
    fn quantified_field_predicates_wait_for_the_last_item_and_evaluate_negation() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let fields = vec![
            crate::model::QuantifiedFieldSpec {
                path: "status".into(),
                operator: "is".into(),
                value: Value::String("completed".into()),
            },
            crate::model::QuantifiedFieldSpec {
                path: "conclusion".into(),
                operator: "is".into(),
                value: Value::String("success".into()),
            },
        ];
        let every = GateSpec::Every {
            name: "all checks passed".into(),
            path: "checks".into(),
            subject: "resource/pull".into(),
            fields: fields.clone(),
        };
        let not_every = GateSpec::NotEvery {
            name: "a check did not pass".into(),
            path: "checks".into(),
            subject: "resource/pull".into(),
            fields,
        };
        let stage = GateContext {
            subject: "step-run/test/checks".into(),
            name: "checks".into(),
            started_at_unix_ms: now_ms(),
            attempt: 1,
            run: "mission-run/test".into(),
            generation: "run-generation/test".into(),
            eval: false,
        };

        assert!(matches!(
            reconciler.evaluate_gate(&stage, &every).unwrap(),
            GateOutcome::Pending
        ));
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &not_every).unwrap(),
            GateOutcome::Pending
        ));

        let observe = |checks: Value, key: &str| {
            store
                .append_claim(&ClaimInput {
                    subject: "resource/pull".into(),
                    kind: "resource.observed".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("kind".into(), Value::String("vcs.pull-request".into())),
                        ("facts".into(), serde_json::json!({"checks": checks})),
                    ]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: Some(key.into()),
                })
                .unwrap();
        };

        observe(
            serde_json::json!([
                {"status": "completed", "conclusion": "success"},
                {"status": "in_progress", "conclusion": null}
            ]),
            "one-check-pending",
        );
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &every).unwrap(),
            GateOutcome::Pending
        ));
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &not_every).unwrap(),
            GateOutcome::Pass
        ));

        observe(
            serde_json::json!([
                {"status": "completed", "conclusion": "success"},
                {"status": "completed", "conclusion": "success"}
            ]),
            "all-pass",
        );
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &every).unwrap(),
            GateOutcome::Pass
        ));
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &not_every).unwrap(),
            GateOutcome::Pending
        ));

        observe(
            serde_json::json!([
                {"status": "completed", "conclusion": "success"},
                {"status": "completed", "conclusion": "failure"}
            ]),
            "one-failed",
        );
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &every).unwrap(),
            GateOutcome::Pending
        ));
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &not_every).unwrap(),
            GateOutcome::Pass
        ));

        observe(Value::Array(Vec::new()), "empty-list");
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &every).unwrap(),
            GateOutcome::Pass
        ));
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &not_every).unwrap(),
            GateOutcome::Pending
        ));

        store
            .append_claim(&ClaimInput {
                subject: "resource/wrong".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("kind".into(), Value::String("custom.st3.test".into())),
                    ("facts".into(), serde_json::json!({"checks": "not-a-list"})),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("wrong-shape".into()),
            })
            .unwrap();
        let mut wrong_every = every.clone();
        let GateSpec::Every { subject, .. } = &mut wrong_every else {
            unreachable!()
        };
        *subject = "resource/wrong".into();
        let mut wrong_not_every = not_every.clone();
        let GateSpec::NotEvery { subject, .. } = &mut wrong_not_every else {
            unreachable!()
        };
        *subject = "resource/wrong".into();
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &wrong_every).unwrap(),
            GateOutcome::Pending
        ));
        assert!(matches!(
            reconciler.evaluate_gate(&stage, &wrong_not_every).unwrap(),
            GateOutcome::Pending
        ));
    }

    fn apply_source(store: &Store, source: &str, idempotency_key: &str) {
        let intent = parse_intent(source, "node").unwrap();
        let mission = store
            .mission(
                &intent,
                crate::model::IntentInput {
                    kdl: source.into(),
                    source_name: None,
                },
            )
            .unwrap();
        store
            .apply(&intent, &mission.subject_tokens, idempotency_key)
            .unwrap();
    }

    /// The in-memory store's connections share one cache. There a call that meets a pass of the
    /// running reconciler loop, which runs on the blocking pool, fails at once with `database
    /// table is locked`, where a daemon's file store would wait. A test beside the running loop
    /// retries such a call.
    fn beside_the_loop<T, E: std::fmt::Display>(mut call: impl FnMut() -> Result<T, E>) -> T {
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        loop {
            match call() {
                Ok(value) => return value,
                Err(error)
                    if error.to_string().contains("database table is locked")
                        && std::time::Instant::now() < deadline =>
                {
                    std::thread::sleep(Duration::from_millis(1));
                }
                Err(error) => panic!("{error}"),
            }
        }
    }

    fn apply_source_beside_the_loop(store: &Store, source: &str, idempotency_key: &str) {
        let intent = parse_intent(source, "node").unwrap();
        let mission = beside_the_loop(|| {
            store.mission(
                &intent,
                crate::model::IntentInput {
                    kdl: source.into(),
                    source_name: None,
                },
            )
        });
        beside_the_loop(|| store.apply(&intent, &mission.subject_tokens, idempotency_key));
    }

