    #[test]
    fn restart_types_follow_success_and_failure() {
        for (name, restart, exit_code, expected_starts) in [
            ("always-success", "always", 0, 2),
            ("failure-success", "on-failure", 0, 1),
            ("failure-error", "on-failure", 1, 2),
            ("never-error", "never", 1, 1),
        ] {
            let store = Arc::new(Store::open_memory("node").unwrap());
            let source = format!(
                r#"
                    version 2

                      agent "worker" {{
                        command "true"
                        restart "{restart}"
                      }}

                "#
            );
            apply_source(&store, &source, name);
            let runtime = Arc::new(FakeRuntime::default());
            let reconciler = Reconciler::new(
                store,
                runtime.clone(),
                "node".into(),
                Arc::new(Notify::new()),
            );

            reconciler.reconcile_once().unwrap();
            runtime.ptys.lock().unwrap().push(RuntimeObservation {
                runtime_id: "node.worker".into(),
                terminal: true,
                status: "exited".into(),
                exit_code: Some(exit_code),
                incarnation_id: Some(format!("{name}-one")),
            });
            reconciler.reconcile_once().unwrap();

            assert_eq!(
                runtime.starts.lock().unwrap().len(),
                expected_starts,
                "{name}"
            );
        }
    }

    #[test]
    fn seat_rename_does_not_relaunch() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, r#"version 2
agent "test/worker" {
    workspace "/tmp"
    command "true"
    name "Initial seat"
    restart "never"
}
"#, "seat");
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(store.clone(), runtime.clone(), "node".into(),
            Arc::new(Notify::new()));
        reconciler.reconcile_once().unwrap();
        let original = store.desired_subject_with_writer("agent/test/worker").unwrap().unwrap();
        let runtime_id = original.0.member.as_ref().unwrap().runtime_id.clone();
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: runtime_id.clone(), terminal: true, status: "running".into(),
            exit_code: None, incarnation_id: Some("unchanged-incarnation".into()),
        });
        store.rename_agent("agent/test/worker", Some("Renamed seat"), "rename").unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().as_slice(), std::slice::from_ref(&runtime_id));
        assert!(runtime.stops.lock().unwrap().is_empty());
        store.rename_agent("agent/test/worker", None, "clear").unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().as_slice(), std::slice::from_ref(&runtime_id));
        assert!(runtime.stops.lock().unwrap().is_empty());
        runtime.ptys.lock().unwrap()[0].status = "exited".into();
        runtime.ptys.lock().unwrap()[0].exit_code = Some(0);
        reconciler.reconcile_once().unwrap();
        assert_eq!(*runtime.starts.lock().unwrap(), vec![runtime_id]);
        assert!(runtime.stops.lock().unwrap().is_empty());
    }

    #[test]
    fn a_relabel_of_an_older_launch_runs_again_after_another_revision_launched() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(&store, r#"version 2
agent "test/worker" { workspace "/tmp"; command "true"; name "X"; restart "never" }
"#, "x");
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(store.clone(), runtime.clone(), "node".into(),
            Arc::new(Notify::new()));
        reconciler.reconcile_once().unwrap();
        let runtime_id = runtime.starts.lock().unwrap()[0].clone();
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: runtime_id.clone(), terminal: true, status: "exited".into(),
            exit_code: Some(0), incarnation_id: Some("x".into()),
        });
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 1);
        // Revision Y launched later; replication then selects a relabel of X again. The seat runs
        // X's configuration once more instead of matching X's older launch.
        store.append_claim(&ClaimInput {
            subject: "agent/test/worker".into(),
            kind: "runtime.action.succeeded".into(),
            actor: None,
            fields: BTreeMap::from([
                ("desired_token".into(), Value::String("revision-y".into())),
                ("runtime_id".into(), Value::String(runtime_id.clone())),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some("launch-y".into()),
        }).unwrap();
        store.rename_agent("agent/test/worker", Some("X again"), "relabel-x").unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 2);
    }

    #[test]
    fn restart_never_starts_a_new_desired_revision() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"
                version 2

                  agent "worker" {
                    workspace "/tmp"
                    command "true"
                    env { REVISION "one" }
                    restart "never"
                  }

            "#,
            "member-one",
        );
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );

        reconciler.reconcile_once().unwrap();
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: "node.worker".into(),
            terminal: true,
            status: "exited".into(),
            exit_code: Some(0),
            incarnation_id: Some("worker-one".into()),
        });
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 1);

        apply_source(
            &store,
            r#"
                version 2

                  agent "worker" {
                    workspace "/tmp"
                    command "true"
                    env { REVISION "two" }
                    restart "never"
                  }

            "#,
            "member-two",
        );
        reconciler.reconcile_once().unwrap();
        reconciler.reconcile_once().unwrap();

        assert_eq!(runtime.starts.lock().unwrap().len(), 2);
        assert_eq!(
            runtime.started_members.lock().unwrap()[1].environment["REVISION"],
            "two"
        );

        apply_source(
            &store,
            r#"version 2
agent "worker" {
    workspace "/tmp"
    command "true"
    env { REVISION "one" }
    restart "never"
}"#,
            "member-one-again",
        );
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 3);
        assert_eq!(runtime.started_members.lock().unwrap()[2].environment["REVISION"], "one");
    }

    #[test]
    fn a_ding_is_an_explicit_child_runtime_not_a_reconciler_side_effect() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
            version 2

              agent "worker" {
                command "sleep 60"
                exec "ding" { command "true" }
              }
              message "one" {
                from "requester"
                to "node.worker"
                content "Do the work."
              }

        "#;
        apply_source(&store, source, "one-message");
        let runtime = Arc::new(FakeRuntime::default());
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: "node.worker".into(),
            terminal: true,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some("worker-one".into()),
        });
        let reconciler = Reconciler::new(
            store,
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );

        reconciler.reconcile_once().unwrap();
        reconciler.reconcile_once().unwrap();

        assert!(
            runtime
                .started_members
                .lock()
                .unwrap()
                .iter()
                .any(|member| member.runtime_id == "exec.node.worker.ding")
        );
    }

    #[test]
    fn legacy_attention_until_conditions_no_longer_mutate_or_surface() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
mission "publish" state="ready" {
  goal "Publish a revision."
  step "approve" { agentless }
}
"#,
            "until-mission",
        );
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "publish".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/alex".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "until-run".into(),
            })
            .unwrap();
        let request = |subject: &str, until: Option<&str>| {
            store
                .request_attention_closing(
                    subject,
                    &AttentionRequest {
                        reviewer: "person/alex".into(),
                        title: "Publish this revision".into(),
                        reason: "Publish the prepared revision as a person.".into(),
                        severity: "warning".into(),
                        targets: vec![run.subject.clone()],
                        actor: "agent/node.requester".into(),
                        idempotency_key: format!("{subject}:requested"),
                    },
                    &crate::model::AttentionClosing {
                        until: until.map(str::to_owned),
                        ..Default::default()
                    },
                )
                .unwrap()
        };
        let until = request("attention/until-completed", Some("completed"));
        let plain = request("attention/plain", None);
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let status = |subject: &str| store.attention_request(subject).unwrap().unwrap().status;

        reconciler.reconcile_once().unwrap();
        assert_eq!(status(&until.subject), "pending");

        store
            .set_mission_run_state(&run.id, "completed", "terminal", None)
            .unwrap();
        reconciler.reconcile_once().unwrap();

        assert_eq!(
            status(&until.subject),
            "pending",
            "legacy claims are retained for audit"
        );
        assert_eq!(status(&plain.subject), "pending");
        assert!(
            store
                .attention_items(Some("person/alex"))
                .unwrap()
                .is_empty()
        );
    }

    #[test]
    fn an_agents_attention_request_resolves_once_the_step_that_raised_it_ends() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
mission "asks" state="ready" {
  goal "Ask a person for a decision while working."
  step "work" { assigned-to "agent/asker" }
}
"#,
            "asks-mission",
        );
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "asks".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/alex".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "asks-run".into(),
            })
            .unwrap();
        let step = run.steps[0].subject.clone();
        store.set_step_state(&step, "ready", None).unwrap();
        store
            .work_action(
                &step,
                "claim",
                &crate::model::WorkRequest {
                    actor: Some("agent/node.asker".into()),
                    incarnation: Some("asker-one".into()),
                    summary: None,
                    reason: None,
                    evidence: Vec::new(),
                    idempotency_key: "asks-claim".into(),
                },
            )
            .unwrap();
        let asked = store
            .request_attention_closing(
                "attention/asked",
                &AttentionRequest {
                    reviewer: "person/alex".into(),
                    title: "Decide the rollout".into(),
                    reason: "A person needs to decide before the rollout.".into(),
                    severity: "warning".into(),
                    targets: Vec::new(),
                    actor: "agent/node.asker".into(),
                    idempotency_key: "asked".into(),
                },
                &crate::model::AttentionClosing::default(),
            )
            .unwrap();
        assert_eq!(asked.step.as_deref(), Some(step.as_str()));
        let _reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        assert!(
            store
                .attention_items(None)
                .unwrap()
                .iter()
                .all(|item| item.subject != asked.subject)
        );
        assert_eq!(
            store
                .attention_request(&asked.subject)
                .unwrap()
                .unwrap()
                .status,
            "pending"
        );

        store.set_step_state(&step, "failed", None).unwrap();
        assert!(
            store
                .attention_items(None)
                .unwrap()
                .iter()
                .all(|item| item.subject != asked.subject)
        );
        let resolved = store.attention_request(&asked.subject).unwrap().unwrap();
        assert_eq!(resolved.status, "pending");
        assert!(
            resolved.resolution_reason.is_none(),
            "legacy requests remain immutable audit data"
        );
    }

    #[test]
    fn codex_start_failures_stop_after_three_attempts_and_request_one_attention() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"
version 2
agent "worker" {
  workspace "."
  restart "always"
  harness "codex" {}
}
"#,
            "codex-start-failures",
        );
        let runtime = Arc::new(FakeRuntime::default());
        runtime
            .failed_starts
            .lock()
            .unwrap()
            .insert("node.worker".into());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..6 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(runtime.starts.lock().unwrap().len(), 3);
        let token = store
            .selected_desired_token("agent/node.worker")
            .unwrap()
            .unwrap();
        let attention = store.fault_items(Some("person/alex")).unwrap();
        assert_eq!(attention.len(), 1);
        assert_eq!(attention[0].subject, "agent/node.worker");
        assert!(
            attention[0]
                .detail
                .contains("the fake runtime rejected the start")
        );
        let decisions = store
            .claims_for("agent/node.worker", Some("runtime.reconcile-decision"))
            .unwrap();
        assert_eq!(
            decisions
                .iter()
                .filter(|claim| {
                    claim.body.pointer("/fields/key").and_then(Value::as_str)
                        == Some(format!("codex-crash-loop:{token}").as_str())
                })
                .count(),
            1
        );
    }

    #[test]
    fn codex_short_lived_exits_stop_relaunching() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"
version 2
agent "worker" {
  workspace "."
  restart "always"
  harness "codex" {}
}
"#,
            "codex-short-lived-exits",
        );
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: "node.worker".into(),
            terminal: true,
            status: "exited".into(),
            exit_code: Some(17),
            incarnation_id: Some("bad-seat".into()),
        });
        for _ in 0..5 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(runtime.starts.lock().unwrap().len(), 3);
        let decision = store
            .latest_claim("agent/node.worker", Some("runtime.reconcile-decision"))
            .unwrap()
            .unwrap();
        assert_eq!(
            decision
                .body
                .pointer("/fields/decision")
                .and_then(Value::as_str),
            Some("raise")
        );
        assert!(
            decision
                .body
                .pointer("/fields/reason")
                .and_then(Value::as_str)
                .unwrap()
                .contains("exit code 17")
        );
    }

    #[test]
    fn fail_restart_intensity_parks_after_the_launch_budget() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
            version 2

              agent "worker" {
                command "true"
                restart "always"
                restart {
                  attempts 1
                  interval "60s"
                  mode "fail"
                }
              }

        "#;
        let intent = parse_intent(source, "node").unwrap();
        let mission = store
            .mission(
                &intent,
                crate::model::IntentInput {
                    kdl: source.into(),
                    source_name: None,
                },
            )
            .unwrap();
        store
            .apply(&intent, &mission.subject_tokens, "one")
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 1);
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: "node.worker".into(),
            terminal: true,
            status: "exited".into(),
            exit_code: Some(1),
            incarnation_id: Some("first".into()),
        });
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 1);
        let actual = store
            .latest_actual_value("agent/node.worker")
            .unwrap()
            .unwrap();
        assert_eq!(
            actual_field(&actual, "reachability"),
            Some(&Value::String("unreachable".into()))
        );
        let desired_token = store
            .selected_desired_token("agent/node.worker")
            .unwrap()
            .unwrap();
        // A label-only revision keeps the exhausted budget; only a reset or launch change restarts.
        store.rename_agent("agent/node.worker", Some("Renamed"), "rename-exhausted").unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 1);
        store
            .append_claim(&ClaimInput {
                subject: "agent/node.worker".into(),
                kind: "runtime.restart-window-reset".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("desired_token".into(), Value::String(desired_token.clone())),
                    ("incarnation_id".into(), Value::String("other".into())),
                    ("reason".into(), Value::String("test the fence".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("wrong-incarnation-reset".into()),
            })
            .unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 1);
        store
            .append_claim(&ClaimInput {
                subject: "agent/node.worker".into(),
                kind: "runtime.restart-window-reset".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("desired_token".into(), Value::String(desired_token)),
                    ("incarnation_id".into(), Value::String("first".into())),
                    (
                        "reason".into(),
                        Value::String("clear this incarnation window".into()),
                    ),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("matching-incarnation-reset".into()),
            })
            .unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 2);
    }

    #[test]
    fn fail_restart_window_excludes_old_generations_even_without_a_matching_reset() {
        let now = 1_000_000_u128;
        let interval = 300_000_u64;
        assert!(!launch_in_restart_window(
            1,
            now - 700_000,
            0,
            now,
            interval,
            "fail"
        ));
        assert!(!launch_in_restart_window(
            2,
            now - 400_000,
            0,
            now,
            interval,
            "fail"
        ));
        assert!(launch_in_restart_window(
            3,
            now - 30_000,
            0,
            now,
            interval,
            "fail"
        ));
        assert!(!launch_in_restart_window(
            3,
            now - 30_000,
            3,
            now,
            interval,
            "fail"
        ));
    }

    #[test]
    fn three_exits_before_readiness_park_a_native_seat() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            "version 2\nagent \"worker\" { workspace \"/tmp\"; command \"true\"; restart \"always\" }\n",
            "unready-exits",
        );
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        for number in 1..=3 {
            *runtime.ptys.lock().unwrap() = vec![RuntimeObservation {
                runtime_id: "node.worker".into(),
                terminal: true,
                status: "exited".into(),
                exit_code: Some(1),
                incarnation_id: Some(format!("crash-{number}")),
            }];
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(runtime.starts.lock().unwrap().len(), 3);
        assert!(
            store
                .fault_items(None)
                .unwrap()
                .iter()
                .any(|attention| { attention.targets.contains(&"agent/node.worker".to_owned()) })
        );
        store.rename_agent("agent/node.worker", Some("Renamed"), "rename-parked").unwrap();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.starts.lock().unwrap().len(), 3, "a rename must not unpark the seat");
    }

