    #[tokio::test]
    async fn unpinned_schedule_keeps_one_attention_until_an_occurrence_succeeds() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"version 2
mission "scheduled-cycle" state="draft" { goal "Not ready." }"#,
            "draft-cycle",
        );
        let root = tempfile::tempdir().unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let attention = schedule_head_attention_subject("schedule/unready");
        let anchor = (Utc::now() + chrono::Duration::milliseconds(100))
            .to_rfc3339_opts(SecondsFormat::Millis, true);
        apply_source(
            &store,
            &format!(r#"version 2
schedule "unready" {{
  every "100ms"
  anchor "{anchor}"
  catch-up "latest"
  work {{ mission "scheduled-cycle"; workspace "{}" }}
}}"#, root.path().display()),
            "unready-schedule",
        );
        for occurrence in 0..4 {
            if occurrence == 3 {
                scheduled_mission_revision(&store);
            }
            reconciler.reconcile_once().unwrap();
            tokio::time::timeout(Duration::from_secs(5), async {
                while store.claims_for("schedule/unready", Some("schedule.occurrence-reached")).unwrap().len() <= occurrence {
                    tokio::time::sleep(Duration::from_millis(5)).await;
                }
            }).await.unwrap();
            if occurrence == 3 {
                reconciler.reconcile_once().unwrap();
            }
            assert_eq!(
                store
                    .claims_for("schedule/unready", Some("operational.failure"))
                    .unwrap()
                    .len(),
                1
            );
            if occurrence < 3 {
                assert_eq!(
                    store
                        .operational_failure(&attention)
                        .unwrap()
                        .unwrap()
                        .status,
                    "pending"
                );
            }
        }
        assert_eq!(
            store
                .claims_for("schedule/unready", Some("schedule.work-failed"))
                .unwrap()
                .len(),
            3
        );
        assert_eq!(
            store
                .claims_for("schedule/unready", Some("schedule.work-started"))
                .unwrap()
                .len(),
            1
        );
        let closed = store
            .claims_for("schedule/unready", Some("operational.recovered"))
            .unwrap();
        assert_eq!(closed.len(), 1);
        assert_eq!(closed[0].kind, "operational.recovered");
        assert!(
            store
                .attention_items(None)
                .unwrap()
                .iter()
                .all(|item| item.subject != attention)
        );
    }

    #[tokio::test]
    async fn one_time_schedule_starts_exactly_one_mission() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let revision = scheduled_mission_revision(&store);
        let root = tempfile::tempdir().unwrap();
        let workspace_root = root.path().join("cycles");
        let at = (Utc::now() + chrono::Duration::milliseconds(50))
            .to_rfc3339_opts(SecondsFormat::Millis, true);
        let source = format!(
            r#"
                version 2

                  schedule "reminder" {{
                    at "{at}"
                    work {{
                      mission "scheduled-cycle@{revision}"
                      workspace "{workspace_root}"
                    }}
                  }}

            "#,
            workspace_root = workspace_root.display()
        );
        apply_source(&store, &source, "schedule-one");
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );

        reconciler.reconcile_once().unwrap();
        tokio::time::sleep(Duration::from_millis(100)).await;
        reconciler.reconcile_once().unwrap();
        tokio::time::sleep(Duration::from_millis(20)).await;

        let schedule_claims = store.claims_for("schedule/reminder", None).unwrap();
        assert_eq!(
            schedule_claims
                .iter()
                .filter(|claim| claim.kind == "schedule.occurrence-reached")
                .count(),
            1,
            "{schedule_claims:#?}"
        );
        assert_eq!(
            schedule_claims
                .iter()
                .filter(|claim| claim.kind == "schedule.work-started")
                .count(),
            1
        );
        let started = schedule_claims
            .iter()
            .find(|claim| claim.kind == "schedule.work-started")
            .unwrap();
        let run = started
            .body
            .pointer("/fields/mission_run")
            .and_then(Value::as_str)
            .unwrap();
        let workspace = store.mission_run(run).unwrap().unwrap().workspace;
        assert!(Path::new(&workspace).is_dir());
        assert!(Path::new(&workspace).starts_with(&workspace_root));
        reconciler.reconcile_once().unwrap();
        assert_eq!(
            store
                .claims_for("schedule/reminder", Some("schedule.work-started"))
                .unwrap()
                .len(),
            1
        );
    }

    #[tokio::test]
    async fn scheduled_work_waits_for_an_available_workspace() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let revision = scheduled_mission_revision(&store);
        let root = tempfile::tempdir().unwrap();
        let workspace_root = root.path().join("cycles");
        fs::write(&workspace_root, "not a directory").unwrap();
        let at = (Utc::now() + chrono::Duration::milliseconds(50))
            .to_rfc3339_opts(SecondsFormat::Millis, true);
        apply_source(
            &store,
            &format!(
                "version 2\nschedule \"cycle\" {{ at \"{at}\"; work {{ mission \"scheduled-cycle@{revision}\"; workspace {:?} }} }}",
                workspace_root.display().to_string()
            ),
            "schedule-unavailable-workspace",
        );
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        tokio::time::sleep(Duration::from_millis(100)).await;
        reconciler.reconcile_once().unwrap();
        assert!(
            store
                .claims_for("schedule/cycle", Some("schedule.work-started"))
                .unwrap()
                .is_empty()
        );
        let diagnostics = store
            .claims_for("daemon/node", Some("daemon.diagnostic"))
            .unwrap();
        assert!(diagnostics.iter().any(|claim| {
            claim.body.pointer("/fields/code").and_then(Value::as_str)
                == Some("workspace-unavailable")
        }));

        fs::remove_file(&workspace_root).unwrap();
        reconciler.reconcile_once().unwrap();
        let started = store
            .claims_for("schedule/cycle", Some("schedule.work-started"))
            .unwrap();
        assert_eq!(started.len(), 1);
        let run = started[0]
            .body
            .pointer("/fields/mission_run")
            .and_then(Value::as_str)
            .unwrap();
        assert!(Path::new(&store.mission_run(run).unwrap().unwrap().workspace).is_dir());
    }

    #[tokio::test]
    async fn a_recurring_schedule_starts_distinct_ordered_occurrences() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let revision = scheduled_mission_revision(&store);
        let anchor = (Utc::now() + chrono::Duration::milliseconds(40))
            .to_rfc3339_opts(SecondsFormat::Millis, true);
        let source = format!(
            r#"version 2
 schedule "cycle" {{
   every "60ms"
   anchor "{anchor}"
   catch-up "latest"
   work {{ mission "scheduled-cycle@{revision}"; workspace "/tmp/st3-schedule-test" }}
 }}"#
        );
        apply_source(&store, &source, "recurring-schedule");
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );

        reconciler.reconcile_once().unwrap();
        tokio::time::sleep(Duration::from_millis(55)).await;
        reconciler.reconcile_once().unwrap();
        tokio::time::sleep(Duration::from_millis(65)).await;
        for _ in 0..10 {
            reconciler.reconcile_once().unwrap();
            tokio::task::yield_now().await;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
        reconciler.reconcile_once().unwrap();

        let reached = store
            .claims_for("schedule/cycle", Some("schedule.occurrence-reached"))
            .unwrap();
        let occurrences = reached
            .iter()
            .map(|claim| {
                claim
                    .body
                    .pointer("/fields/occurrence")
                    .and_then(Value::as_u64)
                    .unwrap()
            })
            .collect::<Vec<_>>();
        assert!(
            occurrences.len() >= 2,
            "the recurring schedule did not start twice: {occurrences:?}"
        );
        assert!(
            occurrences.windows(2).all(|pair| pair[0] < pair[1]),
            "recurring occurrences were not distinct and ordered: {occurrences:?}"
        );
        assert_eq!(
            store
                .claims_for("schedule/cycle", Some("schedule.work-started"))
                .unwrap()
                .len(),
            occurrences.len()
        );
    }

    #[test]
    fn a_stopped_schedule_cancels_its_queued_work() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let revision = scheduled_mission_revision(&store);
        let declared = format!(
            r#"version 2
 schedule "held" {{
   every "1h"
   anchor "2030-01-01T00:00:00Z"
   work {{ mission "scheduled-cycle@{revision}"; workspace "/tmp/st3-schedule-test" }}
 }}"#
        );
        apply_source(&store, &declared, "held-schedule");
        let schedule_revision = store
            .selected_desired_revision("schedule/held")
            .unwrap()
            .unwrap();
        let request = store
            .append_claim(&ClaimInput {
                subject: "schedule/held".into(),
                kind: "schedule.work-requested".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("revision".into(), Value::String(schedule_revision)),
                    ("occurrence".into(), Value::from(0)),
                    (
                        "mission".into(),
                        Value::String("mission/scheduled-cycle".into()),
                    ),
                    ("mission_revision".into(), Value::String(revision)),
                    (
                        "workspace".into(),
                        Value::String("/tmp/st3-schedule-test".into()),
                    ),
                    ("inputs".into(), serde_json::json!({})),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: None,
            })
            .unwrap();
        apply_source(
            &store,
            "version 2\nschedule \"held\" { stop }\n",
            "stop-held-schedule",
        );
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );

        reconciler.reconcile_once().unwrap();

        let failed = store
            .claims_for("schedule/held", Some("schedule.work-failed"))
            .unwrap();
        assert_eq!(failed.len(), 1);
        assert_eq!(failed[0].body["fields"]["request"], request.id.as_str());
        assert_eq!(failed[0].body["fields"]["code"], "schedule-stopped");

        // Declared again, the schedule does not start the work queued before it stopped.
        apply_source(&store, &declared, "held-schedule-again");
        reconciler.reconcile_once().unwrap();
        assert!(
            store
                .claims_for("schedule/held", Some("schedule.work-started"))
                .unwrap()
                .is_empty()
        );
    }

