    #[test]
    fn a_human_can_accept_the_best_result_after_loop_exhaustion() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2
resource "result" { kind "custom.test.loop-result" }
mission "human-exhaustion" state="ready" {
  goal "Let a person accept the bounded result."
  completion { when "all-steps-exhausted" }
  loop "improve" {
    max-rounds 1
    until { gate "ready" { field "state" "resource/result" is "ready" } }
    round { completion { when "all-steps-exhausted" } }
    on-exhausted {
      gate "accept-best" type="human" {
        reviewer "person/alex"
        question "Accept the best bounded result?"
      }
    }
  }
}
"#;
        apply_source(&store, source, "human-loop-exhaustion");
        store
            .append_claim(&ClaimInput {
                subject: "resource/result".into(),
                kind: "resource.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    (
                        "kind".into(),
                        Value::String("custom.test.loop-result".into()),
                    ),
                    ("state".into(), Value::String("not-ready".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("human-loop-result".into()),
            })
            .unwrap();
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "human-exhaustion".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "human-exhaustion-run".into(),
            })
            .unwrap();
        let loop_subject = format!(
            "loop-run/{}/improve",
            run.generation.strip_prefix("run-generation/").unwrap()
        );
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let mut requested = None;
        for _ in 0..20 {
            reconciler.reconcile_once().unwrap();
            if let Some(request) = store.gate_request_for_owner(&loop_subject).unwrap() {
                requested = Some(request);
                break;
            }
        }
        let request = requested.expect("the exhaustion review was not requested");
        assert_eq!(
            request
                .body
                .pointer("/fields/question")
                .and_then(Value::as_str),
            Some("Accept the best bounded result?")
        );
        store
            .append_claim(&ClaimInput {
                subject: request.subject.clone(),
                kind: "gate.result".into(),
                actor: Some("person/alex".into()),
                fields: BTreeMap::from([
                    ("verdict".into(), Value::String("pass".into())),
                    ("request".into(), Value::String(request.id.clone())),
                ]),
                evidence: vec![request.id],
                expected_subject: None,
                idempotency_key: Some("accept-human-loop-result".into()),
            })
            .unwrap();
        for _ in 0..6 {
            reconciler.reconcile_once().unwrap();
        }

        let completed = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(completed.status, "completed");
        assert_eq!(completed.loops[0].status, "exhausted");
    }

    #[test]
    fn a_loop_waiting_on_its_gate_writes_its_state_once() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2
mission "gated-loop" state="ready" {
  goal "Wait for a person without rewriting the loop state."
  completion { when "all-steps-exhausted" }
  loop "improve" {
    max-rounds 2
    until {
      gate "accept" type="human" {
        reviewer "person/example"
        question "Accept this round?"
      }
    }
    round { completion { when "all-steps-exhausted" } }
  }
}
"#;
        apply_source(&store, source, "gated-loop-source");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "gated-loop".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "gated-loop-run".into(),
            })
            .unwrap();
        let loop_subject = format!(
            "loop-run/{}/improve",
            run.generation.strip_prefix("run-generation/").unwrap()
        );
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let mut waiting = false;
        for _ in 0..20 {
            reconciler.reconcile_once().unwrap();
            if store
                .gate_request_for_owner(&loop_subject)
                .unwrap()
                .is_some()
            {
                waiting = true;
                break;
            }
        }
        assert!(waiting, "the loop never asked for its gate");
        reconciler.reconcile_once().unwrap();
        let states = store
            .claims_for(&loop_subject, Some("loop.state"))
            .unwrap()
            .len();
        for _ in 0..30 {
            reconciler.reconcile_once().unwrap();
        }

        let after = store.claims_for(&loop_subject, Some("loop.state")).unwrap();
        assert_eq!(after.len(), states, "a waiting loop rewrote its state");
        let latest = after.last().unwrap();
        assert_eq!(
            latest
                .body
                .pointer("/fields/status")
                .and_then(Value::as_str),
            Some("running")
        );
        assert_eq!(
            latest
                .body
                .pointer("/fields/best_round")
                .and_then(Value::as_u64),
            Some(1),
            "the latest state keeps the round's best result"
        );
        assert_ne!(
            store.mission_run(&run.id).unwrap().unwrap().status,
            "completed"
        );
    }

    #[test]
    fn a_render_receipt_is_recorded_once_on_the_node_that_rendered() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let receipt = |sha: &str| {
            BTreeMap::from([(
                "writes".into(),
                serde_json::json!([{"destination": "/work/example/.st3/boot.md", "mode": 420, "sha256": sha}]),
            )])
        };
        let generation = *reconciler.event_notify.borrow();
        reconciler
            .record_once("agent/node.worker", "render.applied", receipt("first"))
            .unwrap();
        reconciler
            .record_once("agent/node.worker", "render.applied", receipt("first"))
            .unwrap();
        assert_eq!(
            store
                .observations_for("agent/node.worker", "render.applied")
                .unwrap()
                .len(),
            1,
            "an unchanged receipt is not recorded again"
        );
        assert!(
            store
                .claims_for("agent/node.worker", Some("render.applied"))
                .unwrap()
                .is_empty(),
            "a render receipt stays on this node"
        );
        assert_eq!(*reconciler.event_notify.borrow(), generation + 1);
        reconciler
            .record_once("agent/node.worker", "render.applied", receipt("second"))
            .unwrap();
        let receipts = store
            .observations_for("agent/node.worker", "render.applied")
            .unwrap();
        assert_eq!(receipts.len(), 2);
        assert_eq!(receipts[1].body["fields"]["writes"][0]["sha256"], "second");
        assert_eq!(
            store
                .latest_observation("agent/node.worker", "render.applied")
                .unwrap()
                .unwrap()
                .id,
            receipts[1].id
        );
    }

    #[test]
    fn a_failed_loop_requests_attention_once() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2
resource "result" { kind "custom.test.loop-result" }
mission "alert-exhaustion" state="ready" {
  goal "Fail with a visible bounded-loop fault."
  completion { when "all-steps-exhausted" }
  loop "review" {
    max-rounds 1
    until { gate "ready" { field "state" "resource/result" is "ready" } }
    round { completion { when "all-steps-exhausted" } }
    on-exhausted {
      fail
      attention "Automatic review failed" {
        reviewer "person/alex"
        severity "error"
      }
    }
  }
}
"#;
        apply_source(&store, source, "alert-loop-exhaustion");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "alert-exhaustion".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "alert-exhaustion-run".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..20 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(
            store.mission_run(&run.id).unwrap().unwrap().status,
            "failed"
        );
        let attention = store.fault_items(Some("person/alex")).unwrap();
        assert_eq!(attention.len(), 1);
        assert_eq!(attention[0].title, "Automatic review failed");
        assert_eq!(attention[0].kind, "fault");
        assert!(attention[0].targets.contains(&run.subject));
        assert!(
            attention[0].detail.contains("`st work retry step-run/"),
            "{}",
            attention[0].detail
        );
        for _ in 0..5 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(
            store.fault_items(Some("person/alex")).unwrap().len(),
            1
        );
    }

    /// A person's now holds only requests and reviews. A message stays in conversations, and
    /// each fault, on a live run or a terminal one, goes once to the agent that owns it.
    #[test]
    fn faults_reach_their_owning_agent_and_never_a_persons_now() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"
version 2
agent "node.ops" { workspace "/tmp"; command "true"; handles-faults }
agent "node.lead" { workspace "/tmp"; command "true" }
agent "node.builder" { workspace "/tmp"; command "true" }
resource "result" { kind "custom.test.loop-result" }
mission "exhausted" state="ready" {
  goal "Fail a bounded loop."
  completion { when "all-steps-exhausted" }
  loop "review" {
    max-rounds 1
    until { gate "ready" { field "state" "resource/result" is "ready" } }
    round { completion { when "all-steps-exhausted" } }
    on-exhausted {
      fail
      attention "Automatic review failed" {
        reviewer "person/alex"
        severity "error"
      }
    }
  }
}
mission "waiting" state="ready" {
  goal "Wait on a person."
  step "build" {
    assigned-to "agent/node.builder"
    goal "Build the draft."
    gate "review" type="human" { reviewer "person/alex" }
  }
  step "approve" { assigned-to "person/alex"; goal "Approve the copy." }
}
"#,
            "fault-owners",
        );
        let run = |mission: &str, requester: &str| {
            store
                .create_mission_run(&MissionRunRequest {
                    mission: mission.into(),
                    revision: None,
                    workspace: "/tmp".into(),
                    requester: Some(requester.into()),
                    mode: Some("run".into()),
                    inputs: BTreeMap::new(),
                    idempotency_key: format!("{mission}-run"),
                })
                .unwrap()
        };
        let exhausted = run("exhausted", "person/alex");
        let waiting = run("waiting", "agent/node.lead");
        let build = waiting
            .steps
            .iter()
            .find(|step| step.step == "build")
            .unwrap()
            .clone();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..20 {
            reconciler.reconcile_once().unwrap();
        }
        let work = |key: &str| crate::model::WorkRequest {
            actor: Some("agent/node.builder".into()),
            incarnation: Some("builder-one".into()),
            summary: Some("Draft built".into()),
            reason: None,
            evidence: Vec::new(),
            idempotency_key: key.into(),
        };
        store
            .work_action(&build.subject, "claim", &work("build-claim"))
            .unwrap();
        store
            .work_action(&build.subject, "complete", &work("build-submit"))
            .unwrap();
        store
            .append_claim(&ClaimInput {
                subject: "message/quiet-note".into(),
                kind: "message.sent".into(),
                actor: Some("agent/node.lead".into()),
                fields: BTreeMap::from([
                    ("from".into(), Value::String("agent/node.lead".into())),
                    ("to".into(), Value::String("person/alex".into())),
                    ("title".into(), Value::String("The draft is up".into())),
                    ("content".into(), Value::String("No answer needed.".into())),
                    ("status".into(), Value::String("sent".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("quiet-note".into()),
            })
            .unwrap();
        store
            .record_operational_failure(
                "waiting-live",
                &AttentionRequest {
                    reviewer: "person/alex".into(),
                    title: "The waiting run cannot publish".into(),
                    reason: "The publish target refused the run.".into(),
                    severity: "error".into(),
                    targets: vec![waiting.subject.clone()],
                    actor: "daemon/runtime".into(),
                    idempotency_key: "waiting-live".into(),
                },
            )
            .unwrap();
        for _ in 0..5 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(
            store.mission_run(&exhausted.id).unwrap().unwrap().status,
            "failed"
        );
        assert_eq!(
            store.mission_run(&waiting.id).unwrap().unwrap().status,
            "running"
        );

        // Both faults are current, each with its owner: the live run's agent requester, and
        // the fleet's fault agent for the terminal run that a person requested.
        let owners = store
            .fault_snapshot(now_ms())
            .unwrap()
            .into_iter()
            .map(|fault| (fault.item.title, fault.owner))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(
            owners,
            BTreeMap::from([
                (
                    "Automatic review failed".to_owned(),
                    Some("agent/node.ops".to_owned())
                ),
                (
                    "The waiting run cannot publish".to_owned(),
                    Some("agent/node.lead".to_owned())
                ),
            ])
        );

        // The person's now holds the review and the request, and nothing else.
        for person in [Some("person/alex"), None] {
            let kinds = store
                .attention_items(person)
                .unwrap()
                .into_iter()
                .map(|item| item.kind)
                .collect::<BTreeSet<_>>();
            assert_eq!(
                kinds,
                BTreeSet::from(["human-gate".to_owned(), "person-step".to_owned()]),
                "{person:?}"
            );
        }

        // Each owner heard about its fault once, however many passes ran.
        let faults_for = |agent: &str| {
            store
                .messages(Some(agent), false)
                .unwrap()
                .into_iter()
                .filter(|message| message.from == "daemon/runtime")
                .filter_map(|message| message.title)
                .filter(|title| title.starts_with("Fault: "))
                .collect::<Vec<_>>()
        };
        assert_eq!(
            faults_for("agent/node.ops"),
            ["Fault: Automatic review failed"]
        );
        assert_eq!(
            faults_for("agent/node.lead"),
            ["Fault: The waiting run cannot publish"]
        );
        assert!(faults_for("agent/node.builder").is_empty());
        let note = store
            .messages(Some("agent/node.ops"), false)
            .unwrap()
            .into_iter()
            .find(|message| message.title.as_deref() == Some("Fault: Automatic review failed"))
            .unwrap();
        assert!(
            note.content.contains("`st work retry step-run/"),
            "{}",
            note.content
        );
        assert!(note.content.contains("`st work ask`"), "{}", note.content);

        // A fault st raises on the failed step goes to the agent assigned to it.
        reconciler
            .append_fault(&build.subject, "test", "faulted", "the step cannot settle")
            .unwrap();
        let step_fault = store
            .fault_snapshot(now_ms() + 121_000)
            .unwrap()
            .into_iter()
            .find(|fault| fault.item.subject == build.subject)
            .unwrap();
        assert_eq!(step_fault.owner.as_deref(), Some("agent/node.builder"));
        assert!(
            store
                .attention_snapshot(Some("person/alex"), now_ms() + 121_000)
                .unwrap()
                .iter()
                .all(|item| item.kind != "fault")
        );
    }

    /// Without an agent requester or a fleet fault agent, a fault has no owner, and it still
    /// never reaches a person's now.
    #[test]
    fn a_fault_without_an_owning_agent_stays_out_of_a_persons_now() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        store
            .record_operational_failure(
                "disk",
                &AttentionRequest {
                    reviewer: "person/operator".into(),
                    title: "Disk space is low".into(),
                    reason: "The disk is nearly full.".into(),
                    severity: "error".into(),
                    targets: vec!["daemon/node".into()],
                    actor: "daemon/runtime".into(),
                    idempotency_key: "disk".into(),
                },
            )
            .unwrap();
        let faults = store.fault_snapshot(now_ms()).unwrap();
        assert_eq!(faults.len(), 1);
        assert_eq!(faults[0].owner, None);
        assert!(
            store
                .attention_items(Some("person/operator"))
                .unwrap()
                .is_empty()
        );
        assert!(store.attention_items(None).unwrap().is_empty());
    }

    fn stopping_loop_run(
        requester: &str,
        round: &str,
        idempotency_key: &str,
    ) -> (Arc<Store>, Reconciler<FakeRuntime>, MissionRunView) {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = format!(
            r#"
version 2
resource "result" {{ kind "custom.test.loop-result" }}
resource "never" {{ kind "custom.test.loop-result" }}
mission "stopping" state="ready" {{
  goal "Stop a bounded loop."
  completion {{ when "all-steps-exhausted" }}
  loop "review" {{
    max-rounds 3
    until {{ gate "ready" {{ field "state" "resource/result" is "ready" }} }}
    round {{
      completion {{ when "all-steps-exhausted" }}
      {round}
    }}
  }}
}}
"#
        );
        apply_source(&store, &source, idempotency_key);
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "stopping".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some(requester.into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: format!("{idempotency_key}-run"),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        (store, reconciler, run)
    }

    #[test]
    fn every_stopped_loop_asks_its_requester_once_per_stop_until_it_runs_again() {
        let (store, reconciler, run) = stopping_loop_run(
            "person/lichen",
            r#"step "work" { agentless; goal "Round ${loop.round} finds nothing ready." }"#,
            "stopping-loop",
        );
        for _ in 0..30 {
            reconciler.reconcile_once().unwrap();
        }
        let failed = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(failed.status, "failed");
        let step = failed.steps[0].subject.clone();
        let loop_run = format!(
            "loop-run/{}/review",
            failed.generation.strip_prefix("run-generation/").unwrap()
        );
        let items = store.fault_items(Some("person/lichen")).unwrap();
        assert_eq!(items.len(), 1, "{items:?}");
        let first = &items[0];
        assert_eq!(first.title, "Loop `review` stopped");
        assert_eq!(first.kind, "fault");
        assert_eq!(first.targets, vec![loop_run.clone(), run.subject.clone()]);
        for expected in [
            format!("Loop `{loop_run}` stopped in round 3"),
            format!("`st work retry {step} --reason"),
            "runs round 4".into(),
            format!("`st missions cancel {} --reason", run.subject),
        ] {
            assert!(first.detail.contains(&expected), "{}", first.detail);
        }
        for _ in 0..5 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(
            store.fault_items(Some("person/lichen")).unwrap().len(),
            1
        );

        // A retry reopens the run in a new generation, which ends the item. The loop stops
        // again there, and that stop raises its own item.
        store
            .retry_failed_step(&step, "person/lichen", "try the loop again", "retry-loop")
            .unwrap();
        for _ in 0..30 {
            reconciler.reconcile_once().unwrap();
        }
        let items = store.fault_items(Some("person/lichen")).unwrap();
        assert_eq!(items.len(), 1, "{items:?}");
        assert_ne!(items[0].subject, first.subject);
        assert!(!items[0].targets.contains(&loop_run));
        assert!(
            items[0].detail.contains("stopped in round 4"),
            "the retry ran the round the first item named: {}",
            items[0].detail
        );
    }

    #[test]
    fn a_loop_stopped_by_a_cancelled_round_says_how_to_start_over() {
        let (store, reconciler, run) = stopping_loop_run(
            "agent/example/orchid",
            r#"step "wait" {
        agentless
        gate "never" { field "status" "resource/never" "is" "ready" }
      }"#,
            "cancelled-round",
        );
        for _ in 0..10 {
            reconciler.reconcile_once().unwrap();
        }
        let current = store.mission_run(&run.id).unwrap().unwrap();
        let round = store
            .mission_run(&store.mission_run_subject_for_idempotency_key(&format!(
                "loop-round:{}:1",
                current.steps[0].subject
            )))
            .unwrap()
            .unwrap();
        store
            .set_mission_run_state(
                &round.id,
                "cancelled",
                "terminal",
                Some("cancelled by test"),
            )
            .unwrap();
        for _ in 0..10 {
            reconciler.reconcile_once().unwrap();
        }
        let stopped = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(stopped.steps[0].status, "cancelled");
        // The requester is not a person, so the operator is asked.
        let items = store.fault_items(Some("person/operator")).unwrap();
        assert_eq!(items.len(), 1, "{items:?}");
        for expected in [
            "stopped in round 1: the loop round mission had a structural failure.",
            "st cannot retry a cancelled step.",
            "`st missions start stopping`",
        ] {
            assert!(items[0].detail.contains(expected), "{}", items[0].detail);
        }
    }

    #[test]
    #[should_panic(expected = "removed-loop-shape")]
    fn a_removed_best_of_n_loop_is_rejected_before_reconciliation() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2
resource "candidate-1" { kind "custom.test.candidate" }
resource "candidate-2" { kind "custom.test.candidate" }
mission "best" state="ready" {
  goal "Select the best bounded candidate."
  completion { when "all-steps-exhausted" }
  loop "choose" {
    max-rounds 2
    metric "quality" direction="higher" {
      field "score" "resource/candidate-${candidate.index}"
    }
    candidates 2 max-parallel=2 { select metric="quality" }
    round {
      completion { when "all-steps-exhausted" }
      step "create" { agentless; goal "Create candidate ${candidate.index}." }
    }
  }
}
"#;
        apply_source(&store, source, "candidate-loop");
        for (candidate, score) in [(1, 0.25), (2, 0.75)] {
            store
                .append_claim(&ClaimInput {
                    subject: format!("resource/candidate-{candidate}"),
                    kind: "resource.observed".into(),
                    actor: None,
                    fields: BTreeMap::from([
                        ("kind".into(), Value::String("custom.test.candidate".into())),
                        ("score".into(), Value::from(score)),
                    ]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: Some(format!("candidate-score-{candidate}")),
                })
                .unwrap();
        }
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "best".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "best-run".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let mut initial_candidates = 0;
        for _ in 0..5 {
            reconciler.reconcile_once().unwrap();
            initial_candidates = (1..=3)
                .filter(|candidate| {
                    let key = format!("loop-candidate:{}:1:{candidate}", run.steps[0].subject);
                    let subject = store.mission_run_subject_for_idempotency_key(&key);
                    store.mission_run(&subject).unwrap().is_some()
                })
                .count();
            if initial_candidates > 0 {
                break;
            }
        }
        assert_eq!(initial_candidates, 2);
        for _ in 0..40 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(
            store.mission_run(&run.id).unwrap().unwrap().status,
            "completed"
        );
        let subject = format!(
            "loop-run/{}/choose",
            run.generation.strip_prefix("run-generation/").unwrap()
        );
        let state = store
            .latest_claim(&subject, Some("loop.state"))
            .unwrap()
            .unwrap();
        assert_eq!(
            state.body.pointer("/fields/winner").and_then(Value::as_u64),
            Some(2)
        );
    }

    #[test]
    fn an_open_queue_does_not_report_standing_between_ready_items() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

mission "queue" state="ready" {
  goal "Complete an ordered queue."
  queue "work" {
    agentless
    step "one" { goal "Complete the first item." }
    step "two" { goal "Complete the second item." }
  }
}
"#;
        apply_source(&store, source, "publish-queue");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "queue".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-queue".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );

        loop {
            reconciler.reconcile_once().unwrap();
            let view = store.mission_run(&run.id).unwrap().unwrap();
            let all_completed = view.steps.iter().all(|step| step.status == "completed");
            assert!(all_completed || view.status == "running");
            if all_completed {
                for _ in 0..4 {
                    reconciler.reconcile_once().unwrap();
                }
                break;
            }
        }

        assert_eq!(
            store.mission_run(&run.id).unwrap().unwrap().status,
            "completed"
        );
    }

    #[test]
    fn a_strict_queue_starts_agentless_nested_containers_in_order() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

mission "queue-nested" state="ready" {
  completion { when "all-steps-exhausted" }
  goal "Run two nested jobs without overlap."
  agent "worker" { workspace "/tmp"; command "true" }
  queue "jobs" {
    step "first-job" {
      mission "first" {
        assigned-to "agent/${ST_MISSION_RUN}/worker"
        goal "Complete the first nested job."
        step "work" {
          goal "Complete first work."
          retry { attempts 2 }
        }
      }
    }
    step "second-job" {
      mission "second" {
        assigned-to "agent/${ST_MISSION_RUN}/worker"
        goal "Complete the second nested job."
        step "work" { goal "Complete second work." }
      }
    }
  }
}
"#;
        apply_source(&store, source, "publish-queue-nested");
        let published = store.index().unwrap();
        apply_source(&store, source, "publish-queue-nested");
        assert_eq!(
            store.index().unwrap(),
            published,
            "duplicate publication changed the graph"
        );
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "queue-nested".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: Some("run".into()),
                inputs: BTreeMap::new(),
                idempotency_key: "run-queue-nested".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..5 {
            reconciler.reconcile_once().unwrap();
        }

        let view = store.mission_run(&run.id).unwrap().unwrap();
        let step = |path: &str| view.steps.iter().find(|step| step.step == path).unwrap();
        let first = step("first-job");
        let first_work = step("first-job/first/work");
        let second = step("second-job");
        let second_work = step("second-job/second/work");
        assert_eq!(first.status, "working");
        assert!(first.agentless);
        assert_eq!(first_work.status, "ready");
        assert_eq!(second.status, "pending");
        assert_eq!(second_work.status, "pending");
        let unavailable = store
            .work_action(
                &first.subject,
                "claim",
                &crate::model::WorkRequest {
                    actor: Some(first_work.assigned_to.clone().unwrap()),
                    incarnation: Some("current".into()),
                    summary: None,
                    reason: None,
                    evidence: Vec::new(),
                    idempotency_key: "claim-structural-parent".into(),
                },
            )
            .unwrap_err();
        assert_eq!(unavailable.code, "work-not-available");
        assert!(store.step_run(&first.subject).unwrap().is_some());

        let work = |key: &str, actor: String| crate::model::WorkRequest {
            actor: Some(actor),
            incarnation: Some("current".into()),
            summary: None,
            reason: None,
            evidence: Vec::new(),
            idempotency_key: key.into(),
        };
        let first_actor = first_work.assigned_to.clone().unwrap();
        let first_subject = first_work.subject.clone();
        store
            .work_action(
                &first_subject,
                "claim",
                &work("claim-first-nested", first_actor.clone()),
            )
            .unwrap();
        store
            .work_action(
                &first_subject,
                "fail",
                &work("fail-first-nested", first_actor.clone()),
            )
            .unwrap();
        for _ in 0..5 {
            reconciler.reconcile_once().unwrap();
        }

        let after_retry = store.mission_run(&run.id).unwrap().unwrap();
        let retried = after_retry
            .steps
            .iter()
            .find(|step| step.step == "first-job/first/work")
            .unwrap();
        assert_eq!(retried.status, "ready");
        assert_eq!(retried.attempt, 2);
        assert_eq!(
            after_retry
                .steps
                .iter()
                .find(|step| step.step == "second-job")
                .unwrap()
                .status,
            "pending"
        );

        // Reconstructing the reconciler is the daemon-restart boundary. The persisted parent
        // admission and retry attempt resume without duplicating or advancing the queue item.
        drop(reconciler);
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        store
            .work_action(
                &first_subject,
                "claim",
                &work("claim-first-nested-retry", first_actor.clone()),
            )
            .unwrap();
        store
            .work_action(
                &first_subject,
                "complete",
                &work("complete-first-nested-retry", first_actor),
            )
            .unwrap();
        for _ in 0..5 {
            reconciler.reconcile_once().unwrap();
        }

        let view = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(
            view.steps
                .iter()
                .find(|step| step.step == "first-job")
                .unwrap()
                .status,
            "completed"
        );
        let second = view
            .steps
            .iter()
            .find(|step| step.step == "second-job")
            .unwrap();
        let second_work = view
            .steps
            .iter()
            .find(|step| step.step == "second-job/second/work")
            .unwrap();
        assert_eq!(second.status, "working");
        assert_eq!(second_work.status, "ready");
        let second_actor = second_work.assigned_to.clone().unwrap();
        let second_subject = second_work.subject.clone();
        store
            .work_action(
                &second_subject,
                "claim",
                &work("claim-second-nested", second_actor.clone()),
            )
            .unwrap();
        store
            .work_action(
                &second_subject,
                "complete",
                &work("complete-second-nested", second_actor),
            )
            .unwrap();
        for _ in 0..8 {
            reconciler.reconcile_once().unwrap();
        }
        let view = store.mission_run(&run.id).unwrap().unwrap();
        assert!(view.steps.iter().all(|step| step.status == "completed"));
        assert_eq!(view.status, "completed");
    }

    #[test]
    fn a_top_level_seat_outlives_a_zero_step_mission() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  agent "standing-agent" {
    command "sleep 60"
    restart "on-failure"
    exec "helper" { command "true" }
  }

  mission "finite-zero" state="ready" {
    goal "Complete without owning the durable seat."
  }
"#;
        apply_source(&store, source, "publish-standing-agent");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "finite-zero".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-standing-agent".into(),
            })
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );

        for _ in 0..6 {
            reconciler.reconcile_once().unwrap();
        }

        let subjects = store
            .desired_subjects()
            .unwrap()
            .into_iter()
            .map(|subject| subject.subject)
            .collect::<BTreeSet<_>>();
        assert!(subjects.contains("agent/node.standing-agent"));
        assert!(subjects.contains("exec/node.standing-agent/helper"));
        let started = runtime
            .started_members
            .lock()
            .unwrap()
            .iter()
            .map(|member| member.runtime_id.clone())
            .collect::<BTreeSet<_>>();
        assert_eq!(started.len(), 2);
        assert_eq!(
            store.mission_run(&run.id).unwrap().unwrap().status,
            "completed"
        );
    }

