    #[test]
    fn a_terminal_owner_stops_a_runtime_even_without_a_cleanup_declaration() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  mission "direct-terminal" state="ready" {
    goal "Stop runtimes after any authoritative terminal transition."
    completion { when "all-steps-exhausted" }
    agent "worker" { workspace "/tmp"; command "true"; restart "never" }
    step "finish" { agentless }
  }

"#;
        apply_source(&store, source, "publish-direct-terminal");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "direct-terminal".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-direct-terminal".into(),
            })
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        let member = store
            .desired_subjects()
            .unwrap()
            .into_iter()
            .find(|desired| desired.subject == format!("agent/{}/worker", run.id))
            .and_then(|desired| desired.member)
            .unwrap();
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: member.runtime_id.clone(),
            terminal: true,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some("direct-terminal-incarnation".into()),
        });
        reconciler.reconcile_once().unwrap();
        store
            .append_claim(&ClaimInput {
                subject: format!("agent/{}/worker", run.id),
                kind: "runtime.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("status".into(), Value::String("stopped".into())),
                    (
                        "runtime_id".into(),
                        Value::String(member.runtime_id.clone()),
                    ),
                    ("terminal".into(), Value::Bool(true)),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("stale-stopped-worker".into()),
            })
            .unwrap();

        assert!(
            store
                .set_mission_run_state(
                    &run.id,
                    "cancelled",
                    "terminal",
                    Some("cancelled by an older client"),
                )
                .unwrap()
        );
        assert!(
            store
                .desired_subjects()
                .unwrap()
                .iter()
                .any(
                    |desired| desired.subject == format!("agent/{}/worker", run.id)
                        && desired.kind == "agent"
                )
        );

        *runtime.snapshot_error.lock().unwrap() = true;
        reconciler.reconcile_once().unwrap();
        assert!(runtime.stops.lock().unwrap().is_empty());
        *runtime.snapshot_error.lock().unwrap() = false;
        reconciler.reconcile_once().unwrap();
        assert_eq!(
            runtime.stops.lock().unwrap().as_slice(),
            &[member.runtime_id]
        );
        let actual = store
            .latest_actual_value(&format!("agent/{}/worker", run.id))
            .unwrap()
            .unwrap();
        assert_eq!(
            actual_field(&actual, "status").and_then(Value::as_str),
            Some("running"),
            "a live incarnation must displace the stale stopped projection"
        );
    }

    /// A finished run whose seat is live, with the seat's runtime id and the fake runtime.
    fn finished_run_with_a_live_seat(
        extra: impl FnOnce(&Store, &str),
    ) -> (
        Arc<Store>,
        Arc<FakeRuntime>,
        Reconciler<FakeRuntime>,
        String,
        String,
    ) {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"
version 2

  mission "retained" state="ready" {
    goal "Finish while the seat is wanted elsewhere."
    completion { when "all-steps-exhausted" }
    agent "worker" { workspace "/tmp"; command "true"; restart "never" }
    step "finish" { agentless; depends-on { step "gate" completed } }
    step "gate" { agentless; title "Waits for the test" }
  }

"#,
            "publish-retained",
        );
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "retained".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-retained".into(),
            })
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        let seat = format!("agent/{}/worker", run.id);
        let member = store
            .desired_subjects()
            .unwrap()
            .into_iter()
            .find(|desired| desired.subject == seat)
            .and_then(|desired| desired.member)
            .unwrap();
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: member.runtime_id.clone(),
            terminal: true,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some("retained-incarnation".into()),
        });
        extra(&store, &seat);
        (store, runtime, reconciler, run.id, member.runtime_id)
    }

    #[test]
    fn a_seat_with_an_unread_message_outlives_the_run_that_declared_it() {
        let (store, runtime, reconciler, run_id, runtime_id) =
            finished_run_with_a_live_seat(|store, seat| {
                store
                    .append_claim(&ClaimInput {
                        subject: "message/urgent".into(),
                        kind: "message.sent".into(),
                        actor: Some("person/test".into()),
                        fields: BTreeMap::from([
                            ("from".into(), Value::String("person/test".into())),
                            ("to".into(), Value::String(seat.into())),
                            ("content".into(), Value::String("P0: read me".into())),
                            ("status".into(), Value::String("sent".into())),
                        ]),
                        evidence: Vec::new(),
                        expected_subject: None,
                        idempotency_key: Some("urgent-message".into()),
                    })
                    .unwrap();
            });
        for _ in 0..10 {
            reconciler.reconcile_once().unwrap();
        }
        // Completing the gate lets the run finish and clean up.
        let gate = store
            .mission_run(&run_id)
            .unwrap()
            .unwrap()
            .steps
            .into_iter()
            .find(|step| step.step == "gate")
            .unwrap();
        store
            .set_step_state(&gate.subject, "completed", None)
            .unwrap();
        for _ in 0..10 {
            reconciler.reconcile_once().unwrap();
        }
        let run = store.mission_run(&run_id).unwrap().unwrap();
        assert_eq!(
            run.status, "completed",
            "the held seat does not hold the run open"
        );
        assert!(
            runtime.stops.lock().unwrap().is_empty(),
            "the seat still has an unread message"
        );
        assert!(store.desired_subjects().unwrap().iter().any(|desired| {
            desired.subject == format!("agent/{run_id}/worker") && desired.kind == "stop"
        }));

        // Once the message is read the stop goes ahead.
        for (kind, status) in [
            ("message.staged", "staged"),
            ("message.delivered", "delivered"),
            ("message.read", "read"),
        ] {
            store
                .append_claim(&ClaimInput {
                    subject: "message/urgent".into(),
                    kind: kind.into(),
                    actor: Some(format!("agent/{run_id}/worker")),
                    fields: BTreeMap::from([("status".into(), Value::String(status.into()))]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: Some(format!("urgent-{status}")),
                })
                .unwrap();
        }
        reconciler.seat_retention.lock().unwrap().clear();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.stops.lock().unwrap().as_slice(), &[runtime_id]);
    }

    #[test]
    fn a_seat_with_work_in_another_run_outlives_the_run_that_declared_it() {
        let (store, runtime, reconciler, run_id, runtime_id) =
            finished_run_with_a_live_seat(|store, seat| {
                apply_source(
                    store,
                    &format!(
                        r#"
version 2

  mission "elsewhere" state="ready" {{
    goal "Give the seat other work."
    step "other" {{ assigned-to "{seat}"; title "Work in another run" }}
  }}

"#
                    ),
                    "publish-elsewhere",
                );
                store
                    .create_mission_run(&MissionRunRequest {
                        mission: "elsewhere".into(),
                        revision: None,
                        workspace: "/tmp".into(),
                        requester: Some("person/test".into()),
                        mode: None,
                        inputs: BTreeMap::new(),
                        idempotency_key: "run-elsewhere".into(),
                    })
                    .unwrap();
            });
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let gate = store
            .mission_run(&run_id)
            .unwrap()
            .unwrap()
            .steps
            .into_iter()
            .find(|step| step.step == "gate")
            .unwrap();
        store
            .set_step_state(&gate.subject, "completed", None)
            .unwrap();
        for _ in 0..10 {
            reconciler.reconcile_once().unwrap();
        }
        assert_eq!(
            store.mission_run(&run_id).unwrap().unwrap().status,
            "completed"
        );
        assert!(
            runtime.stops.lock().unwrap().is_empty(),
            "the seat still holds work for another run"
        );

        // The other run's work ends, and the stop goes ahead.
        let elsewhere = store
            .seat_work_in_other_runs(&format!("agent/{run_id}/worker"), &run_id)
            .unwrap();
        assert_eq!(elsewhere.len(), 1);
        store
            .set_step_state(&elsewhere[0], "completed", None)
            .unwrap();
        reconciler.seat_retention.lock().unwrap().clear();
        reconciler.reconcile_once().unwrap();
        assert_eq!(runtime.stops.lock().unwrap().as_slice(), &[runtime_id]);
    }

    /// A run whose final step stops a seat that holds an unread message, with the seat live.
    fn run_with_a_final_stop_of_a_held_seat() -> (Arc<Store>, Reconciler<FakeRuntime>, String) {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"
version 2

mission "held-stop" state="ready" {
  goal "Stop a seat that is still wanted."
  completion { when "all-steps-exhausted" }
  agent "worker" { workspace "/tmp"; command "true"; restart "never" }
  step "work" { agentless }
  finally { step "stop-worker" timeout="10m" { agentless; stop "agent/${ST_MISSION_RUN}/worker" } }
}
"#,
            "publish-held-stop",
        );
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "held-stop".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-held-stop".into(),
            })
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.reconcile_once().unwrap();
        let seat = format!("agent/{}/worker", run.id);
        let member = store
            .desired_subjects()
            .unwrap()
            .into_iter()
            .find(|desired| desired.subject == seat)
            .and_then(|desired| desired.member)
            .unwrap();
        runtime.ptys.lock().unwrap().push(RuntimeObservation {
            runtime_id: member.runtime_id,
            terminal: true,
            status: "running".into(),
            exit_code: None,
            incarnation_id: Some("held-incarnation".into()),
        });
        store
            .append_claim(&ClaimInput {
                subject: "message/held".into(),
                kind: "message.sent".into(),
                actor: Some("person/test".into()),
                fields: BTreeMap::from([
                    ("from".into(), Value::String("person/test".into())),
                    ("to".into(), Value::String(seat)),
                    ("content".into(), Value::String("read me".into())),
                    ("status".into(), Value::String("sent".into())),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("held-message".into()),
            })
            .unwrap();
        (store, reconciler, run.id)
    }

    #[test]
    fn a_final_stop_of_a_held_seat_completes_and_the_run_completes() {
        let (store, reconciler, run_id) = run_with_a_final_stop_of_a_held_seat();
        for _ in 0..20 {
            reconciler.reconcile_once().unwrap();
        }
        let run = store.mission_run(&run_id).unwrap().unwrap();
        let stop = run
            .steps
            .iter()
            .find(|step| step.step == "stop-worker")
            .unwrap();
        assert_eq!(stop.status, "completed", "{:?}", stop.blocked_reason);
        assert_eq!(run.status, "completed");
        assert!(
            !store
                .claims_for(&format!("agent/{run_id}/worker"), Some("runtime.reconcile-decision"))
                .unwrap()
                .iter()
                .any(|claim| claim.body.to_string().contains("invalid-claim-field")),
            "the deferral diagnostic is a valid claim"
        );
    }

    #[test]
    fn a_final_stop_of_a_seat_already_stopping_completes_at_once() {
        let (store, reconciler, run_id) = run_with_a_final_stop_of_a_held_seat();
        let seat = format!("agent/{run_id}/worker");
        // The message is read, so only the stop itself is in progress.
        for (kind, status) in [
            ("message.staged", "staged"),
            ("message.delivered", "delivered"),
            ("message.read", "read"),
        ] {
            store
                .append_claim(&ClaimInput {
                    subject: "message/held".into(),
                    kind: kind.into(),
                    actor: Some(seat.clone()),
                    fields: BTreeMap::from([("status".into(), Value::String(status.into()))]),
                    evidence: Vec::new(),
                    expected_subject: None,
                    idempotency_key: Some(format!("held-{status}")),
                })
                .unwrap();
        }
        for _ in 0..20 {
            reconciler.reconcile_once().unwrap();
        }
        let run = store.mission_run(&run_id).unwrap().unwrap();
        assert_eq!(
            run.steps
                .iter()
                .find(|step| step.step == "stop-worker")
                .unwrap()
                .status,
            "completed"
        );
        // Cleanup still waits for the seat the stop is bringing down.
        assert_eq!(run.status, "running");
    }

    #[test]
    fn a_failed_final_step_after_completed_work_is_a_fault_not_the_outcome() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        apply_source(
            &store,
            r#"
version 2

resource "never" { kind "custom.test.never-ready" }
mission "cleanup-fails" state="ready" {
  goal "Finish the work, then fail the cleanup."
  completion { when "all-steps-exhausted" }
  step "work" { agentless }
  finally {
    step "tidy" timeout="1ms" {
      agentless
      gate "the absent resource becomes ready" { field "state" "resource/never" is "ready" }
    }
  }
}
"#,
            "publish-cleanup-fails",
        );
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "cleanup-fails".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-cleanup-fails".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..20 {
            reconciler.reconcile_once().unwrap();
            std::thread::sleep(Duration::from_millis(2));
        }
        let finished = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(
            finished
                .steps
                .iter()
                .find(|step| step.step == "tidy")
                .unwrap()
                .status,
            "failed"
        );
        assert_eq!(
            (finished.status.as_str(), finished.phase.as_str()),
            ("completed", "terminal")
        );
        let faults = store
            .claims_for(&run.subject, Some("operational.failure"))
            .unwrap();
        assert_eq!(faults.len(), 1);
        assert!(
            faults[0].body["fields"]["reason"]
                .as_str()
                .unwrap()
                .contains("tidy: the active execution timeout expired")
        );
    }

    #[test]
    fn a_failed_dependency_selects_terminal_cleanup_for_a_finite_mission() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  mission "blocked" state="ready" {
    goal "Expose an unreachable explicit completion frontier."
    completion { when "all-steps-exhausted" }
    step "failed" { agentless }
    step "dependent" { agentless; depends-on { step "failed" completed } }
  }

"#;
        apply_source(&store, source, "publish-blocked");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "blocked".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-blocked".into(),
            })
            .unwrap();
        let failed = run.steps.iter().find(|step| step.step == "failed").unwrap();
        store
            .set_step_state(&failed.subject, "failed", Some("test failure"))
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        for _ in 0..3 {
            reconciler.reconcile_once().unwrap();
        }
        let run = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(run.status, "failed");
        assert_eq!(run.phase, "terminal");
        assert_eq!(
            run.steps
                .iter()
                .find(|step| step.step == "dependent")
                .unwrap()
                .status,
            "cancelled"
        );
    }

    #[test]
    fn a_retried_step_reopens_its_failed_run_and_the_run_completes() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  mission "takeover" state="ready" {
    goal "Take over one service."
    agent "watcher" { workspace "/tmp"; command "true"; restart "never" }
    step "prepare" { agentless }
    step "deploy-check" { agentless; depends-on { step "prepare" completed } }
    step "announce" { agentless; depends-on { step "deploy-check" completed } }
    finally { step "report" { agentless } }
  }

"#;
        apply_source(&store, source, "publish-takeover");
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "takeover".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-takeover".into(),
            })
            .unwrap();
        let step = |run: &crate::model::MissionRunView, path: &str| {
            run.steps
                .iter()
                .find(|step| step.step == path)
                .unwrap()
                .clone()
        };
        store
            .set_step_state(&step(&run, "prepare").subject, "completed", None)
            .unwrap();
        store
            .set_step_state(
                &step(&run, "deploy-check").subject,
                "failed",
                Some("the deploy check failed"),
            )
            .unwrap();
        let runtime = Arc::new(FakeRuntime::default());
        let reconciler = Reconciler::new(
            store.clone(),
            runtime.clone(),
            "node".into(),
            Arc::new(Notify::new()),
        );
        let settle = || {
            for _ in 0..20 {
                reconciler.reconcile_once().unwrap();
                if store.mission_run(&run.id).unwrap().unwrap().phase == "terminal" {
                    break;
                }
            }
            store.mission_run(&run.id).unwrap().unwrap()
        };
        let failed = settle();
        assert_eq!(failed.status, "failed");
        assert_eq!(step(&failed, "announce").status, "cancelled");
        assert_eq!(step(&failed, "report").status, "completed");
        // The watcher is the only member this mission declares.
        let watcher_starts = || runtime.started_members.lock().unwrap().len();
        assert_eq!(watcher_starts(), 1);

        let reopened = store
            .retry_failed_step(
                &step(&failed, "deploy-check").subject,
                "person/test",
                "the deploy check host is back",
                "retry-deploy-check",
            )
            .unwrap();
        assert_eq!(reopened.status, "running");

        let finished = settle();
        assert_eq!(finished.status, "completed");
        assert_eq!(finished.generation, reopened.generation);
        assert_eq!(step(&finished, "deploy-check").attempt, 2);
        assert_eq!(
            watcher_starts(),
            2,
            "the reopened run relaunches its mission agent"
        );
        assert!(
            finished.steps.iter().all(|step| step.status == "completed"),
            "{:?}",
            finished.steps
        );
    }

    #[test]
    fn one_agent_can_claim_only_one_independent_pool_step_and_a_claim_is_exclusive() {
        let store = Arc::new(Store::open_memory("node").unwrap());
        let source = r#"
version 2

  agent "one" { workspace "/tmp"; command "true"; restart "never" }
  mission "pool" state="ready" {
    goal "Expose two steps to one explicit pool."
    available-to "agent/node.one"
    available-to "agent/node.missing"
    step "a" { }
    step "b" { }
  }

"#;
        apply_source(&store, source, "publish-pool");
        store
            .append_claim(&ClaimInput {
                subject: "agent/node.one".into(),
                kind: "harness.observed".into(),
                actor: None,
                fields: BTreeMap::from([
                    ("state".into(), Value::String("ready".into())),
                    (
                        "incarnation_id".into(),
                        Value::String("incarnation-one".into()),
                    ),
                ]),
                evidence: Vec::new(),
                expected_subject: None,
                idempotency_key: Some("pool-agent-ready".into()),
            })
            .unwrap();
        let run = store
            .create_mission_run(&MissionRunRequest {
                mission: "pool".into(),
                revision: None,
                workspace: "/tmp".into(),
                requester: Some("person/test".into()),
                mode: None,
                inputs: BTreeMap::new(),
                idempotency_key: "run-pool".into(),
            })
            .unwrap();
        let reconciler = Reconciler::new(
            store.clone(),
            Arc::new(FakeRuntime::default()),
            "node".into(),
            Arc::new(Notify::new()),
        );
        reconciler.evaluate_mission_runs().unwrap();
        let work = store.work(Some("agent/node.one"), false).unwrap();
        assert_eq!(work.len(), 2);
        let claim = |step: &crate::model::StepRunView, key: &str| {
            store.work_action(
                &step.subject,
                "claim",
                &crate::model::WorkRequest {
                    actor: Some("agent/node.one".into()),
                    incarnation: Some("incarnation-one".into()),
                    summary: None,
                    reason: None,
                    evidence: Vec::new(),
                    idempotency_key: key.into(),
                },
            )
        };
        claim(&work[0], "pool-claim-a").unwrap();
        let capacity = claim(&work[1], "pool-claim-b").unwrap_err();
        assert_eq!(capacity.code, "agent-capacity");
        let run = store.mission_run(&run.id).unwrap().unwrap();
        assert_eq!(
            run.steps
                .iter()
                .filter(|step| step.claimant.as_deref() == Some("agent/node.one"))
                .count(),
            1
        );
        let error = store
            .work_action(
                &work[0].subject,
                "claim",
                &crate::model::WorkRequest {
                    actor: Some("agent/node.missing".into()),
                    incarnation: Some("other".into()),
                    summary: None,
                    reason: None,
                    evidence: Vec::new(),
                    idempotency_key: "pool-lost-race".into(),
                },
            )
            .unwrap_err();
        assert!(
            matches!(
                error.code,
                "work-already-claimed"
                    | "invalid-work-transition"
                    | "work-not-eligible"
                    | "agent-not-active"
            ),
            "{}",
            error.code
        );
    }

